INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91811, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "判决是法官听完了以后，说谁对谁错。", "primary_collocate": null, "pronunciation": "pàn jué", "ipa": "pʰan⁵¹ tɕyɛ³⁵", "syllable_count": 2, "sentences": [{"text": "法官听完两边的话，判决小王没有错。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判决那个男人要还钱。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官想了很久才判决。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判决小李赢了这场官司。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居吵架，法官判决谁也不用赔。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判决他每个月要给孩子钱。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午法官会判决这件事。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，法官判决得很公平。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判决她是对的。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在等法官判决。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "判决了", "label": "体标（了）"}, {"form": "判决过", "label": "体标（过）"}, {"form": "判决书", "label": "复合词"}], "register": "正式", "sense_fingerprint": "法官听完双方后说明谁对谁错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91811, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逮捕", "is_correct": false, "explanation": "语义：“逮捕”是强制拘押，与“没有错”的裁断不符。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”用于创造事物，不能用于判断人的对错。"}, {"text": "判决", "is_correct": true, "explanation": "正确：法官听完双方后作出裁断，“判决”说明谁对谁错。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”针对错误，与“没有错”矛盾。"}], "explanations": {"逮捕": "语义：“逮捕”是强制拘押，与“没有错”的裁断不符。", "发明": "搭配：“发明”用于创造事物，不能用于判断人的对错。", "判决": "正确：法官听完双方后作出裁断，“判决”说明谁对谁错。", "批评": "语义：“批评”针对错误，与“没有错”矛盾。"}, "sentence_index": 0, "correct_answer": "判决"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我判决他明天会来。", "explanation": "这里应该用〈猜测〉。“判决”要由法官依据事实作裁断，对未来的推断要用“猜测”。"}, {"text": "我们判决去哪家餐厅吃饭。", "explanation": "这里应该用〈选择〉。“判决”只用于法官裁定案件，挑选餐厅要用“选择”。"}, {"text": "老板判决下周开会。", "explanation": "这里应该用〈安排〉。“判决”是法院的裁定，老板定会议时间要用“安排”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91811, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浇灌", "is_correct": false, "explanation": "语义：“浇灌”用于给植物浇水，与“这件事”不搭。"}, {"text": "判决", "is_correct": true, "explanation": "正确：“判决”指法官对案件作出裁断，与“法官”“这件事”相合。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭，与法官和事情都无关。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”用于动物、婴儿，不能用于事情。"}], "explanations": {"浇灌": "语义：“浇灌”用于给植物浇水，与“这件事”不搭。", "判决": "正确：“判决”指法官对案件作出裁断，与“法官”“这件事”相合。", "烹饪": "语义：“烹饪”指做饭，与法官和事情都无关。", "喂养": "搭配：“喂养”用于动物、婴儿，不能用于事情。"}, "sentence_index": 6, "correct_answer": "判决"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我判决你可以去看电影。", "explanation": "这里应该用〈同意〉。“判决”是法官裁定谁对谁错，允许别人做事要用“同意”。"}, {"text": "妈妈判决了周末去哪儿玩。", "explanation": "这里应该用〈决定〉。“判决”只用于法院的裁定，全家周末去哪儿要用“决定”。"}, {"text": "学校判决了他的入学申请。", "explanation": "这里应该用〈批准〉。“判决”是法院的裁定，学校同意申请要用“批准”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91811, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天法官判决了这件事。", "corrected_sentence": "明天法官判决这件事。", "error_description": "错误：“明天”指将来，“判决”后不能加“了”。正确：将来的动作不用“了”，应说“明天法官判决这件事。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91811, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法官很判决这件事。", "corrected_sentence": "法官判决这件事。", "error_description": "错误：程度副词“很”不能直接修饰动词“判决”。正确：去掉“很”，应说“法官判决这件事。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
