INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91812, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "法院对案件作出的决定；作出这种决定。", "primary_collocate": null, "pronunciation": "pàn jué", "ipa": "pʰan⁵¹ tɕyɛ³⁵", "syllable_count": 2, "sentences": [{"text": "法院昨天判决了这个案子。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判决他有罪。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院判决公司赔钱给他们。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子还没有判决。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院判决他们离婚。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官当场判决小偷坐牢三年。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院判决的结果大家都接受了。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院判决他不用坐牢。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事法院会公平地判决。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官判决这家工厂停产。", "target_word": "判决", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "判决了", "label": "体标（了）"}, {"form": "判决过", "label": "体标（过）"}, {"form": "判决书", "label": "复合词"}], "register": "正式", "sense_fingerprint": "法院对案件作出裁决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91812, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发表", "is_correct": false, "explanation": "搭配：“发表”用于文章、声明，不能用于案子。"}, {"text": "判决", "is_correct": true, "explanation": "正确：“判决”指法院对案件作出裁定，与“法院”“案子”相合。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”指建造房屋、道路等工程，与案子无关。"}, {"text": "出售", "is_correct": false, "explanation": "语义：案子不是商品，不能出售。"}], "explanations": {"发表": "搭配：“发表”用于文章、声明，不能用于案子。", "判决": "正确：“判决”指法院对案件作出裁定，与“法院”“案子”相合。", "修建": "语义：“修建”指建造房屋、道路等工程，与案子无关。", "出售": "语义：案子不是商品，不能出售。"}, "sentence_index": 0, "correct_answer": "判决"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很会判决局势。", "explanation": "这里应该用〈判断〉。“判决”指法院对案件作出裁定，分析局势要用“判断”。"}, {"text": "我们班长判决了春游去哪儿。", "explanation": "这里应该用〈决定〉。“判决”只用于法院对案件的裁定，班里的安排要用“决定”。"}, {"text": "老师判决我的作文写得很好。", "explanation": "这里应该用〈认为〉。“判决”是法官作出的裁断，老师对作文的看法要用“认为”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91812, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做菜，与法院无关。"}, {"text": "判决", "is_correct": true, "explanation": "正确：“判决”是法院作出的裁定，与“法院”相合，可修饰“结果”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽培植物，法院不种植东西，句意不通。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”指制造产品，法院的裁定不是产品。"}], "explanations": {"烹饪": "语义：“烹饪”指做菜，与法院无关。", "判决": "正确：“判决”是法院作出的裁定，与“法院”相合，可修饰“结果”。", "种植": "语义：“种植”指栽培植物，法院不种植东西，句意不通。", "生产": "语义：“生产”指制造产品，法院的裁定不是产品。"}, "sentence_index": 6, "correct_answer": "判决"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈判决我今晚不许出门。", "explanation": "这里应该用〈规定〉。“判决”是法院对案件的裁定，家长对孩子的要求要用“规定”。"}, {"text": "天气专家判决明天会下雨。", "explanation": "这里应该用〈预测〉。“判决”只用于法院裁定，对天气的推断要用“预测”。"}, {"text": "学校判决了他的入学申请。", "explanation": "这里应该用〈批准〉。“判决”是法院的裁定，学校同意申请要用“批准”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91812, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院明天判决了这个案子。", "corrected_sentence": "法院明天判决这个案子。", "error_description": "错误：“明天”指将来，“判决”后不能加“了”。正确：将来的动作不用“了”，应说“法院明天判决这个案子。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91812, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法院很判决公司赔钱。", "corrected_sentence": "法院公平地判决公司赔钱。", "error_description": "错误：程度副词“很”不能直接修饰动词“判决”。正确：应说“法院公平地判决公司赔钱。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
