INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91813, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在电影院和电视里看的故事和画面。", "primary_collocate": null, "pronunciation": "yǐng shì", "ipa": "iŋ˨˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "影视里的画面特别美。", "target_word": "影视", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我常常用影视学习汉语。", "target_word": "影视", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "影视里的故事常常让我哭。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就爱看影视里的故事。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们喜欢影视里的动画故事。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "影视中的风景让我很想去那里旅行。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说影视里的生活和真实生活不一样。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我常常在家看影视。", "target_word": "影视", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "影视里的英雄总是很勇敢。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢看影视里的故事，不看新闻。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "影視", "label": "繁体"}, {"form": "影视剧", "label": "复合词"}, {"form": "影视作品", "label": "复合词"}], "register": "通用", "sense_fingerprint": "在电影院和电视里看到的故事与画面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea62575-be54-46e7-9a6e-46e7d7867e98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91813, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影视", "is_correct": true, "explanation": "影视：电影和电视的合称，指在电影院和电视里看的故事和画面。"}, {"text": "应试", "is_correct": false, "explanation": "yìng（第四声）与 yǐng（第三声）声调不同，意思是参加考试。"}, {"text": "隐士", "is_correct": false, "explanation": "yǐn 与 yǐng 韵尾不同（n 与 ng），意思是隐居的人。"}, {"text": "影史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是电影的历史。"}, {"text": "硬是", "is_correct": false, "explanation": "yìng（第四声）与 yǐng（第三声）声调不同，意思是确实、竟然。"}], "explanations": {"影视": "影视：电影和电视的合称，指在电影院和电视里看的故事和画面。", "应试": "yìng（第四声）与 yǐng（第三声）声调不同，意思是参加考试。", "隐士": "yǐn 与 yǐng 韵尾不同（n 与 ng），意思是隐居的人。", "影史": "shǐ（第三声）与 shì（第四声）声调不同，意思是电影的历史。", "硬是": "yìng（第四声）与 yǐng（第三声）声调不同，意思是确实、竟然。"}, "sentence_index": null, "correct_answer": "影视"}, "level_3": {"options": [{"text": "影视", "is_correct": true, "explanation": "影视：电影和电视里的故事与画面，可以有美丽的画面，与句意相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道是味觉的感受，没有画面，“味道里的画面”说不通。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“里的画面”一般指影像或景象，声音不能说有画面。"}, {"text": "汗水", "is_correct": false, "explanation": "语义：汗水是身体分泌的液体，没有画面，“汗水里的画面”说不通。"}], "explanations": {"影视": "影视：电影和电视里的故事与画面，可以有美丽的画面，与句意相符。", "味道": "语义：味道是味觉的感受，没有画面，“味道里的画面”说不通。", "声音": "搭配：“里的画面”一般指影像或景象，声音不能说有画面。", "汗水": "语义：汗水是身体分泌的液体，没有画面，“汗水里的画面”说不通。"}, "sentence_index": 0, "correct_answer": "影视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "影视坏了，我得去修一下。", "explanation": "这里应该用〈电视〉。影视指电影和电视作品或行业，不是机器，不会坏；说机器坏了应是“电视坏了”。"}, {"text": "下午三点，我的影视在地上变得很短。", "explanation": "这里应该用〈影子〉。影视指电影和电视作品，地上的黑色投影应说“影子”。"}, {"text": "他从小就爱玩影视，不爱看书。", "explanation": "这里应该用〈游戏〉。玩的是游戏，影视是用来看的，不能说“玩影视”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91813, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影视", "is_correct": true, "explanation": "影视：电影和电视里的故事，“影视里的生活”指作品中的生活，与句意相符。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是工具书，里面没有生活内容，“字典里的生活”说不通。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是书写工具，里面没有可以叫做生活的内容，“铅笔里的生活”说不通。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是气体，没有可以叫做“生活”的内容，句子说不通。"}], "explanations": {"影视": "影视：电影和电视里的故事，“影视里的生活”指作品中的生活，与句意相符。", "字典": "语义：字典是工具书，里面没有生活内容，“字典里的生活”说不通。", "铅笔": "语义：铅笔是书写工具，里面没有可以叫做生活的内容，“铅笔里的生活”说不通。", "空气": "语义：空气是气体，没有可以叫做“生活”的内容，句子说不通。"}, "sentence_index": 6, "correct_answer": "影视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天早上读影视，不看新闻。", "explanation": "这里应该用〈报纸〉。“读”的对象是文字，影视是用来看的作品，不能说“读影视”。"}, {"text": "我喜欢唱影视，不看新闻。", "explanation": "这里应该用〈歌〉。唱的是歌，影视不能用“唱”。"}, {"text": "我们去影视看电影。", "explanation": "这里应该用〈影院〉。影视是电影和电视作品的统称，不是放映电影的地方，去那里看电影应说“去影院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我晚上常常听影视。", "corrected_sentence": "我晚上常常看影视。", "error_description": "搭配错误：影视是用眼睛看的作品，动词应该用“看”，不能说“听影视”，应说“看影视”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我常常在家看一个影视。", "corrected_sentence": "我常常在家看影视。", "error_description": "量词错误：“影视”前不用量词“一个”，应直接说“在家看影视”，不能说“看一个影视”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
