INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91814, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电影和电视的合称。", "primary_collocate": null, "pronunciation": "yǐng shì", "ipa": "iŋ˨˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司专门做影视。", "target_word": "影视", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的大学专业是影视。", "target_word": "影视", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想学影视，以后当导演。", "target_word": "影视", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我哥哥的工作和影视有关。", "target_word": "影视", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在影视行业工作了十年。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是影视界很有名的演员。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "影视行业这几年发展得很快。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市有很多影视公司。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "影视作品要受到观众的欢迎。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "影视和音乐都是他的爱好。", "target_word": "影视", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "影視", "label": "繁体"}, {"form": "影视行业", "label": "复合词"}, {"form": "影视公司", "label": "复合词"}], "register": "通用", "sense_fingerprint": "电影和电视这一行业或领域的合称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea62575-be54-46e7-9a6e-46e7d7867e98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91814, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "影视", "is_correct": true, "explanation": "影视：电影和电视的合称，这里指电影和电视这一行业或领域。"}, {"text": "应试", "is_correct": false, "explanation": "yìng（第四声）与 yǐng（第三声）声调不同，意思是参加考试。"}, {"text": "隐士", "is_correct": false, "explanation": "yǐn 与 yǐng 韵尾不同（n 与 ng），意思是隐居的人。"}, {"text": "影史", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是电影的历史。"}, {"text": "硬是", "is_correct": false, "explanation": "yìng（第四声）与 yǐng（第三声）声调不同，意思是确实、竟然。"}], "explanations": {"影视": "影视：电影和电视的合称，这里指电影和电视这一行业或领域。", "应试": "yìng（第四声）与 yǐng（第三声）声调不同，意思是参加考试。", "隐士": "yǐn 与 yǐng 韵尾不同（n 与 ng），意思是隐居的人。", "影史": "shǐ（第三声）与 shì（第四声）声调不同，意思是电影的历史。", "硬是": "yìng（第四声）与 yǐng（第三声）声调不同，意思是确实、竟然。"}, "sentence_index": null, "correct_answer": "影视"}, "level_3": {"options": [{"text": "影视", "is_correct": true, "explanation": "影视：电影和电视这一行业，公司可以专门做，与句意相符。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是生理活动，不是公司可以“专门做”的事，句子说不通。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“做”一般搭配作品或产品，“噪音”通常说“制造”，不说“专门做噪音”。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不是公司可以“专门做”的东西，句子说不通。"}], "explanations": {"影视": "影视：电影和电视这一行业，公司可以专门做，与句意相符。", "呼吸": "语义：呼吸是生理活动，不是公司可以“专门做”的事，句子说不通。", "噪音": "搭配：“做”一般搭配作品或产品，“噪音”通常说“制造”，不说“专门做噪音”。", "雨": "语义：雨是天气现象，不是公司可以“专门做”的东西，句子说不通。"}, "sentence_index": 0, "correct_answer": "影视"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我哥哥每天骑车去影视上班。", "explanation": "这里应该用〈影视城〉。影视是电影和电视的统称，不是地方，去某处上班应说“去影视城”。"}, {"text": "我哥哥是影视。", "explanation": "这里应该用〈导演〉。影视是电影和电视的合称，不是人的身份，人不能“是影视”。"}, {"text": "我哥哥的工作地址在影视。", "explanation": "这里应该用〈片场〉。影视是电影和电视的统称，不是地址；工作地点应是具体的片场或公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91814, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "影视", "is_correct": true, "explanation": "影视：电影和电视这一行业，可以说“影视行业”，与句意相符。"}, {"text": "儿子", "is_correct": false, "explanation": "搭配：“××行业”的修饰词要是行业或领域，人不能修饰行业。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不是行业，“老虎行业”说不通。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星是天体，不是行业，“星星行业”说不通。"}], "explanations": {"影视": "影视：电影和电视这一行业，可以说“影视行业”，与句意相符。", "儿子": "搭配：“××行业”的修饰词要是行业或领域，人不能修饰行业。", "老虎": "语义：老虎是动物，不是行业，“老虎行业”说不通。", "星星": "语义：星星是天体，不是行业，“星星行业”说不通。"}, "sentence_index": 6, "correct_answer": "影视"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "影视和音乐都是他的老板。", "explanation": "这里应该用〈爱好〉。影视是作品或行业的统称，不是能管人的人，这里说的是兴趣。"}, {"text": "他每天都去影视买点心。", "explanation": "这里应该用〈超市〉。影视是电影和电视的统称，不是卖东西的地方，买点心应去超市或商店。"}, {"text": "他的影视比我还高一个头。", "explanation": "这里应该用〈哥哥〉。影视是行业的统称，不是人，不能说“比我还高一个头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91814, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把影视是专业。", "corrected_sentence": "他把影视当作专业。", "error_description": "动词错误：“把影视”后应用动词“当作”，不能用“是”。应说“他把影视当作专业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91814, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跟影视很感兴趣。", "corrected_sentence": "他对影视很感兴趣。", "error_description": "介词错误：“感兴趣”的对象应用“对”引出，说“对影视很感兴趣”，不能用“跟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
