INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91815, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到此是来到这个地方。", "primary_collocate": null, "pronunciation": "dào cǐ", "ipa": "tau⁵¹ tsʰɨ²¹⁴", "syllable_count": 2, "sentences": [{"text": "游客到此，都要先拍一张照片。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人到此，都会去湖边走一走。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天到此，今天就去工作了。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次到此，什么都觉得新鲜。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人到此，请先在门口登记。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，他年轻时曾到此考察过三次。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问您是什么时候到此的？", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友到此后，先给我打了电话。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从北京坐火车到此，要五个小时。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无论是谁，到此都会爱上这座小城。", "target_word": "到此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "到此一游", "label": "复合"}, {"form": "到此为止", "label": "复合"}], "register": "书面", "sense_fingerprint": "来到这个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1253fbc-9288-40c9-a9b1-e95e77d08214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91815, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到此", "is_correct": true, "explanation": "正确：到此即到达这里，符合游客来到景点的语境。"}, {"text": "到期", "is_correct": false, "explanation": "语义：到期多指票、合同等期限，不用来形容游客。"}, {"text": "散场", "is_correct": false, "explanation": "语义：散场指活动结束后离场，与“先拍一张照片”的入场要求矛盾。"}, {"text": "驶入", "is_correct": false, "explanation": "搭配：驶入多用于车辆，不说“游客驶入”。"}], "explanations": {"到此": "正确：到此即到达这里，符合游客来到景点的语境。", "到期": "语义：到期多指票、合同等期限，不用来形容游客。", "散场": "语义：散场指活动结束后离场，与“先拍一张照片”的入场要求矛盾。", "驶入": "搭配：驶入多用于车辆，不说“游客驶入”。"}, "sentence_index": 0, "correct_answer": "到此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们到此北京，就去吃烤鸭了。", "explanation": "语法：“到此”是不及物动词，不能直接带处所宾语“北京”，应说“到北京”。"}, {"text": "他们到此上海，就给家里打了电话。", "explanation": "语法：“到此”不能直接带处所宾语“上海”，应说“到上海”。"}, {"text": "妈妈到此厨房，就开始做饭了。", "explanation": "语法：“到此”不能直接带处所宾语“厨房”，应说“到厨房”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91815, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到此", "is_correct": true, "explanation": "正确：“到此的”即到达这里的，用来询问对方到达的时间，符合语境。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：倒塌指房屋、墙等倒下，不能用来问人。"}, {"text": "掉落", "is_correct": false, "explanation": "语义：掉落指物体落下，不指人。"}, {"text": "驶离", "is_correct": false, "explanation": "搭配：驶离多用于车辆，不对人说“驶离的”。"}], "explanations": {"到此": "正确：“到此的”即到达这里的，用来询问对方到达的时间，符合语境。", "倒塌": "语义：倒塌指房屋、墙等倒下，不能用来问人。", "掉落": "语义：掉落指物体落下，不指人。", "驶离": "搭配：驶离多用于车辆，不对人说“驶离的”。"}, "sentence_index": 6, "correct_answer": "到此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板到此公司，就开始开会。", "explanation": "语法：“到此”不能直接带处所宾语“公司”，应说“到公司”。"}, {"text": "他们到此火车站，又坐车回家了。", "explanation": "语法：“到此”不能直接带处所宾语“火车站”，应说“到火车站”。"}, {"text": "朋友到此了我的房间，很高兴。", "explanation": "语法：“到此”不能带宾语“我的房间”，应说“到我的房间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旅客到此机场，请先出示护照。", "corrected_sentence": "旅客到此，请先出示护照。", "error_description": "宾语错误：“到此”是不及物动词，后面不能直接带处所宾语“机场”。正确说法：旅客到此，请先出示护照。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家到此火车站，都累得坐了下来。", "corrected_sentence": "大家到此，都累得坐了下来。", "error_description": "宾语错误：“到此”是不及物动词，后面不能直接带处所宾语“火车站”。正确说法：大家到此，都累得坐了下来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
