INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91817, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91817, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "比别人晚学的人，也是有礼貌的自称。", "primary_collocate": null, "pronunciation": "hòu xué", "ipa": "xou˥˩ ɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "在下是后学，请前辈多多指教。", "target_word": "后学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是一个后学，不敢在老师面前乱说。", "target_word": "后学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们这行的后学，学得比我们晚。", "target_word": "后学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前辈对后学总是很耐心。", "target_word": "后学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "后学今天来拜访您，想请教几个问题。", "target_word": "后学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人常常帮助年轻的后学。", "target_word": "后学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为后学，我要向各位前辈好好学习。", "target_word": "后学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自称后学，说话非常客气。", "target_word": "后学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我学画画比你们晚，只能算后学。", "target_word": "后学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老先生把自己的经验都告诉了后学。", "target_word": "后学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "後學", "label": "繁体"}], "register": "书面", "sense_fingerprint": "学得比别人晚的人；谦称自己", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '501e030f-9419-4045-ab4d-0d12862286c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91817, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后学", "is_correct": true, "explanation": "“后学”指学得比别人晚的人，也是谦称，与后半句“请前辈多多指教”相符。"}, {"text": "前辈", "is_correct": false, "explanation": "语义：自称“前辈”与后半句的“请前辈指教”自相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能用“在下”自称，也不能请前辈指教，句意荒谬。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能用“在下”自称，也无法请前辈指教，句意荒谬。"}], "explanations": {"后学": "“后学”指学得比别人晚的人，也是谦称，与后半句“请前辈多多指教”相符。", "前辈": "语义：自称“前辈”与后半句的“请前辈指教”自相矛盾。", "桌子": "语义：桌子不能用“在下”自称，也不能请前辈指教，句意荒谬。", "石头": "语义：石头不能用“在下”自称，也无法请前辈指教，句意荒谬。"}, "sentence_index": 0, "correct_answer": "后学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学院来了一只后学。", "explanation": "量词错误。这里应该用〈位〉：“一位后学”。“只”用于动物，不能用来数人。"}, {"text": "他是我们的后学，学得比我们早。", "explanation": "这里应该用〈前辈〉。“后学”指比别人晚学的人；这句说他学得比我们早，与词义矛盾。"}, {"text": "老先生是我的后学，他教了我很多东西。", "explanation": "这里应该用〈老师〉。“后学”指比别人晚学的人，老先生曾经教过我，不能称他为后学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91817, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后学", "is_correct": true, "explanation": "“后学”表示谦卑的晚辈，与“我要向前辈学习”的身份相符。"}, {"text": "老人", "is_correct": false, "explanation": "语义：说“作为老人”向前辈学习，身份与句意冲突。"}, {"text": "长辈", "is_correct": false, "explanation": "语义：“长辈”指辈分高、年长的人，自称长辈却要向前辈学习，身份与句意矛盾。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客与学习无关，不能作为“我要向前辈学习”的身份。"}], "explanations": {"后学": "“后学”表示谦卑的晚辈，与“我要向前辈学习”的身份相符。", "老人": "语义：说“作为老人”向前辈学习，身份与句意冲突。", "长辈": "语义：“长辈”指辈分高、年长的人，自称长辈却要向前辈学习，身份与句意矛盾。", "乘客": "语义：乘客与学习无关，不能作为“我要向前辈学习”的身份。"}, "sentence_index": 6, "correct_answer": "后学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口站着一棵后学。", "explanation": "量词错误。“棵”用于植物，“后学”指人，这里应该用〈位〉：“一位后学”。"}, {"text": "我的后学比我早三年毕业，常常给我建议。", "explanation": "这里应该用〈学长〉。“后学”指学得比别人晚的人，与“早三年毕业”矛盾。"}, {"text": "孔子是我们的后学。", "explanation": "这里应该用〈前辈〉。“后学”指比别人晚学的人；孔子生活的时代早于我们，应称他为前辈，不能说是后学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91817, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我只是只后学，请各位多指教。", "corrected_sentence": "我只是个后学，请各位多指教。", "error_description": "量词错误：“后学”指人，这里误用了“只”（动物量词），应说“个后学”或“位后学”，不说“只后学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91817, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "作为一条后学，我要向前辈学习。", "corrected_sentence": "作为一名后学，我要向前辈学习。", "error_description": "量词错误：“后学”指人，应用“名”，这里误用了“条”（长条状事物的量词），不能说“一条后学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
