INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91820, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示由前面所说的情况而造成某种结果，多指不好的结果。", "primary_collocate": null, "pronunciation": "yǐ zhì", "ipa": "i˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他不听大家的话，以致犯了大错。", "target_word": "以致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，以致我们迟到了。", "target_word": "以致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直不运动，以致身体越来越差。", "target_word": "以致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没带钥匙，以致进不了家门。", "target_word": "以致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲得太快，以致很多学生没听懂。", "target_word": "以致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骗了朋友很多次，以致没人再相信他。", "target_word": "以致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器没有人检查，以致出了事故。", "target_word": "以致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱说话，以致没有什么朋友。", "target_word": "以致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说得不清楚，以致病人吃错了药。", "target_word": "以致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花钱太多，以致月底没钱吃饭。", "target_word": "以致", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "以致于", "label": "复合"}], "register": "书面", "sense_fingerprint": "前面的情况造成后面多为不好的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99fe3606-75b6-4d45-9eb3-6ab141772d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91820, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "以致", "is_correct": true, "explanation": "正确：“以致”（yǐzhì）是连词，表示由前面的情况造成某种结果。"}, {"text": "一致", "is_correct": false, "explanation": "yízhì（第二声）与 yǐzhì（第三声）声调不同，意思是“一致”。"}, {"text": "意志", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，yìzhì 意思是“意志”。"}, {"text": "已知", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，yǐzhī 意思是“已知”。"}, {"text": "一直", "is_correct": false, "explanation": "yì 与 yǐ、zhí 与 zhì 声调都不同，yìzhí 意思是“一直”。"}, {"text": "遗址", "is_correct": false, "explanation": "yí 与 yǐ、zhǐ 与 zhì 声调都不同，yízhǐ 意思是“遗址”。"}], "explanations": {"以致": "正确：“以致”（yǐzhì）是连词，表示由前面的情况造成某种结果。", "一致": "yízhì（第二声）与 yǐzhì（第三声）声调不同，意思是“一致”。", "意志": "yì（第四声）与 yǐ（第三声）声调不同，yìzhì 意思是“意志”。", "已知": "zhī（第一声）与 zhì（第四声）声调不同，yǐzhī 意思是“已知”。", "一直": "yì 与 yǐ、zhí 与 zhì 声调都不同，yìzhí 意思是“一直”。", "遗址": "yí 与 yǐ、zhǐ 与 zhì 声调都不同，yízhǐ 意思是“遗址”。"}, "sentence_index": null, "correct_answer": "以致"}, "level_3": {"options": [{"text": "以致", "is_correct": true, "explanation": "正确：“以致”引出由“不听大家的话”造成的不好结果“犯了大错”。"}, {"text": "以便", "is_correct": false, "explanation": "语义：“以便”表示目的，“犯了大错”不是目的，不能用目的连词。"}, {"text": "尽管", "is_correct": false, "explanation": "搭配：“尽管”表示让步，需与“但/却”呼应，句中没有，且与因果不合。"}, {"text": "以免", "is_correct": false, "explanation": "语义：“以免”表示为了避免某种后果，而“犯了大错”已经发生，不能用“以免”。"}], "explanations": {"以致": "正确：“以致”引出由“不听大家的话”造成的不好结果“犯了大错”。", "以便": "语义：“以便”表示目的，“犯了大错”不是目的，不能用目的连词。", "尽管": "搭配：“尽管”表示让步，需与“但/却”呼应，句中没有，且与因果不合。", "以免": "语义：“以免”表示为了避免某种后果，而“犯了大错”已经发生，不能用“以免”。"}, "sentence_index": 0, "correct_answer": "以致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很努力，以致请大家祝贺他。", "explanation": "这里后一分句是请求语气，不是前因造成的结果，“以致”不能引出它。"}, {"text": "他考上了大学，以致他很努力学习。", "explanation": "这里因果颠倒：“以致”引出的是由前面原因造成的结果，“考上大学”不会导致“很努力学习”。"}, {"text": "以致他没带钥匙，但还是进了家门。", "explanation": "这里应该用〈虽然〉，并与后面的“但”呼应。“以致”引出结果，不能表示让步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91820, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "以致", "is_correct": true, "explanation": "正确：“以致”（yǐzhì）是连词，表示由前面的情况造成某种结果。"}, {"text": "抑制", "is_correct": false, "explanation": "yìzhì 中 yì（第四声）与 yǐ（第三声）声调不同，意思是“抑制”。"}, {"text": "一只", "is_correct": false, "explanation": "yìzhī 的两个音节声调都与 yǐzhì 不同，意思是“一只”。"}, {"text": "一纸", "is_correct": false, "explanation": "yìzhǐ 中 yì 与 yǐ、zhǐ 与 zhì 声调都不同，意思是“一纸”。"}, {"text": "益智", "is_correct": false, "explanation": "yì（第四声）与 yǐ（第三声）声调不同，yìzhì 意思是“益智”。"}], "explanations": {"以致": "正确：“以致”（yǐzhì）是连词，表示由前面的情况造成某种结果。", "抑制": "yìzhì 中 yì（第四声）与 yǐ（第三声）声调不同，意思是“抑制”。", "一只": "yìzhī 的两个音节声调都与 yǐzhì 不同，意思是“一只”。", "一纸": "yìzhǐ 中 yì 与 yǐ、zhǐ 与 zhì 声调都不同，意思是“一纸”。", "益智": "yì（第四声）与 yǐ（第三声）声调不同，yìzhì 意思是“益智”。"}, "sentence_index": null, "correct_answer": "以致"}, "level_3": {"options": [{"text": "以致", "is_correct": true, "explanation": "正确：“以致”引出因“机器没有人检查”造成的结果“出了事故”。"}, {"text": "如果", "is_correct": false, "explanation": "语义：“如果”引出假设，而“出了事故”是已经发生的事，不能假设。"}, {"text": "即使", "is_correct": false, "explanation": "搭配：“即使”要与“也/还”呼应，这里没有，句子不完整。"}, {"text": "倘若", "is_correct": false, "explanation": "语义：“倘若”同样表示假设，与已经发生的“出了事故”不合。"}], "explanations": {"以致": "正确：“以致”引出因“机器没有人检查”造成的结果“出了事故”。", "如果": "语义：“如果”引出假设，而“出了事故”是已经发生的事，不能假设。", "即使": "搭配：“即使”要与“也/还”呼应，这里没有，句子不完整。", "倘若": "语义：“倘若”同样表示假设，与已经发生的“出了事故”不合。"}, "sentence_index": 6, "correct_answer": "以致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他进了场，以致先买了票。", "explanation": "这里因果颠倒：“以致”引出的结果应在后面，“进场”不能导致“先买票”。"}, {"text": "以致你不来，我们就出发。", "explanation": "这里应该用〈如果〉。“以致”引出结果，不能引出假设条件。"}, {"text": "以致天气怎么样，我们都去。", "explanation": "这里应该用〈不管〉。“以致”引出结果，不能表示无条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91820, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气不好，很以致航班取消了。", "corrected_sentence": "天气不好，以致航班取消了。", "error_description": "程度副词误用：“以致”是连词，不能受“很”修饰，应删去“很”，改为“天气不好，以致航班取消了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91820, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作太多，以致了身体不舒服。", "corrected_sentence": "工作太多，以致身体不舒服。", "error_description": "“了”的误用：“以致”是连词，后面不能加“了”，应删去“了”，改为“工作太多，以致身体不舒服。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
