INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91823, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从这些东西里面。", "primary_collocate": null, "pronunciation": "cóng zhōng", "ipa": "tsʰʊŋ˧˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这里有三本书，你可以从中选一本。", "target_word": "从中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "盒子里有很多糖，他从中拿了两块。", "target_word": "从中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请从中挑出你最喜欢的一张照片。", "target_word": "从中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给了我们五个题目，让我们从中选一个。", "target_word": "从中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些衣服都很好看，你从中挑一件吧。", "target_word": "从中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌上有几支笔，我从中拿了一支红的。", "target_word": "从中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上有很多故事书，她从中找到了一本。", "target_word": "从中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这十个人里，老师要从中选出两个。", "target_word": "从中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜单上有二十道菜，我们从中点了四道。", "target_word": "从中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一堆石头，他从中捡起最小的一块。", "target_word": "从中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "從中", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从中：从前面提到的一些东西里面（挑选、拿取）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91823, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突然", "is_correct": false, "explanation": "语义：“突然”指意外发生的事，与“你可以选”所表达的许可意思不符。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示碰巧，与“你可以选”的主动选择意义冲突。"}, {"text": "很", "is_correct": false, "explanation": "程度副词：“很”不能修饰“选”这类动作动词，句子不通。"}, {"text": "从中", "is_correct": true, "explanation": "从中表示从前面提到的几样东西里面挑选，与“你可以选一本”搭配。"}], "explanations": {"突然": "语义：“突然”指意外发生的事，与“你可以选”所表达的许可意思不符。", "恰好": "语义：“恰好”表示碰巧，与“你可以选”的主动选择意义冲突。", "很": "程度副词：“很”不能修饰“选”这类动作动词，句子不通。", "从中": "从中表示从前面提到的几样东西里面挑选，与“你可以选一本”搭配。"}, "sentence_index": 0, "correct_answer": "从中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天黑了，他从中开了灯。", "explanation": "这里应该用〈就〉。从中只表示从几样东西里挑选，不能表示紧接着发生的动作。"}, {"text": "我写完作业，从中看了会儿电视。", "explanation": "这里应该用〈然后〉。从中只表示从几样东西里挑选，不能表示动作的先后。"}, {"text": "老师讲完课，从中布置了作业。", "explanation": "这里应该用〈接着〉。从中只表示从某些东西里挑选，不能表示动作的先后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91823, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳无功，与“找到了一本”的成功结果相矛盾。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”需要多人共同行动，“她”一个人找到一本书不搭。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“不断”指持续反复，与“找到了一本”这一次的结果不符。"}, {"text": "从中", "is_correct": true, "explanation": "从中表示从书架上的很多故事书里挑选，与“找到了一本”搭配。"}], "explanations": {"白白": "语义：“白白”表示徒劳无功，与“找到了一本”的成功结果相矛盾。", "一起": "搭配：“一起”需要多人共同行动，“她”一个人找到一本书不搭。", "不断": "语义：“不断”指持续反复，与“找到了一本”这一次的结果不符。", "从中": "从中表示从书架上的很多故事书里挑选，与“找到了一本”搭配。"}, "sentence_index": 6, "correct_answer": "从中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨了，我们从中没去公园。", "explanation": "这里应该用〈因此〉。从中表示从几样东西里挑选，不表示因果关系。"}, {"text": "他很累，从中躺下睡觉了。", "explanation": "这里应该用〈于是〉。从中只表示从几样东西里挑选，不能表示因果或动作的先后。"}, {"text": "他听完建议，从中回家了。", "explanation": "这里应该用〈于是〉。从中不能表示动作的先后或结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91823, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从中了挑出最好的一个。", "corrected_sentence": "他从中挑出最好的一个。", "error_description": "错误：“从中”是副词，直接修饰动词，中间不能加“了”。正确说法是“他从中挑出最好的一个。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91823, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从中的挑了一本书。", "corrected_sentence": "她从中挑了一本书。", "error_description": "错误：“从中”是副词，直接修饰动词，中间不能加“的”。正确说法是“她从中挑了一本书。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
