INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91824, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从其中；在事情当中。", "primary_collocate": null, "pronunciation": "cóng zhōng", "ipa": "tsʰʊŋ˧˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "我们能从中学到很多东西。", "target_word": "从中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从中得到了很大的快乐。", "target_word": "从中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛很难，但我从中学会了坚持。", "target_word": "从中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作虽然累，她却从中找到了乐趣。", "target_word": "从中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次失败，你都要从中找出原因。", "target_word": "从中", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行很有意思，我从中认识了不少朋友。", "target_word": "从中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事让他很难过，但他从中明白了很多。", "target_word": "从中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做生意十年，从中积累了不少经验。", "target_word": "从中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书不只是为了考试，也能从中得到安慰。", "target_word": "从中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误不大，你可以从中吸取教训。", "target_word": "从中", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "從中", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从中：从前面所说的事情当中（学到、得到、发现）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳，与“学到很多东西”的收获意思相矛盾。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指突发的一次事件，与“能学到很多东西”所说的长期收获不符。"}, {"text": "竟然", "is_correct": false, "explanation": "语序：“竟然”应放在“能”之前，放在“能”之后语序不通。"}, {"text": "从中", "is_correct": true, "explanation": "从中表示在某件事情当中获得，与“能学到很多东西”搭配。"}], "explanations": {"白白": "语义：“白白”表示徒劳，与“学到很多东西”的收获意思相矛盾。", "突然": "语义：“突然”指突发的一次事件，与“能学到很多东西”所说的长期收获不符。", "竟然": "语序：“竟然”应放在“能”之前，放在“能”之后语序不通。", "从中": "从中表示在某件事情当中获得，与“能学到很多东西”搭配。"}, "sentence_index": 0, "correct_answer": "从中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他生病了，从中没来上课。", "explanation": "这里应该用〈所以〉。从中只表示“从其中”或“在事情当中”，不能表示因果关系。"}, {"text": "他吃完饭，从中去散步了。", "explanation": "这里应该用〈然后〉。从中不能表示动作的先后顺序。"}, {"text": "天气不好，从中我们没出门。", "explanation": "这里应该用〈因此〉。从中不能表示因果关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一起", "is_correct": false, "explanation": "搭配：“一起”需要多人共同行动，“他”一个人领悟不搭。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“不断”指持续反复，与“明白了很多”这种一次性的领悟不符。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中的动作，与表示结果的“明白了”不搭。"}, {"text": "从中", "is_correct": true, "explanation": "从中表示在这件事当中，与“但他明白了很多”搭配，说明他从经历中获得了领悟。"}], "explanations": {"一起": "搭配：“一起”需要多人共同行动，“他”一个人领悟不搭。", "不断": "语义：“不断”指持续反复，与“明白了很多”这种一次性的领悟不符。", "正在": "体貌：“正在”表示进行中的动作，与表示结果的“明白了”不搭。", "从中": "从中表示在这件事当中，与“但他明白了很多”搭配，说明他从经历中获得了领悟。"}, "sentence_index": 6, "correct_answer": "从中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她起晚了，从中没赶上公交车。", "explanation": "这里应该用〈结果〉。从中只表示“从其中”或“在事情当中”，不能表示结果。"}, {"text": "他很高兴，从中哭了起来。", "explanation": "这里应该用〈忽然〉。从中不能表示突然发生的动作或情绪变化，“从中”只表示“从其中”或“在事情当中”。"}, {"text": "他已经从中睡了三个小时。", "explanation": "这里应该用〈整整〉。从中不能表示时间的长度，这里说的是持续的时间，应用“整整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我从中的明白了一个道理。", "corrected_sentence": "我从中明白了一个道理。", "error_description": "错误：“从中”是副词，直接修饰动词，中间不能加“的”。正确说法是“我从中明白了一个道理。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你可以从中了吸取教训。", "corrected_sentence": "你可以从中吸取教训。", "error_description": "错误：“从中”是副词，直接修饰动词，后面不能加“了”。去掉“了”，应说“你可以从中吸取教训。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
