INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91826, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，什么地方。", "primary_collocate": null, "pronunciation": "hé chù", "ipa": "xɤ˧˥ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "这条路通向何处？", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想知道钱花在了何处。", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑了，我们今晚住在何处？", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看到我的手机放在何处了吗？", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小鸟飞向何处了？", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我，车站在何处。", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河水从何处来？", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她问我，书包落在了何处。", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很累，却不知何处能坐。", "target_word": "何处", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都在找他，不知他在何处。", "target_word": "何处", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "何處", "label": "繁体"}], "register": "书面", "sense_fingerprint": "何处：疑问代词，指什么地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4c1239-4184-41d0-a500-af91482a0938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "何处", "is_correct": true, "explanation": "正确。“何处”问地方，与“这条路通向……”的去向相符。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问人，与路的去向不符。"}, {"text": "何时", "is_correct": false, "explanation": "配价：“通向”的宾语需是地点或去向，“何时”表示时间，不能作宾语。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样”问方式或状况，不能问路通往哪里。"}], "explanations": {"何处": "正确。“何处”问地方，与“这条路通向……”的去向相符。", "谁": "语义：“谁”问人，与路的去向不符。", "何时": "配价：“通向”的宾语需是地点或去向，“何时”表示时间，不能作宾语。", "怎样": "语义：“怎样”问方式或状况，不能问路通往哪里。"}, "sentence_index": 0, "correct_answer": "何处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的钥匙就在何处。", "explanation": "这里应该用〈这里〉。何处是疑问代词，只用于提问，不能用来陈述说话人已知的地方。"}, {"text": "这家店就开在何处。", "explanation": "这里应该用〈这儿〉。何处只用于疑问，陈述已知地点时不能用它。"}, {"text": "我喜欢住在何处的小房子。", "explanation": "这里应该用〈那里〉。何处表示疑问，描述确定的地方时要用“那里”之类的指示词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "何处", "is_correct": true, "explanation": "正确。“何处”问地方，与“河水从……来”问来源相符。"}, {"text": "何人", "is_correct": false, "explanation": "语义：“何人”问人，不能问河水从哪里来。"}, {"text": "如何", "is_correct": false, "explanation": "语义：“如何”问方式，不能问河水的来源。"}, {"text": "何事", "is_correct": false, "explanation": "语义：“何事”问事情，不能问河水的来源。"}], "explanations": {"何处": "正确。“何处”问地方，与“河水从……来”问来源相符。", "何人": "语义：“何人”问人，不能问河水从哪里来。", "如何": "语义：“如何”问方式，不能问河水的来源。", "何事": "语义：“何事”问事情，不能问河水的来源。"}, "sentence_index": 6, "correct_answer": "何处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你买的是何处？", "explanation": "这里应该用〈什么〉。“何处”只问地点，问买的东西要用“什么”。"}, {"text": "这个箱子何处重？", "explanation": "这里应该用〈多重〉。“何处”只问地点，问重量要用“多重”。"}, {"text": "你何处这么生气？", "explanation": "这里应该用〈为什么〉。“何处”问地点，问原因要用“为什么”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个车站何处？", "corrected_sentence": "这个车站在何处？", "error_description": "错误形式：“这个车站何处？”；正确形式：“这个车站在何处？”。问处所时，“何处”前需要有谓语动词（如“在”“通向”“去”）引出，句中缺少动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不记得伞放去何处了。", "corrected_sentence": "我不记得伞放在何处了。", "error_description": "错误形式：“放去何处”；正确形式：“放在何处”。“放”表示存放，其后引出处所要用“在”（或“到”），不能用“去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
