INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91827, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取代是把旧的拿走，换成新的。", "primary_collocate": null, "pronunciation": "qǔ dài", "ipa": "tɕʰy˨˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我们用新电脑取代了旧电脑。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想用新办法取代旧办法。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用新零件取代了坏零件。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的菜单取代了去年的菜单。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用新书取代了旧课本。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板打算用新车取代这辆旧车。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张新照片取代了墙上的旧照片。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用新密码取代原来的密码。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧灯坏了，我想买新灯取代它。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定取代了以前的老规定。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "取代了", "label": "完成体"}, {"form": "取代过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "用新的东西换掉旧的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0682de28-216e-408a-8dda-edcb161f2d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91827, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取代", "is_correct": true, "explanation": "取代：新电脑换掉了旧电脑，符合句意。"}, {"text": "购买", "is_correct": false, "explanation": "语义：「购买」是花钱买东西，与用新电脑换掉旧电脑不符。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：「喜欢」表示心里有好感，不能表示替换旧东西。"}, {"text": "送给", "is_correct": false, "explanation": "搭配：「送给」的对象应是人，不能说送给旧电脑。"}], "explanations": {"取代": "取代：新电脑换掉了旧电脑，符合句意。", "购买": "语义：「购买」是花钱买东西，与用新电脑换掉旧电脑不符。", "喜欢": "语义：「喜欢」表示心里有好感，不能表示替换旧东西。", "送给": "搭配：「送给」的对象应是人，不能说送给旧电脑。"}, "sentence_index": 0, "correct_answer": "取代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去银行取代了一百块钱。", "explanation": "这里应该用〈取〉。〈取代〉指用新的换掉旧的，取钱要用〈取〉。"}, {"text": "桌子上取代了一盘水果。", "explanation": "这里应该用〈摆〉。〈取代〉要有被换掉的旧事物，桌上并没有东西被替换，应该用〈摆〉。"}, {"text": "用胶水取代了裂缝。", "explanation": "这里应该用〈填补〉。〈取代〉的对象是被换掉的事物，修补裂缝要用〈填补〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91827, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取代", "is_correct": true, "explanation": "取代：新照片换掉了墙上的旧照片，符合句意。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：「欢迎」是迎接客人或事物到来，不能表示用新照片换掉旧照片。"}, {"text": "寄", "is_correct": false, "explanation": "配价：「寄」需要收件人作宾语，句中没有收件人，且不表示替换。"}, {"text": "出售", "is_correct": false, "explanation": "搭配：「出售」指卖掉东西，不能用于照片被替换的情况。"}], "explanations": {"取代": "取代：新照片换掉了墙上的旧照片，符合句意。", "欢迎": "语义：「欢迎」是迎接客人或事物到来，不能表示用新照片换掉旧照片。", "寄": "配价：「寄」需要收件人作宾语，句中没有收件人，且不表示替换。", "出售": "搭配：「出售」指卖掉东西，不能用于照片被替换的情况。"}, "sentence_index": 6, "correct_answer": "取代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们取代了一次事故。", "explanation": "这里应该用〈避免〉。〈取代〉要替换掉一个已有的旧事物，事故不能被换掉，应该用〈避免〉。"}, {"text": "她取代了一场大雨。", "explanation": "这里应该用〈躲避〉。〈取代〉不能用于大雨，躲开大雨要用〈躲避〉。"}, {"text": "爸爸取代了一个电话。", "explanation": "这里应该用〈接〉。〈取代〉要替换掉旧事物，接电话要用〈接〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91827, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司被新系统取代了旧系统。", "corrected_sentence": "公司用新系统取代了旧系统。", "error_description": "「被」字句错误：「用」改成「被」后，「取代」后面不能再带宾语「旧系统」。应说「公司用新系统取代了旧系统」，或「旧系统被新系统取代了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91827, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张新地图没有取代了旧地图。", "corrected_sentence": "这张新地图没有取代旧地图。", "error_description": "「了」错误：表示否定的「没有」不能与「了」同用，「取代」后不能加「了」。应说「没有取代旧地图」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
