INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91828, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "排挤掉别人或别的事物而占据其位置。", "primary_collocate": null, "pronunciation": "qǔ dài", "ipa": "tɕʰy˨˩ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "手机取代了很多人的闹钟。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的经理取代了老张的位置。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电子书会取代纸质书吗？", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人正在取代工厂里的工人。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上购物取代了很多小商店。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个年轻人想取代他成为队长。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车取代了马车，成为主要交通工具。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没能取代哥哥，当上总经理。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人能取代妈妈在我心里的位置。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微信取代了短信，大家很少发短信了。", "target_word": "取代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "取代了", "label": "完成体"}, {"form": "取代过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "排挤别人或别的事物并占据其位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0682de28-216e-408a-8dda-edcb161f2d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91828, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取代", "is_correct": true, "explanation": "取代：手机排挤并占据了闹钟的位置，符合句意。"}, {"text": "购买", "is_correct": false, "explanation": "语义：「购买」是花钱买东西，与手机占据闹钟位置的意思不符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：「修理」是把坏东西弄好，不能表示占据闹钟的位置。"}, {"text": "送给", "is_correct": false, "explanation": "搭配：「送给」的对象应是人，闹钟不能作为送给的对象。"}], "explanations": {"取代": "取代：手机排挤并占据了闹钟的位置，符合句意。", "购买": "语义：「购买」是花钱买东西，与手机占据闹钟位置的意思不符。", "修理": "语义：「修理」是把坏东西弄好，不能表示占据闹钟的位置。", "送给": "搭配：「送给」的对象应是人，闹钟不能作为送给的对象。"}, "sentence_index": 0, "correct_answer": "取代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天取代牙膏刷牙。", "explanation": "这里应该用〈用〉。〈取代〉指占据别人或别的事物的位置，刷牙只是使用牙膏，应该用〈用〉。"}, {"text": "他取代了一杯咖啡。", "explanation": "这里应该用〈喝〉。〈取代〉不能表示喝东西，喝咖啡要用〈喝〉。"}, {"text": "他取代了那笔钱。", "explanation": "这里应该用〈付〉。〈取代〉不能表示付钱，付钱要用〈付〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取代", "is_correct": true, "explanation": "取代：汽车排挤并占据了马车的位置，成为主要交通工具，符合句意。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：「欢迎」是迎接人或事物到来，不能表示汽车占据马车的位置。"}, {"text": "出售", "is_correct": false, "explanation": "搭配：「出售」指卖东西，汽车与马车之间没有买卖关系。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」是取笑别人，与句中「成为主要交通工具」的意思不符。"}], "explanations": {"取代": "取代：汽车排挤并占据了马车的位置，成为主要交通工具，符合句意。", "欢迎": "语义：「欢迎」是迎接人或事物到来，不能表示汽车占据马车的位置。", "出售": "搭配：「出售」指卖东西，汽车与马车之间没有买卖关系。", "嘲笑": "语义：「嘲笑」是取笑别人，与句中「成为主要交通工具」的意思不符。"}, "sentence_index": 6, "correct_answer": "取代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上取代着一幅画。", "explanation": "这里应该用〈挂〉。墙上挂画要用〈挂〉，〈取代〉指排挤别的事物并占据它的位置，这里说不通。"}, {"text": "她取代了一件红衣服。", "explanation": "这里应该用〈穿〉。穿衣服要用〈穿〉，〈取代〉不能用于穿衣。"}, {"text": "她取代了一首歌。", "explanation": "这里应该用〈唱〉。唱歌要用〈唱〉，〈取代〉不能表示唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新来的主任被取代了老李的位置。", "corrected_sentence": "新来的主任取代了老李的位置。", "error_description": "「被」字句错误：「新来的主任」是取代的一方，不能用「被」字句表示被取代；且「被」字句中「取代」后不能再带宾语「老李的位置」。应说「新来的主任取代了老李的位置」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个年轻人没有取代了他的位置。", "corrected_sentence": "这个年轻人没有取代他的位置。", "error_description": "「了」错误：「没有」表示否定，不能与「了」同用，「取代」后不能加「了」。应说「没有取代他的位置」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
