INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91829, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91829, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以前，过去。", "primary_collocate": null, "pronunciation": "cóng xiān", "ipa": "tsʰʊŋ³⁵ ɕjɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "从先这里没有路，现在有了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从先我不爱吃辣，现在天天吃。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从先住在乡下，后来搬到了城里。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从先的日子很苦，现在好多了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从先不会游泳，去年才学会。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从先这条河很宽，现在变窄了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶常说，从先的人都很节省。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从先他每天骑车上班，现在开车了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店从先很小，现在很大了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从先不喝酒，现在常常喝。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "从先：指以前、过去的时间，常与现在对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33259699-dfd2-43c8-bf62-e169fa2186e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91829, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "语义：“明天”指未来，与后半句“现在有了”的对比不合，句子说不通。"}, {"text": "从先", "is_correct": true, "explanation": "从先：以前、过去的时间，与“现在”形成对比，与句子相符。"}, {"text": "中间", "is_correct": false, "explanation": "搭配：“中间”作主语时需要指明范围，“中间这里没有路”不通顺。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”指将来，与“现在有了”所表示的过去到现在的变化不符。"}], "explanations": {"明天": "语义：“明天”指未来，与后半句“现在有了”的对比不合，句子说不通。", "从先": "从先：以前、过去的时间，与“现在”形成对比，与句子相符。", "中间": "搭配：“中间”作主语时需要指明范围，“中间这里没有路”不通顺。", "未来": "语义：“未来”指将来，与“现在有了”所表示的过去到现在的变化不符。"}, "sentence_index": 0, "correct_answer": "从先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "从先我会去北京工作。", "explanation": "这里应该用〈将来〉。从先指以前、过去的时间，不能用于还没发生的计划。"}, {"text": "从先我们要出发去上海。", "explanation": "这里应该用〈明天〉。从先指过去，不能用于明天要做的事。"}, {"text": "从先会有很多机器人帮我们做饭。", "explanation": "这里应该用〈未来〉。从先指过去，不能用于将来才会发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91829, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电脑", "is_correct": false, "explanation": "语义：“的人”修饰的是有生命的人，“电脑”不能指人，句子说不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能用来指人，“天气的人”搭配不当。"}, {"text": "从先", "is_correct": true, "explanation": "从先：以前、过去，修饰“人”，表示过去的人，与“奶奶常说”的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是无生命的物体，不能作指人的定语。"}], "explanations": {"电脑": "语义：“的人”修饰的是有生命的人，“电脑”不能指人，句子说不通。", "天气": "搭配：“天气”不能用来指人，“天气的人”搭配不当。", "从先": "从先：以前、过去，修饰“人”，表示过去的人，与“奶奶常说”的语境相符。", "石头": "语义：“石头”是无生命的物体，不能作指人的定语。"}, "sentence_index": 6, "correct_answer": "从先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从先要考上大学，这是我的目标。", "explanation": "这里应该用〈以后〉。从先指以前的时间，不能用于还未实现的目标。"}, {"text": "我从先要去美国留学。", "explanation": "这里应该用〈明年〉。从先指过去，不能用于说明年才要做的计划。"}, {"text": "从先我们要搬家，下周就走。", "explanation": "这里应该用〈下周〉。从先指过去，不能用于下周才要做的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91829, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个村子从先的没有电，现在家家都通了电。", "corrected_sentence": "这个村子从先没有电，现在家家都通了电。", "error_description": "误加“的”：“从先”作时间状语直接修饰“没有电”，中间不能加“的”；“从先的没有电”不成词组，句子不通。正确说法是“这个村子从先没有电”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91829, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把从先住在山里，后来才搬到城里。", "corrected_sentence": "我们从先住在山里，后来才搬到城里。", "error_description": "误加“把”：“从先”是表示以前的时间状语，不能作“把”字句的宾语，“把从先住在山里”结构不成立；应删去“把”，正确说法是“我们从先住在山里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
