INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从前；以前。", "primary_collocate": null, "pronunciation": "cóng xiān", "ipa": "tsʰʊŋ³⁵ ɕjɛn⁵⁵", "syllable_count": 2, "sentences": [{"text": "从先这里是一片田，现在是学校。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷从先是个老师，后来不教书了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从先我们家很穷，现在日子好过了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比从先瘦多了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她还是和从先一样爱笑。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从先的老朋友，现在都不联系了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从先没来过这个城市，这是第一次。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从先村里没有电，晚上点着灯。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的天气和从先不一样了。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐从先爱哭，现在很坚强。", "target_word": "从先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "从先：指从前、以前，可作定语或比较的对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33259699-dfd2-43c8-bf62-e169fa2186e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海洋", "is_correct": false, "explanation": "语义：“海洋”是大片水域，不可能是一片可以盖学校的田，句子说不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”指海水，与“一片田”所指的对象冲突，句子语义不通。"}, {"text": "从先", "is_correct": true, "explanation": "从先：从前、以前，修饰“这里”的过去状况，与后半句“现在是学校”形成对比。"}, {"text": "中间", "is_correct": false, "explanation": "搭配：“中间”作主语时需要指明范围，“中间这里是一片田”不通顺。"}], "explanations": {"海洋": "语义：“海洋”是大片水域，不可能是一片可以盖学校的田，句子说不通。", "大海": "语义：“大海”指海水，与“一片田”所指的对象冲突，句子语义不通。", "从先": "从先：从前、以前，修饰“这里”的过去状况，与后半句“现在是学校”形成对比。", "中间": "搭配：“中间”作主语时需要指明范围，“中间这里是一片田”不通顺。"}, "sentence_index": 0, "correct_answer": "从先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "从先我们的学校会很大。", "explanation": "这里应该用〈将来〉。从先指过去的时间，不能用来修饰还没建成的学校。"}, {"text": "从先我们下个月要去北京出差。", "explanation": "这里应该用〈下个月〉。从先指过去，不能用来说下个月的安排。"}, {"text": "从先我要成为一名医生。", "explanation": "这里应该用〈以后〉。从先指过去，不能用来说将来的理想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "明天", "is_correct": false, "explanation": "语义：“明天”指未来，与“没来过”所表示的以前经历矛盾。"}, {"text": "车站", "is_correct": false, "explanation": "搭配：“车站”是地点，不能作时间状语，说“我车站没来过”不通顺。"}, {"text": "下午", "is_correct": false, "explanation": "语义：“下午”是具体的时段，不能表示“以前”的时间，句子语义不通。"}, {"text": "从先", "is_correct": true, "explanation": "从先：以前、从前，表示过去的时间，与“这是第一次”相符。"}], "explanations": {"明天": "语义：“明天”指未来，与“没来过”所表示的以前经历矛盾。", "车站": "搭配：“车站”是地点，不能作时间状语，说“我车站没来过”不通顺。", "下午": "语义：“下午”是具体的时段，不能表示“以前”的时间，句子语义不通。", "从先": "从先：以前、从前，表示过去的时间，与“这是第一次”相符。"}, "sentence_index": 6, "correct_answer": "从先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我从先要参加考试，很紧张。", "explanation": "这里应该用〈明天〉。从先指过去，不能用来说明天的安排。"}, {"text": "从先会下雨，记得带伞。", "explanation": "这里应该用〈后天〉。从先指过去，不能用来说将要发生的天气。"}, {"text": "从先我要去医院复查。", "explanation": "这里应该用〈下个星期天〉。从先指过去，不能用来说还没到来的安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "从先了田地现在都盖了楼房。", "corrected_sentence": "从先的田地现在都盖了楼房。", "error_description": "错误在“了”误作定语标记。“了”不能修饰名词，“从先了田地”不成词组；应改为定语标记“的”，即“从先的田地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把从先很爱笑，现在不笑了。", "corrected_sentence": "他从先很爱笑，现在不笑了。", "error_description": "误加“把”：“从先”是表示以前的时间名词，在句中作时间状语，不能作“把”字句的宾语，“把从先很爱笑”结构不成立；应删去“把”，正确说法是“他从先很爱笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91831, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91831, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91831, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "来神是突然很有精神，很想做某件事。", "primary_collocate": null, "pronunciation": "lái shén", "ipa": "lai˧˥ ʂən˧˥", "syllable_count": 2, "sentences": [{"text": "一说到打球，他马上就来神了。", "target_word": "来神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才他还很累，一听有好吃的就来神了。", "target_word": "来神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看到雪，一下子都来神了。", "target_word": "来神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你一提旅游，她就来神。", "target_word": "来神", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他平时爱睡觉，可是一玩游戏就来神。", "target_word": "来神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说明天放假，大家都来神了。", "target_word": "来神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王一喝完咖啡就来神了，开始认真工作。", "target_word": "来神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲到有趣的故事，同学们都来神了。", "target_word": "来神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟一看见足球就来神。", "target_word": "来神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚才还没精神，现在你怎么突然来神了？", "target_word": "来神", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "来神了", "label": "体标"}, {"form": "來神", "label": "繁体"}], "register": "口语", "sense_fingerprint": "突然来了精神、很想做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e595aba8-a327-4dfa-933f-cb10e384922d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91831, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "来神", "is_correct": true, "explanation": "正确：“来神”指突然精神振奋、很想做某事，与“一说到打球，他马上就”的反应吻合。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，主语不能是“他”。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜”形容价格，不能描述人对打球的反应。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：“莅临”是正式书面用语，用来描述朋友日常的反应显得不伦不类，口语中不能这样说。"}], "explanations": {"来神": "正确：“来神”指突然精神振奋、很想做某事，与“一说到打球，他马上就”的反应吻合。", "下雨": "语义：“下雨”是天气现象，主语不能是“他”。", "便宜": "语义：“便宜”形容价格，不能描述人对打球的反应。", "莅临": "语域：“莅临”是正式书面用语，用来描述朋友日常的反应显得不伦不类，口语中不能这样说。"}, "sentence_index": 0, "correct_answer": "来神"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一看到蛇，就来神了，吓得直往后退。", "explanation": "这里应该用〈害怕〉。来神表示精神振奋、有劲头，不能描述被蛇吓到后往后退的反应。"}, {"text": "一想到期末考试，他头疼得厉害，躺在床上直哼哼，突然来神了。", "explanation": "这里应该用〈难受〉。来神表示精神振奋、很想做事，与“躺在床上直哼哼”的状态相矛盾。"}, {"text": "弟弟抢走了他的玩具，他一下子呆住了，像丢了魂似的，突然来神了。", "explanation": "这里应该用〈发呆〉。来神表示精神振奋、很想做事，与“呆住了、丢了魂似的”的状态相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91831, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "来神", "is_correct": true, "explanation": "正确：“来神”表示突然精神振奋，与“一喝完咖啡就”的效果及后句“开始认真工作”吻合。"}, {"text": "睡着", "is_correct": false, "explanation": "语义：“睡着”与咖啡提神的作用相反，且与后句“开始认真工作”矛盾。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：“发呆”表示出神、没有行动，与“开始认真工作”不能连用。"}, {"text": "喝醉", "is_correct": false, "explanation": "搭配：“喝醉”一般搭配酒类，咖啡不会让人喝醉，这一搭配不成立。"}], "explanations": {"来神": "正确：“来神”表示突然精神振奋，与“一喝完咖啡就”的效果及后句“开始认真工作”吻合。", "睡着": "语义：“睡着”与咖啡提神的作用相反，且与后句“开始认真工作”矛盾。", "发呆": "语义：“发呆”表示出神、没有行动，与“开始认真工作”不能连用。", "喝醉": "搭配：“喝醉”一般搭配酒类，咖啡不会让人喝醉，这一搭配不成立。"}, "sentence_index": 6, "correct_answer": "来神"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摔了一跤，腿疼得直来神。", "explanation": "这里应该用〈喊疼〉。来神只表示精神振奋，不能用来描写身体疼痛时的状态。"}, {"text": "他一闻到那股味道，两眼一翻，身子一软倒在地上，又突然来神了。", "explanation": "这里应该用〈昏厥〉。来神表示精神振奋，与“两眼一翻、倒在地上”的昏迷状态相矛盾。"}, {"text": "老师一点名，他就来神了，吓得缩在座位上发抖。", "explanation": "这里应该用〈害怕〉。来神表示精神振奋，不能用于被吓得发抖的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91831, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一听有人叫他去运动，他就把来神了。", "corrected_sentence": "一听有人叫他去运动，他就来神了。", "error_description": "“来神”是不及物的动词性短语，不能带宾语放在“把”字之后，应说“他就来神了”，不能说“把来神”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91831, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一喝浓茶就来神着，能熬夜写作业。", "corrected_sentence": "我一喝浓茶就来神，能熬夜写作业。", "error_description": "“来神”后面不能加“着”表示持续，这种说法不自然。应说“就来神”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
