INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91833, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吃人是把人当成食物吃掉，故事里的怪物才这样。", "primary_collocate": null, "pronunciation": "chī rén", "ipa": "ʈʂʰɨ˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "村里的人都怕那个怪物，因为它会吃人。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里有一只会吃人的老虎。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里说那种巨蛇吃人，村里的人都很害怕。", "target_word": "吃人", "complexity_tier": "T3", "furigana": "chī rén", "sentence_source": "generated"}, {"text": "孩子怕那个吃人的大怪物。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人讲了一个吃人妖怪的故事。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狮子饿了，也可能吃人。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只熊没有吃人，只是吓跑了他们。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条鲨鱼曾经吃人，海边没人敢下水。", "target_word": "吃人", "complexity_tier": "T3", "furigana": "chī rén", "sentence_source": "generated"}, {"text": "小时候我总怕床下有吃人的怪物。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说山上有个吃人的巨人。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃了人", "label": "体标"}, {"form": "吃过人", "label": "体标"}], "register": "中性", "sense_fingerprint": "把人当成食物吃掉（字面义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91833, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吃人", "is_correct": true, "explanation": "吃人：把人当成食物吃掉。"}, {"text": "诗人", "is_correct": false, "explanation": "shī 与 chī 声母不同（sh 与 ch），声调相同，意思是诗人。"}, {"text": "知人", "is_correct": false, "explanation": "zhī 与 chī 声母不同（zh 与 ch），声调相同，意思是了解他人。"}, {"text": "七人", "is_correct": false, "explanation": "qī 与 chī 声母不同（q 与 ch），声调相同，意思是七个人。"}], "explanations": {"吃人": "吃人：把人当成食物吃掉。", "诗人": "shī 与 chī 声母不同（sh 与 ch），声调相同，意思是诗人。", "知人": "zhī 与 chī 声母不同（zh 与 ch），声调相同，意思是了解他人。", "七人": "qī 与 chī 声母不同（q 与 ch），声调相同，意思是七个人。"}, "sentence_index": null, "correct_answer": "吃人"}, "level_3": {"options": [{"text": "吃人", "is_correct": true, "explanation": "吃人：把人当食物吞食，符合故事里怪物的形象。"}, {"text": "吃素", "is_correct": false, "explanation": "语义：“吃素”指不吃荤食，与怪物会“吃人”的设定相反。"}, {"text": "养活人", "is_correct": false, "explanation": "语义：“养活人”是供养人的行为，与怪物的凶残形象不符。"}, {"text": "喂人", "is_correct": false, "explanation": "搭配：“喂”一般用于动物或婴儿，不能用于成年人。"}], "explanations": {"吃人": "吃人：把人当食物吞食，符合故事里怪物的形象。", "吃素": "语义：“吃素”指不吃荤食，与怪物会“吃人”的设定相反。", "养活人": "语义：“养活人”是供养人的行为，与怪物的凶残形象不符。", "喂人": "搭配：“喂”一般用于动物或婴儿，不能用于成年人。"}, "sentence_index": 0, "correct_answer": "吃人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从小吃人，不怕累，什么难都扛得住。", "explanation": "这里应该用〈吃苦〉。吃人只指把人当成食物吞食，不能表示经受艰难。"}, {"text": "老师夸这个学生很会读书，说他真是吃人。", "explanation": "这里应该用〈厉害〉。吃人只指把人当成食物吞食，不能用来夸学生会读书。"}, {"text": "他看见弟弟拿了第一名，就吃人，一句话也不说。", "explanation": "这里应该用〈吃醋〉。吃人只指把人当成食物吞食，不能表示因嫉妒而生气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91833, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃人", "is_correct": true, "explanation": "吃人：把人当食物吞食，与“没有吃人，只是吓跑了他们”的情节相合。"}, {"text": "救人", "is_correct": false, "explanation": "语义：“救人”是施救，与“只是吓跑了他们”的情节不符。"}, {"text": "招待人", "is_correct": false, "explanation": "语义：“招待人”是待客，与“吓跑了他们”的语境矛盾。"}, {"text": "哺育人", "is_correct": false, "explanation": "搭配：“哺育”多指养育幼崽，不用于描述熊对成人的行为。"}], "explanations": {"吃人": "吃人：把人当食物吞食，与“没有吃人，只是吓跑了他们”的情节相合。", "救人": "语义：“救人”是施救，与“只是吓跑了他们”的情节不符。", "招待人": "语义：“招待人”是待客，与“吓跑了他们”的语境矛盾。", "哺育人": "搭配：“哺育”多指养育幼崽，不用于描述熊对成人的行为。"}, "sentence_index": 6, "correct_answer": "吃人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在饭店吃人，点了一盘鱼。", "explanation": "〈吃人〉取“把人当食物吞食”的字面义，不表示进食，这里说的点菜吃饭不能用〈吃人〉。"}, {"text": "这幅画吃人，大家都愿意多看一会儿。", "explanation": "这里应该用〈吸引人〉。吃人只指把人当成食物吞食，不能用来形容画的吸引力。"}, {"text": "这次搬家吃人，我们忙了一整天。", "explanation": "这里应该用〈吃力〉。吃人只指把人当成食物吞食，不能用来形容搬家费力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "森林里的老虎把吃人，大家都不敢进去。", "corrected_sentence": "森林里的老虎吃人，大家都不敢进去。", "error_description": "“把”字句中“把”之后不能直接接动宾式复合词“吃人”，此处应删去“把”，句子即为“老虎吃人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "狼过吃人，村里的人都很害怕。", "corrected_sentence": "狼吃过人，村里的人都很害怕。", "error_description": "“过”是动态助词，必须放在动词“吃”之后，应说“吃过人”，不能放在“吃”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
