INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91834, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比喻残害、压榨他人。", "primary_collocate": null, "pronunciation": "chī rén", "ipa": "ʈʂʰɨ˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "旧社会吃人，穷人连饭都吃不上。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个吃人的制度毁了很多家庭。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里写了吃人的旧礼教。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人说高房价吃人，年轻人压力很大。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得有钱人吃人，一点也不心疼穷人。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板天天让工人加班，真是吃人。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种吃人的规矩早就该改了。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个年代的制度吃人不吐骨头。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲁迅说旧社会是吃人的社会。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说这家公司吃人，员工天天哭。", "target_word": "吃人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃了人", "label": "体标"}, {"form": "吃过人", "label": "体标"}], "register": "中性", "sense_fingerprint": "比喻残害、压榨他人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91834, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吃人", "is_correct": true, "explanation": "吃人：比喻残害、压榨他人。"}, {"text": "诗人", "is_correct": false, "explanation": "shī 与 chī 声母不同（sh 与 ch），声调相同，意思是诗人。"}, {"text": "知人", "is_correct": false, "explanation": "zhī 与 chī 声母不同（zh 与 ch），声调相同，意思是了解他人。"}, {"text": "七人", "is_correct": false, "explanation": "qī 与 chī 声母不同（q 与 ch），声调相同，意思是七个人。"}], "explanations": {"吃人": "吃人：比喻残害、压榨他人。", "诗人": "shī 与 chī 声母不同（sh 与 ch），声调相同，意思是诗人。", "知人": "zhī 与 chī 声母不同（zh 与 ch），声调相同，意思是了解他人。", "七人": "qī 与 chī 声母不同（q 与 ch），声调相同，意思是七个人。"}, "sentence_index": null, "correct_answer": "吃人"}, "level_3": {"options": [{"text": "吃人", "is_correct": true, "explanation": "吃人：比喻残害、压榨他人，与“穷人连饭都吃不上”的语境相合。"}, {"text": "养活人", "is_correct": false, "explanation": "语义：“养活人”指供给生活所需，与“穷人连饭都吃不上”的描述相矛盾。"}, {"text": "帮助人", "is_correct": false, "explanation": "语义：“帮助人”是善意的行为，与后文描述的苦难不相合。"}, {"text": "喂人", "is_correct": false, "explanation": "搭配：“喂”多用于动物或婴儿，一般不用于成年人。"}], "explanations": {"吃人": "吃人：比喻残害、压榨他人，与“穷人连饭都吃不上”的语境相合。", "养活人": "语义：“养活人”指供给生活所需，与“穷人连饭都吃不上”的描述相矛盾。", "帮助人": "语义：“帮助人”是善意的行为，与后文描述的苦难不相合。", "喂人": "搭配：“喂”多用于动物或婴儿，一般不用于成年人。"}, "sentence_index": 0, "correct_answer": "吃人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和朋友在饭店吃人，点了一只烤鸭。", "explanation": "这里应该用〈吃饭〉。吃人表示残害或压榨他人，不能用来指在饭店吃普通的饭菜。"}, {"text": "这本书吃人，我一口气读到了天亮。", "explanation": "这里应该用〈吸引人〉。吃人只表示残害或吞食他人，不能用来说书的内容让人入迷。"}, {"text": "她一听朋友有了男朋友，就吃人，脸色很难看。", "explanation": "这里应该用〈吃醋〉。吃人只表示残害或吞食他人，不能表示因嫉妒而不高兴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃人", "is_correct": true, "explanation": "吃人：比喻残害、压榨他人，正是“早就该改了”的恶规矩。"}, {"text": "尊重人", "is_correct": false, "explanation": "语义：“尊重人”是敬重他人，与“早就该改了”的批判语气不合。"}, {"text": "保护人", "is_correct": false, "explanation": "语义：规矩若是“保护人”，就不会需要“早就该改了”。"}, {"text": "哺育人", "is_correct": false, "explanation": "搭配：“哺育”多指对婴幼儿或幼崽的养育，不用于形容成年人的规矩。"}], "explanations": {"吃人": "吃人：比喻残害、压榨他人，正是“早就该改了”的恶规矩。", "尊重人": "语义：“尊重人”是敬重他人，与“早就该改了”的批判语气不合。", "保护人": "语义：规矩若是“保护人”，就不会需要“早就该改了”。", "哺育人": "搭配：“哺育”多指对婴幼儿或幼崽的养育，不用于形容成年人的规矩。"}, "sentence_index": 6, "correct_answer": "吃人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从小吃人，不怕累，什么难都扛得住。", "explanation": "这里应该用〈吃苦〉。吃人只表示残害或吞食他人，不能表示经受艰难。"}, {"text": "这位医生很有爱心，经常免费帮助病人，大家都说他吃人。", "explanation": "这里误把〈吃人〉当作称赞词，它只表示残害或压榨他人，应改用〈乐于助人〉之类的词。"}, {"text": "这项工作吃人，我每天都累得不行。", "explanation": "这里应该用〈吃力〉。吃人只表示残害或吞食他人，不能用来形容工作费力、累人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个制度过吃人，大家都很怕它。", "corrected_sentence": "那个制度吃过人，大家都很怕它。", "error_description": "体标位置错误。“过”是动态助词，必须放在动词“吃”之后，应说“吃过人”，不能放在“吃”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一家吃人地公司。", "corrected_sentence": "这是一家吃人的公司。", "error_description": "“的”和“地”混用。“吃人”修饰名词“公司”时要用“的”，“地”用于修饰动词，应说“吃人的公司”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91835, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": true, "explanation": "高兴与“悲伤”（心里很难过）意思相反，是反义词。"}, {"text": "聪明", "is_correct": false, "explanation": "聪明形容智力高，与悲伤的情绪没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "干净形容没有污物，不是“悲伤”的反义词。"}, {"text": "安静", "is_correct": false, "explanation": "安静形容没有声音或心情平和，与“悲伤”不构成反义。"}], "correct_answer": "高兴", "explanations": {"高兴": "高兴与“悲伤”（心里很难过）意思相反，是反义词。", "聪明": "聪明形容智力高，与悲伤的情绪没有反义关系。", "干净": "干净形容没有污物，不是“悲伤”的反义词。", "安静": "安静形容没有声音或心情平和，与“悲伤”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91835, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高兴", "is_correct": true, "explanation": "高兴与“悲伤”（心里很难过）意思相反，是反义词。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙形容表面不光滑，与悲伤的情绪无反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐形容排列有序，不是“悲伤”的反义词。"}, {"text": "辛辣", "is_correct": false, "explanation": "辛辣形容味道刺激，与悲伤没有反义关系。"}], "correct_answer": "高兴", "explanations": {"高兴": "高兴与“悲伤”（心里很难过）意思相反，是反义词。", "粗糙": "粗糙形容表面不光滑，与悲伤的情绪无反义关系。", "整齐": "整齐形容排列有序，不是“悲伤”的反义词。", "辛辣": "辛辣形容味道刺激，与悲伤没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91835, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里很难过，想哭。", "primary_collocate": null, "pronunciation": "bēi shāng", "ipa": "pei̯˥ ʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "听到这个消息，她非常悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来很悲伤，一句话也不说。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶走了以后，全家人都很悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她悲伤地哭了一晚上。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌听起来太悲伤了。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想让你这么悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友搬走了，我心里很悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到小狗死了，孩子悲伤极了。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她悲伤得说不出话来。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别太悲伤，一切都会好起来的。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "悲傷", "label": "繁体"}], "register": "中性", "sense_fingerprint": "形容人心里难过、想哭的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '923791ca-0690-495c-bb48-7710886093fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91835, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "悲伤", "is_correct": true, "explanation": "悲伤 bēi shāng，形容心里很难过、想哭。"}, {"text": "北上", "is_correct": false, "explanation": "běi shàng 与 bēi shāng 声调不同（第三、第四声与第一声），意思是向北去。"}, {"text": "背上", "is_correct": false, "explanation": "bèi shang 与 bēi shāng 声调不同，意思是背部的上面。"}, {"text": "悲声", "is_correct": false, "explanation": "bēi shēng 与 bēi shāng 的韵母不同（shēng 与 shāng），意思是哭泣的声音。"}], "explanations": {"悲伤": "悲伤 bēi shāng，形容心里很难过、想哭。", "北上": "běi shàng 与 bēi shāng 声调不同（第三、第四声与第一声），意思是向北去。", "背上": "bèi shang 与 bēi shāng 声调不同，意思是背部的上面。", "悲声": "bēi shēng 与 bēi shāng 的韵母不同（shēng 与 shāng），意思是哭泣的声音。"}, "sentence_index": null, "correct_answer": "悲伤"}, "level_3": {"options": [{"text": "悲伤", "is_correct": true, "explanation": "悲伤形容心里难过，放在“非常”之后作谓语，与“听到这个消息”的语境相符。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：明亮多形容光线或眼睛，不能用来形容听到消息后的心情。"}, {"text": "宽敞", "is_correct": false, "explanation": "语义：宽敞形容空间大，不能用来形容人的心情。"}, {"text": "嘈杂", "is_correct": false, "explanation": "语义：嘈杂形容声音吵闹或环境混乱，与“听到这个消息”后的心情无关。"}], "explanations": {"悲伤": "悲伤形容心里难过，放在“非常”之后作谓语，与“听到这个消息”的语境相符。", "明亮": "体貌：明亮多形容光线或眼睛，不能用来形容听到消息后的心情。", "宽敞": "语义：宽敞形容空间大，不能用来形容人的心情。", "嘈杂": "语义：嘈杂形容声音吵闹或环境混乱，与“听到这个消息”后的心情无关。"}, "sentence_index": 0, "correct_answer": "悲伤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我吃坏了肚子，今天很悲伤。", "explanation": "这里应该用〈难受〉。悲伤只形容心里的难过，身体不舒服要用难受。"}, {"text": "听到这个好消息，他很悲伤。", "explanation": "这里应该用〈高兴〉。悲伤表示心里难过，不能用来形容听到好消息时的心情。"}, {"text": "这家公司的产品很悲伤，没人愿意买。", "explanation": "这里应该用〈糟糕〉。悲伤只形容人心里难过，不能用来评价产品的质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91835, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悲伤", "is_correct": true, "explanation": "悲伤形容心里难过，与“朋友搬走了”之后的心情相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：热闹形容场面或环境喧闹，不能说心里很热闹。"}, {"text": "笔直", "is_correct": false, "explanation": "体貌：笔直形容形状或姿态，不能用来形容心里的情绪。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：陡峭形容地势，与心情无关。"}], "explanations": {"悲伤": "悲伤形容心里难过，与“朋友搬走了”之后的心情相符。", "热闹": "语义：热闹形容场面或环境喧闹，不能说心里很热闹。", "笔直": "体貌：笔直形容形状或姿态，不能用来形容心里的情绪。", "陡峭": "语义：陡峭形容地势，与心情无关。"}, "sentence_index": 6, "correct_answer": "悲伤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天是我的婚礼，我悲伤地笑个不停。", "explanation": "这里应该用〈开心〉。悲伤表示心里难过，不能形容婚礼上笑个不停的心情。"}, {"text": "听到比赛获胜，大家悲伤地欢呼起来。", "explanation": "这里应该用〈兴奋〉。悲伤与欢呼的情绪相反，不能这样搭配。"}, {"text": "他拿到了录取通知书，悲伤地跑去告诉妈妈。", "explanation": "这里应该用〈激动〉。悲伤表示难过，与拿到录取通知书后的心情不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91835, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她听到消息后，悲伤的坐了很久。", "corrected_sentence": "她听到消息后，悲伤地坐了很久。", "error_description": "错误：“悲伤”修饰动词“坐”时应该用“地”，写成“的”是错误的。正确说法是“悲伤地坐了很久”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91835, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈，别很悲伤，他很快就会回来的。", "corrected_sentence": "妈妈，别太悲伤，他很快就会回来的。", "error_description": "错误：副词“很”不能用于“别”之后的劝阻句，应说“别太悲伤”。正确说法是“别太悲伤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
