INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91836, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "伤心，哀痛。", "primary_collocate": null, "pronunciation": "bēi shāng", "ipa": "pei̯˥ ʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "他的脸上带着悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里充满了悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间能慢慢带走悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力不让别人看到他的悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事给全家带来了很大的悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她沉浸在悲伤里，不愿见人。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐让我想起了过去的悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都分担了他的悲伤。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "悲伤慢慢过去了，她又开始工作了。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把悲伤藏在心里。", "target_word": "悲伤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "悲傷", "label": "繁体"}], "register": "书面", "sense_fingerprint": "指心中伤心、哀痛的感情本身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '923791ca-0690-495c-bb48-7710886093fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91836, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "悲伤", "is_correct": true, "explanation": "悲伤 bēi shāng，指悲哀的感情。"}, {"text": "北上", "is_correct": false, "explanation": "běi shàng 与 bēi shāng 声调不同，意思是向北去。"}, {"text": "背上", "is_correct": false, "explanation": "bèi shàng（第四声）与 bēi shāng（第一声）声调不同，意思是背在背部。"}, {"text": "悲声", "is_correct": false, "explanation": "bēi shēng 与 bēi shāng 的韵母不同（shēng 与 shāng），意思是哭泣的声音。"}], "explanations": {"悲伤": "悲伤 bēi shāng，指悲哀的感情。", "北上": "běi shàng 与 bēi shāng 声调不同，意思是向北去。", "背上": "bèi shàng（第四声）与 bēi shāng（第一声）声调不同，意思是背在背部。", "悲声": "bēi shēng 与 bēi shāng 的韵母不同（shēng 与 shāng），意思是哭泣的声音。"}, "sentence_index": null, "correct_answer": "悲伤"}, "level_3": {"options": [{"text": "悲伤", "is_correct": true, "explanation": "“脸上带着”后可以接表示神情的名词，悲伤符合这个语境。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是纸制的图，不能作为神情带在脸上。"}, {"text": "仓库", "is_correct": false, "explanation": "语义：仓库是存放物品的建筑，不是可以显示在脸上的神情。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“带着”后接表情、神情类名词，不接“价格”。"}], "explanations": {"悲伤": "“脸上带着”后可以接表示神情的名词，悲伤符合这个语境。", "地图": "语义：地图是纸制的图，不能作为神情带在脸上。", "仓库": "语义：仓库是存放物品的建筑，不是可以显示在脸上的神情。", "价格": "搭配：“带着”后接表情、神情类名词，不接“价格”。"}, "sentence_index": 0, "correct_answer": "悲伤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把悲伤放进冰箱里了。", "explanation": "这里应该用〈牛奶〉。悲伤是心里的感情，不是能放进冰箱的东西。"}, {"text": "他每天骑着悲伤去上班。", "explanation": "这里应该用〈自行车〉。悲伤指伤心哀痛的感情，不能骑。"}, {"text": "我们买了一斤悲伤，回家炖了汤。", "explanation": "这里应该用〈排骨〉。悲伤指伤心哀痛的感情，不能按斤买，也不能炖汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悲伤", "is_correct": true, "explanation": "“过去的悲伤”指已经发生过的伤心之情，与句意相符。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“过去的”指已经发生的时间，与“未来”的时间方向相反。"}, {"text": "明天", "is_correct": false, "explanation": "搭配：“过去的”通常不修饰“明天”这种尚未到来的时间。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指尚未发生的时间，与“过去的”不能搭配。"}], "explanations": {"悲伤": "“过去的悲伤”指已经发生过的伤心之情，与句意相符。", "未来": "语义：“过去的”指已经发生的时间，与“未来”的时间方向相反。", "明天": "搭配：“过去的”通常不修饰“明天”这种尚未到来的时间。", "将来": "语义：“将来”指尚未发生的时间，与“过去的”不能搭配。"}, "sentence_index": 6, "correct_answer": "悲伤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他手上的悲伤流了很多血，医生说要缝针。", "explanation": "这里应该用〈伤口〉。悲伤指心里的哀痛，不能流血，身上的伤要说“伤口”。"}, {"text": "他的悲伤坏了，拿去修理了。", "explanation": "这里应该用〈自行车〉。悲伤是心里的感情，不会坏，也不能拿去修理。"}, {"text": "我要去医院检查我的悲伤。", "explanation": "这里应该用〈病情〉。悲伤是心里的哀痛，不是身体的状况，不能拿去医院检查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里压着一阵悲伤的，很久没有说话。", "corrected_sentence": "他心里压着一阵悲伤，很久没有说话。", "error_description": "错误：名词“悲伤”后面多加了“的”，句子在“悲伤的”处中断。正确说法是“一阵悲伤，很久没有说话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他心里有一只悲伤，说不清楚。", "corrected_sentence": "他心里有一种悲伤，说不清楚。", "error_description": "错误：“只”是用于具体事物的量词，不用于抽象名词“悲伤”；应该用“种”，说“一种悲伤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
