INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91837, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "便车是顺路载你一段的车。", "primary_collocate": null, "pronunciation": "biàn chē", "ipa": "pjɛn˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "你顺路的话，可以让我搭个便车吗？", "target_word": "便车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都蹭同事的便车上班。", "target_word": "便车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车坏了，我们只能搭别人的便车。", "target_word": "便车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老张开车去县城，让我搭了一段便车。", "target_word": "便车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一趟便车，不收钱。", "target_word": "便车", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下班后，他请我搭便车回家。", "target_word": "便车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在山路上走了两个小时，却一趟便车也没搭到。", "target_word": "便车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的便车是朋友帮忙找的。", "target_word": "便车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在路口招手，一辆便车停了。", "target_word": "便车", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搭便车要注意安全，最好告诉家人。", "target_word": "便车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "趟", "label": "量词"}, {"form": "便車", "label": "繁体"}], "register": "口语", "sense_fingerprint": "顺路载人一段路的车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e595aba8-a327-4dfa-933f-cb10e384922d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "便车", "is_correct": true, "explanation": "正确：“便车”指顺路载人一段路的车，与“你顺路的话”的语境吻合。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发不是交通工具，与“顺路”的语境不合。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：飞机不能顺路搭乘，与“你顺路的话”的语境不合。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯不是交通工具，不能用来“顺路”搭乘，与“你顺路的话”的语境不合。"}], "explanations": {"便车": "正确：“便车”指顺路载人一段路的车，与“你顺路的话”的语境吻合。", "沙发": "语义：沙发不是交通工具，与“顺路”的语境不合。", "飞机": "语义：飞机不能顺路搭乘，与“你顺路的话”的语境不合。", "电梯": "语义：电梯不是交通工具，不能用来“顺路”搭乘，与“你顺路的话”的语境不合。"}, "sentence_index": 0, "correct_answer": "便车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都付便车费，觉得很划算。", "explanation": "这里应该用〈出租车〉。便车是顺路搭乘、不收费的车，不能说付费。"}, {"text": "这辆便车每天七点准时发车，开往市中心。", "explanation": "这里应该用〈班车〉。便车没有固定的时间和路线，不能说准时发车。"}, {"text": "这是我自己的便车，每天开着上班。", "explanation": "这里应该用〈私家车〉。便车是别人顺路带你一段的车，不能是自己的车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "便车", "is_correct": true, "explanation": "正确：“便车”指顺路载人一段路的车，在山路上很少见，与“我们走了两个小时”的情境吻合。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：山路上没有地铁，与“走了两个小时却没搭到”的语境不合。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：山路上没有电梯，与语境不合。"}, {"text": "救护车", "is_correct": false, "explanation": "语义：救护车专用于急救，不供人顺路搭乘，与“山路上走了两个小时”的情境不合。"}], "explanations": {"便车": "正确：“便车”指顺路载人一段路的车，在山路上很少见，与“我们走了两个小时”的情境吻合。", "地铁": "语义：山路上没有地铁，与“走了两个小时却没搭到”的语境不合。", "电梯": "语义：山路上没有电梯，与语境不合。", "救护车": "语义：救护车专用于急救，不供人顺路搭乘，与“山路上走了两个小时”的情境不合。"}, "sentence_index": 6, "correct_answer": "便车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外面下雨了，我撑开便车出了门。", "explanation": "这里应该用〈雨伞〉。便车是顺路载人的车，不能撑开挡雨。"}, {"text": "我坐便车去北京，飞了三个小时。", "explanation": "这里应该用〈飞机〉。便车是顺路搭乘的陆上车辆，不能用于飞行。"}, {"text": "他是我的便车，每天开车送我上学。", "explanation": "这里应该用〈司机〉。便车指的是车，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他顺路带我去了车站，我坐了他的一块便车。", "corrected_sentence": "他顺路带我去了车站，我坐了他的一段便车。", "error_description": "“便车”指顺路载人的一段路程，量词应用“段”，“块”不能用于便车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天骑车上班，从不搭了便车。", "corrected_sentence": "他每天骑车上班，从不搭便车。", "error_description": "否定句“从不”之后不能加“了”。“搭便车”的否定说法应为“从不搭便车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b01c547-1683-4d71-a152-95bc8582122a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
