INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91839, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "合并是把两个合成一个。", "primary_collocate": null, "pronunciation": "hé bìng", "ipa": "xɤ˧˥ piŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这两家公司下个月合并。", "target_word": "合并", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把两个小班合并成一个大班。", "target_word": "合并", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个部门合并了，人少了很多。", "target_word": "合并", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这两个文件合并起来。", "target_word": "合并", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家银行去年合并成一家了。", "target_word": "合并", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这两张表合并成一张。", "target_word": "合并", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个村子合并后，变成了一个镇。", "target_word": "合并", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们决定合并两家小店。", "target_word": "合并", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个球队合并过一次，后来又分开了。", "target_word": "合并", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把两份作业合并成一份交上来。", "target_word": "合并", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合并了", "label": "完成体"}, {"form": "合并过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把两个合成一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0682de28-216e-408a-8dda-edcb161f2d00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91839, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "合并", "is_correct": true, "explanation": "合并：两家公司合成一家，符合句意。"}, {"text": "散会", "is_correct": false, "explanation": "语义：「散会」指会议结束，与两家公司合成一家的意思不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：「睡觉」的主体是人或动物，公司不能睡觉。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：「散步」的主体通常是人，公司不能散步。"}], "explanations": {"合并": "合并：两家公司合成一家，符合句意。", "散会": "语义：「散会」指会议结束，与两家公司合成一家的意思不符。", "睡觉": "搭配：「睡觉」的主体是人或动物，公司不能睡觉。", "散步": "搭配：「散步」的主体通常是人，公司不能散步。"}, "sentence_index": 0, "correct_answer": "合并"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和同学合并完成了这个项目。", "explanation": "这里应该用〈合作〉。两个人一起做事要用〈合作〉，〈合并〉指把东西合成一个。"}, {"text": "我合并了新朋友。", "explanation": "这里应该用〈结识〉。〈合并〉指把东西合成一个，不能用于人，认识新朋友要用〈结识〉。"}, {"text": "我合并了一碗面。", "explanation": "这里应该用〈吃〉。〈合并〉指把东西合成一个，吃一碗面要用〈吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91839, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "合并", "is_correct": true, "explanation": "合并：两个村子合成一个，变成了一个镇，符合句意。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：「繁殖」指生物增加后代，村子不能繁殖。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：「失踪」指人或物不知去向，与「变成了一个镇」不符。"}, {"text": "合影", "is_correct": false, "explanation": "搭配：「合影」的主体是人，村子不能合影。"}], "explanations": {"合并": "合并：两个村子合成一个，变成了一个镇，符合句意。", "繁殖": "语义：「繁殖」指生物增加后代，村子不能繁殖。", "失踪": "语义：「失踪」指人或物不知去向，与「变成了一个镇」不符。", "合影": "搭配：「合影」的主体是人，村子不能合影。"}, "sentence_index": 6, "correct_answer": "合并"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书合并到楼上了。", "explanation": "这里应该用〈搬〉。〈合并〉指把东西合成一个，不能表示把东西移到某处，应该用〈搬〉。"}, {"text": "他合并给我一支笔。", "explanation": "这里应该用〈借〉。〈合并〉不能表示把东西借给别人，借给别人要用〈借〉。"}, {"text": "他合并了感冒。", "explanation": "这里应该用〈得〉。〈合并〉的对象是事物，患病要说「得」，不能用〈合并〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91839, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两所学校上个月合并了成一所。", "corrected_sentence": "两所学校上个月合并成了一所。", "error_description": "「了」位置错误：「了」应放在补语「成」之后，说成「合并成了一所」，不能插在「合并」和「成」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91839, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个村子没有合并了。", "corrected_sentence": "这两个村子没有合并。", "error_description": "「了」错误：「没有」表示否定，不能与「了」同用，「合并」后不能加「了」。应说「这两个村子没有合并」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c7c967a3-c3f4-4f41-b0db-2262c61bf953') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
