INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91842, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用力拉；撕开。", "primary_collocate": null, "pronunciation": "chě", "ipa": "ʈʂʰɤ²¹⁴", "syllable_count": 1, "sentences": [{"text": "他把那张旧海报扯了下来。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把我的袜子扯破了。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈扯下一块布，给孩子包扎伤口。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气地扯碎了那封信。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，把门口的红布条扯走了。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一扯，口袋就破了。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别扯我的衣服，我自己走。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从本子上扯下一页纸。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子扯坏了新窗帘。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把墙上的旧画扯下来，扔进了垃圾桶。", "target_word": "扯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扯了", "label": "体标"}, {"form": "扯着", "label": "体标"}, {"form": "扯过", "label": "体标"}, {"form": "扯了扯", "label": "重叠"}, {"form": "扯开", "label": "复合"}, {"form": "扯破", "label": "复合"}], "register": "口语", "sense_fingerprint": "用力拉并撕开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1253fbc-9288-40c9-a9b1-e95e77d08214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91842, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "扯", "is_correct": true, "explanation": "扯（chě，第三声）：用力拉或撕开。"}, {"text": "车", "is_correct": false, "explanation": "chē（第一声）与 chě（第三声）声调不同，意思是车。"}, {"text": "彻", "is_correct": false, "explanation": "chè（第四声）与 chě（第三声）声调不同，意思是彻底。"}, {"text": "尺", "is_correct": false, "explanation": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是尺子。"}, {"text": "舍", "is_correct": false, "explanation": "shě 与 chě 声母不同（sh 与 ch），声调相同，意思是舍弃。"}], "explanations": {"扯": "扯（chě，第三声）：用力拉或撕开。", "车": "chē（第一声）与 chě（第三声）声调不同，意思是车。", "彻": "chè（第四声）与 chě（第三声）声调不同，意思是彻底。", "尺": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是尺子。", "舍": "shě 与 chě 声母不同（sh 与 ch），声调相同，意思是舍弃。"}, "sentence_index": null, "correct_answer": "扯"}, "level_3": {"options": [{"text": "扯", "is_correct": true, "explanation": "扯：用力拉下，符合“把海报取下来”的动作。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，海报不能被吃下来。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”指咽下，与取下海报的动作无关。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与把海报取下来无关。"}], "explanations": {"扯": "扯：用力拉下，符合“把海报取下来”的动作。", "吃": "搭配：“吃”的对象是食物，海报不能被吃下来。", "吞": "语义：“吞”指咽下，与取下海报的动作无关。", "唱": "语义：“唱”指发出歌声，与把海报取下来无关。"}, "sentence_index": 0, "correct_answer": "扯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用剪刀扯开了那个信封。", "explanation": "这里应该用〈剪〉。扯是用力拉或撕，用剪刀裁开要用剪，不能用扯。"}, {"text": "妈妈用刀扯开了那块肉。", "explanation": "这里应该用〈切〉。扯靠拉或撕，用刀分开食物要用切，不能用扯。"}, {"text": "她用线扯好了衣服的扣子。", "explanation": "这里应该用〈缝〉。扯是用力拉或撕，缝补扣子要用缝，不能用扯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91842, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "扯", "is_correct": true, "explanation": "扯（chě，第三声）：用力拉或撕开。"}, {"text": "撤", "is_correct": false, "explanation": "chè（第四声）与 chě（第三声）声调不同，意思是撤退。"}, {"text": "齿", "is_correct": false, "explanation": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是牙齿。"}, {"text": "耻", "is_correct": false, "explanation": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是羞耻。"}, {"text": "者", "is_correct": false, "explanation": "zhě 与 chě 声母不同（zh 与 ch），声调相同，意思是人，如作者的“者”。"}], "explanations": {"扯": "扯（chě，第三声）：用力拉或撕开。", "撤": "chè（第四声）与 chě（第三声）声调不同，意思是撤退。", "齿": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是牙齿。", "耻": "chǐ 与 chě 韵母不同（i 与 e），声调相同，意思是羞耻。", "者": "zhě 与 chě 声母不同（zh 与 ch），声调相同，意思是人，如作者的“者”。"}, "sentence_index": null, "correct_answer": "扯"}, "level_3": {"options": [{"text": "扯", "is_correct": true, "explanation": "扯：用力拉住，与“我自己走”所暗示的拉扯情境相符。"}, {"text": "吸", "is_correct": false, "explanation": "搭配：“吸”用于气体、液体，衣服不能被吸。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃衣服。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”不会阻止别人走，与“我自己走”的拉扯情境不符。"}], "explanations": {"扯": "扯：用力拉住，与“我自己走”所暗示的拉扯情境相符。", "吸": "搭配：“吸”用于气体、液体，衣服不能被吸。", "吃": "搭配：“吃”的对象是食物，不能说吃衣服。", "看": "语义：“看”不会阻止别人走，与“我自己走”的拉扯情境不符。"}, "sentence_index": 6, "correct_answer": "扯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用双手把那块石头扯碎了。", "explanation": "这里应该用〈砸〉。扯碎是用力拉或撕，多用于布、纸等柔软物；石头要靠重物击打，应该用砸。"}, {"text": "他用小刀把铅笔扯尖了。", "explanation": "这里应该用〈削〉。削是用刀刮去表皮使物体变尖，扯是用力拉或撕，不能用于削铅笔。"}, {"text": "他气得一拳扯在墙上。", "explanation": "这里应该用〈捶〉。捶是用拳头猛击，扯是用力拉或撕，不能用于击打墙面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那封信碎扯了。", "corrected_sentence": "他把那封信扯碎了。", "error_description": "错误形式：“碎扯了”；正确形式：“扯碎了”。结果补语“碎”要紧跟在动词“扯”后面，表示扯到碎的结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从箱子里出扯了一件旧毛衣。", "corrected_sentence": "他从箱子里扯出了一件旧毛衣。", "error_description": "错误形式：“出扯了”；正确形式：“扯出了”。趋向补语“出”要紧跟在动词“扯”后面，表示从里向外拉出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
