INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91843, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "借助是靠别的东西帮忙做成事。", "primary_collocate": null, "pronunciation": "jiè zhù", "ipa": "tɕjɛ˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他借助手电筒走过了黑黑的小路。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我借助手机查到了公交车的时间。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们借助大机器搬走了石头。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她借助图片给孩子讲了这个故事。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客借助导游的讲解了解了这座古城。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借助一把刀打开了箱子。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生借助视频学会了做蛋糕。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们借助风力让小船走得更快。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李借助朋友的介绍找到了工作。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他借助放大镜看清了纸上的小字。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "借助了", "label": "体标"}, {"form": "借助于", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：靠别的东西帮忙做成事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91843, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只能带食物等可食之物，不能与“手电筒”搭配。"}, {"text": "借助", "is_correct": true, "explanation": "借助是动词，表示借外力来达到目的，这里指靠手电筒照明走过小路，符合句意。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”通常与衣服、鞋袜搭配，不能用于“手电筒”。"}, {"text": "寄", "is_correct": false, "explanation": "配价：“寄”需要收件人，句中缺少对象，读来不通。"}], "explanations": {"吃": "搭配：“吃”只能带食物等可食之物，不能与“手电筒”搭配。", "借助": "借助是动词，表示借外力来达到目的，这里指靠手电筒照明走过小路，符合句意。", "穿": "搭配：“穿”通常与衣服、鞋袜搭配，不能用于“手电筒”。", "寄": "配价：“寄”需要收件人，句中缺少对象，读来不通。"}, "sentence_index": 0, "correct_answer": "借助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我借助三天就看完了这本书。", "explanation": "这里应该用〈只用〉。借助指借外力或条件办事，不能用来表示花费的时间。"}, {"text": "他借助明天去北京。", "explanation": "这里应该用〈打算〉。借助后面要带所借的工具或条件，不能接时间表示计划。"}, {"text": "他借助生病不来上班。", "explanation": "这里应该用〈借口〉。借助指借外力或条件办事，不表示以某事为理由。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91843, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等，不能与“视频”搭配。"}, {"text": "借助", "is_correct": true, "explanation": "借助是动词，表示借视频这一途径学习，与“学会了做蛋糕”搭配，符合句意。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”与“学会了做蛋糕”的结果相矛盾，句意不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的对象应是食物，不能与“视频”搭配。"}], "explanations": {"戴": "搭配：“戴”用于帽子、眼镜等，不能与“视频”搭配。", "借助": "借助是动词，表示借视频这一途径学习，与“学会了做蛋糕”搭配，符合句意。", "反对": "语义：“反对”与“学会了做蛋糕”的结果相矛盾，句意不通。", "煮": "搭配：“煮”的对象应是食物，不能与“视频”搭配。"}, "sentence_index": 6, "correct_answer": "借助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他借助悲伤忘记了过去。", "explanation": "这里表示因果，应该用〈由于〉。借助只表示借外力或条件办事，不能表示原因。"}, {"text": "他借助天太热，没有出门。", "explanation": "这里表示原因，应该用〈因为〉。借助指借外力或条件办事，不能表示原因。"}, {"text": "他借助工作忙没来看我。", "explanation": "这里应该用〈借口〉。借助指借外力或条件办事，不表示以某事为理由。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91843, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他借助看清了远处的船。", "corrected_sentence": "他借助望远镜看清了远处的船。", "error_description": "“借助”是动词，后面必须带出所借的工具，这里缺少宾语“望远镜”。正确说法是“他借助望远镜看清了远处的船”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91843, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们借助得地图找到了山上的小屋。", "corrected_sentence": "我们借助地图找到了山上的小屋。", "error_description": "“借助”后面不能加“得”。“得”用于动词后引出补语，这里不需要。正确说法是“我们借助地图找到了山上的小屋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
