INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91844, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依靠外力或某种条件来达到目的。", "primary_collocate": null, "pronunciation": "jiè zhù", "ipa": "tɕjɛ˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他借助地图找到了那家小店。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们借助网络学习汉语。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王借助一根长棍拿到了树上的球。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她借助翻译软件看懂了这封信。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人借助拐杖慢慢走上了楼。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生借助机器检查病人的身体。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我借助词典读完了这篇文章。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们借助朋友的资金开了一家饭店。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们借助梯子爬上了屋顶。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司借助电视广告让很多人认识了新产品。", "target_word": "借助", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "借助了", "label": "体标"}, {"form": "借助于", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：依靠外力或条件来达到目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撕", "is_correct": false, "explanation": "语义：“撕”会毁掉地图，与“靠地图找到了小店”的意思相矛盾，句子读来不通。"}, {"text": "借助", "is_correct": true, "explanation": "借助是动词，表示借外力或条件来达到目的，这里指靠地图找到小店，符合句意。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：“欢迎”的对象应是人，不能以“地图”作宾语，搭配不当。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与后面靠地图找到小店的结果相反。"}], "explanations": {"撕": "语义：“撕”会毁掉地图，与“靠地图找到了小店”的意思相矛盾，句子读来不通。", "借助": "借助是动词，表示借外力或条件来达到目的，这里指靠地图找到小店，符合句意。", "欢迎": "配价：“欢迎”的对象应是人，不能以“地图”作宾语，搭配不当。", "扔": "语义：“扔”表示丢弃，与后面靠地图找到小店的结果相反。"}, "sentence_index": 0, "correct_answer": "借助"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我借助一个星期就学会了游泳。", "explanation": "这里应该用〈只用〉。借助指借外力或条件办事，不能用来表示花费的时间。"}, {"text": "他借助老师不在，偷偷溜了出去。", "explanation": "这里应该用〈趁〉。借助指借外力或条件办事，不表示利用时机。"}, {"text": "他借助下雨不来上课。", "explanation": "这里应该用〈借口〉。借助指借外力或条件办事，不表示以某事为理由。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：“烧”会毁掉词典，与后面“读完了这篇文章”的凭借关系相矛盾。"}, {"text": "借助", "is_correct": true, "explanation": "借助是动词，表示借词典这一工具完成阅读，符合句意。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“读完了这篇文章”的结果相反，句意自相矛盾。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”的对象应是人或行为，不能以“词典”为对象，搭配不当。"}], "explanations": {"烧": "语义：“烧”会毁掉词典，与后面“读完了这篇文章”的凭借关系相矛盾。", "借助": "借助是动词，表示借词典这一工具完成阅读，符合句意。", "拒绝": "语义：“拒绝”与“读完了这篇文章”的结果相反，句意自相矛盾。", "批评": "配价：“批评”的对象应是人或行为，不能以“词典”为对象，搭配不当。"}, "sentence_index": 6, "correct_answer": "借助"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他借助昨天去了上海。", "explanation": "借助后面要带所借的工具或条件，不能接时间词。这里直接说“他昨天去了上海”。"}, {"text": "她借助开心睡着了。", "explanation": "这里表示因果，应该用〈由于〉。借助只表示借外力或条件办事，不能表示原因。"}, {"text": "他借助一次失败就放弃了学习。", "explanation": "这里应该用〈因为〉。借助指借外力或条件办事，不能表示因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我借助找到了车站。", "corrected_sentence": "我借助导航找到了车站。", "error_description": "“借助”是动词，后面必须带出所借的工具或条件，这里缺少宾语。正确说法是“我借助导航找到了车站”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们借助得网络查资料。", "corrected_sentence": "我们借助网络查资料。", "error_description": "“借助”后面不能加“得”。“得”用于动词后引出补语，这里不需要。正确说法是“我们借助网络查资料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
