INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91845, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名义是做一件事时用的名字或身份。", "primary_collocate": null, "pronunciation": "míng yì", "ipa": "miŋ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "这张卡是用我的名义办的。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以会员的名义进了俱乐部。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用哥哥的名义写了一篇文章。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以朋友的名义，我想问你一件事。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张以代表的名义参加了会议。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行里这笔钱是用爸爸的名义存的。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用班级的名义给老人送了花。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我可以用你的名义订房间吗？", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们以学生的名义去参观了工厂。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店是用姐姐的名义开的。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名义上", "label": "复合"}], "register": "中性", "sense_fingerprint": "做一件事时用的名字或身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91845, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名义", "is_correct": true, "explanation": "名义：做某事时所用的名字或身份。"}, {"text": "名医", "is_correct": false, "explanation": "yī 与 yì 声调不同（阴平与去声），声母韵母相同，意思是名医。"}, {"text": "民意", "is_correct": false, "explanation": "mín 与 míng 的韵尾不同（in 与 ing），声调相同，意思是民众的意愿。"}, {"text": "名利", "is_correct": false, "explanation": "lì 与 yì 声母不同（l 与 y），声调相同，意思是名声和利益。"}], "explanations": {"名义": "名义：做某事时所用的名字或身份。", "名医": "yī 与 yì 声调不同（阴平与去声），声母韵母相同，意思是名医。", "民意": "mín 与 míng 的韵尾不同（in 与 ing），声调相同，意思是民众的意愿。", "名利": "lì 与 yì 声母不同（l 与 y），声调相同，意思是名声和利益。"}, "sentence_index": null, "correct_answer": "名义"}, "level_3": {"options": [{"text": "名义", "is_correct": true, "explanation": "名义：用我的名义办卡，表示以我的身份办理，与句意相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不能用来说明办卡的身份，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与办卡的身份无关，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“用我的体重办卡”不成立，“体重”与此结构无关。"}], "explanations": {"名义": "名义：用我的名义办卡，表示以我的身份办理，与句意相合。", "年龄": "语义：“年龄”不能用来说明办卡的身份，句意不通。", "颜色": "语义：“颜色”与办卡的身份无关，句意不通。", "体重": "搭配：“用我的体重办卡”不成立，“体重”与此结构无关。"}, "sentence_index": 0, "correct_answer": "名义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的名义很好看。", "explanation": "这里应该用〈样式〉。名义指做事时所用的名称或身份，不能用来形容衣服的样子。"}, {"text": "他的名义很响亮，大家都知道。", "explanation": "这里应该用〈名声〉。名义表示做事时的名称或身份，不表示名气。"}, {"text": "我家的名义在北京。", "explanation": "这里应该用〈地址〉。名义不指住址，它表示做事时所用的名称或身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91845, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名义", "is_correct": true, "explanation": "名义：用班级的名义送花，表示以班级的身份行事，与句意相合。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”不能用来说明送花时的身份，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“用班级的身高”不成立，“身高”与此结构无关。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”不能用来说明送花时的身份，句意不通。"}], "explanations": {"名义": "名义：用班级的名义送花，表示以班级的身份行事，与句意相合。", "地点": "语义：“地点”不能用来说明送花时的身份，句意不通。", "身高": "搭配：“用班级的身高”不成立，“身高”与此结构无关。", "心情": "语义：“心情”不能用来说明送花时的身份，句意不通。"}, "sentence_index": 6, "correct_answer": "名义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班买了一只名义，大家都很开心。", "explanation": "这里把名义当成了具体的东西。名义指做事时所用的名称或身份，是抽象名词，不能用量词“只”。"}, {"text": "这本书的名义很好听，我想买。", "explanation": "这里应该用〈书名〉。书名指书的题目，名义表示做事时所用的名称或身份。"}, {"text": "这家饭馆的名义很香，我们都想进去。", "explanation": "名义是抽象的名称或身份，不能指饭菜的味道，这里的用法不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91845, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一只特殊的名义参加了比赛。", "corrected_sentence": "他用一种特殊的名义参加了比赛。", "error_description": "“名义”是抽象名词，量词应用“种”或“个”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91845, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以我地名义写了这封信。", "corrected_sentence": "他以我的名义写了这封信。", "error_description": "“我”修饰“名义”是定语，应用“的”，不能用状语标记“地”；此处应改为“以我的名义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
