INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91846, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做某事时所用的名称、身份或借口。", "primary_collocate": null, "pronunciation": "míng yì", "ipa": "miŋ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他以公司的名义给客人送了礼物。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用朋友的名义借了一笔钱。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们以学校的名义办了一场比赛。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车是用妈妈的名义买的。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打着帮忙的名义，其实是想收钱。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以我个人的名义，我想谢谢大家。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别借工作的名义不回家。", "target_word": "名义", "complexity_tier": "T3", "furigana": "míng yì", "sentence_source": "generated"}, {"text": "她以医生的名义向大家说了几句话。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用爱的名义管着孩子的一切。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你不要以我的名义乱说话。", "target_word": "名义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名义上", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事时所用的名称、身份或借口", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c2c863-16c7-4006-ae6b-2673000b2f08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91846, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名义", "is_correct": true, "explanation": "名义：做某事时所用的名称、身份或借口。"}, {"text": "名医", "is_correct": false, "explanation": "yī 与 yì 声调不同（阴平与去声），声母韵母相同，意思是名医。"}, {"text": "民意", "is_correct": false, "explanation": "mín 与 míng 的韵尾不同（in 与 ing），声调相同，意思是民众的意愿。"}, {"text": "名利", "is_correct": false, "explanation": "lì 与 yì 声母不同（l 与 y），声调相同，意思是名声和利益。"}], "explanations": {"名义": "名义：做某事时所用的名称、身份或借口。", "名医": "yī 与 yì 声调不同（阴平与去声），声母韵母相同，意思是名医。", "民意": "mín 与 míng 的韵尾不同（in 与 ing），声调相同，意思是民众的意愿。", "名利": "lì 与 yì 声母不同（l 与 y），声调相同，意思是名声和利益。"}, "sentence_index": null, "correct_answer": "名义"}, "level_3": {"options": [{"text": "名义", "is_correct": true, "explanation": "名义：以公司的名义送礼，表示以公司身份行事，与句意相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不能说明送礼时的名义或身份，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与送礼的名义无关，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“以公司的体重”不成立，“体重”与此结构无关。"}], "explanations": {"名义": "名义：以公司的名义送礼，表示以公司身份行事，与句意相合。", "年龄": "语义：“年龄”不能说明送礼时的名义或身份，句意不通。", "颜色": "语义：“颜色”与送礼的名义无关，句意不通。", "体重": "搭配：“以公司的体重”不成立，“体重”与此结构无关。"}, "sentence_index": 0, "correct_answer": "名义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的名义很好看。", "explanation": "这里应该用〈样式〉。名义指做事时所用的名称、身份或借口，不能用来形容衣服的样子。"}, {"text": "他很有名义，大家都很喜欢他。", "explanation": "这里应该用〈名声〉。名义表示做事时的名称或身份，不表示名气。"}, {"text": "我的名义在北京，离学校很近。", "explanation": "名义不指居住地，它表示做事时所用的名称或身份，这里用法不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名义", "is_correct": true, "explanation": "名义：借工作的名义不回家，表示以工作为借口，与句意相合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”不能作为不回家的理由，句意不通。"}, {"text": "地点", "is_correct": false, "explanation": "语义：“地点”不能用来说明不回家的理由，句意不通。"}, {"text": "气温", "is_correct": false, "explanation": "语义：“气温”不能作为不回家的借口，句意不通。"}], "explanations": {"名义": "名义：借工作的名义不回家，表示以工作为借口，与句意相合。", "身高": "语义：“身高”不能作为不回家的理由，句意不通。", "地点": "语义：“地点”不能用来说明不回家的理由，句意不通。", "气温": "语义：“气温”不能作为不回家的借口，句意不通。"}, "sentence_index": 6, "correct_answer": "名义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我一只名义，让我去办事。", "explanation": "这里把名义当成了具体的东西。名义指做事时所用的名称或身份，是抽象名词，不能用量词“只”。"}, {"text": "这本书的名义很好听，大家都爱读。", "explanation": "这里应该用〈书名〉。书名指书的题目，名义表示做事时所用的名称或身份。"}, {"text": "这个饭店的名义很香，我们都想吃。", "explanation": "名义是抽象的名称或身份，不能指饭菜的味道，这里的用法不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以一只特殊的名义帮了我们。", "corrected_sentence": "他以一种特殊的名义帮了我们。", "error_description": "“名义”是抽象名词，量词应用“种”或“个”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd68c03e4-9d2d-4de5-9c5b-efb439215c6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
