INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91847, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "雇佣是给钱请人来做事。", "primary_collocate": null, "pronunciation": "gù yōng", "ipa": "ku˥˩ jʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这家饭店雇佣了十个新服务员。", "target_word": "雇佣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板想雇佣一个会说英语的人。", "target_word": "雇佣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈雇佣阿姨每天来家里打扫。", "target_word": "雇佣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不雇佣没有经验的新人。", "target_word": "雇佣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他雇佣过两个司机，但都做得不久。", "target_word": "雇佣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们雇佣了一位老师来教孩子画画。", "target_word": "雇佣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场夏天会雇佣很多人来摘水果。", "target_word": "雇佣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店太小了，不能雇佣更多的人。", "target_word": "雇佣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板雇佣了三个工人，每月都要给他们发工资。", "target_word": "雇佣", "complexity_tier": "T3", "furigana": "lǎobǎn gùyōng le sān ge gōngrén, měi yuè dōu yào gěi tāmen fā gōngzī.", "sentence_source": "generated"}, {"text": "他想雇佣两个工人帮他搬家，可是钱不够。", "target_word": "雇佣", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "雇佣了", "label": "体标"}, {"form": "雇佣着", "label": "体标"}, {"form": "雇佣过", "label": "体标"}, {"form": "僱傭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "给钱请人来做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5a5e0a7-1931-406f-8fa8-4b6b6a09a7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91847, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雇佣", "is_correct": true, "explanation": "雇佣：请人来做事，与饭店请了新服务员相符。"}, {"text": "摆放", "is_correct": false, "explanation": "语义：摆放指把东西放好，不能用来指请人。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除指拆掉建筑或设施，不能用于人。"}, {"text": "请客", "is_correct": false, "explanation": "配价：“请客”是离合词，后面不能直接带“十个新服务员”作宾语。"}], "explanations": {"雇佣": "雇佣：请人来做事，与饭店请了新服务员相符。", "摆放": "语义：摆放指把东西放好，不能用来指请人。", "拆除": "语义：拆除指拆掉建筑或设施，不能用于人。", "请客": "配价：“请客”是离合词，后面不能直接带“十个新服务员”作宾语。"}, "sentence_index": 0, "correct_answer": "雇佣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们雇佣了一套公寓。", "explanation": "这里应该用〈租用〉。雇佣是请人做事，房屋要用“租用”。"}, {"text": "他雇佣了一个果园。", "explanation": "这里应该用〈承包〉。雇佣的对象是人，果园要用“承包”。"}, {"text": "我雇佣了一把剪刀。", "explanation": "这里应该用〈借用〉。雇佣的对象是人，借东西要用“借用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91847, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雇佣", "is_correct": true, "explanation": "雇佣：请人来做事，与农场请人摘水果相符。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：驱赶是赶走，与“来摘水果”矛盾。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：饲养用于动物，不能说“饲养很多人”。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：种植用于植物，不能说“种植很多人”。"}], "explanations": {"雇佣": "雇佣：请人来做事，与农场请人摘水果相符。", "驱赶": "语义：驱赶是赶走，与“来摘水果”矛盾。", "饲养": "搭配：饲养用于动物，不能说“饲养很多人”。", "种植": "搭配：种植用于植物，不能说“种植很多人”。"}, "sentence_index": 6, "correct_answer": "雇佣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他雇佣了一箱水果。", "explanation": "这里应该用〈订购〉。雇佣是请人做事，买东西要用“订购”。"}, {"text": "我们雇佣了一台冰箱。", "explanation": "这里应该用〈购买〉。雇佣的对象是人，买东西要用“购买”。"}, {"text": "这家公司雇佣了一块土地。", "explanation": "这里应该用〈租赁〉。雇佣的对象是人，土地要用“租赁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91847, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板把三个工人雇佣。", "corrected_sentence": "老板把三个工人雇佣了。", "error_description": "错误：“把”字句中动词后缺少“了”。正确：应说“把三个工人雇佣了”，“把”字句的动词后要有成分。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91847, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们雇佣了过一位老师，效果很好。", "corrected_sentence": "我们雇佣过一位老师，效果很好。", "error_description": "错误：动词后同时用了“了”和“过”，体标重复。正确：应只用“过”，说“雇佣过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
