INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91849, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用画或用话，把看到的东西讲出来。", "primary_collocate": null, "pronunciation": "miáo huì", "ipa": "miɑʊ˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "你能描绘一下你看到的人吗？", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向警察描绘了小偷的样子。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子努力描绘他看到的大象。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你描绘一下那座山的样子。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她回来后向我们描绘了海边的景色。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用简单的话描绘了那只小鸟。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们描绘一下窗外的树。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明用画笔描绘他在动物园看到的老虎。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "目击者向警察描绘了那辆车的颜色。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷常常向我描绘他小时候的家。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "描繪", "label": "繁体"}, {"form": "描绘了", "label": "体标"}, {"form": "描绘着", "label": "体标"}, {"form": "描绘过", "label": "体标"}], "register": "书面", "sense_fingerprint": "用画或用话把亲眼看到的样子表现或讲述出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea62575-be54-46e7-9a6e-46e7d7867e98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91849, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "描绘", "is_correct": true, "explanation": "描绘指用话或画把看到的样子讲出来，与句意相符。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：演奏用于乐器或乐曲，不能用于描述人。"}, {"text": "拆解", "is_correct": false, "explanation": "语义：拆解是把物体分开，与“看到的人”不相符。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：缝补是修补破损的织物，与“人”无关。"}], "explanations": {"描绘": "描绘指用话或画把看到的样子讲出来，与句意相符。", "演奏": "搭配：演奏用于乐器或乐曲，不能用于描述人。", "拆解": "语义：拆解是把物体分开，与“看到的人”不相符。", "缝补": "语义：缝补是修补破损的织物，与“人”无关。"}, "sentence_index": 0, "correct_answer": "描绘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民用镰刀描绘了一片麦子。", "explanation": "这里应该用〈收割〉。描绘是用话或画刻画，不表示用镰刀割下庄稼。"}, {"text": "妈妈正在厨房里描绘一锅粥。", "explanation": "这里应该用〈煮〉。描绘不表示用火加热食物做成熟。"}, {"text": "他用火柴描绘了蜡烛。", "explanation": "这里应该用〈点燃〉。描绘不表示用火柴使蜡烛燃烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91849, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "描绘", "is_correct": true, "explanation": "描绘指把看到的树的样子讲出或画出，与“老师让我们”相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：烹饪的对象是食材，不能用于树。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：演奏用于乐器或乐曲，不能用于树。"}, {"text": "装订", "is_correct": false, "explanation": "语义：装订是把纸张订在一起，与“树”无关。"}], "explanations": {"描绘": "描绘指把看到的树的样子讲出或画出，与“老师让我们”相符。", "烹饪": "搭配：烹饪的对象是食材，不能用于树。", "演奏": "搭配：演奏用于乐器或乐曲，不能用于树。", "装订": "语义：装订是把纸张订在一起，与“树”无关。"}, "sentence_index": 6, "correct_answer": "描绘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用洗衣机描绘了那件衣服。", "explanation": "这里应该用〈洗涤〉。描绘是刻画事物，不表示用洗衣机清洁衣物。"}, {"text": "工人用螺丝刀描绘了那扇门。", "explanation": "这里应该用〈拆〉。描绘不表示用螺丝刀把门卸下来。"}, {"text": "他用电子邮箱描绘了一封信。", "explanation": "这里应该用〈发送〉。描绘不表示通过邮箱把信传送出去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91849, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐向我描绘着了昨天的晚霞。", "corrected_sentence": "姐姐向我描绘了昨天的晚霞。", "error_description": "错误形式为“描绘着了”。“着”表示持续或状态，与表示完成的“了”不能同时用在“描绘”后；表示完成只用“了”，应说“描绘了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91849, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用简单的话把那只小鸟描绘很清楚。", "corrected_sentence": "他用简单的话把那只小鸟描绘得很清楚。", "error_description": "错误形式为“描绘很清楚”，正确形式为“描绘得很清楚”。补语“很清楚”前必须加“得”，去掉“得”则句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
