INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91850, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用文字或图画描写刻画。", "primary_collocate": null, "pronunciation": "miáo huì", "ipa": "miɑʊ˧˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "作家用文字描绘了家乡的春天。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位画家喜欢描绘山和水。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书描绘了一百年前的生活。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的小说把老北京描绘得很生动。", "target_word": "描绘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家用颜色描绘夏天的海。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "诗人在诗里描绘过秋天的月亮。", "target_word": "描绘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画描绘的是一个小村子。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想用画笔描绘孩子们的笑脸。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课文描绘了一个下雨的早晨。", "target_word": "描绘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章把农村的生活描绘得很清楚。", "target_word": "描绘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "描繪", "label": "繁体"}, {"form": "描绘了", "label": "体标"}, {"form": "描绘着", "label": "体标"}, {"form": "描绘过", "label": "体标"}], "register": "书面", "sense_fingerprint": "用文字或图画把人、景、事生动地写出或画出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ea62575-be54-46e7-9a6e-46e7d7867e98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "描绘", "is_correct": true, "explanation": "描绘指用文字或图画把景物写出、画出，与“作家用文字”和“春天”相符。"}, {"text": "煮沸", "is_correct": false, "explanation": "语义：煮沸是把水加热到沸腾，与“文字”和“春天”都不搭，句子说不通。"}, {"text": "弹奏", "is_correct": false, "explanation": "搭配：弹奏用于乐器，不能用文字弹奏。"}, {"text": "切割", "is_correct": false, "explanation": "语义：切割是把实物分开，与“文字”和“春天”都不搭。"}], "explanations": {"描绘": "描绘指用文字或图画把景物写出、画出，与“作家用文字”和“春天”相符。", "煮沸": "语义：煮沸是把水加热到沸腾，与“文字”和“春天”都不搭，句子说不通。", "弹奏": "搭配：弹奏用于乐器，不能用文字弹奏。", "切割": "语义：切割是把实物分开，与“文字”和“春天”都不搭。"}, "sentence_index": 0, "correct_answer": "描绘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们用混凝土描绘了一座大桥。", "explanation": "这里应该用〈修建〉。描绘是用文字或图画刻画事物，修建桥梁是建造实体工程，不能用描绘。"}, {"text": "老师傅正在描绘一块玉。", "explanation": "这里应该用〈雕刻〉。描绘是用文字或图画刻画，雕刻是用刀在玉石上刻出形状，不能用描绘。"}, {"text": "工厂每天描绘五百辆汽车。", "explanation": "这里应该用〈制造〉。描绘不表示生产实物，生产汽车要用制造。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "描绘", "is_correct": true, "explanation": "描绘指用图画刻画景物，与“这幅画”和“小村子”相符。"}, {"text": "朗诵", "is_correct": false, "explanation": "搭配：朗诵的对象是诗文，画不能朗诵。"}, {"text": "驾驶", "is_correct": false, "explanation": "语义：驾驶是操纵车船，与“画”和“村子”都不搭。"}, {"text": "修补", "is_correct": false, "explanation": "语义：修补是修理破损之物，画中的村子不能被修补。"}], "explanations": {"描绘": "描绘指用图画刻画景物，与“这幅画”和“小村子”相符。", "朗诵": "搭配：朗诵的对象是诗文，画不能朗诵。", "驾驶": "语义：驾驶是操纵车船，与“画”和“村子”都不搭。", "修补": "语义：修补是修理破损之物，画中的村子不能被修补。"}, "sentence_index": 6, "correct_answer": "描绘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用扳手描绘了那台机器。", "explanation": "这里应该用〈组装〉。描绘是刻画事物，不表示用工具把零件拼成机器。"}, {"text": "他用清水描绘了那只杯子。", "explanation": "这里应该用〈清洗〉。描绘是刻画事物，不表示用水洗净物品。"}, {"text": "裁缝用剪刀描绘了一块布。", "explanation": "这里应该用〈裁剪〉。描绘不表示用剪刀把布剪开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "画家用笔描绘着了湖边的树林。", "corrected_sentence": "画家用笔描绘了湖边的树林。", "error_description": "错误形式为“描绘着了”。“着”表示持续或状态，与表示完成的“了”不能同时用在“描绘”后；表示完成只用“了”，应说“描绘了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用铅笔把窗前的小猫描绘很清楚。", "corrected_sentence": "她用铅笔把窗前的小猫描绘得很清楚。", "error_description": "错误形式为“描绘很清楚”，正确形式为“描绘得很清楚”。补语“很清楚”前必须加“得”，去掉“得”则句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96c8cb48-45b0-4166-939d-c3aabca4f1c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
