INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91851, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "哇是你看到了让你吃惊的事，叫出来的声音。", "primary_collocate": null, "pronunciation": "wā", "ipa": "wa˥", "syllable_count": 1, "sentences": [{"text": "哇，这个蛋糕真大！", "target_word": "哇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哇，你今天穿得真漂亮！", "target_word": "哇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哇，外面下雪了！", "target_word": "哇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哇，这么多书，你都看完了吗？", "target_word": "哇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打开门，说：“哇，好大的房间！”", "target_word": "哇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哇，你一个人做了这么多菜？", "target_word": "哇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哇，这只小狗真可爱！", "target_word": "哇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到海，孩子们叫起来：“哇！”", "target_word": "哇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哇，你的汉语说得真好！", "target_word": "哇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哇，今天的月亮又大又圆！", "target_word": "哇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "看到令人吃惊或赞叹的事时发出的感叹声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d38b327-4414-4368-adb7-46d76c9371a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91851, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哇", "is_correct": true, "explanation": "正确答案：哇（wā，第一声），看到令人吃惊或赞叹的事时发出的感叹声。"}, {"text": "娃", "is_correct": false, "explanation": "wá（第二声）与 wā（第一声）声调不同，娃的意思是小孩儿、娃娃。"}, {"text": "瓦", "is_correct": false, "explanation": "wǎ（第三声）与 wā（第一声）声调不同，瓦的意思是瓦片。"}, {"text": "袜", "is_correct": false, "explanation": "wà（第四声）与 wā（第一声）声调不同，袜的意思是袜子。"}, {"text": "歪", "is_correct": false, "explanation": "wāi 与 wā 韵母不同（ai 与 a），歪的意思是歪斜。"}], "explanations": {"哇": "正确答案：哇（wā，第一声），看到令人吃惊或赞叹的事时发出的感叹声。", "娃": "wá（第二声）与 wā（第一声）声调不同，娃的意思是小孩儿、娃娃。", "瓦": "wǎ（第三声）与 wā（第一声）声调不同，瓦的意思是瓦片。", "袜": "wà（第四声）与 wā（第一声）声调不同，袜的意思是袜子。", "歪": "wāi 与 wā 韵母不同（ai 与 a），歪的意思是歪斜。"}, "sentence_index": null, "correct_answer": "哇"}, "level_3": {"options": [{"text": "哇", "is_correct": true, "explanation": "正确：哇表示看到令人吃惊或赞叹的事时发出的感叹声，与「这个蛋糕真大」的赞叹语境相符。"}, {"text": "咳", "is_correct": false, "explanation": "语义：咳多用于清嗓子或懊悔，与赞叹蛋糕大不符。"}, {"text": "呸", "is_correct": false, "explanation": "语义：呸表示厌恶或唾弃，与赞叹蛋糕大正相反。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：嘘表示让人安静，与赞叹蛋糕大无关。"}], "explanations": {"哇": "正确：哇表示看到令人吃惊或赞叹的事时发出的感叹声，与「这个蛋糕真大」的赞叹语境相符。", "咳": "语义：咳多用于清嗓子或懊悔，与赞叹蛋糕大不符。", "呸": "语义：呸表示厌恶或唾弃，与赞叹蛋糕大正相反。", "嘘": "语义：嘘表示让人安静，与赞叹蛋糕大无关。"}, "sentence_index": 0, "correct_answer": "哇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "田里有很多哇在叫。", "explanation": "这里应该用〈青蛙〉。哇是叹词，不指动物；〈蛙〉与〈哇〉同音（wā），意思不同。"}, {"text": "我哇了一下她的手。", "explanation": "这里应该用〈摸〉。哇是叹词，不能作动词表示触碰。"}, {"text": "哇，我的钱包丢了，我很难过。", "explanation": "这里应该用〈唉〉。哇表示惊讶或赞叹，不用来表达难过、叹息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91851, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哇", "is_correct": true, "explanation": "正确答案：哇（wā，第一声），看到令人吃惊或赞叹的事时发出的感叹声。"}, {"text": "娃", "is_correct": false, "explanation": "wá（第二声）与 wā（第一声）声调不同，娃的意思是小孩儿。"}, {"text": "汪", "is_correct": false, "explanation": "wāng 与 wā 韵母不同（多了 ng 尾），汪的意思是狗叫声。"}, {"text": "瓦", "is_correct": false, "explanation": "wǎ（第三声）与 wā（第一声）声调不同，瓦的意思是瓦片。"}, {"text": "弯", "is_correct": false, "explanation": "wān 与 wā 韵母不同（多了 n 尾），弯的意思是弯曲。"}], "explanations": {"哇": "正确答案：哇（wā，第一声），看到令人吃惊或赞叹的事时发出的感叹声。", "娃": "wá（第二声）与 wā（第一声）声调不同，娃的意思是小孩儿。", "汪": "wāng 与 wā 韵母不同（多了 ng 尾），汪的意思是狗叫声。", "瓦": "wǎ（第三声）与 wā（第一声）声调不同，瓦的意思是瓦片。", "弯": "wān 与 wā 韵母不同（多了 n 尾），弯的意思是弯曲。"}, "sentence_index": null, "correct_answer": "哇"}, "level_3": {"options": [{"text": "哇", "is_correct": true, "explanation": "正确：哇表示惊讶赞叹，与「这只小狗真可爱」的赞美语境相符。"}, {"text": "唉", "is_correct": false, "explanation": "语义：唉表示叹息、懊悔或无奈，与赞美小狗的语境不符。"}, {"text": "哼", "is_correct": false, "explanation": "语义：哼表示不满或轻蔑，与赞美小狗的语境相反。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：嘘表示让人安静，不表示赞叹，与赞美小狗的语境不符。"}], "explanations": {"哇": "正确：哇表示惊讶赞叹，与「这只小狗真可爱」的赞美语境相符。", "唉": "语义：唉表示叹息、懊悔或无奈，与赞美小狗的语境不符。", "哼": "语义：哼表示不满或轻蔑，与赞美小狗的语境相反。", "嘘": "语义：嘘表示让人安静，不表示赞叹，与赞美小狗的语境不符。"}, "sentence_index": 6, "correct_answer": "哇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很想去，哇，没有时间。", "explanation": "这里应该用〈可是〉。哇是叹词，只表示惊叹或赞叹，不能表示转折。"}, {"text": "哇，明天见。", "explanation": "这里应该用〈再见〉。哇表示惊讶或赞叹，不用于告别。"}, {"text": "哇，我是小明。", "explanation": "这里应该用〈你好〉。哇表示惊讶或赞叹，不用于打招呼或自我介绍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91851, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哇，这朵花哇真香！", "corrected_sentence": "哇，这朵花真香！", "error_description": "「哇」是叹词，不能插在主语「这朵花」和谓语「真香」之间；句中多出的这个「哇」应删去。正确说法是「哇，这朵花真香！」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91851, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哇了，那个孩子真聪明！", "corrected_sentence": "哇，那个孩子真聪明！", "error_description": "多加了「了」：「哇」是叹词，后面不能加「了」。正确说法是「哇，那个孩子真聪明！」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
