INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91854, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写作文章或著作。", "primary_collocate": null, "pronunciation": "zhuàn xiě", "ipa": "ʈʂʷan⁵¹ ɕjɛ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这位教授一生撰写了十几本著作。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他退休后开始撰写自己的回忆录。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在报纸上撰写专栏已经五年了。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部历史书由几位专家共同撰写。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想撰写一部关于长江的小说。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王教授正在撰写一本语言学教材。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了撰写这篇论文，她读了很多书。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠给杂志撰写文章赚稿费。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位作家花十年时间撰写了一部传记。", "target_word": "撰写", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人希望亲手撰写家族的历史。", "target_word": "撰写", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "撰写了", "label": "完成体"}, {"form": "撰写着", "label": "持续体"}, {"form": "撰写过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "撰写-写作文章或著作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1253fbc-9288-40c9-a9b1-e95e77d08214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "撰写", "is_correct": true, "explanation": "撰写：写作著作，与“十几本著作”相符。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”指种植，与著作无关。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指烹调食物，与写著作无关。"}, {"text": "盖", "is_correct": false, "explanation": "搭配：“盖”用于房屋、印章等，不能说盖著作。"}], "explanations": {"撰写": "撰写：写作著作，与“十几本著作”相符。", "种": "语义：“种”指种植，与著作无关。", "煮": "语义：“煮”指烹调食物，与写著作无关。", "盖": "搭配：“盖”用于房屋、印章等，不能说盖著作。"}, "sentence_index": 0, "correct_answer": "撰写"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们把房子撰写得很漂亮。", "explanation": "这里应该用〈装修〉。撰写用于文字作品，房子要用装修。"}, {"text": "这家酒厂撰写了一种好酒。", "explanation": "这里应该用〈酿造〉。撰写用于文字，酒要用酿造。"}, {"text": "他撰写了一支舞。", "explanation": "这里应该用〈编排〉。撰写用于文章、著作，舞蹈要用编排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撰写", "is_correct": true, "explanation": "撰写：写作论文，与“这篇论文”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃论文。"}, {"text": "割", "is_correct": false, "explanation": "语义：“割”指用刀切断，与写论文无关。"}, {"text": "腌", "is_correct": false, "explanation": "语义：“腌”指用盐等处理食物，与论文无关。"}], "explanations": {"撰写": "撰写：写作论文，与“这篇论文”相符。", "吃": "搭配：“吃”的对象是食物，不能说吃论文。", "割": "语义：“割”指用刀切断，与写论文无关。", "腌": "语义：“腌”指用盐等处理食物，与论文无关。"}, "sentence_index": 6, "correct_answer": "撰写"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂撰写了一台机器。", "explanation": "这里应该用〈制造〉。撰写用于文字作品，机器要用制造。"}, {"text": "工匠撰写了一座佛像。", "explanation": "这里应该用〈塑〉。撰写用于文字作品，佛像是立体造型，要用塑。"}, {"text": "农民撰写了一片果树。", "explanation": "这里应该用〈种植〉。撰写用于文字，果树要用种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她已经在撰写好了这部著作。", "corrected_sentence": "她已经撰写好了这部著作。", "error_description": "错误形式：“已经在撰写好了”；正确形式：“已经撰写好了”。“在”表示动作正在进行，与表示完成的“好了”矛盾，不能同用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在撰写了一本词典。", "corrected_sentence": "他正在撰写一本词典。", "error_description": "错误形式：“正在撰写了”；正确形式：“正在撰写”。“正在”表示动作进行中，不能与表示完成的“了”同用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
