INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91858, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "哥哥的简称。", "primary_collocate": null, "pronunciation": "gē", "ipa": "kɤ˥", "syllable_count": 1, "sentences": [{"text": "我哥在北京工作。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥每天早上跑步。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哥是一名医生。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的哥今年二十岁。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥送给我一个新手机。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我哥带我去公园了。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哥喜欢踢足球。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥比我高很多。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥会做饭，做得很好吃。", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你哥现在住在哪儿？", "target_word": "哥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大哥", "label": "复合"}], "register": "口语", "sense_fingerprint": "名词：哥哥的简称，多说我哥、你哥、他哥，指亲哥哥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e29bc64e-453d-4bb9-9adb-ad6f4c6b55a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91858, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "哥", "is_correct": true, "explanation": "哥 gē 为本词，指哥哥，是对亲哥哥的称呼"}, {"text": "棵", "is_correct": false, "explanation": "kē 与 gē 声母不同（k 送气，g 不送气），意思是量词“棵”"}, {"text": "隔", "is_correct": false, "explanation": "gé（第二声）与 gē（第一声）声调不同，意思是“隔开”"}, {"text": "各", "is_correct": false, "explanation": "gè（第四声）与 gē（第一声）声调不同，意思是“各自”"}], "explanations": {"哥": "哥 gē 为本词，指哥哥，是对亲哥哥的称呼", "棵": "kē 与 gē 声母不同（k 送气，g 不送气），意思是量词“棵”", "隔": "gé（第二声）与 gē（第一声）声调不同，意思是“隔开”", "各": "gè（第四声）与 gē（第一声）声调不同，意思是“各自”"}, "sentence_index": null, "correct_answer": "哥"}, "level_3": {"options": [{"text": "哥", "is_correct": true, "explanation": "哥指亲哥哥，“我哥在北京工作”中指说话人的哥哥，符合句意"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会在北京工作，不能指人"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“在北京工作”的主语须是人或单位，“饭”不能搭配"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有工作的能力，句意不通"}], "explanations": {"哥": "哥指亲哥哥，“我哥在北京工作”中指说话人的哥哥，符合句意", "椅子": "语义：椅子不会在北京工作，不能指人", "饭": "搭配：“在北京工作”的主语须是人或单位，“饭”不能搭配", "书": "语义：书没有工作的能力，句意不通"}, "sentence_index": 0, "correct_answer": "哥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明的哥是女生，今年二十岁。", "explanation": "这里应该用〈姐〉。哥只指哥哥，说女性要用姐"}, {"text": "小明的哥是他爸爸的哥哥，今年五十岁。", "explanation": "这里应该用〈伯伯〉。哥指自己的哥哥，爸爸的哥哥要叫伯伯"}, {"text": "小明的哥比他小三岁，今年二十岁。", "explanation": "这里应该用〈弟〉。哥指比自己大的哥哥，与“比他小三岁”矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2449332-8818-4cdf-b350-9a46151234f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91858, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "哥", "is_correct": true, "explanation": "哥 gē 为本词，指哥哥，是对亲哥哥的称呼"}, {"text": "科", "is_correct": false, "explanation": "kē 与 gē 声母不同（k 送气，g 不送气），意思是“科学”"}, {"text": "格", "is_correct": false, "explanation": "gé（第二声）与 gē（第一声）声调不同，意思是“格子”"}, {"text": "个", "is_correct": false, "explanation": "gè（第四声）与 gē（第一声）声调不同，意思是量词“个”"}], "explanations": {"哥": "哥 gē 为本词，指哥哥，是对亲哥哥的称呼", "科": "kē 与 gē 声母不同（k 送气，g 不送气），意思是“科学”", "格": "gé（第二声）与 gē（第一声）声调不同，意思是“格子”", "个": "gè（第四声）与 gē（第一声）声调不同，意思是量词“个”"}, "sentence_index": null, "correct_answer": "哥"}, "level_3": {"options": [{"text": "哥", "is_correct": true, "explanation": "哥指亲哥哥，“他哥喜欢踢足球”中指他的哥哥，符合句意"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不会踢足球，句意不通"}, {"text": "门", "is_correct": false, "explanation": "语义：门不能喜欢踢足球"}, {"text": "车", "is_correct": false, "explanation": "搭配：“喜欢踢足球”的主语须是人，车不搭配"}], "explanations": {"哥": "哥指亲哥哥，“他哥喜欢踢足球”中指他的哥哥，符合句意", "雨": "语义：雨不会踢足球，句意不通", "门": "语义：门不能喜欢踢足球", "车": "搭配：“喜欢踢足球”的主语须是人，车不搭配"}, "sentence_index": 6, "correct_answer": "哥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你哥是个女孩，现在住在哪儿？", "explanation": "这里应该用〈姐〉。哥只指哥哥，说女性要用姐"}, {"text": "你哥是你妈妈的哥哥，现在住在哪儿？", "explanation": "这里应该用〈舅舅〉。哥指自己的哥哥，妈妈的哥哥要叫舅舅"}, {"text": "你哥比你小，现在住在哪儿？", "explanation": "这里应该用〈弟〉。哥指比自己大的哥哥，与“比你小”矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2449332-8818-4cdf-b350-9a46151234f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
