INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91859, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带在身上。", "primary_collocate": null, "pronunciation": "xié dài", "ipa": "ɕjɛ³⁵ taɪ⁵¹", "syllable_count": 2, "sentences": [{"text": "坐飞机不能携带刀具。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门请携带身份证。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他随身携带一本小书。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她携带着很多行李上了车。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进山的人要携带足够的水。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出差时，他习惯携带一把伞。", "target_word": "携带", "complexity_tier": "T3", "furigana": "chū chāi shí, tā xí guàn xié dài yì bǎ sǎn.", "sentence_source": "generated"}, {"text": "游客不得携带宠物进入。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有携带手机，所以没接到电话。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不携带现金出门。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生携带药箱走进了村子。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "携带了", "label": "完成体"}, {"form": "携带着", "label": "持续体"}, {"form": "携带过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "携带：把物品带在身上或带在身边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33259699-dfd2-43c8-bf62-e169fa2186e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91859, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "携带", "is_correct": true, "explanation": "携带：随身带着物品，与“坐飞机不能”的安检限制相合。"}, {"text": "饮用", "is_correct": false, "explanation": "搭配：“饮用”的对象是饮品，不能与“刀具”搭配。"}, {"text": "翻阅", "is_correct": false, "explanation": "搭配：“翻阅”的对象是书报资料，不能与“刀具”搭配。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的对象是植物或土地，不能用于刀具，句子说不通。"}], "explanations": {"携带": "携带：随身带着物品，与“坐飞机不能”的安检限制相合。", "饮用": "搭配：“饮用”的对象是饮品，不能与“刀具”搭配。", "翻阅": "搭配：“翻阅”的对象是书报资料，不能与“刀具”搭配。", "浇灌": "搭配：“浇灌”的对象是植物或土地，不能用于刀具，句子说不通。"}, "sentence_index": 0, "correct_answer": "携带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他携带了一个好办法。", "explanation": "这里应该用〈想出〉。携带指把能随身带的物品带在身上，不能用于抽象的办法。"}, {"text": "她携带了一首歌。", "explanation": "这里应该用〈唱〉。携带指带在身上的物件，不能用于歌曲；唱歌才是对歌曲的动作。"}, {"text": "她携带了一栋房子。", "explanation": "这里应该用〈买〉。携带只用于能随身带的物品，房子不能带在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91859, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "携带", "is_correct": true, "explanation": "携带：随身带着，与“游客不得……进入”的携带限制相合。"}, {"text": "饲养", "is_correct": false, "explanation": "语义：“饲养”指长期养育，与“不得……进入”的入场限制语境不符。"}, {"text": "抚摸", "is_correct": false, "explanation": "语义：“抚摸”是接触动作，与“不得……进入”的限制无关，句意不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能用于宠物，“游客不得驾驶宠物进入”不成立。"}], "explanations": {"携带": "携带：随身带着，与“游客不得……进入”的携带限制相合。", "饲养": "语义：“饲养”指长期养育，与“不得……进入”的入场限制语境不符。", "抚摸": "语义：“抚摸”是接触动作，与“不得……进入”的限制无关，句意不通。", "驾驶": "搭配：“驾驶”的对象是车辆，不能用于宠物，“游客不得驾驶宠物进入”不成立。"}, "sentence_index": 6, "correct_answer": "携带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他携带一座农场。", "explanation": "这里应该用〈拥有〉。携带指随身拿着，只能用于可以随身带的物件，不能指不动产。"}, {"text": "医生携带着车进了村子。", "explanation": "这里应该用〈开〉。携带只用于随身拿着的物件，车辆要靠驾驶，不能携带。"}, {"text": "医生携带了一座医院。", "explanation": "这里应该用〈建〉。携带只用于能随身带的物品，医院这类建筑不能带在身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91859, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人出门时把携带一把旧伞。", "corrected_sentence": "老人出门时携带一把旧伞。", "error_description": "错误在“携带”前多加了“把”。“把”字句要求“把+宾语+动词+补语”，单独的“把携带”没有宾语位置，且句子不成立。应删去“把”，为“携带一把旧伞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91859, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每次出门都携带过钥匙。", "corrected_sentence": "他每次出门都携带着钥匙。", "error_description": "错误在“携带”后用了“过”。“过”表示经历，与“每次出门都”表示的习惯性持续不符，应用持续态“着”。应为“携带着钥匙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
