INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91860, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "随身带着。", "primary_collocate": null, "pronunciation": "xié dài", "ipa": "ɕjɛ³⁵ taɪ⁵¹", "syllable_count": 2, "sentences": [{"text": "他每天都携带着雨伞。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她随时携带笔记本，记下想法。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时不能携带手机。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察携带武器进入房间。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国前，他携带了两张银行卡。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人身上携带着家人的照片。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外出时请携带自己的贵重物品。", "target_word": "携带", "complexity_tier": "T3", "furigana": "wài chū shí, qǐng xié dài zì jǐ de guì zhòng wù pǐn.", "sentence_source": "generated"}, {"text": "他携带着一把旧吉他走遍各地。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子携带午饭去学校。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野外旅行要携带急救包。", "target_word": "携带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "携带了", "label": "完成体"}, {"form": "携带着", "label": "持续体"}, {"form": "携带过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "携带：随身带着某物，强调不离身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33259699-dfd2-43c8-bf62-e169fa2186e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91860, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "携带", "is_correct": true, "explanation": "携带：随身带着，与“每天都”和“着”所表示的持续随身相合。"}, {"text": "倒", "is_correct": false, "explanation": "搭配：“倒”指倾倒液体，不与“雨伞”搭配。"}, {"text": "吞咽", "is_correct": false, "explanation": "语义：“吞咽”的对象是食物或液体，不能用于雨伞，句意不通。"}, {"text": "研磨", "is_correct": false, "explanation": "语义：“研磨”指碾碎，与雨伞无关，句意不通。"}], "explanations": {"携带": "携带：随身带着，与“每天都”和“着”所表示的持续随身相合。", "倒": "搭配：“倒”指倾倒液体，不与“雨伞”搭配。", "吞咽": "语义：“吞咽”的对象是食物或液体，不能用于雨伞，句意不通。", "研磨": "语义：“研磨”指碾碎，与雨伞无关，句意不通。"}, "sentence_index": 0, "correct_answer": "携带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她携带着一座小山走进了屋。", "explanation": "这里应该用〈看着〉。携带只用于能随身带的物品，山不能带在身上。"}, {"text": "他携带了一个古老的故事。", "explanation": "这里应该用〈讲述〉。携带指随身拿着物件，不能用于抽象的故事。"}, {"text": "他携带门走进屋。", "explanation": "这里应该用〈打开〉。携带不能用于门这类固定的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "携带", "is_correct": true, "explanation": "携带：随身带着，与“外出时请”的随身要求相合。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”与“请”所表示的要求相反，句意矛盾。"}, {"text": "食用", "is_correct": false, "explanation": "搭配：“食用”针对食物，不能用于“贵重物品”。"}, {"text": "抵押", "is_correct": false, "explanation": "语义：“抵押”指以物作担保，与“外出时请”随身携带的语境不符。"}], "explanations": {"携带": "携带：随身带着，与“外出时请”的随身要求相合。", "丢失": "语义：“丢失”与“请”所表示的要求相反，句意矛盾。", "食用": "搭配：“食用”针对食物，不能用于“贵重物品”。", "抵押": "语义：“抵押”指以物作担保，与“外出时请”随身携带的语境不符。"}, "sentence_index": 6, "correct_answer": "携带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们携带了一片森林。", "explanation": "这里应该用〈保护〉。携带指随身拿着的物件，不能用于森林这类大片自然区域；保护森林才是正确搭配。"}, {"text": "学生们认真地携带考试。", "explanation": "这里应该用〈参加〉。携带不能与“考试”搭配，参加考试才是正确搭配。"}, {"text": "工人们携带了一座新桥。", "explanation": "这里应该用〈建造〉。携带只用于能随身拿着的物件，不能用于建造桥梁这类大型固定设施。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人身上把携带着一本旧书。", "corrected_sentence": "老人身上携带着一本旧书。", "error_description": "错误在“携带”前多加了“把”。“把”字句要求“把+宾语+动词+补语”，“把携带着”缺少宾语位置，句子不成立。应删去“把”，为“老人身上携带着一本旧书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她总是随身携带过药品。", "corrected_sentence": "她总是随身携带着药品。", "error_description": "错误在“携带”后用了“过”。“过”表示经历，与“总是”表示的习惯不相符，应用“着”表示持续随身。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b374449b-a511-4b65-9f90-cfd9464aa0ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
