INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91861, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全书是整本书。", "primary_collocate": null, "pronunciation": "quán shū", "ipa": "tɕʰɥɛn˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "这本书我从头到尾读完了，全书一共有十章。", "target_word": "全书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全书一共三百页，我一个星期就看完了。", "target_word": "全书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说全书的重点都在第一章。", "target_word": "全书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全书只有一个主角，他是一名年轻的医生。", "target_word": "全书", "complexity_tier": "T3", "furigana": "quán shū zhǐ yǒu yí ge zhǔjué, tā shì yì míng niánqīng de yīshēng.", "sentence_source": "generated"}, {"text": "我把全书看了两遍，还是不太懂。", "target_word": "全书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全书的最后一页有一张地图。", "target_word": "全书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本画册很薄，全书都是照片，没有多少字。", "target_word": "全书", "complexity_tier": "T3", "furigana": "zhè běn huàcè hěn báo, quán shū dōu shì zhàopiàn, méiyǒu duōshao zì.", "sentence_source": "generated"}, {"text": "你不用读全书，只要看目录就知道内容了。", "target_word": "全书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者在前言里介绍了全书的内容。", "target_word": "全书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全书分为上下两部分，每部分都很有意思。", "target_word": "全书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "整本书", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5a5e0a7-1931-406f-8fa8-4b6b6a09a7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91861, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "全书", "is_correct": true, "explanation": "全书：整本书。"}, {"text": "权术", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是权谋手段。"}, {"text": "全数", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，意思是全部的数目。"}, {"text": "全收", "is_correct": false, "explanation": "shōu 与 shū 韵母不同（ou 与 u），意思是全部收下。"}, {"text": "全熟", "is_correct": false, "explanation": "shú（第二声）与 shū（第一声）声调不同，意思是完全煮熟。"}], "explanations": {"全书": "全书：整本书。", "权术": "shù（第四声）与 shū（第一声）声调不同，意思是权谋手段。", "全数": "shù（第四声）与 shū（第一声）声调不同，意思是全部的数目。", "全收": "shōu 与 shū 韵母不同（ou 与 u），意思是全部收下。", "全熟": "shú（第二声）与 shū（第一声）声调不同，意思是完全煮熟。"}, "sentence_index": null, "correct_answer": "全书"}, "level_3": {"options": [{"text": "全书", "is_correct": true, "explanation": "全书：整本书的全部内容，与“一共有十章”相符。"}, {"text": "封面", "is_correct": false, "explanation": "语义：封面是书的外皮，不能分成十章。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者是人，不能说“一共有十章”。"}, {"text": "书名", "is_correct": false, "explanation": "搭配：“有十章”说的是内容的分段，书名不能分章。"}], "explanations": {"全书": "全书：整本书的全部内容，与“一共有十章”相符。", "封面": "语义：封面是书的外皮，不能分成十章。", "作者": "语义：作者是人，不能说“一共有十章”。", "书名": "搭配：“有十章”说的是内容的分段，书名不能分章。"}, "sentence_index": 0, "correct_answer": "全书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章全书只有三页。", "explanation": "这里应该用〈全文〉。全书指一本书的全部，这里说的是一篇文章，要用全文。"}, {"text": "这部交响曲的全书有四个乐章。", "explanation": "这里应该用〈全曲〉。全书指书籍的全部，乐曲的全部要用全曲。"}, {"text": "这出京剧的全书演了四个小时。", "explanation": "这里应该用〈全本〉。戏曲的完整版叫全本，全书只指书籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91861, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "全书", "is_correct": true, "explanation": "全书：整本书。"}, {"text": "拳术", "is_correct": false, "explanation": "拳术 quánshù：shù（第四声）与 shū（第一声）声调不同，意思是拳法武术。"}, {"text": "权属", "is_correct": false, "explanation": "权属 quánshǔ：shǔ（第三声）与 shū（第一声）声调不同，意思是权利的归属。"}, {"text": "圈数", "is_correct": false, "explanation": "圈数 quānshù：quān 与 quán、shù 与 shū 声调都不同，意思是绕圈的次数。"}], "explanations": {"全书": "全书：整本书。", "拳术": "拳术 quánshù：shù（第四声）与 shū（第一声）声调不同，意思是拳法武术。", "权属": "权属 quánshǔ：shǔ（第三声）与 shū（第一声）声调不同，意思是权利的归属。", "圈数": "圈数 quānshù：quān 与 quán、shù 与 shū 声调都不同，意思是绕圈的次数。"}, "sentence_index": null, "correct_answer": "全书"}, "level_3": {"options": [{"text": "全书", "is_correct": true, "explanation": "全书：整本书，所指的内容与“都是照片”相符。"}, {"text": "文字", "is_correct": false, "explanation": "语义：文字指字，与“都是照片，没有多少字”矛盾。"}, {"text": "厚度", "is_correct": false, "explanation": "语义：厚度是厚薄的程度，不能说“都是照片”。"}, {"text": "页数", "is_correct": false, "explanation": "搭配：“都是照片”说的是内容，页数是数字，不能是照片。"}], "explanations": {"全书": "全书：整本书，所指的内容与“都是照片”相符。", "文字": "语义：文字指字，与“都是照片，没有多少字”矛盾。", "厚度": "语义：厚度是厚薄的程度，不能说“都是照片”。", "页数": "搭配：“都是照片”说的是内容，页数是数字，不能是照片。"}, "sentence_index": 6, "correct_answer": "全书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首长诗的全书有一万行。", "explanation": "这里应该用〈全篇〉。全书指整部书，诗歌是一篇作品，要用全篇。"}, {"text": "这份试卷的全书只有三页。", "explanation": "这里应该用〈全卷〉。全书指整部书，试卷的全部要用全卷。"}, {"text": "这部电影的全书有两个小时。", "explanation": "这里应该用〈全片〉。全书指书籍的全部，电影的全部要用全片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经看完着全书，觉得很有意思。", "corrected_sentence": "我已经看完了全书，觉得很有意思。", "error_description": "体标错误：“看完”表示动作已经完成，要用“了”，不能用表示持续的“着”。应说“看完了全书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他完写了全书，用了三年时间。", "corrected_sentence": "他写完了全书，用了三年时间。", "error_description": "错误：结果补语“完”放在动词“写”前面。正确：应说“写完了”，“完”要紧跟在动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
