INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91864, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "台湾地区指初中（国民中学）。", "primary_collocate": null, "pronunciation": "guó zhōng", "ipa": "kuo˧˥ ʈʂʊŋ˥", "syllable_count": 2, "sentences": [{"text": "我弟弟今年上国中二年级。", "target_word": "国中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国中毕业以后，他想去读高中。", "target_word": "国中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在国中教了十年英文。", "target_word": "国中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的国中离家很近。", "target_word": "国中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹刚考上一所很好的国中。", "target_word": "国中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国中的同学今天要来家里吃饭。", "target_word": "国中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他国中时就喜欢打篮球。", "target_word": "国中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们国中的老师人很好。", "target_word": "国中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明明年就要从国中毕业了。", "target_word": "国中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国中放学后，孩子们走路回家。", "target_word": "国中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國中", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国中：台湾地区指初中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d38b327-4414-4368-adb7-46d76c9371a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91864, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国中", "is_correct": true, "explanation": "正确：国中是台湾指初中的说法，「上国中二年级」即初二。"}, {"text": "幼儿园", "is_correct": false, "explanation": "语义：幼儿园没有「二年级」这种分级，与句中的「二年级」相矛盾。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：「上公司」指去上班，不能与「二年级」搭配。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不分年级，「上医院二年级」说不通。"}], "explanations": {"国中": "正确：国中是台湾指初中的说法，「上国中二年级」即初二。", "幼儿园": "语义：幼儿园没有「二年级」这种分级，与句中的「二年级」相矛盾。", "公司": "搭配：「上公司」指去上班，不能与「二年级」搭配。", "医院": "语义：医院不分年级，「上医院二年级」说不通。"}, "sentence_index": 0, "correct_answer": "国中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天国中很晴朗，不会下雨。", "explanation": "这里应该用〈天气〉。国中是学校，不能用来说天气。"}, {"text": "我妈妈去国中买菜。", "explanation": "这里应该用〈超市〉。国中是学校，不是买菜的地方。"}, {"text": "我的国中是一本很厚的书。", "explanation": "这里应该用〈课本〉。国中是初中，指学校，不能指一本书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91864, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国中", "is_correct": true, "explanation": "正确：国中指初中，「他国中时」表示他上初中的那段时间，与句意相符。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不是学习阶段，「他银行时就喜欢打篮球」说不通。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园不表示人的成长阶段，与句意不符。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：「公司时」不表示一段时间，不能这样用来表示人生阶段。"}], "explanations": {"国中": "正确：国中指初中，「他国中时」表示他上初中的那段时间，与句意相符。", "银行": "语义：银行不是学习阶段，「他银行时就喜欢打篮球」说不通。", "动物园": "语义：动物园不表示人的成长阶段，与句意不符。", "公司": "搭配：「公司时」不表示一段时间，不能这样用来表示人生阶段。"}, "sentence_index": 6, "correct_answer": "国中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国中很好吃。", "explanation": "这里应该用〈午饭〉。国中是学校，不能用来形容味道。"}, {"text": "我爸爸下午去国中看病。", "explanation": "这里应该用〈医院〉。国中是学校，不是看病的地方。"}, {"text": "我们坐国中去台北。", "explanation": "这里应该用〈火车〉。国中是学校，不是交通工具，不能用来乘坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91864, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家附近有一条很好的国中。", "corrected_sentence": "我家附近有一所很好的国中。", "error_description": "量词错误：学校用「所」，不用「条」（「条」用于路、河、鱼等）。正确说法是「一所国中」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91864, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐三年前就向国中毕业了。", "corrected_sentence": "我姐姐三年前就从国中毕业了。", "error_description": "介词错误：「毕业」表示从某所学校毕业，应用「从」，不能用「向」；正确说法是「从国中毕业」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
