INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责国家政治事务和管理的组织。", "primary_collocate": null, "pronunciation": "zhèng zhì jī gòu", "ipa": "ʈʂəŋ˥˩ ʈʂʐ̩˥˩ tɕi˥ kou˥˩", "syllable_count": 4, "sentences": [{"text": "政府是管理国家的政治机构。", "target_word": "政治机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议会也是重要的政治机构。", "target_word": "政治机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治机构要处理很多国家大事。", "target_word": "政治机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个国家都有自己的政治机构。", "target_word": "政治机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政治机构负责管理全国的事务。", "target_word": "政治机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的政治机构已经成立了。", "target_word": "政治机构", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他研究过世界各国的政治机构。", "target_word": "政治机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治机构的工作人员要遵守法律。", "target_word": "政治机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政治机构做得好，人民就满意。", "target_word": "政治机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政治机构有三百多个工作人员。", "target_word": "政治机构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "政治機構", "label": "繁体"}], "register": "书面", "sense_fingerprint": "负责国家政治事务和管理的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '501e030f-9419-4045-ab4d-0d12862286c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "政治机构", "is_correct": true, "explanation": "正确：“政治机构”指负责国家政治事务和管理的组织，与“管理国家”相符。"}, {"text": "亲戚", "is_correct": false, "explanation": "语义：亲戚是家族成员，不是管理国家的组织。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是天空中的自然现象，不是组织，不能管理国家。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏是娱乐活动，不能管理国家。"}], "explanations": {"政治机构": "正确：“政治机构”指负责国家政治事务和管理的组织，与“管理国家”相符。", "亲戚": "语义：亲戚是家族成员，不是管理国家的组织。", "云": "语义：云是天空中的自然现象，不是组织，不能管理国家。", "游戏": "语义：游戏是娱乐活动，不能管理国家。"}, "sentence_index": 0, "correct_answer": "政治机构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个政治机构每年都赚很多钱，利润很高。", "explanation": "这里应该用〈企业〉。政治机构负责国家事务，不以赚钱为目的，“利润”属于企业。"}, {"text": "这个政治机构有两百多名医生，都在这里看病。", "explanation": "这里应该用〈医院〉。政治机构不是看病的地方，医生不在这里工作。"}, {"text": "我每个星期都去政治机构取钱。", "explanation": "这里应该用〈银行〉。政治机构不办理取款业务，“取钱”要去银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "政治机构", "is_correct": true, "explanation": "正确：“研究”可以以“政治机构”为对象，与“世界各国的”相符。"}, {"text": "北京", "is_correct": false, "explanation": "语义：北京是某一座城市，不是各国都有的事物。"}, {"text": "长城", "is_correct": false, "explanation": "语义：长城是中国的建筑，不是世界各国普遍存在的事物。"}, {"text": "老大", "is_correct": false, "explanation": "语域：“老大”是口语化的称呼，与书面语的语域不符。"}], "explanations": {"政治机构": "正确：“研究”可以以“政治机构”为对象，与“世界各国的”相符。", "北京": "语义：北京是某一座城市，不是各国都有的事物。", "长城": "语义：长城是中国的建筑，不是世界各国普遍存在的事物。", "老大": "语域：“老大”是口语化的称呼，与书面语的语域不符。"}, "sentence_index": 6, "correct_answer": "政治机构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月都去政治机构游泳。", "explanation": "这里应该用〈游泳池〉。政治机构不是游泳的地方，“游泳”要去游泳池。"}, {"text": "妈妈晚上去政治机构健身。", "explanation": "这里应该用〈健身房〉。政治机构不是健身的场所，“健身”要去健身房。"}, {"text": "我们每天都在政治机构买菜。", "explanation": "这里应该用〈菜市场〉。政治机构不卖蔬菜，“买菜”要去菜市场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个国家有三只政治机构。", "corrected_sentence": "那个国家有三个政治机构。", "error_description": "量词错误：“政治机构”用量词“个”计量，“只”用于动物，不能说“三只政治机构”，应说“三个政治机构”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只政治机构很大。", "corrected_sentence": "这个政治机构很大。", "error_description": "量词错误：“政治机构”应该用量词“个”，“只”多用于动物，不能用来数机构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
