INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91867, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "八卦是别人家里小事的闲话，也指议论这类闲话的行为。", "primary_collocate": null, "pronunciation": "bā guà", "ipa": "pa˥ kwa˥˩", "syllable_count": 2, "sentences": [{"text": "邻居们在楼下聊八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢听别人家的八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶最爱和邻居说八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里的人午饭后都爱聊八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一说起八卦就停不下来。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别在孩子面前讲八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隔壁王太太总打听我们家的八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没时间听你们的八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们喝茶的时候又说起了八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些八卦都是别人家的小事。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "八卦新闻", "label": "复合"}, {"form": "八卦消息", "label": "复合"}], "register": "口语", "sense_fingerprint": "爱议论别人家里的小事和闲话，聊家长里短", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91867, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "八卦", "is_correct": true, "explanation": "“八卦”指爱说别人家里的小事和闲话，“聊八卦”符合邻居闲聊的场景。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是机械零件，不是邻居聊天的话题。"}, {"text": "氧气", "is_correct": false, "explanation": "语义：氧气是气体，邻居在楼下聊天时不会拿它当话题。"}, {"text": "公务", "is_correct": false, "explanation": "语域：公务指公事，邻居在楼下闲聊时不这样说。"}], "explanations": {"八卦": "“八卦”指爱说别人家里的小事和闲话，“聊八卦”符合邻居闲聊的场景。", "螺丝": "语义：螺丝是机械零件，不是邻居聊天的话题。", "氧气": "语义：氧气是气体，邻居在楼下聊天时不会拿它当话题。", "公务": "语域：公务指公事，邻居在楼下闲聊时不这样说。"}, "sentence_index": 0, "correct_answer": "八卦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们的八卦下周开始执行。", "explanation": "这里应该用〈计划〉。八卦指闲话和传闻，不能用来指要执行的计划。"}, {"text": "他把我们的八卦写进了合同。", "explanation": "这里应该用〈条款〉。八卦指闲话和传闻，不能写进合同作为条款。"}, {"text": "经理宣布了一个八卦。", "explanation": "这里应该用〈消息〉。八卦指私下流传的闲话，不能用于正式宣布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91867, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "八卦", "is_correct": true, "explanation": "“八卦”指爱说别人家的小事和闲话，“打听”的正是这类内容。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔指高度，不是可以打听的家事。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数是文字的数量，不是可以打听的家事。"}, {"text": "公文", "is_correct": false, "explanation": "语域：公文是正式文书，闲话里的家事不用这个词。"}], "explanations": {"八卦": "“八卦”指爱说别人家的小事和闲话，“打听”的正是这类内容。", "海拔": "语义：海拔指高度，不是可以打听的家事。", "字数": "语义：字数是文字的数量，不是可以打听的家事。", "公文": "语域：公文是正式文书，闲话里的家事不用这个词。"}, "sentence_index": 6, "correct_answer": "八卦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈正在厨房里煮一个八卦。", "explanation": "这里应该用〈汤〉。八卦是闲谈，不能用来煮。"}, {"text": "这辆八卦跑得很快。", "explanation": "这里应该用〈汽车〉。八卦是闲话，不能跑。"}, {"text": "老师出了一道八卦。", "explanation": "这里应该用〈考题〉。八卦是闲谈，不能用于出题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
