INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她被八卦告诉了我。", "corrected_sentence": "她把八卦告诉了我。", "error_description": "错误形式：“被”代替“把”，使“八卦”像施事一样“告诉”别人。正确形式：“她把八卦告诉了我”，“把”引出受事“八卦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
