INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "流传的闲谈或小道消息，多指明星或同事的传闻。", "primary_collocate": null, "pronunciation": "bā guà", "ipa": "pa˥ kwa˥˩", "syllable_count": 2, "sentences": [{"text": "网上有很多明星的八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条八卦不知道是真的还是假的。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天在群里听到一个八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都看娱乐圈的八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学之间传着一个关于老师的八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个八卦传得很快，大家都知道了。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你听说公司的八卦了吗？", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小道消息和八卦常常不是真的。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说：这只是个八卦，别当真。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上登了一条明星的八卦。", "target_word": "八卦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "八卦消息", "label": "复合"}, {"form": "娱乐八卦", "label": "复合"}], "register": "口语", "sense_fingerprint": "流传的小道消息，多指明星或同事的传闻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "八卦", "is_correct": true, "explanation": "“八卦”指流传的明星或同事传闻，“明星的八卦”符合句意。"}, {"text": "齿轮", "is_correct": false, "explanation": "语义：齿轮是机械零件，不是网上流传的明星传闻。"}, {"text": "矿石", "is_correct": false, "explanation": "语义：矿石是岩石，不指明星的传闻。"}, {"text": "决议", "is_correct": false, "explanation": "语域：决议是正式的决定，不用于明星的传闻。"}], "explanations": {"八卦": "“八卦”指流传的明星或同事传闻，“明星的八卦”符合句意。", "齿轮": "语义：齿轮是机械零件，不是网上流传的明星传闻。", "矿石": "语义：矿石是岩石，不指明星的传闻。", "决议": "语域：决议是正式的决定，不用于明星的传闻。"}, "sentence_index": 0, "correct_answer": "八卦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校昨天发了一份八卦。", "explanation": "这里应该用〈通告〉。八卦是流传的传闻，不是正式发布的通知。"}, {"text": "这台冰箱的八卦很大，放得下十个西瓜。", "explanation": "这里应该用〈容量〉。八卦指古代符号或流传的闲谈，不能用来说冰箱的容积。"}, {"text": "他每天早上吃八卦当早饭。", "explanation": "这里应该用〈面包〉。八卦是传闻，不能拿来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "八卦", "is_correct": true, "explanation": "“八卦”指流传的同事传闻，“听说公司的八卦”符合句意。"}, {"text": "电流", "is_correct": false, "explanation": "语义：电流是电的流动，不是可以听说的传闻。"}, {"text": "年轮", "is_correct": false, "explanation": "语义：年轮是树木的纹理，不指公司里的传闻。"}, {"text": "判词", "is_correct": false, "explanation": "语域：判词是法律判决的文书用语，不用于同事之间的传闻。"}], "explanations": {"八卦": "“八卦”指流传的同事传闻，“听说公司的八卦”符合句意。", "电流": "语义：电流是电的流动，不是可以听说的传闻。", "年轮": "语义：年轮是树木的纹理，不指公司里的传闻。", "判词": "语域：判词是法律判决的文书用语，不用于同事之间的传闻。"}, "sentence_index": 6, "correct_answer": "八卦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天要喝一杯八卦。", "explanation": "这里应该用〈咖啡〉。八卦是传闻，不能喝。"}, {"text": "这首八卦很感人。", "explanation": "这里应该用〈诗〉。八卦是传闻，不能用来形容感人的作品。"}, {"text": "这份八卦有十页，需要签字。", "explanation": "这里应该用〈文件〉。八卦是流传的闲谈，不能说需要签字、按页数计算的文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
