INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91871, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "多出来的新的。", "primary_collocate": null, "pronunciation": "xīn zēng", "ipa": "ɕin⁵⁵ tsɤŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "这个月新增的学生有二十人。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新增的教室在三楼。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看一下新增的菜。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新增人口主要是年轻人。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把新增的钱用在学习上。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院新增的床位还是不够。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天新增的病人比昨天少。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上新增的路很方便。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新增的工作让他很忙。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是书里新增的内容。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "新增的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "放在名词前，指多出来的新的人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91871, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新增", "is_correct": true, "explanation": "正确：「新增」作定语，指多出来的新的人，符合句意。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：「辽阔」形容地域或天空，不用来修饰学生。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：「潮湿」指含有水分，与「新加入的学生」的意思无关。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：「宽敞」形容房间或场地，不能修饰学生。"}], "explanations": {"新增": "正确：「新增」作定语，指多出来的新的人，符合句意。", "辽阔": "搭配：「辽阔」形容地域或天空，不用来修饰学生。", "潮湿": "语义：「潮湿」指含有水分，与「新加入的学生」的意思无关。", "宽敞": "搭配：「宽敞」形容房间或场地，不能修饰学生。"}, "sentence_index": 0, "correct_answer": "新增"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新增的空气很清新。", "explanation": "这里应该用〈新鲜〉。新增只指新加入的人或东西，形容空气好闻要用新鲜。"}, {"text": "他的想法很新增。", "explanation": "这里应该用〈新颖〉。新增只放在名词前指多出来的人或东西，不能作谓语形容想法新奇。"}, {"text": "这件衣服还很新增。", "explanation": "这里应该用〈新〉。新增不能作谓语描述东西不旧，要用新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91871, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新增", "is_correct": true, "explanation": "正确：「新增」作定语，指今天新加入的病人，符合句意。"}, {"text": "锋利", "is_correct": false, "explanation": "搭配：「锋利」形容刀具等，不用来修饰病人。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：「陈旧」指东西旧，不用来形容新加入的人。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：「响亮」形容声音，不用来修饰病人。"}], "explanations": {"新增": "正确：「新增」作定语，指今天新加入的病人，符合句意。", "锋利": "搭配：「锋利」形容刀具等，不用来修饰病人。", "陈旧": "语义：「陈旧」指东西旧，不用来形容新加入的人。", "响亮": "搭配：「响亮」形容声音，不用来修饰病人。"}, "sentence_index": 6, "correct_answer": "新增"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天买的鱼很新增。", "explanation": "这里应该用〈新鲜〉。新增只指多出来的人或东西，形容食物刚做好、没变质要用新鲜。"}, {"text": "这个设计非常新增。", "explanation": "这里应该用〈新颖〉。新增不能受「非常」修饰作谓语，设计新奇要用新颖。"}, {"text": "他买了一辆新增的自行车，一点儿也不旧。", "explanation": "这里应该用〈崭新〉。新增指多出来的，不表示东西没用过、不旧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91871, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次新增地班级有三个。", "corrected_sentence": "这次新增的班级有三个。", "error_description": "「新增」作定语修饰「班级」时应用「的」，不能用「地」。错误形式是「新增地班级」，正确形式是「新增的班级」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91871, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们小区新增地停车位有两个。", "corrected_sentence": "我们小区新增的停车位有两个。", "error_description": "「新增」作定语修饰「停车位」时应用「的」，不能用「地」（「地」用于修饰动词、形容词）。错误形式是「新增地停车位」，正确形式是「新增的停车位」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91872, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减少", "is_correct": true, "explanation": "正确：「减少」指数量变少，与「新增」相对。"}, {"text": "保持", "is_correct": false, "explanation": "与「新增」没有反义关系，指维持原状。"}, {"text": "完成", "is_correct": false, "explanation": "与「新增」没有反义关系，指做成某件事。"}, {"text": "设立", "is_correct": false, "explanation": "与「新增」没有反义关系，指建立机构或制度。"}], "correct_answer": "减少", "explanations": {"减少": "正确：「减少」指数量变少，与「新增」相对。", "保持": "与「新增」没有反义关系，指维持原状。", "完成": "与「新增」没有反义关系，指做成某件事。", "设立": "与「新增」没有反义关系，指建立机构或制度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
