INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91872, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "新近增加。", "primary_collocate": null, "pronunciation": "xīn zēng", "ipa": "ɕin⁵⁵ tsɤŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "学校新增了两间教室。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年新增了三百个工作岗位。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市新增了很多公园。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月医院新增病人十个。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店新增了一种便宜的茶。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁新增两条线，坐车更方便了。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年我们班新增了五个同学。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆新增了很多新书。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里新增了一家小医院。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司上个月新增了两个部门。", "target_word": "新增", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "新增了", "label": "体标"}], "register": "中性", "sense_fingerprint": "作谓语，表示最近增加了人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91872, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "新增", "is_correct": true, "explanation": "正确：「新增」表示学校增加了两间教室，符合句意。"}, {"text": "研究", "is_correct": false, "explanation": "搭配：「研究」的宾语是问题或学问，不说研究教室。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：「欢迎」指接待或表示迎接，不能带「教室」作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指发出歌声，与教室无关。"}], "explanations": {"新增": "正确：「新增」表示学校增加了两间教室，符合句意。", "研究": "搭配：「研究」的宾语是问题或学问，不说研究教室。", "欢迎": "配价：「欢迎」指接待或表示迎接，不能带「教室」作宾语。", "唱": "语义：「唱」指发出歌声，与教室无关。"}, "sentence_index": 0, "correct_answer": "新增"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我往牛奶里新增了一勺糖。", "explanation": "这里应该用〈添加〉。新增指新加入的人或东西，往食物里放调料要用添加。"}, {"text": "这次锻炼新增了他的体质。", "explanation": "这里应该用〈增强〉。新增不能与体质这类抽象素质搭配，增强体质才自然。"}, {"text": "他的年龄新增了一岁。", "explanation": "这里应该用〈增长〉。「新增」指新加入的人或东西，年龄随时间变大要用「增长」，不说新增了一岁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91872, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新增", "is_correct": true, "explanation": "正确：「新增」表示去年班里增加了五个同学，符合句意。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：「参观」指去某地观看，不能用来说参观同学。"}, {"text": "修理", "is_correct": false, "explanation": "语义：「修理」指修补器物，不用来形容同学。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：「冲洗」用于照片或器物，不能用来说同学。"}], "explanations": {"新增": "正确：「新增」表示去年班里增加了五个同学，符合句意。", "参观": "搭配：「参观」指去某地观看，不能用来说参观同学。", "修理": "语义：「修理」指修补器物，不用来形容同学。", "冲洗": "搭配：「冲洗」用于照片或器物，不能用来说同学。"}, "sentence_index": 6, "correct_answer": "新增"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我这个月体重新增了三公斤。", "explanation": "这里应该用〈增加〉。新增指新加入的人或东西，体重等数量的增长要用增加。"}, {"text": "学生们的水平新增了不少。", "explanation": "这里应该用〈提高〉。水平这类程度要用提高，新增只指新加入的人或事物。"}, {"text": "这次改革新增了生产速度。", "explanation": "这里应该用〈加快〉。速度的变化要用加快，不说新增速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市里新增着一条地铁线。", "corrected_sentence": "市里新增了一条地铁线。", "error_description": "「新增」表示已经完成的动作，应用「了」，不用「着」（「着」表示持续状态）。错误形式是「新增着」，正确形式是「新增了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班这学期新增了过五个同学。", "corrected_sentence": "我们班这学期新增了五个同学。", "error_description": "「新增」后已有「了」表示完成，不能再加「过」。错误形式是「新增了过」，正确形式是「新增了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
