INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91873, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "兵力是有多少当兵的人。", "primary_collocate": null, "pronunciation": "bīng lì", "ipa": "piŋ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的兵力不多。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的兵力有十万人。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人的兵力比我们多。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道山下有多少兵力吗？", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城里的兵力很少。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军下令清点兵力，以便制定作战计划。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的兵力差不多。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老将军数了数兵力。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北边的兵力越来越多。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道敌人有多少兵力。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兵力部署", "label": "复合"}], "register": "书面语", "sense_fingerprint": "兵力：军队中士兵的数量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbb1089a-7f0e-4a1d-9b64-4094ab18e718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91873, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兵力", "is_correct": true, "explanation": "正确：兵力指军队中的士兵人数。"}, {"text": "病历", "is_correct": false, "explanation": "bìng lì（第四声）与 bīng lì（第一声）只有第一个音节声调不同，意思是病人的诊疗记录。"}, {"text": "病理", "is_correct": false, "explanation": "bìng lǐ（第四、三声）与 bīng lì（第一、四声）两个音节声调都不同，意思是疾病的发生与变化。"}, {"text": "病例", "is_correct": false, "explanation": "bìng lì（第四、四声）与 bīng lì（第一、四声）只有第一个音节声调不同，意思是某种疾病的具体病人或案例。"}], "explanations": {"兵力": "正确：兵力指军队中的士兵人数。", "病历": "bìng lì（第四声）与 bīng lì（第一声）只有第一个音节声调不同，意思是病人的诊疗记录。", "病理": "bìng lǐ（第四、三声）与 bīng lì（第一、四声）两个音节声调都不同，意思是疾病的发生与变化。", "病例": "bìng lì（第四、四声）与 bīng lì（第一、四声）只有第一个音节声调不同，意思是某种疾病的具体病人或案例。"}, "sentence_index": null, "correct_answer": "兵力"}, "level_3": {"options": [{"text": "兵力", "is_correct": true, "explanation": "正确：“兵力”指军队的人数，可以说“不多”。"}, {"text": "气温", "is_correct": false, "explanation": "语义：气温是温度，不能用“不多”来形容。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”用“高/低”描述，不说“多/少”。"}, {"text": "物价", "is_correct": false, "explanation": "语义：“物价”说高低，不能说“不多”。"}], "explanations": {"兵力": "正确：“兵力”指军队的人数，可以说“不多”。", "气温": "语义：气温是温度，不能用“不多”来形容。", "海拔": "搭配：“海拔”用“高/低”描述，不说“多/少”。", "物价": "语义：“物价”说高低，不能说“不多”。"}, "sentence_index": 0, "correct_answer": "兵力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座工厂需要大量的兵力。", "explanation": "这里应该用〈人力〉。兵力指军队的人数，工厂需要的工人要说人力。"}, {"text": "这家公司的兵力很强。", "explanation": "这里应该用〈实力〉。兵力只用于军队，形容公司的力量要说实力。"}, {"text": "他做饭的兵力很强。", "explanation": "这里应该用〈能力〉。兵力只指军队，形容人做事的本领要说能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兵力", "is_correct": true, "explanation": "正确：两国的兵力可以比较是否差不多。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，不能用来比较两个国家。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”只描写人或动物的体型，国家没有身材。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”只用于人或动物，不能说两国的体重。"}], "explanations": {"兵力": "正确：两国的兵力可以比较是否差不多。", "身高": "语义：“身高”指人的高矮，不能用来比较两个国家。", "身材": "体貌：“身材”只描写人或动物的体型，国家没有身材。", "体重": "语义：“体重”只用于人或动物，不能说两国的体重。"}, "sentence_index": 6, "correct_answer": "兵力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校的兵力很充足，老师们都很努力。", "explanation": "这里应该用〈师资〉。兵力只指军队的士兵数量，学校的老师要说师资。"}, {"text": "这家餐厅的兵力很多，客人总是排队。", "explanation": "这里应该用〈人手〉。兵力只指军队的士兵数量，餐厅的工作人员要说人手。"}, {"text": "这个班的兵力很多，每天都很热闹。", "explanation": "这里应该用〈人数〉。兵力只用于军队，班级里的学生数量要说人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
