INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91874, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "军队的人数和战斗力量。", "primary_collocate": null, "pronunciation": "bīng lì", "ipa": "piŋ˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "这支军队的兵力很强。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方的兵力远远超过我们。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用强大的兵力守着城门。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兵力不够，我们只好后退。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军决定集中兵力打一仗。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争中，兵力的大小很重要。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的兵力虽然少，但是很有战斗力。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王增加了边境的兵力。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护家园，村里加强了兵力。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手的兵力太强，我们打不过。", "target_word": "兵力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兵力部署", "label": "复合"}], "register": "书面语", "sense_fingerprint": "兵力：军队的人数与战斗力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbb1089a-7f0e-4a1d-9b64-4094ab18e718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = E