INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91874, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "兵力", "is_correct": true, "explanation": "正确：兵力指军队中的士兵人数和战斗力量。"}, {"text": "病历", "is_correct": false, "explanation": "bìng lì（第四声）与 bīng lì（第一声）只有第一个音节声调不同，意思是病人的诊疗记录。"}, {"text": "病理", "is_correct": false, "explanation": "bìng lǐ（第四、三声）与 bīng lì（第一、四声）两个音节声调都不同，意思是疾病的发生与变化。"}, {"text": "病例", "is_correct": false, "explanation": "bìng lì（第四、四声）与 bīng lì（第一、四声）只有第一个音节声调不同，意思是某种疾病的具体病人或案例。"}], "explanations": {"兵力": "正确：兵力指军队中的士兵人数和战斗力量。", "病历": "bìng lì（第四声）与 bīng lì（第一声）只有第一个音节声调不同，意思是病人的诊疗记录。", "病理": "bìng lǐ（第四、三声）与 bīng lì（第一、四声）两个音节声调都不同，意思是疾病的发生与变化。", "病例": "bìng lì（第四、四声）与 bīng lì（第一、四声）只有第一个音节声调不同，意思是某种疾病的具体病人或案例。"}, "sentence_index": null, "correct_answer": "兵力"}, "level_3": {"options": [{"text": "兵力", "is_correct": true, "explanation": "正确：“兵力很强”符合军队的战斗力量。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”用“深/浅”描述，不说“强”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的重量，军队没有体重。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”用“重/淡”描述，不说“强”。"}], "explanations": {"兵力": "正确：“兵力很强”符合军队的战斗力量。", "颜色": "搭配：“颜色”用“深/浅”描述，不说“强”。", "体重": "语义：体重指人或动物的重量，军队没有体重。", "口味": "搭配：“口味”用“重/淡”描述，不说“强”。"}, "sentence_index": 0, "correct_answer": "兵力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个项目需要大量的兵力。", "explanation": "这里应该用〈财力〉。兵力指军队的人数和战斗力量，项目所需的经费要说财力。"}, {"text": "这家商店的兵力很强，客人很多。", "explanation": "这里应该用〈实力〉。兵力只用于军队，形容商店的力量要说实力。"}, {"text": "她唱歌的兵力很强。", "explanation": "这里应该用〈能力〉。兵力只指军队，形容人的本领要说能力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXC