INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91876, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "数量很多的。", "primary_collocate": null, "pronunciation": "dà pī", "ipa": "ta⁵¹ pʰi⁵⁵", "syllable_count": 2, "sentences": [{"text": "仓库里堆着大批货物。", "target_word": "大批", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店昨天进了大批新书。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂买进了大批原材料。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店一次进了大批冬季外套。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海关查到了大批走私的药品。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次演出需要大批灯光设备。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大批新车已经运到了港口。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个季节市场上有大批水果。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司为这个项目采购了大批办公用品。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店正在处理大批旧杂志。", "target_word": "大批", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "大批大批", "label": "重叠"}], "register": "中性", "sense_fingerprint": "大批-数量很多的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b1253fbc-9288-40c9-a9b1-e95e77d08214') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91876, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稀少", "is_correct": false, "explanation": "语义：仓库里“堆着”货物，说明数量不少，“稀少”与堆满货物的画面矛盾。"}, {"text": "大批", "is_correct": true, "explanation": "正确：“大批”修饰“货物”，表示数量很多，符合“堆着”的描述。"}, {"text": "浩瀚", "is_correct": false, "explanation": "搭配：“浩瀚”形容广阔的事物，不能用来修饰“货物”这类具体东西。"}, {"text": "零星", "is_correct": false, "explanation": "语义：“零星”指分散、数量少，与“堆着”的集中状态相反。"}], "explanations": {"稀少": "语义：仓库里“堆着”货物，说明数量不少，“稀少”与堆满货物的画面矛盾。", "大批": "正确：“大批”修饰“货物”，表示数量很多，符合“堆着”的描述。", "浩瀚": "搭配：“浩瀚”形容广阔的事物，不能用来修饰“货物”这类具体东西。", "零星": "语义：“零星”指分散、数量少，与“堆着”的集中状态相反。"}, "sentence_index": 0, "correct_answer": "大批"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂每天排放大批废气。", "explanation": "这里应该用〈大量〉。废气是不可数的物质，大批强调成群的人或物，不能修饰废气。"}, {"text": "他花了大批力气搬家。", "explanation": "这里应该用〈很多〉。力气是不可数的，大批不用来修饰力气。"}, {"text": "他肩负着大批责任。", "explanation": "这里应该用〈巨大〉。责任是抽象的，大批不能用来修饰责任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91876, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寥寥", "is_correct": false, "explanation": "语义：运到港口的新车应当不少，“寥寥”表示数量很少，与“已经运到”的描述不合。"}, {"text": "微量", "is_correct": false, "explanation": "搭配：“微量”指极少的用量，多用于物质，不能修饰“新车”这类成件的商品。"}, {"text": "大批", "is_correct": true, "explanation": "正确：“大批”修饰“新车”，表示数量多，符合运到港口的语境。"}, {"text": "浩荡", "is_correct": false, "explanation": "搭配：“浩荡”形容水势壮阔或队伍声势盛大，不能直接修饰“新车”这类具体物品。"}], "explanations": {"寥寥": "语义：运到港口的新车应当不少，“寥寥”表示数量很少，与“已经运到”的描述不合。", "微量": "搭配：“微量”指极少的用量，多用于物质，不能修饰“新车”这类成件的商品。", "大批": "正确：“大批”修饰“新车”，表示数量多，符合运到港口的语境。", "浩荡": "搭配：“浩荡”形容水势壮阔或队伍声势盛大，不能直接修饰“新车”这类具体物品。"}, "sentence_index": 6, "correct_answer": "大批"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给孩子存了大批学费。", "explanation": "这里应该用〈大笔〉。学费是款项，要用大笔；大批强调成群的人或物，不用来修饰款项。"}, {"text": "他退休后有大批空闲时间。", "explanation": "这里应该用〈大把〉。大把是口语，修饰时间；大批不修饰时间。"}, {"text": "公司一次性缴纳了大批罚款。", "explanation": "这里应该用〈大额〉。罚款的金额大要用大额，大批不能修饰罚款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
