INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "上周一大批了新车运到了港口。", "corrected_sentence": "上周一大批新车运到了港口。", "error_description": "错误形式“一大批了新车”，正确形式“一大批新车”。表示完成的“了”应放在动词后，不能加在“大批”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2a65ab04-5de9-4493-8108-c756468757b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
