INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91877, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "结婚那天的女人。", "primary_collocate": null, "pronunciation": "xīn niáng", "ipa": "ɕin⁵⁵ niɑŋ³⁵", "syllable_count": 2, "sentences": [{"text": "新娘穿着白色的婚纱。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的新娘非常漂亮。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘从车上慢慢走下来。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新郎看着新娘，笑了。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘的妈妈哭了。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位新娘今年二十五岁。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在等新娘出来。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘手里拿着一束花。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位新娘是我的姐姐。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人们给新娘送了很多花。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "新娘子", "label": "复合"}], "register": "中性", "sense_fingerprint": "婚礼当天的女人，穿婚纱，与新郎相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91877, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新娘", "is_correct": true, "explanation": "正确答案：新娘，指结婚那天的女子。"}, {"text": "新粮", "is_correct": false, "explanation": "新粮与新娘第二个音节的声母不同（l 与 n），意思是新收获的粮食。"}, {"text": "新凉", "is_correct": false, "explanation": "新凉与新娘第二个音节的声母不同（l 与 n），意思是天气刚刚转凉。"}, {"text": "亲娘", "is_correct": false, "explanation": "亲娘与新娘第一个音节的声母不同（q 与 x），意思是亲生母亲。"}, {"text": "新酿", "is_correct": false, "explanation": "新酿与新娘第二个音节的声调不同（第四声与第二声），意思是刚酿成的酒。"}, {"text": "新年", "is_correct": false, "explanation": "新年与新娘第二个音节的韵尾不同（-n 与 -ng），意思是一年的开始。"}], "explanations": {"新娘": "正确答案：新娘，指结婚那天的女子。", "新粮": "新粮与新娘第二个音节的声母不同（l 与 n），意思是新收获的粮食。", "新凉": "新凉与新娘第二个音节的声母不同（l 与 n），意思是天气刚刚转凉。", "亲娘": "亲娘与新娘第一个音节的声母不同（q 与 x），意思是亲生母亲。", "新酿": "新酿与新娘第二个音节的声调不同（第四声与第二声），意思是刚酿成的酒。", "新年": "新年与新娘第二个音节的韵尾不同（-n 与 -ng），意思是一年的开始。"}, "sentence_index": null, "correct_answer": "新娘"}, "level_3": {"options": [{"text": "新娘", "is_correct": true, "explanation": "正确答案：新娘，结婚当天穿婚纱的女子，与“婚纱”搭配。"}, {"text": "新郎", "is_correct": false, "explanation": "语义：婚纱是新娘穿的，新郎穿的是西装，“新郎穿着白色的婚纱”与常识不符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能“穿着”婚纱。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师在工作时穿白色的厨师服，不会穿婚纱。"}], "explanations": {"新娘": "正确答案：新娘，结婚当天穿婚纱的女子，与“婚纱”搭配。", "新郎": "语义：婚纱是新娘穿的，新郎穿的是西装，“新郎穿着白色的婚纱”与常识不符。", "桌子": "语义：桌子是家具，不能“穿着”婚纱。", "厨师": "语义：厨师在工作时穿白色的厨师服，不会穿婚纱。"}, "sentence_index": 0, "correct_answer": "新娘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位新娘每天开着公共汽车送大家上班。", "explanation": "这里应该用〈司机〉。“新娘”只指结婚当天的女子，不能指开公共汽车的人。"}, {"text": "奶奶每天在菜市场卖菜，她是这里的新娘。", "explanation": "这里应该用〈摊主〉。“新娘”只指结婚当天的女子，不能指卖菜的人。"}, {"text": "我的爱人在学校教书，是班里的新娘。", "explanation": "这里应该用〈老师〉。“新娘”只指结婚当天的女子，不能指教书的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91877, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新娘", "is_correct": true, "explanation": "正确答案：新娘，从房间里走出来的结婚女子，与“等……出来”搭配。"}, {"text": "拖把", "is_correct": false, "explanation": "搭配：“等……出来”多用于等人或等结果，拖把不搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不会“出来”让大家等。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“出来”需要能移动或出场的主体，石头不搭配。"}], "explanations": {"新娘": "正确答案：新娘，从房间里走出来的结婚女子，与“等……出来”搭配。", "拖把": "搭配：“等……出来”多用于等人或等结果，拖把不搭配。", "冰箱": "语义：冰箱是家用电器，不会“出来”让大家等。", "石头": "搭配：“出来”需要能移动或出场的主体，石头不搭配。"}, "sentence_index": 6, "correct_answer": "新娘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的新娘每天都在车间里检查机器。", "explanation": "这里应该用〈工人〉。“新娘”只指结婚当天的女子，不能指工厂里的工作人员。"}, {"text": "这家银行的新娘每天都在柜台前办理业务。", "explanation": "这里应该用〈柜员〉。“新娘”只指结婚当天的女子，不能指银行的工作人员。"}, {"text": "我的新娘已经上小学了，每天背着书包。", "explanation": "这里应该用〈小学生〉。“新娘”只指结婚当天的女子，不能指上小学的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91877, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只新娘在婚礼上笑得很开心。", "corrected_sentence": "一位新娘在婚礼上笑得很开心。", "error_description": "量词错误：“新娘”指人，应该用量词“位”，不能用“只”（“只”用于动物）。这是学习者常见的错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91877, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位新娘们在门口排队。", "corrected_sentence": "两位新娘在门口排队。", "error_description": "“们”的错误：名词前面已经有数量词“两位”时，名词后面不能再加“们”。应该说“两位新娘”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
