INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91878, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "结婚时的女子。", "primary_collocate": null, "pronunciation": "xīn niáng", "ipa": "ɕin⁵⁵ niɑŋ³⁵", "syllable_count": 2, "sentences": [{"text": "婚礼上，新娘很紧张。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做新娘的那天，天气很好。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，新娘笑得很开心。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘和新郎一起给客人倒茶。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没见过这么高兴的新娘。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘的红衣服很好看。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都说她是最美的新娘。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘换了三次衣服。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸牵着新娘走进来。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次当新娘，心里又高兴又紧张。", "target_word": "新娘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "新娘子", "label": "复合"}], "register": "中性", "sense_fingerprint": "办婚礼时的女子，是婚礼上的主角之一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91878, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新娘", "is_correct": true, "explanation": "正确答案：新娘，指结婚那天的女子。"}, {"text": "新粮", "is_correct": false, "explanation": "新粮与新娘第二个音节的声母不同（l 与 n），意思是新收获的粮食。"}, {"text": "新凉", "is_correct": false, "explanation": "新凉与新娘第二个音节的声母不同（l 与 n），意思是天气刚刚转凉。"}, {"text": "亲娘", "is_correct": false, "explanation": "亲娘与新娘第一个音节的声母不同（q 与 x），意思是亲生母亲。"}, {"text": "新酿", "is_correct": false, "explanation": "新酿与新娘第二个音节的声调不同（第四声与第二声），意思是刚酿成的酒。"}, {"text": "新年", "is_correct": false, "explanation": "新年与新娘第二个音节的韵尾不同（-n 与 -ng），意思是一年的开始。"}], "explanations": {"新娘": "正确答案：新娘，指结婚那天的女子。", "新粮": "新粮与新娘第二个音节的声母不同（l 与 n），意思是新收获的粮食。", "新凉": "新凉与新娘第二个音节的声母不同（l 与 n），意思是天气刚刚转凉。", "亲娘": "亲娘与新娘第一个音节的声母不同（q 与 x），意思是亲生母亲。", "新酿": "新酿与新娘第二个音节的声调不同（第四声与第二声），意思是刚酿成的酒。", "新年": "新年与新娘第二个音节的韵尾不同（-n 与 -ng），意思是一年的开始。"}, "sentence_index": null, "correct_answer": "新娘"}, "level_3": {"options": [{"text": "新娘", "is_correct": true, "explanation": "正确答案：新娘，婚礼上紧张的主角，与“紧张”搭配。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“很紧张”描述人的心情，冰箱不会紧张。"}, {"text": "婚纱", "is_correct": false, "explanation": "语义：婚纱是衣服，没有紧张的心情，这句话说的是人。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“很紧张”需要有感情的主语，石头不搭配。"}], "explanations": {"新娘": "正确答案：新娘，婚礼上紧张的主角，与“紧张”搭配。", "冰箱": "搭配：“很紧张”描述人的心情，冰箱不会紧张。", "婚纱": "语义：婚纱是衣服，没有紧张的心情，这句话说的是人。", "石头": "搭配：“很紧张”需要有感情的主语，石头不搭配。"}, "sentence_index": 0, "correct_answer": "新娘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈在超市收银，是这家超市的新娘。", "explanation": "这里应该用〈收银员〉。“新娘”只指结婚当天的女子，不能指超市的工作人员。"}, {"text": "我的新娘上初中了，成绩很好。", "explanation": "这里应该用〈初中生〉。“新娘”只指结婚当天的女子，不能指上初中的学生。"}, {"text": "这位新娘每天在医院给病人打针。", "explanation": "这里应该用〈护士〉。“新娘”只指结婚当天的女子，不能指给病人打针的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "新娘", "is_correct": true, "explanation": "正确答案：新娘，结婚时的女子，是“最美的”人。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：“她”指人，书桌是家具，不能被说成“最美的”人。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚是打扫用的工具，不能用来形容“她”是最美的人。"}, {"text": "老头", "is_correct": false, "explanation": "体貌：“她”是女性，“老头”指男性老人，与“她”的形象不合。"}], "explanations": {"新娘": "正确答案：新娘，结婚时的女子，是“最美的”人。", "书桌": "语义：“她”指人，书桌是家具，不能被说成“最美的”人。", "扫帚": "语义：扫帚是打扫用的工具，不能用来形容“她”是最美的人。", "老头": "体貌：“她”是女性，“老头”指男性老人，与“她”的形象不合。"}, "sentence_index": 6, "correct_answer": "新娘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外婆在医院照顾病人，她是医院的新娘。", "explanation": "这里应该用〈护工〉。“新娘”只指结婚当天的女子，不能指照顾病人的人。"}, {"text": "她每天在学校食堂做饭，是食堂的新娘。", "explanation": "这里应该用〈厨师〉。“新娘”只指结婚当天的女子，不能指做饭的人。"}, {"text": "我家邻居的新娘每天在路口指挥交通。", "explanation": "这里应该用〈警察〉。“新娘”只指结婚当天的女子，不能指指挥交通的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只新娘穿着红色的裙子。", "corrected_sentence": "那位新娘穿着红色的裙子。", "error_description": "量词错误：“新娘”指人，应该用量词“位”，不能用“只”（“只”用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位新娘们在门口等车。", "corrected_sentence": "两位新娘在门口等车。", "error_description": "“们”的错误：名词前面已经有数量词“两位”时，名词后面不能再加“们”。应该说“两位新娘”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91879, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
