INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91879, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "到时候是说到了那个时间的时候。", "primary_collocate": null, "pronunciation": "dào shí hou", "ipa": "taʊ˥˩ ʂɻ̩˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "音乐会八点开始，到时候我在门口等你。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下周二考试，到时候别忘了带笔。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们六点吃饭，到时候你一定要来。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说周五交作业，到时候我会交给她。", "target_word": "到时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节快到了，到时候我们全家一起回老家。", "target_word": "到时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上七点出发，到时候大家在楼下见。", "target_word": "到时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛下个月举行，到时候我去给你加油。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机十点到，到时候我去机场接你。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "约好周日见面，到时候再决定去哪儿。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生日聚会在周六，到时候给你一个惊喜。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "指前文已说到的某个时间点，到了那个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99fe3606-75b6-4d45-9eb3-6ab141772d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91879, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到时候", "is_correct": true, "explanation": "正确。「到时候」指前文说到的八点音乐会那个时间，与“八点开始”呼应。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：「已经」表示动作已经完成，与尚未开始的八点音乐会矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」指刚过去的时间，与将来的八点不符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：「马上」表示立即，与预定在八点的安排冲突。"}], "explanations": {"到时候": "正确。「到时候」指前文说到的八点音乐会那个时间，与“八点开始”呼应。", "已经": "体貌：「已经」表示动作已经完成，与尚未开始的八点音乐会矛盾。", "刚刚": "语义：「刚刚」指刚过去的时间，与将来的八点不符。", "马上": "语义：「马上」表示立即，与预定在八点的安排冲突。"}, "sentence_index": 0, "correct_answer": "到时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "去年暑假我去了云南，到时候玩得很开心。", "explanation": "这里应该用〈那时〉。「到时候」只指前文说到的将来时间，这里说的是去年，已经过去了。"}, {"text": "我十岁那年搬了家，到时候还不认识同学。", "explanation": "这里应该用〈当时〉。「到时候」指尚未到来的时间，不能用来指十岁时已经过去的事。"}, {"text": "他在台上说错了话，到时候道歉了。", "explanation": "这里应该用〈当场〉。「到时候」指尚未到来的时间，而说错话后的道歉是当场发生的，不能用「到时候」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91879, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到时候", "is_correct": true, "explanation": "正确。「到时候」指前文说到的下个月比赛那个时间。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：「曾经」表示过去的经历，与尚未举行的比赛矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：「立刻」指马上，与「下个月」的时间安排冲突。"}, {"text": "早已", "is_correct": false, "explanation": "体貌：「早已」表示很早以前就已完成，与将来的比赛矛盾。"}], "explanations": {"到时候": "正确。「到时候」指前文说到的下个月比赛那个时间。", "曾经": "体貌：「曾经」表示过去的经历，与尚未举行的比赛矛盾。", "立刻": "语义：「立刻」指马上，与「下个月」的时间安排冲突。", "早已": "体貌：「早已」表示很早以前就已完成，与将来的比赛矛盾。"}, "sentence_index": 6, "correct_answer": "到时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我大学毕业那年找到了工作，到时候很高兴。", "explanation": "这里应该用〈那会儿〉。「到时候」指将来的时间，这里说的是大学毕业那年，已经过去了。"}, {"text": "他小时候住在农村，到时候家里很穷。", "explanation": "这里应该用〈当初〉。「到时候」不能指小时候那段已经过去的时间。"}, {"text": "我刚才在门口等了很久，到时候觉得很冷。", "explanation": "这里应该用〈那一刻〉。「到时候」只指将来的时间，而「刚才」的等待已经结束。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电影七点开始，到时候的我们一起去。", "corrected_sentence": "电影七点开始，到时候我们一起去。", "error_description": "错误在于「到时候」后面多加了「的」。「到时候」是副词，后面不能加「的」修饰「我们」。正确说法是「到时候我们一起去」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火车十点开，到时候时候我们在车站见。", "corrected_sentence": "火车十点开，到时候我们在车站见。", "error_description": "错误在于「时候」重复出现了两次。「到时候」是一个词，不能在后面再加「时候」。正确说法是「到时候我们在车站见」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
