INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91880, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "到了将来某个时间。", "primary_collocate": null, "pronunciation": "dào shí hou", "ipa": "taʊ˥˩ ʂɻ̩˧˥ xoʊ", "syllable_count": 3, "sentences": [{"text": "现在别担心，到时候总会有办法的。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先去忙吧，到时候我再给你打电话。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱不够也没关系，到时候我们再想办法。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我也不知道会怎么样，到时候再说吧。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "等我有了钱，到时候我就去环游世界。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先别急着决定，到时候看情况吧。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个旧手机还能用，到时候坏了再买新的。", "target_word": "到时候", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，到时候我一定帮你。", "target_word": "到时候", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你多练习，到时候就会说得很好。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在不用准备，到时候我们一起做。", "target_word": "到时候", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "泛指将来某个还不确定的时间，常和“再说、再看”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99fe3606-75b6-4d45-9eb3-6ab141772d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91880, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "到时候", "is_correct": true, "explanation": "正确。「到时候」泛指将来不确定的时间，与「总会有办法」的将来语气一致。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：「刚才」指刚过去的时间，与「总会有办法」所说的将来矛盾。"}, {"text": "当时", "is_correct": false, "explanation": "语义：「当时」指过去的某一时刻，与「现在别担心，总会」的将来含义矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：「已经」表示已经完成，与「总会有办法」所指的未来不符。"}], "explanations": {"到时候": "正确。「到时候」泛指将来不确定的时间，与「总会有办法」的将来语气一致。", "刚才": "语义：「刚才」指刚过去的时间，与「总会有办法」所说的将来矛盾。", "当时": "语义：「当时」指过去的某一时刻，与「现在别担心，总会」的将来含义矛盾。", "已经": "体貌：「已经」表示已经完成，与「总会有办法」所指的未来不符。"}, "sentence_index": 0, "correct_answer": "到时候"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天下大雨，到时候我们都没出门。", "explanation": "这里应该用〈那时〉。「到时候」指将来不确定的时间，这里说的是昨天已经发生的事。"}, {"text": "去年夏天我们去了海边，到时候天气很热。", "explanation": "这里应该用〈那时〉。「到时候」指将来的某个时间，与「去年夏天」这个已经过去的时间矛盾。"}, {"text": "他去年就拿到了驾照，到时候开车带我们去了海边。", "explanation": "这里应该用〈那时〉。「到时候」指将来不确定的时间，这里说的是去年已经发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到时候", "is_correct": true, "explanation": "正确。「到时候」泛指将来某个时间，与「坏了再买新的」的将来语气一致。"}, {"text": "早已", "is_correct": false, "explanation": "体貌：「早已」表示很久以前就已经发生，与「还能用」的现状矛盾。"}, {"text": "从前", "is_correct": false, "explanation": "语义：「从前」指过去的时间，与「坏了再买新的」所指的将来不符。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：「曾经」表示过去的经历，与「还能用」的现状矛盾。"}], "explanations": {"到时候": "正确。「到时候」泛指将来某个时间，与「坏了再买新的」的将来语气一致。", "早已": "体貌：「早已」表示很久以前就已经发生，与「还能用」的现状矛盾。", "从前": "语义：「从前」指过去的时间，与「坏了再买新的」所指的将来不符。", "曾经": "体貌：「曾经」表示过去的经历，与「还能用」的现状矛盾。"}, "sentence_index": 6, "correct_answer": "到时候"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吃完饭到时候我们去散步。", "explanation": "这里应该用〈之后〉。「到时候」指某个时间点，不能直接接在动作后面表示先后顺序。"}, {"text": "我昨天就把钱还给他了，到时候他说了声谢谢。", "explanation": "这里应该用〈那时〉。「到时候」指将来不确定的时间，这里说的是昨天已经发生的事。"}, {"text": "他去年就毕业了，到时候又去读了研究生。", "explanation": "这里应该用〈那时〉。「到时候」指将来的不确定时间，这里说的是去年已经发生的毕业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天的事情我们到时候已经说。", "corrected_sentence": "明天的事情我们到时候再说。", "error_description": "错误在于「已经」表示已经完成，与「到时候」所指的将来时间矛盾。应将「已经」改为「再」，即「到时候再说」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题先放着，到时候已经看。", "corrected_sentence": "这个问题先放着，到时候再看。", "error_description": "错误在于「已经」表示已经完成，与「到时候」所指的将来时间矛盾。应将「已经」改为「再」，即「到时候再看」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91881, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91881, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91881, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "奋斗是为了一个目标，一直很努力。", "primary_collocate": null, "pronunciation": "fèn dòu", "ipa": "fən˥˩ tou˥˩", "syllable_count": 2, "sentences": [{"text": "他为了买房子，一直在努力奋斗。", "target_word": "奋斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要为美好的生活奋斗。", "target_word": "奋斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他奋斗了十年，终于开了自己的店。", "target_word": "奋斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就为当医生而奋斗。", "target_word": "奋斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻的时候，我们都要努力奋斗。", "target_word": "奋斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸为这个家奋斗了一辈子。", "target_word": "奋斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都在为自己的梦想奋斗。", "target_word": "奋斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起奋斗，一定能成功。", "target_word": "奋斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了考上大学，奋斗了三年。", "target_word": "奋斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在不奋斗，以后会后悔的。", "target_word": "奋斗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "奋斗了", "label": "体标"}, {"form": "奋斗着", "label": "体标"}, {"form": "奋斗过", "label": "体标"}, {"form": "奋斗目标", "label": "复合"}], "register": "中性", "sense_fingerprint": "为一个目标长期持续地努力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e0a565-ff65-4751-a7de-98805f80eb54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91881, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奋斗", "is_correct": true, "explanation": "“奋斗”表示为目标长期拼搏，与“为了买房子”“努力”相合，填入正确。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”表示不再坚持，与“努力”正相反，句子说不通。"}, {"text": "休息", "is_correct": false, "explanation": "语义：“休息”表示停下来不做事，与“努力”的意思矛盾。"}, {"text": "玩耍", "is_correct": false, "explanation": "搭配：“玩耍”不能与“努力”搭配，也与“为了买房子”的目标不合。"}], "explanations": {"奋斗": "“奋斗”表示为目标长期拼搏，与“为了买房子”“努力”相合，填入正确。", "放弃": "语义：“放弃”表示不再坚持，与“努力”正相反，句子说不通。", "休息": "语义：“休息”表示停下来不做事，与“努力”的意思矛盾。", "玩耍": "搭配：“玩耍”不能与“努力”搭配，也与“为了买房子”的目标不合。"}, "sentence_index": 0, "correct_answer": "奋斗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在水里奋斗。", "explanation": "这里应该用〈挣扎〉。“奋斗”指为目标长期努力，不能用于落水后的求生挣扎。"}, {"text": "周末我们在超市奋斗。", "explanation": "这里应该用〈购物〉。“奋斗”表示为目标拼搏，不能用于日常买东西。"}, {"text": "孩子们在院子里奋斗。", "explanation": "这里应该用〈玩耍〉。“奋斗”强调为目标拼搏，不能用于孩子在院子里游戏的场景。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91881, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奋斗", "is_correct": true, "explanation": "“奋斗”表示为目标努力，与“每天都在”和“为自己的梦想”相合，填入正确。"}, {"text": "放松", "is_correct": false, "explanation": "搭配：“放松”表示休闲，不能用来修饰“为梦想”，与持续为梦想努力的意思不合。"}, {"text": "忘记", "is_correct": false, "explanation": "配价：“忘记”要带直接宾语，不能用“为梦想……忘记”的结构，且与“每天都在”的努力意义相反。"}, {"text": "怀疑", "is_correct": false, "explanation": "语义：“怀疑”表示不确定，与“为梦想”的积极行动不符，句子不通。"}], "explanations": {"奋斗": "“奋斗”表示为目标努力，与“每天都在”和“为自己的梦想”相合，填入正确。", "放松": "搭配：“放松”表示休闲，不能用来修饰“为梦想”，与持续为梦想努力的意思不合。", "忘记": "配价：“忘记”要带直接宾语，不能用“为梦想……忘记”的结构，且与“每天都在”的努力意义相反。", "怀疑": "语义：“怀疑”表示不确定，与“为梦想”的积极行动不符，句子不通。"}, "sentence_index": 6, "correct_answer": "奋斗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在公园奋斗。", "explanation": "这里应该用〈玩耍〉。“奋斗”强调为目标拼搏，不能用于孩子在公园游戏的场景。"}, {"text": "累了就坐下来奋斗一会儿。", "explanation": "这里应该用〈休息〉。“奋斗”指为目标长期努力，不能用于累了坐下来歇一歇的场合。"}, {"text": "他在车里奋斗。", "explanation": "这里应该用〈睡觉〉。“奋斗”指为目标长期拼搏，不能用于在车里歇着睡觉这种场景。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91881, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们为了实现梦想而奋斗着了。", "corrected_sentence": "他们为了实现梦想而奋斗着。", "error_description": "错误：“着”表示动作正在持续，与表示完成的“了”语义冲突，应删去“了”。正确：他们为了实现梦想而奋斗着。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91881, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "为了孩子的未来，他们一起奋斗梦想。", "corrected_sentence": "为了孩子的未来，他们一起奋斗。", "error_description": "错误：“奋斗”是不及物动词，后面不能直接带宾语“梦想”，应删去“梦想”。正确：为了孩子的未来，他们一起奋斗。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
