INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91883, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管钱，把钱怎么花写下来的人。", "primary_collocate": null, "pronunciation": "kuài jì", "ipa": "kʰuaɪ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "会计把每一笔钱都写在本子上。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的会计在办公室里算钱。", "target_word": "会计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买东西的钱花了多少，会计都记得。", "target_word": "会计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我爸爸是会计，他管着公司的钱。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小张当会计已经五年了。", "target_word": "会计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会计告诉我们，这个月花得太多了。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店请了一位会计管账。", "target_word": "会计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会计拿着本子，一笔一笔地写。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的钱花到哪儿去了，问问会计就知道。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想做会计，因为她喜欢数字。", "target_word": "会计", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "会计师", "label": "复合"}, {"form": "會計", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会计：管钱并把钱的去向记录下来的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会计", "is_correct": true, "explanation": "正确答案：会计，能把每一笔钱写在本子上的人。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会写字，也不会记录钱的去向。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不会写字，不能把钱记在本子上。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“写在本子上”的主语须是能写字的人，窗户不能写字。"}], "explanations": {"会计": "正确答案：会计，能把每一笔钱写在本子上的人。", "冰箱": "语义：冰箱不会写字，也不会记录钱的去向。", "小狗": "语义：小狗不会写字，不能把钱记在本子上。", "窗户": "搭配：“写在本子上”的主语须是能写字的人，窗户不能写字。"}, "sentence_index": 0, "correct_answer": "会计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会计每天在医院给病人打针。", "explanation": "这里应该用〈护士〉。“会计”是管钱、记账的人，不给病人打针。"}, {"text": "会计开着出租车送客人去机场。", "explanation": "这里应该用〈司机〉。“会计”是管钱、记账的人，不开车送客人。"}, {"text": "会计在饭店的厨房里炒菜。", "explanation": "这里应该用〈厨师〉。“会计”是管钱、记账的人，不负责做菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会计", "is_correct": true, "explanation": "正确答案：会计，负责管账的人，与“管账”搭配。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机负责开车，不负责管账。"}, {"text": "护士", "is_correct": false, "explanation": "语义：护士负责护理病人，不负责管账。"}, {"text": "演员", "is_correct": false, "explanation": "搭配：“管账”不与“演员”搭配，演员不负责财务。"}], "explanations": {"会计": "正确答案：会计，负责管账的人，与“管账”搭配。", "司机": "语义：司机负责开车，不负责管账。", "护士": "语义：护士负责护理病人，不负责管账。", "演员": "搭配：“管账”不与“演员”搭配，演员不负责财务。"}, "sentence_index": 6, "correct_answer": "会计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计在教室里给学生上数学课。", "explanation": "这里应该用〈老师〉。“会计”是管钱、记账的人，不给学生上课。"}, {"text": "会计每天在路口指挥交通。", "explanation": "这里应该用〈警察〉。“会计”是管钱、记账的人，不指挥交通。"}, {"text": "会计在台上唱了三首歌。", "explanation": "这里应该用〈歌手〉。“会计”是管钱、记账的人，不负责唱歌表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在银行当一把会计。", "corrected_sentence": "她在银行当一名会计。", "error_description": "量词错误：“会计”指人，应该用量词“名”，不能用“把”（“把”用于有把手的物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位会计们都在忙着算账。", "corrected_sentence": "两位会计都在忙着算账。", "error_description": "“们”的错误：名词前面已经有数量词“两位”时，名词后面不能再加“们”。应该说“两位会计”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
