INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91884, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责管理和计算钱财收支的人员。", "primary_collocate": null, "pronunciation": "kuài jì", "ipa": "kʰuaɪ˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "我们公司的会计每天都要记账。", "target_word": "会计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会计每个月都要算一次账。", "target_word": "会计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在小公司当会计，每天管钱和记账。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让会计把工资发给大家。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想知道公司花了多少钱，去问会计。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会计下班以后还在检查账本。", "target_word": "会计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会计说今年花的钱比去年多。", "target_word": "会计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我姐姐是一名会计，天天跟数字打交道。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把买东西的单子交给会计报账。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会计查了一遍账，没有发现错误。", "target_word": "会计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "会计师", "label": "复合"}, {"form": "會計", "label": "繁体"}], "register": "中性", "sense_fingerprint": "会计：公司或单位里负责管理、计算钱财收支的人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91884, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会计", "is_correct": true, "explanation": "正确答案：会计，负责公司钱财收支和记账的人员。"}, {"text": "老师", "is_correct": false, "explanation": "语义：老师不负责公司的记账工作。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会写字，不能记账。"}, {"text": "账本", "is_correct": false, "explanation": "搭配：“账本”是物品，不会“记账”，记账的是人。"}], "explanations": {"会计": "正确答案：会计，负责公司钱财收支和记账的人员。", "老师": "语义：老师不负责公司的记账工作。", "小猫": "语义：小猫不会写字，不能记账。", "账本": "搭配：“账本”是物品，不会“记账”，记账的是人。"}, "sentence_index": 0, "correct_answer": "会计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会计每天在学校门口给学生看病。", "explanation": "这里应该用〈医生〉。“会计”是管理钱财收支的人员，不给人看病。"}, {"text": "会计在工地上搬砖盖房子。", "explanation": "这里应该用〈工人〉。“会计”是管理钱财收支的人员，不在工地盖房子。"}, {"text": "会计在台上表演跳舞。", "explanation": "这里应该用〈演员〉。“会计”是管理钱财收支的人员，不负责表演。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会计", "is_correct": true, "explanation": "正确答案：会计，负责管钱和记账的人，能说出钱花得多不多。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不会说话，也不了解钱花了多少。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会说话，不能说今年花的钱比去年多。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“说”需要会说话的主语，窗户不能说话。"}], "explanations": {"会计": "正确答案：会计，负责管钱和记账的人，能说出钱花得多不多。", "冰箱": "语义：冰箱不会说话，也不了解钱花了多少。", "石头": "语义：石头不会说话，不能说今年花的钱比去年多。", "窗户": "搭配：“说”需要会说话的主语，窗户不能说话。"}, "sentence_index": 6, "correct_answer": "会计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会计开着公共汽车送大家回家。", "explanation": "这里应该用〈司机〉。“会计”是管理钱财收支的人员，不开公共汽车。"}, {"text": "会计在饭店里给客人炒菜。", "explanation": "这里应该用〈厨师〉。“会计”是管理钱财收支的人员，不负责做菜。"}, {"text": "会计在医院给病人打针。", "explanation": "这里应该用〈护士〉。“会计”是管理钱财收支的人员，不给病人打针。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈是一把会计，她每天都很忙。", "corrected_sentence": "我妈妈是一位会计，她每天都很忙。", "error_description": "量词错误：“会计”指人，应该用量词“位”，不能用“把”（“把”用于有把手的物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位会计们在办公室里算账。", "corrected_sentence": "两位会计在办公室里算账。", "error_description": "“们”的错误：名词前面已经有数量词“两位”时，名词后面不能再加“们”。应该说“两位会计”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91885, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增加", "is_correct": true, "explanation": "正确：「增加」与「削减」构成反义，表示数量变多"}, {"text": "保持", "is_correct": false, "explanation": "保持表示维持原状，与「削减」的数量变化不构成反义"}, {"text": "维持", "is_correct": false, "explanation": "维持表示使某种状态持续，与「削减」不构成反义"}, {"text": "执行", "is_correct": false, "explanation": "执行指实施某项决定，与「削减」不构成反义"}], "correct_answer": "增加", "explanations": {"增加": "正确：「增加」与「削减」构成反义，表示数量变多", "保持": "保持表示维持原状，与「削减」的数量变化不构成反义", "维持": "维持表示使某种状态持续，与「削减」不构成反义", "执行": "执行指实施某项决定，与「削减」不构成反义"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91885, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "增加", "is_correct": true, "explanation": "正确：「增加」与「削减」构成反义，表示数量变多"}, {"text": "保留", "is_correct": false, "explanation": "保留表示留下不去掉，与「削减」不构成反义"}, {"text": "坚持", "is_correct": false, "explanation": "坚持表示持续做某事，与「削减」不构成反义"}, {"text": "开展", "is_correct": false, "explanation": "开展表示推动某项活动，与「削减」不构成反义"}], "correct_answer": "增加", "explanations": {"增加": "正确：「增加」与「削减」构成反义，表示数量变多", "保留": "保留表示留下不去掉，与「削减」不构成反义", "坚持": "坚持表示持续做某事，与「削减」不构成反义", "开展": "开展表示推动某项活动，与「削减」不构成反义"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91885, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "削减是把数量弄少一点。", "primary_collocate": null, "pronunciation": "xuē jiǎn", "ipa": "ɕɥɛ˥ tɕjɛn˨˩", "syllable_count": 2, "sentences": [{"text": "公司决定削减今年的开支。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校削减了三个班的人数。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了省钱，我们削减了买衣服的钱。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府削减了今年的预算。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里钱不多，只好削减吃饭的费用。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂削减了一半工人。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理说要削减开会的次数。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把每月的零花钱削减了一半。", "target_word": "削减", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院削减了晚上的门诊时间。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先削减不用的开支，再买新电脑。", "target_word": "削减", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "削减了", "label": "体标"}, {"form": "削减过", "label": "体标"}, {"form": "削減", "label": "繁体"}], "register": "正式", "sense_fingerprint": "削减：把费用、人数等数量减少一些", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4c1239-4184-41d0-a500-af91482a0938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91885, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "削减", "is_correct": true, "explanation": "正确：削减指把数量弄少一点，即本条目的词"}, {"text": "靴尖", "is_correct": false, "explanation": "jiān 与 jiǎn 声调不同，意思是靴子的前端"}, {"text": "血检", "is_correct": false, "explanation": "xuè（第四声）与 xuē（第一声）声调不同，意思是血液检查"}, {"text": "斜肩", "is_correct": false, "explanation": "xié jiān 与 xuē jiǎn 读音相近但声韵调不同，意思是肩膀向下倾斜"}], "explanations": {"削减": "正确：削减指把数量弄少一点，即本条目的词", "靴尖": "jiān 与 jiǎn 声调不同，意思是靴子的前端", "血检": "xuè（第四声）与 xuē（第一声）声调不同，意思是血液检查", "斜肩": "xié jiān 与 xuē jiǎn 读音相近但声韵调不同，意思是肩膀向下倾斜"}, "sentence_index": null, "correct_answer": "削减"}, "level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能说「吃开支」"}, {"text": "削减", "is_correct": true, "explanation": "正确：「削减」表示减少数量，可以搭配「开支」，符合句意"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：「欣赏」指喜爱美好的事物，与开支的减少相矛盾"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不能带「开支」作宾语，句子无法成立"}], "explanations": {"吃": "搭配：「吃」的对象是食物，不能说「吃开支」", "削减": "正确：「削减」表示减少数量，可以搭配「开支」，符合句意", "欣赏": "语义：「欣赏」指喜爱美好的事物，与开支的减少相矛盾", "唱": "搭配：「唱」不能带「开支」作宾语，句子无法成立"}, "sentence_index": 0, "correct_answer": "削减"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重削减了三公斤。", "explanation": "这里应该用〈减少〉。削减多用于费用、人数、预算等可以压缩的数量，体重的变化要说减少"}, {"text": "今年的气温削减了五度。", "explanation": "这里应该用〈降低〉。削减指主动压缩费用、人数等数量，气温的下降要说降低"}, {"text": "秋风一吹，树上的叶子纷纷削减了。", "explanation": "这里应该用〈脱落〉。削减指人主动压缩数量，叶子自然掉落要说脱落"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91885, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮用", "is_correct": false, "explanation": "搭配：「饮用」的对象是饮品，不能说「饮用次数」"}, {"text": "削减", "is_correct": true, "explanation": "正确：「削减」表示减少数量，可以搭配「次数」，符合句意"}, {"text": "观赏", "is_correct": false, "explanation": "语义：「观赏」指欣赏景物或表演，与「开会的次数」不相容"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：「熄灭」指火或光的消失，不能用于「次数」"}], "explanations": {"饮用": "搭配：「饮用」的对象是饮品，不能说「饮用次数」", "削减": "正确：「削减」表示减少数量，可以搭配「次数」，符合句意", "观赏": "语义：「观赏」指欣赏景物或表演，与「开会的次数」不相容", "熄灭": "语义：「熄灭」指火或光的消失，不能用于「次数」"}, "sentence_index": 6, "correct_answer": "削减"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吃了药以后，他的头痛削减了。", "explanation": "这里应该用〈减轻〉。削减用于数量、费用的压缩，疼痛的减弱要说减轻"}, {"text": "这块海绵被削减了。", "explanation": "这里应该用〈压缩〉。削减用于数量或费用，物体体积变小要说压缩"}, {"text": "今天中午，他的体温削减了两度。", "explanation": "这里应该用〈降低〉。削减指压缩费用、人数等数量，体温的下降要说降低"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把今年的开支削减。", "corrected_sentence": "我们把今年的开支削减了。", "error_description": "错误：「把」字句中「削减」后缺少「了」，句子不完整；正确：应说「我们把今年的开支削减了」，「把」字句的动词后通常要带「了」或补语", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
