INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91887, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "马上就要到来。", "primary_collocate": null, "pronunciation": "jiāng zhì", "ipa": "tɕjaŋ˥ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "春节将至，街上的人越来越多。", "target_word": "将至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暴风雨将至，大家快回家吧。", "target_word": "将至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试将至，他每天都学到很晚。", "target_word": "将至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年将至，家家户户都挂上了红灯笼。", "target_word": "将至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天将至，天气一天比一天冷。", "target_word": "将至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业将至，同学们都有点舍不得。", "target_word": "将至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知道比赛将至，所以天天练习。", "target_word": "将至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人将至，妈妈把房间打扫干净了。", "target_word": "将至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜晚将至，山里很快就黑了。", "target_word": "将至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中秋将至，商店里摆满了月饼。", "target_word": "将至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "將至", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "将至：马上就要到了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d38b327-4414-4368-adb7-46d76c9371a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91887, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "散去", "is_correct": false, "explanation": "语义：“散去”表示人群离开，与“街上的人越来越多”矛盾，句意不通。"}, {"text": "将至", "is_correct": true, "explanation": "将至：即将到来，与“春节”搭配，符合句意。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”用于火或灯，不能与“春节”搭配。"}, {"text": "失踪", "is_correct": false, "explanation": "语义：“失踪”指人或物不见，不能用于“春节”，句意不通。"}], "explanations": {"散去": "语义：“散去”表示人群离开，与“街上的人越来越多”矛盾，句意不通。", "将至": "将至：即将到来，与“春节”搭配，符合句意。", "熄灭": "搭配：“熄灭”用于火或灯，不能与“春节”搭配。", "失踪": "语义：“失踪”指人或物不见，不能用于“春节”，句意不通。"}, "sentence_index": 0, "correct_answer": "将至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试已经将至，成绩都公布了。", "explanation": "这里应该用〈结束〉。“将至”表示尚未到来，不能与“成绩都公布了”的已完成情形同用；考试完了要说〈结束〉。"}, {"text": "这次旅行已经将至，我们都回家了。", "explanation": "这里应该用〈结束〉。“将至”表示尚未到来，不能与“已经”“都回家了”的已完成情形同用；旅行完了要说〈结束〉。"}, {"text": "比赛已经将至，比赛结果出来了。", "explanation": "这里应该用〈落幕〉。“将至”表示尚未到来，不能与“比赛结果出来了”的已完成情形同用；比赛结束要说〈落幕〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91887, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出发", "is_correct": false, "explanation": "语义：“比赛”不会“出发”，与句意不符。"}, {"text": "将至", "is_correct": true, "explanation": "将至：即将到来，与“比赛”搭配，符合“他知道比赛将至”的句意。"}, {"text": "倒塌", "is_correct": false, "explanation": "搭配：“倒塌”用于建筑等，不能与“比赛”搭配。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指没有按时到达，比赛本身不能迟到，句意不通。"}], "explanations": {"出发": "语义：“比赛”不会“出发”，与句意不符。", "将至": "将至：即将到来，与“比赛”搭配，符合“他知道比赛将至”的句意。", "倒塌": "搭配：“倒塌”用于建筑等，不能与“比赛”搭配。", "迟到": "语义：“迟到”指没有按时到达，比赛本身不能迟到，句意不通。"}, "sentence_index": 6, "correct_answer": "将至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "假期已经将至，大家都回去上班了。", "explanation": "这里应该用〈结束〉。“将至”表示即将到来，与“已经”及“回去上班了”的已完成情形矛盾；假期结束要用〈结束〉。"}, {"text": "他的梦想已经将至，他终于可以放心了。", "explanation": "这里应该用〈实现〉。“将至”表示尚未到来，不能描述已经达成的愿望；愿望达成要用〈实现〉。"}, {"text": "事故已经将至，大家都知道了。", "explanation": "这里应该用〈发生〉。“将至”表示尚未到来，与“大家都知道了”的已知情况矛盾；已经出现的事情要用〈发生〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "假期很将至，学校里很热闹。", "corrected_sentence": "假期将至，学校里很热闹。", "error_description": "程度副词错误：“将至”是动词性用法，不能受程度副词“很”修饰，应删去“很”。正确说法是“假期将至”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "中秋很将至，商店里很热闹。", "corrected_sentence": "中秋将至，商店里很热闹。", "error_description": "程度副词错误：“将至”是动词性用法，不能受程度副词“很”修饰，应删去“很”。正确说法是“中秋将至”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf8607d1-2f51-45a4-a97d-72b0af9d7910') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91889, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无用", "is_correct": true, "explanation": "“有价值”在“很有用、很重要”这一义项下的反义词是“无用”，表示没有用处。"}, {"text": "高兴", "is_correct": false, "explanation": "与“有价值”无反义关系：“高兴”是人的情绪，与价值无关。"}, {"text": "宽敞", "is_correct": false, "explanation": "与“有价值”无反义关系：“宽敞”形容空间大。"}, {"text": "聪明", "is_correct": false, "explanation": "与“有价值”无反义关系：“聪明”形容人的智力。"}], "correct_answer": "无用", "explanations": {"无用": "“有价值”在“很有用、很重要”这一义项下的反义词是“无用”，表示没有用处。", "高兴": "与“有价值”无反义关系：“高兴”是人的情绪，与价值无关。", "宽敞": "与“有价值”无反义关系：“宽敞”形容空间大。", "聪明": "与“有价值”无反义关系：“聪明”形容人的智力。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91889, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无用", "is_correct": true, "explanation": "“有价值”在“很有用、很重要”这一义项下的反义词是“无用”，表示没有用处。"}, {"text": "热闹", "is_correct": false, "explanation": "与“有价值”无反义关系：“热闹”形容场面，与用处无关。"}, {"text": "冷静", "is_correct": false, "explanation": "与“有价值”无反义关系：“冷静”形容情绪状态。"}, {"text": "可爱", "is_correct": false, "explanation": "与“有价值”无反义关系：“可爱”形容外貌或性格。"}], "correct_answer": "无用", "explanations": {"无用": "“有价值”在“很有用、很重要”这一义项下的反义词是“无用”，表示没有用处。", "热闹": "与“有价值”无反义关系：“热闹”形容场面，与用处无关。", "冷静": "与“有价值”无反义关系：“冷静”形容情绪状态。", "可爱": "与“有价值”无反义关系：“可爱”形容外貌或性格。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91889, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很有用，很重要。", "primary_collocate": null, "pronunciation": "yǒu jià zhí", "ipa": "jou˨˩˦ tɕja˥˩ ʈʂɨ˧˥", "syllable_count": 3, "sentences": [{"text": "这条消息对我们很有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图很有价值，别弄丢了。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的经验对新同事非常有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份材料有价值，请你收好。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给了我一些有价值的意见。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的时间很有价值，不要浪费。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电话号码很有价值，我一直留着。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数据对公司有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要找出最有价值的信息。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话对我有价值，我记在本子上。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有價值", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很有用、很重要，用于信息、材料、经验、时间等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87150d12-542a-4cd3-9d47-2268558069be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91889, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有价值", "is_correct": true, "explanation": "这里要用“有价值”，意思是很有用、很重要，正好描述消息的作用。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或建筑的身材，不能用来形容消息。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指人的智力，消息没有智力，句子说不通。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”描述场面，不能直接修饰“消息”。"}], "explanations": {"有价值": "这里要用“有价值”，意思是很有用、很重要，正好描述消息的作用。", "高大": "体貌：“高大”形容人或建筑的身材，不能用来形容消息。", "聪明": "语义：“聪明”指人的智力，消息没有智力，句子说不通。", "热闹": "搭配：“热闹”描述场面，不能直接修饰“消息”。"}, "sentence_index": 0, "correct_answer": "有价值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗饺子很有价值，我一口气吃了十个。", "explanation": "这里应该用〈美味〉。有价值说事物有用处或很重要，不描述食物的味道。"}, {"text": "这股味道很有价值，我闻了一下就想打喷嚏。", "explanation": "这里应该用〈呛人〉。有价值说事物有用处或很重要，不用来形容气味；形容气味刺鼻要说呛人。"}, {"text": "这块布的颜色很有价值，红得很亮眼。", "explanation": "这里应该用〈鲜艳〉。有价值说事物有用处或很重要，不用来形容颜色；形容颜色亮丽要说鲜艳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有价值", "is_correct": true, "explanation": "这里要用“有价值”，意思是很有用、很重要，说这个号码对我很重要。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”形容人的态度，号码没有态度，句子说不通。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”形容环境或人的状态，不能说号码很安静。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”描述空间，不能用来形容号码。"}], "explanations": {"有价值": "这里要用“有价值”，意思是很有用、很重要，说这个号码对我很重要。", "热情": "语义：“热情”形容人的态度，号码没有态度，句子说不通。", "安静": "语义：“安静”形容环境或人的状态，不能说号码很安静。", "狭窄": "搭配：“狭窄”描述空间，不能用来形容号码。"}, "sentence_index": 6, "correct_answer": "有价值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的身材很有价值，瘦得像一根竹竿。", "explanation": "这里应该用〈纤细〉。有价值说事物有用处或很重要，不用来形容身材的胖瘦；形容人身形瘦弱纤细要说纤细。"}, {"text": "我的脾气很有价值，一生气就摔东西。", "explanation": "这里应该用〈暴躁〉。有价值说事物有用处或很重要，不用来形容性情；脾气火爆要说暴躁。"}, {"text": "他的动作很有价值，大家笑个不停。", "explanation": "这里应该用〈滑稽〉。有价值说意义，不描述动作逗人发笑；形容动作好笑要用滑稽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一次很有价值讨论。", "corrected_sentence": "这是一次很有价值的讨论。", "error_description": "错误形式：很有价值讨论；正确形式：很有价值的讨论。“有价值”修饰名词时要加“的”，不能直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些资料对研究者不有价值。", "corrected_sentence": "这些资料对研究者没有价值。", "error_description": "错误形式：不有价值；正确形式：没有价值。“有”的否定要用“没”，不能说“不有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无价值", "is_correct": true, "explanation": "“有价值”在“有用处、有意义”这一义项下的反义词是“无价值”，表示没有用处或意义。"}, {"text": "美丽", "is_correct": false, "explanation": "与“有价值”无反义关系：“美丽”形容外貌或景色。"}, {"text": "聪明", "is_correct": false, "explanation": "与“有价值”无反义关系：“聪明”形容人的智力。"}, {"text": "安静", "is_correct": false, "explanation": "与“有价值”无反义关系：“安静”形容环境或状态，和有没有用处无关。"}], "correct_answer": "无价值", "explanations": {"无价值": "“有价值”在“有用处、有意义”这一义项下的反义词是“无价值”，表示没有用处或意义。", "美丽": "与“有价值”无反义关系：“美丽”形容外貌或景色。", "聪明": "与“有价值”无反义关系：“聪明”形容人的智力。", "安静": "与“有价值”无反义关系：“安静”形容环境或状态，和有没有用处无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无价值", "is_correct": true, "explanation": "“有价值”在“有用处、有意义”这一义项下的反义词是“无价值”，表示没有用处或意义。"}, {"text": "热情", "is_correct": false, "explanation": "与“有价值”无反义关系：“热情”形容人的态度。"}, {"text": "高大", "is_correct": false, "explanation": "与“有价值”无反义关系：“高大”形容身材，与价值无关。"}, {"text": "清楚", "is_correct": false, "explanation": "与“有价值”无反义关系：“清楚”形容清晰程度，与价值的有无不对应。"}], "correct_answer": "无价值", "explanations": {"无价值": "“有价值”在“有用处、有意义”这一义项下的反义词是“无价值”，表示没有用处或意义。", "热情": "与“有价值”无反义关系：“热情”形容人的态度。", "高大": "与“有价值”无反义关系：“高大”形容身材，与价值无关。", "清楚": "与“有价值”无反义关系：“清楚”形容清晰程度，与价值的有无不对应。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "具有价值的；有用处、有意义的。", "primary_collocate": null, "pronunciation": "yǒu jià zhí", "ipa": "jou˨˩˦ tɕja˥˩ ʈʂɨ˧˥", "syllable_count": 3, "sentences": [{"text": "这本书对学生很有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行对我来说很有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出了一个很有价值的建议。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个问题很有价值，值得讨论。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧照片对历史研究很有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这份工作非常有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验得到了有价值的结果。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮助别人是一件有价值的事。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博物馆里有价值的东西很多。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的看法很有价值，我们要认真想想。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有價值", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有用处、有意义的，值得做或值得讨论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87150d12-542a-4cd3-9d47-2268558069be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有价值", "is_correct": true, "explanation": "这里要用“有价值”，意思是有用处、有意义，正好描述这本书对学生的作用。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或建筑的身材，不能用来说书的好处。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指人的智力，书本身没有智力，句子说不通。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”多用于场所或场面，不能说“对学生很热闹”。"}], "explanations": {"有价值": "这里要用“有价值”，意思是有用处、有意义，正好描述这本书对学生的作用。", "高大": "体貌：“高大”形容人或建筑的身材，不能用来说书的好处。", "聪明": "语义：“聪明”指人的智力，书本身没有智力，句子说不通。", "热闹": "搭配：“热闹”多用于场所或场面，不能说“对学生很热闹”。"}, "sentence_index": 0, "correct_answer": "有价值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤很有价值，我一口气喝了两碗。", "explanation": "这里应该用〈美味〉。有价值说事物的意义或用处，不描述味道；形容汤好喝要说美味。"}, {"text": "他长得很有价值，一看就很帅气。", "explanation": "这里应该用〈英俊〉。有价值说事物的意义或用处，不用来形容人的长相；形容相貌好看要说英俊。"}, {"text": "这阵风很有价值，吹得人睁不开眼。", "explanation": "这里应该用〈猛烈〉。有价值说事物的意义或用处，不用来形容风力；形容风势很大要说猛烈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有价值", "is_correct": true, "explanation": "这里要用“有价值”修饰“结果”，表示结果有意义、有用处。"}, {"text": "雄伟", "is_correct": false, "explanation": "体貌：“雄伟”形容山川或建筑的气势，不能用来形容实验的结果。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”说空间小，不能用来形容结果。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音或环境，不能修饰“结果”。"}], "explanations": {"有价值": "这里要用“有价值”修饰“结果”，表示结果有意义、有用处。", "雄伟": "体貌：“雄伟”形容山川或建筑的气势，不能用来形容实验的结果。", "狭窄": "语义：“狭窄”说空间小，不能用来形容结果。", "嘈杂": "搭配：“嘈杂”形容声音或环境，不能修饰“结果”。"}, "sentence_index": 6, "correct_answer": "有价值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气很有价值，一生气就摔东西。", "explanation": "这里应该用〈暴躁〉。有价值说事物的意义或用处，不用来形容性情；脾气火爆要说暴躁。"}, {"text": "我的感冒很有价值，烧了三天也没退。", "explanation": "这里应该用〈严重〉。有价值说事物的意义或用处，不用来形容病情；病情厉害要说严重。"}, {"text": "窗外的鸟叫声很有价值，吵得我睡不着。", "explanation": "这里应该用〈嘈杂〉。有价值说事物的意义或用处，不用来形容声音杂乱；鸟叫声杂乱吵人要说嘈杂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法对我们的有价值。", "corrected_sentence": "这个方法对我们很有价值。", "error_description": "错误形式：对我们的有价值；正确形式：对我们很有价值。“的”是结构助词，不能放在“对我们”和“有价值”之间，应用程度副词“很”修饰“有价值”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
