INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91892, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "逻辑中条件句的前一部分（与“后件”相对）。", "primary_collocate": null, "pronunciation": "qián jiàn", "ipa": "tɕʰjɛn˧˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "在“下雨，我就不去”这句话里，“下雨”是前件。", "target_word": "前件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们这个条件句的前件是什么。", "target_word": "前件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前件为真，后件为假，这个推理就不成立。", "target_word": "前件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题要我们先找出句子的前件。", "target_word": "前件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把前件和后件写在黑板上。", "target_word": "前件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子的前件很短，后件却很长。", "target_word": "前件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前件不同，后件的意思也会不同。", "target_word": "前件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学逻辑时，我总是分不清前件和后件。", "target_word": "前件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你努力，就会进步”的前件是“你努力”。", "target_word": "前件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指出了这句话的前件。", "target_word": "前件", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个前件", "label": "量词"}], "register": "书面语", "sense_fingerprint": "逻辑条件句的前一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02255d63-88e7-4cee-a6d4-c25bafea51c5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91892, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前件", "is_correct": true, "explanation": "正确：前件（qián jiàn），指条件句的前一部分。"}, {"text": "浅见", "is_correct": false, "explanation": "声调不同：浅（qiǎn，第三声）与前（qián，第二声）声调不同，意思是浅见，不是前件。"}, {"text": "嵌件", "is_correct": false, "explanation": "声调不同：嵌（qiàn，第四声）与前（qián，第二声）声调不同，意思是嵌件，不是前件。"}, {"text": "前进", "is_correct": false, "explanation": "读音相近：前进（qián jìn）与前件（qián jiàn）只差第二个字的韵母，意思是向前走，不是前件。"}], "explanations": {"前件": "正确：前件（qián jiàn），指条件句的前一部分。", "浅见": "声调不同：浅（qiǎn，第三声）与前（qián，第二声）声调不同，意思是浅见，不是前件。", "嵌件": "声调不同：嵌（qiàn，第四声）与前（qián，第二声）声调不同，意思是嵌件，不是前件。", "前进": "读音相近：前进（qián jìn）与前件（qián jiàn）只差第二个字的韵母，意思是向前走，不是前件。"}, "sentence_index": null, "correct_answer": "前件"}, "level_3": {"options": [{"text": "前件", "is_correct": true, "explanation": "正确：前件指条件句的前一部分，“下雨”正是这一部分。"}, {"text": "后件", "is_correct": false, "explanation": "语义：后件指条件句的后一部分，与句中“下雨”作前件的关系相反。"}, {"text": "结论", "is_correct": false, "explanation": "语义：“不去”才是推理的结论，“下雨”是条件，不是结论。"}, {"text": "前头", "is_correct": false, "explanation": "搭配：“前头”是方位词，不能用来指条件句中的一部分。"}], "explanations": {"前件": "正确：前件指条件句的前一部分，“下雨”正是这一部分。", "后件": "语义：后件指条件句的后一部分，与句中“下雨”作前件的关系相反。", "结论": "语义：“不去”才是推理的结论，“下雨”是条件，不是结论。", "前头": "搭配：“前头”是方位词，不能用来指条件句中的一部分。"}, "sentence_index": 0, "correct_answer": "前件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的前件非常苛刻，很多同学都没通过。", "explanation": "这里应该用〈条件〉。前件专指条件句的前一部分，不指一般意义上的条件；考试的条件要说“条件”。"}, {"text": "他拒绝参加，前件是身体不好。", "explanation": "这里应该用〈理由〉。前件只用于逻辑条件句，说明拒绝的原因要用“理由”。"}, {"text": "他成功的前件有很多，最主要的是努力。", "explanation": "这里应该用〈原因〉。前件不指事情的原因，说成功的原因要用“原因”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91892, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前件", "is_correct": true, "explanation": "正确：只有“前件”能指条件句的前一部分，与后面的“后件”相对。"}, {"text": "后半截", "is_correct": false, "explanation": "语域：“后半截”是口语，与句中书面语“后件”不协调，而且“后半截不同”也不通顺。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：“苹果”是水果，不是条件句的组成部分，不能与“后件”相对。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是条件句的组成部分，不能与“后件”相对。"}], "explanations": {"前件": "正确：只有“前件”能指条件句的前一部分，与后面的“后件”相对。", "后半截": "语域：“后半截”是口语，与句中书面语“后件”不协调，而且“后半截不同”也不通顺。", "苹果": "语义：“苹果”是水果，不是条件句的组成部分，不能与“后件”相对。", "声音": "语义：“声音”不是条件句的组成部分，不能与“后件”相对。"}, "sentence_index": 6, "correct_answer": "前件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个推理里有一条前件。", "explanation": "这里应该用〈个〉。前件是抽象的逻辑概念，量词用“个”；“条”多用于细长的东西，不能用来数前件。"}, {"text": "这个论证里有一扇前件。", "explanation": "这里应该用〈个〉。“扇”用于门窗，前件是抽象的逻辑概念，不能用“扇”来数。"}, {"text": "这个句子里有一只前件。", "explanation": "这里应该用〈个〉。前件是抽象名词，量词用“个”；“只”多用于动物或成对的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91892, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这个句子里找到了两前件。", "corrected_sentence": "他在这个句子里找到了两个前件。", "error_description": "数量词后漏了量词“个”。前件是名词，数词后要带量词，应说“两个前件”，不说“两前件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91892, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个推理里有两只前件。", "corrected_sentence": "这个推理里有两个前件。", "error_description": "量词用错。“前件”是抽象概念，量词应用“个”，不用“只”。应说“两个前件”，不说“两只前件”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3cc69ac-f399-4d58-a377-46fede2e622c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
