INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91893, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "尚是到现在还是，还没有变。", "primary_collocate": null, "pronunciation": "shàng", "ipa": "ʂɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "老人尚在，家里很热闹。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷身体尚好。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的雪尚在。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条老街尚存几家旧店。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们手里尚有一些钱。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他尚在国外，下个月才回来。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里尚保持着老样子。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开会时间尚有两个小时。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年纪尚轻，还需要多学习。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子尚在，只是没有人住。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词：到现在仍然是这样，没有变化，常见尚在、尚有、尚存", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e29bc64e-453d-4bb9-9adb-ad6f4c6b55a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91893, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尚", "is_correct": true, "explanation": "尚 shàng 为本词，表示到现在仍然如此"}, {"text": "赏", "is_correct": false, "explanation": "shǎng（第三声）与 shàng（第四声）声调不同，意思是“欣赏”"}, {"text": "扇", "is_correct": false, "explanation": "shàn 与 shàng 韵母不同（an 与 ang），意思是量词“扇”"}, {"text": "丧", "is_correct": false, "explanation": "sàng 与 shàng 声母不同（s 与 sh），意思是“丧失”"}], "explanations": {"尚": "尚 shàng 为本词，表示到现在仍然如此", "赏": "shǎng（第三声）与 shàng（第四声）声调不同，意思是“欣赏”", "扇": "shàn 与 shàng 韵母不同（an 与 ang），意思是量词“扇”", "丧": "sàng 与 shàng 声母不同（s 与 sh），意思是“丧失”"}, "sentence_index": null, "correct_answer": "尚"}, "level_3": {"options": [{"text": "尚", "is_correct": true, "explanation": "尚表示到现在仍然在，“老人尚在”句意通顺"}, {"text": "很", "is_correct": false, "explanation": "语义：“很”表示程度，无法修饰“在”，句意不通"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”不能修饰“在”"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”表示程度，不能与“在”搭配"}], "explanations": {"尚": "尚表示到现在仍然在，“老人尚在”句意通顺", "很": "语义：“很”表示程度，无法修饰“在”，句意不通", "太": "搭配：“太”不能修饰“在”", "最": "搭配：“最”表示程度，不能与“在”搭配"}, "sentence_index": 0, "correct_answer": "尚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里尚变了样。", "explanation": "这里应该用〈已经〉。尚表示到现在仍然没有变化，与“变了样”矛盾"}, {"text": "这些树尚长高了不少。", "explanation": "这里应该用〈已经〉。尚表示到现在仍然没有变化，不能表示已经发生的变化，与“长高了不少”矛盾"}, {"text": "旧店尚卖光了。", "explanation": "这里应该用〈早就〉。尚表示到现在仍然如此，不能表示很久以前就已发生，与“卖光了”的完成义矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2449332-8818-4cdf-b350-9a46151234f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91893, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "尚", "is_correct": true, "explanation": "尚 shàng 为本词，表示到现在仍然如此"}, {"text": "商", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是“商店”"}, {"text": "伤", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是“受伤”"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 shàng 韵母不同（an 与 ang），意思是“善良”"}], "explanations": {"尚": "尚 shàng 为本词，表示到现在仍然如此", "商": "shāng（第一声）与 shàng（第四声）声调不同，意思是“商店”", "伤": "shāng（第一声）与 shàng（第四声）声调不同，意思是“受伤”", "善": "shàn 与 shàng 韵母不同（an 与 ang），意思是“善良”"}, "sentence_index": null, "correct_answer": "尚"}, "level_3": {"options": [{"text": "尚", "is_correct": true, "explanation": "尚表示到现在仍然如此，“这里尚保持着老样子”句意通顺"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”指动作刚刚发生，与“保持着”的持续状态不合"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”表示程度，不能修饰“保持着”"}, {"text": "猛", "is_correct": false, "explanation": "语义：“猛”表示突然或猛烈，与“是老样子”的状态不合"}], "explanations": {"尚": "尚表示到现在仍然如此，“这里尚保持着老样子”句意通顺", "刚": "语义：“刚”指动作刚刚发生，与“保持着”的持续状态不合", "太": "搭配：“太”表示程度，不能修饰“保持着”", "猛": "语义：“猛”表示突然或猛烈，与“是老样子”的状态不合"}, "sentence_index": 6, "correct_answer": "尚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老房子尚拆完了。", "explanation": "这里应该用〈终于〉。尚表示到现在仍然如此，不能表示拆完的结果"}, {"text": "老街尚修过两次。", "explanation": "这里应该用〈曾经〉。尚表示到现在仍然如此，与“修过两次”的既往经历矛盾"}, {"text": "旧房子尚被推倒了。", "explanation": "这里应该用〈刚刚〉。尚表示到现在仍然如此，不能表示刚刚发生的变化，与“被推倒了”的完成义矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2449332-8818-4cdf-b350-9a46151234f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老屋在尚，里面的家具都还在。", "corrected_sentence": "老屋尚在，里面的家具都还在。", "error_description": "错误：“在尚”。正确：“尚在”。“尚”是副词，要放在动词“在”前面，表示到现在仍然存在", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2449332-8818-4cdf-b350-9a46151234f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇有尚一座古桥。", "corrected_sentence": "这个小镇尚有一座古桥。", "error_description": "错误：“有尚”。正确：“尚有”。“尚”是副词，要放在“有”前面，不能放在“有”和数量词之间", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2449332-8818-4cdf-b350-9a46151234f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
