INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91895, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "前总理是以前做过总理的人。", "primary_collocate": null, "pronunciation": "qián zǒng lǐ", "ipa": "tɕʰjɛn˧˥ tsʊŋ˨˩˦ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "那位前总理现在住在小城，每天都种花。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Nà wèi qián zǒng lǐ xiànzài zhù zài xiǎochéng, měi tiān dōu zhònghuā.", "sentence_source": "generated"}, {"text": "这位前总理退休以后，开了一家小书店。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Zhè wèi qián zǒng lǐ tuìxiū yǐhòu, kāi le yì jiā xiǎo shūdiàn.", "sentence_source": "generated"}, {"text": "他是我们国家的前总理，现在在大学教书。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Tā shì wǒmen guójiā de qián zǒng lǐ, xiànzài zài dàxué jiāoshū.", "sentence_source": "generated"}, {"text": "前总理昨天来我们学校，给学生讲了一个故事。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Qián zǒng lǐ zuótiān lái wǒmen xuéxiào, gěi xuésheng jiǎngle yí ge gùshi.", "sentence_source": "generated"}, {"text": "我在电视上看到过那位前总理。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Wǒ zài diànshì shàng kàndàoguo nà wèi qián zǒng lǐ.", "sentence_source": "generated"}, {"text": "前总理写了一本书，很多人都买了。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Qián zǒng lǐ xiěle yì běn shū, hěn duō rén dōu mǎile.", "sentence_source": "generated"}, {"text": "前总理今年七十岁了，身体还很好。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Qián zǒng lǐ jīnnián qīshí suì le, shēntǐ hái hěn hǎo.", "sentence_source": "generated"}, {"text": "那位前总理喜欢坐着看报纸，也喜欢喝茶。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Nà wèi qián zǒng lǐ xǐhuan zuòzhe kàn bàozhǐ, yě xǐhuan hē chá.", "sentence_source": "generated"}, {"text": "我爷爷以前认识这位前总理。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Wǒ yéye yǐqián rènshi zhè wèi qián zǒng lǐ.", "sentence_source": "generated"}, {"text": "前总理没有坐汽车，他走路去开会。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Qián zǒng lǐ méiyǒu zuò qìchē, tā zǒulù qù kāihuì.", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "前總理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "前总理：以前做过总理的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前总理", "is_correct": true, "explanation": "正确。前总理指以前做过总理的人，可以作主语。"}, {"text": "前奏", "is_correct": false, "explanation": "语义：“前奏”指音乐开始的部分，不能指人。"}, {"text": "前途", "is_correct": false, "explanation": "语义：“前途”指未来的发展，不能指人。"}, {"text": "前缀", "is_correct": false, "explanation": "语义：“前缀”指词语前面的附加成分，不能指人。"}], "explanations": {"前总理": "正确。前总理指以前做过总理的人，可以作主语。", "前奏": "语义：“前奏”指音乐开始的部分，不能指人。", "前途": "语义：“前途”指未来的发展，不能指人。", "前缀": "语义：“前缀”指词语前面的附加成分，不能指人。"}, "sentence_index": 0, "correct_answer": "前总理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前总理正在国会主持辩论，大家都在等他发言。", "explanation": "这里应该用〈现任总理〉。前总理指已经卸任的人，不能指正在主持辩论的在任者。"}, {"text": "前总理今天签署了政府令，宣布下调税率。", "explanation": "这里应该用〈现任总理〉。前总理已经卸任，不能签署政府令、宣布政策。"}, {"text": "前总理下令全国进入紧急状态。", "explanation": "这里应该用〈现任总理〉。前总理已经卸任，不能下令让全国进入紧急状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前总理", "is_correct": true, "explanation": "正确。前总理作主语，指今年七十岁、身体很好的前任总理。"}, {"text": "前天", "is_correct": false, "explanation": "语义：“前天”是时间词，不能作指人的主语。"}, {"text": "前言", "is_correct": false, "explanation": "语义：“前言”指书籍的序言，不能指人。"}, {"text": "前景", "is_correct": false, "explanation": "语义：“前景”指事物将来的发展趋势，不能指人，也不能作“今年七十岁了”的主语。"}], "explanations": {"前总理": "正确。前总理作主语，指今年七十岁、身体很好的前任总理。", "前天": "语义：“前天”是时间词，不能作指人的主语。", "前言": "语义：“前言”指书籍的序言，不能指人。", "前景": "语义：“前景”指事物将来的发展趋势，不能指人，也不能作“今年七十岁了”的主语。"}, "sentence_index": 6, "correct_answer": "前总理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "前总理今天上午签发了一份任命书，秘书们忙个不停。", "explanation": "这里应该用〈现任总理〉。前总理已经卸任，不能签发任命书。"}, {"text": "前总理明天将以总理身份出访，他正在准备行程。", "explanation": "这里应该用〈现任总理〉。前总理已经卸任，不能以总理身份出访。"}, {"text": "前总理每天都要主持国务会议，忙得不可开交。", "explanation": "这里应该用〈现任总理〉。前总理已经卸任，不能每天主持国务会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只前总理每周都来社区讲课。", "corrected_sentence": "那位前总理每周都来社区讲课。", "error_description": "“前总理”指人，量词应用“位”，用“只”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位的前总理每天早上都去公园散步。", "corrected_sentence": "这位前总理每天早上都去公园散步。", "error_description": "“这位”与“前总理”之间不能插入“的”；“这位”直接修饰“前总理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
