INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91896, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "曾经担任过总理、现已卸任的人。", "primary_collocate": null, "pronunciation": "qián zǒng lǐ", "ipa": "tɕʰjɛn˧˥ tsʊŋ˨˩˦ li˨˩˦", "syllable_count": 3, "sentences": [{"text": "这位前总理已经卸任五年了。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Zhè wèi qián zǒng lǐ yǐjīng xièrèn wǔ nián le.", "sentence_source": "generated"}, {"text": "前总理的家在海边，房子不大。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Qián zǒng lǐ de jiā zài hǎibiān, fángzi bú dà.", "sentence_source": "generated"}, {"text": "记者想请前总理说说当年的事。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Jìzhě xiǎng qǐng qián zǒng lǐ shuōshuo dāngnián de shì.", "sentence_source": "generated"}, {"text": "那位前总理去年出版了一本新书。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Nà wèi qián zǒng lǐ qùnián chūbǎnle yì běn xīn shū.", "sentence_source": "generated"}, {"text": "前总理今天上午去医院看望老朋友。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Qián zǒng lǐ jīntiān shàngwǔ qù yīyuàn kànwàng lǎo péngyou.", "sentence_source": "generated"}, {"text": "很多人在街上等着前总理来。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Hěn duō rén zài jiē shang děngzhe qián zǒng lǐ lái.", "sentence_source": "generated"}, {"text": "他爸爸是前总理，可是他很普通。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Tā bàba shì qián zǒng lǐ, kěshì tā hěn pǔtōng.", "sentence_source": "generated"}, {"text": "前总理说，当总理的时候他很忙。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Qián zǒng lǐ shuō, dāng zǒnglǐ de shíhou tā hěn máng.", "sentence_source": "generated"}, {"text": "这位前总理常常在公园里跟老人下棋。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Zhè wèi qián zǒng lǐ chángcháng zài gōngyuán lǐ gēn lǎorén xiàqí.", "sentence_source": "generated"}, {"text": "报纸上有一张前总理年轻时的照片。", "target_word": "前总理", "complexity_tier": "T3", "furigana": "Bàozhǐ shang yǒu yì zhāng qián zǒng lǐ niánqīng shí de zhàopiàn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "前總理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "前总理：曾任总理、现已卸任者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eee8ab4b-9732-4bb5-bd7e-a6513a3e7225') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91896, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前总理", "is_correct": true, "explanation": "正确。前总理指曾任总理、现已卸任的人，与“卸任五年”相符。"}, {"text": "前奏", "is_correct": false, "explanation": "语义：“前奏”指音乐开始的部分，不能指人。"}, {"text": "前门", "is_correct": false, "explanation": "语义：“前门”指建筑的正面入口，不能指人，也不能“卸任”。"}, {"text": "前言", "is_correct": false, "explanation": "语义：“前言”指书籍的序言，不能指人。"}], "explanations": {"前总理": "正确。前总理指曾任总理、现已卸任的人，与“卸任五年”相符。", "前奏": "语义：“前奏”指音乐开始的部分，不能指人。", "前门": "语义：“前门”指建筑的正面入口，不能指人，也不能“卸任”。", "前言": "语义：“前言”指书籍的序言，不能指人。"}, "sentence_index": 0, "correct_answer": "前总理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那位前总理明天就要主持内阁会议。", "explanation": "这里应该用〈现任总理〉。前总理已经卸任，不能主持内阁会议。"}, {"text": "那位前总理上周刚刚组建了内阁，今天要签署法案。", "explanation": "这里应该用〈新任总理〉。前总理已经卸任，不能说“刚刚组建内阁”。"}, {"text": "那位前总理现在每天都要签署重要的法案。", "explanation": "这里应该用〈现任总理〉。前总理已经卸任，不能每天签署法案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91896, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前总理", "is_correct": true, "explanation": "正确。前总理作“是”的表语，指曾任总理的人，与“很普通”形成对比。"}, {"text": "前天", "is_correct": false, "explanation": "语义：“前天”是时间词，不能作指人的表语。"}, {"text": "前途", "is_correct": false, "explanation": "语义：“前途”指未来的发展，不能指人。"}, {"text": "前门", "is_correct": false, "explanation": "语义：“前门”指建筑的正面入口，不能指人。"}], "explanations": {"前总理": "正确。前总理作“是”的表语，指曾任总理的人，与“很普通”形成对比。", "前天": "语义：“前天”是时间词，不能作指人的表语。", "前途": "语义：“前途”指未来的发展，不能指人。", "前门": "语义：“前门”指建筑的正面入口，不能指人。"}, "sentence_index": 6, "correct_answer": "前总理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "报纸上说，前总理正在主持新一届内阁会议。", "explanation": "这里应该用〈现任总理〉。前总理已经卸任，不能主持内阁会议。"}, {"text": "报纸上说，前总理下周将主持政府的预算审议。", "explanation": "这里应该用〈现任总理〉。前总理已经卸任，不能主持政府的预算审议。"}, {"text": "报纸上写着，这位前总理还在任上，很忙。", "explanation": "这里应该用〈现任总理〉。前总理指已经卸任的人，“还在任上”与此矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只前总理退休以后，喜欢在河边散步。", "corrected_sentence": "那位前总理退休以后，喜欢在河边散步。", "error_description": "“前总理”指人，量词应用“位”，用“只”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位的前总理退休后，常常给学生写信。", "corrected_sentence": "这位前总理退休后，常常给学生写信。", "error_description": "“这位”与“前总理”之间不能插入“的”；“这位”直接修饰“前总理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd23f1238-0d03-425e-b2af-f860e7d43e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
