INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91897, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去问一问，找一找。", "primary_collocate": null, "pronunciation": "chá xún", "ipa": "ʈʂʰa˧˥ ɕyn˧˥", "syllable_count": 2, "sentences": [{"text": "你可以打电话查询航班时间。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想查询一下明天的天气。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请到前台查询你的房间号。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去车站查询了火车票的价格。", "target_word": "查询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不知道路，可以用手机查询。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去图书馆以前，我先查询了开门时间。", "target_word": "查询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题可以去服务台查询。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她正在查询去北京的飞机票。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想知道快递到哪儿了，可以自己查询。", "target_word": "查询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们查询一下这个词的意思。", "target_word": "查询", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "查询了", "label": "体标"}, {"form": "查询过", "label": "体标"}, {"form": "查询系统", "label": "复合"}, {"form": "查詢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "查询：为了知道某个信息而去问或去找", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91897, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "查询", "is_correct": true, "explanation": "正确：“查询”指打电话去问、去查航班时间，与句意相符。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象应是商品，不能说“购买航班时间”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是把坏了的东西弄好，航班时间不能被修理。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与打电话、航班时间毫无关系，句子说不通。"}], "explanations": {"查询": "正确：“查询”指打电话去问、去查航班时间，与句意相符。", "购买": "搭配：“购买”的对象应是商品，不能说“购买航班时间”。", "修理": "语义：“修理”是把坏了的东西弄好，航班时间不能被修理。", "吃": "语义：“吃”与打电话、航班时间毫无关系，句子说不通。"}, "sentence_index": 0, "correct_answer": "查询"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生查询了他的身体，发现他很健康。", "explanation": "这里应该用〈检查〉。查询用于在资料或系统中找信息，检查身体状况要用“检查”。"}, {"text": "妈妈查询了厨房的地板。", "explanation": "这里应该用〈打扫〉。查询是查找信息，清洁地面要用“打扫”。"}, {"text": "警察查询了小偷的作案动机。", "explanation": "这里应该用〈调查〉。查询不用于探究人的动机或原因，要用“调查”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "查询", "is_correct": true, "explanation": "正确：“查询”指去服务台问或查找信息，与“有问题”相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是人，不能说“去服务台欢迎”。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：“下棋”与解决问题无关，服务台不是下棋的地方。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是悠闲地走，与“有问题”要去解决的事情无关。"}], "explanations": {"查询": "正确：“查询”指去服务台问或查找信息，与“有问题”相符。", "欢迎": "搭配：“欢迎”的对象是人，不能说“去服务台欢迎”。", "下棋": "语义：“下棋”与解决问题无关，服务台不是下棋的地方。", "散步": "语义：“散步”是悠闲地走，与“有问题”要去解决的事情无关。"}, "sentence_index": 6, "correct_answer": "查询"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想查询他最近的心情。", "explanation": "这里应该用〈了解〉。查询用于查找信息，不能用来弄清别人的心情。"}, {"text": "工人查询了漏水的水管。", "explanation": "这里应该用〈修理〉。查询是查找信息，修好漏水的水管要用“修理”。"}, {"text": "妈妈查询了我的书包，把它放好。", "explanation": "这里应该用〈整理〉。查询针对信息，收拾物品要用“整理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想查询了一下后天的天气。", "corrected_sentence": "我想查询一下后天的天气。", "error_description": "“想”表示打算，后面不能接表示完成的“了”，应说“想查询一下”，不能说“想查询了一下”（“查询了一下”表示已经查过）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在网上查询了到航班信息。", "corrected_sentence": "我在网上查询到了航班信息。", "error_description": "“到”是结果补语，要紧跟动词，“了”应放在“到”后面，应说“查询到了”，不能说“查询了到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
