INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91898, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在系统、资料或记录中检索某项信息。", "primary_collocate": null, "pronunciation": "chá xún", "ipa": "ʈʂʰa˧˥ ɕyn˧˥", "syllable_count": 2, "sentences": [{"text": "银行卡里有多少钱，可以在机器上查询。", "target_word": "查询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "输入名字，系统就能查询到结果。", "target_word": "查询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站可以查询公司的信息。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生可以用学号查询考试成绩。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察查询了这辆车的资料。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆的电脑能查询到想借的书。", "target_word": "查询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请输入密码后再查询余额。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用身份证号码查询了自己的记录。", "target_word": "查询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上可以查询快递的位置。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以登录网站查询订单状态。", "target_word": "查询", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "查询了", "label": "体标"}, {"form": "查询过", "label": "体标"}, {"form": "查询结果", "label": "复合"}, {"form": "查詢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "查询：在系统、资料或记录中检索某项信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "查询", "is_correct": true, "explanation": "正确：“查询”指在机器上检索银行卡余额，与句意相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是坏了的物品，不能用来查看银行卡余额。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与银行卡里有多少钱毫无关系，句子说不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与银行卡余额无关，句子说不通。"}], "explanations": {"查询": "正确：“查询”指在机器上检索银行卡余额，与句意相符。", "修理": "搭配：“修理”的对象是坏了的物品，不能用来查看银行卡余额。", "唱歌": "语义：“唱歌”与银行卡里有多少钱毫无关系，句子说不通。", "吃": "语义：“吃”与银行卡余额无关，句子说不通。"}, "sentence_index": 0, "correct_answer": "查询"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用尺子查询了桌子的长度。", "explanation": "这里应该用〈测量〉。查询是在系统或资料中检索信息，用尺子量长度要用“测量”。"}, {"text": "妈妈用针线把我的破衣服查询好了。", "explanation": "这里应该用〈缝补〉。查询是在系统或资料中检索信息，用针线修补破衣服要用“缝补”。"}, {"text": "医生查询了他的心跳。", "explanation": "这里应该用〈检查〉。查询针对记录中的信息，检查身体状况要用“检查”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "查询", "is_correct": true, "explanation": "正确：“查询”指在系统中查看余额，与“输入密码”的步骤相符。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”的对象是人，不能用于“余额”。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：输入密码之后下棋，与余额毫无关系。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”与查看余额没有关系，句子说不通。"}], "explanations": {"查询": "正确：“查询”指在系统中查看余额，与“输入密码”的步骤相符。", "欢迎": "搭配：“欢迎”的对象是人，不能用于“余额”。", "下棋": "语义：输入密码之后下棋，与余额毫无关系。", "散步": "语义：“散步”与查看余额没有关系，句子说不通。"}, "sentence_index": 6, "correct_answer": "查询"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想查询他最近的心情。", "explanation": "这里应该用〈了解〉。查询用于查找信息，不能用来弄清别人的心情。"}, {"text": "工人查询了漏水的水管。", "explanation": "这里应该用〈修理〉。查询是检索信息，修好漏水的水管要用“修理”。"}, {"text": "我在草地上查询了一只小猫。", "explanation": "这里应该用〈发现〉。查询是检索信息，找到一只实物要用“发现”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在手机上查询了了快递的位置。", "corrected_sentence": "他在手机上查询了快递的位置。", "error_description": "“了”在动词后只能用一个，这里“查询了了”重复了“了”，应说“他在手机上查询了快递的位置”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "系统查询了出三条记录。", "corrected_sentence": "系统查询出了三条记录。", "error_description": "“出”是结果补语，要紧跟动词，“了”应放在“出”后面，应说“查询出了”，不能说“查询了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
