INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91899, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "废除是把旧规矩不要了，取消掉。", "primary_collocate": null, "pronunciation": "fèi chú", "ipa": "feɪ⁵¹ ʈʂʰu³⁵", "syllable_count": 2, "sentences": [{"text": "学校废除了宿舍的旧规矩。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说要废除以前的座位办法。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班废除了每天扫地的老规定。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂废除了上班不许说话的规矩。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司废除了上班要打卡的做法。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把这个旧规定废除了。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起废除了这条没用的规矩。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里废除了过年必须请客的规矩。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新老板废除了很多旧制度。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校废除了晚上不能玩手机的规定。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "废除了", "label": "体标（了）"}, {"form": "废除过", "label": "体标（过）"}], "register": "正式", "sense_fingerprint": "不再要旧规矩，把它取消", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91899, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指毁坏实物，规矩不能被烧毁。"}, {"text": "废除", "is_correct": true, "explanation": "正确：“废除”指取消旧规矩，与“宿舍的旧规矩”相合。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”用于破损的物件，不能用于规矩。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指种庄稼或树木，与规矩无关。"}], "explanations": {"烧毁": "语义：“烧毁”指毁坏实物，规矩不能被烧毁。", "废除": "正确：“废除”指取消旧规矩，与“宿舍的旧规矩”相合。", "修补": "搭配：“修补”用于破损的物件，不能用于规矩。", "种植": "语义：“种植”指种庄稼或树木，与规矩无关。"}, "sentence_index": 0, "correct_answer": "废除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们废除了桌上的垃圾。", "explanation": "这里应该用〈清除〉。“废除”指取消规矩，清理垃圾要用“清除”。"}, {"text": "老板废除了那个员工。", "explanation": "这里应该用〈解雇〉。“废除”不用于人，辞退员工要用“解雇”。"}, {"text": "工人废除了工作。", "explanation": "这里应该用〈停止〉。“废除”指取消规矩，停下工作要用“停止”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91899, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭，与规矩无关。"}, {"text": "摘取", "is_correct": false, "explanation": "搭配：“摘取”用于果实、荣誉，不能用于规矩。"}, {"text": "废除", "is_correct": true, "explanation": "正确：“废除”指取消规矩，与“没用的规矩”相合。"}, {"text": "浇灌", "is_correct": false, "explanation": "语义：“浇灌”指给植物浇水，与规矩无关。"}], "explanations": {"烹饪": "语义：“烹饪”指做饭，与规矩无关。", "摘取": "搭配：“摘取”用于果实、荣誉，不能用于规矩。", "废除": "正确：“废除”指取消规矩，与“没用的规矩”相合。", "浇灌": "语义：“浇灌”指给植物浇水，与规矩无关。"}, "sentence_index": 6, "correct_answer": "废除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他废除了刚交的报名表。", "explanation": "这里应该用〈撤回〉。“废除”指取消规矩，撤回已交的报名表要用“撤回”。"}, {"text": "士兵废除了那个入侵者。", "explanation": "这里应该用〈驱逐〉。“废除”不用于人，把入侵者赶出去要用“驱逐”。"}, {"text": "我们要废除心里的疑虑。", "explanation": "这里应该用〈消除〉。“废除”指取消规矩，去掉疑虑要用“消除”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91899, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校明天废除了这条规矩。", "corrected_sentence": "学校明天废除这条规矩。", "error_description": "错误：“明天”指将来，“废除”后不能加“了”。正确：将来的动作不用“了”，应说“学校明天废除这条规矩。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91899, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家一起废除得这条规矩。", "corrected_sentence": "大家一起废除这条规矩。", "error_description": "助词错误：“废除”后接“得”需要补语，句子不成立。正确：应去掉“得”，说“大家一起废除这条规矩。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
