INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取消；废止（法令、制度等）。", "primary_collocate": null, "pronunciation": "fèi chú", "ipa": "feɪ⁵¹ ʈʂʰu³⁵", "syllable_count": 2, "sentences": [{"text": "这个国家废除了死刑。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府决定废除这条旧法律。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校废除了那条不合理的规定。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人希望废除这种制度。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司废除了迟到扣钱的办法。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国会去年废除了这条法令。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家早就废除了奴隶制度。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都同意废除这个旧规定。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要求废除不公平的条约。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项制度废除以后，人们的生活好多了。", "target_word": "废除", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "废除了", "label": "体标（了）"}, {"form": "废除过", "label": "体标（过）"}], "register": "正式", "sense_fingerprint": "正式取消法令、制度等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f844a7-37b6-46f8-b44a-6d095923f5a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，死刑不能被发明。"}, {"text": "废除", "is_correct": true, "explanation": "正确：“废除”指取消法律、制度，与“死刑”相合。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：“出版”用于书刊，不能用于制度。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指种庄稼或树木，与死刑无关。"}], "explanations": {"发明": "语义：“发明”指创造新事物，死刑不能被发明。", "废除": "正确：“废除”指取消法律、制度，与“死刑”相合。", "出版": "搭配：“出版”用于书刊，不能用于制度。", "种植": "语义：“种植”指种庄稼或树木，与死刑无关。"}, "sentence_index": 0, "correct_answer": "废除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法院废除了这份判决。", "explanation": "这里应该用〈撤销〉。“废除”用于法令、制度，取消法院的判决要用“撤销”。"}, {"text": "工厂废除了生产。", "explanation": "这里应该用〈停止〉。“废除”指取消法令或制度，工厂暂停生产要用“停止”。"}, {"text": "公司废除了他。", "explanation": "这里应该用〈解雇〉。“废除”只用于制度、法令，不能用于人，辞退员工要用“解雇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修建", "is_correct": false, "explanation": "搭配：“修建”用于房屋、道路，不能用于制度。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭，与奴隶制度无关。"}, {"text": "废除", "is_correct": true, "explanation": "正确：“废除”指取消制度，与“奴隶制度”相合。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”用于文章、声明，不能用于制度。"}], "explanations": {"修建": "搭配：“修建”用于房屋、道路，不能用于制度。", "烹饪": "语义：“烹饪”指做饭，与奴隶制度无关。", "废除": "正确：“废除”指取消制度，与“奴隶制度”相合。", "发表": "搭配：“发表”用于文章、声明，不能用于制度。"}, "sentence_index": 6, "correct_answer": "废除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他废除了这份申请。", "explanation": "这里应该用〈撤回〉。“废除”用于法令、制度，撤回已提交的申请要用“撤回”。"}, {"text": "警察废除了那个外国人。", "explanation": "这里应该用〈驱逐〉。“废除”不用于人，把外国人赶出境要用“驱逐”。"}, {"text": "我们要废除这个误会。", "explanation": "这里应该用〈消除〉。“废除”用于制度、法令，去掉误会要用“消除”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府明年废除了这项规定。", "corrected_sentence": "政府明年废除这项规定。", "error_description": "错误：“明年”指将来，“废除”后不能加“了”。正确：将来的动作不用“了”，应说“政府明年废除这项规定。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府废除得这条法律。", "corrected_sentence": "政府废除了这条法律。", "error_description": "助词错误：“废除”后接“得”需要补语，句子不成立。正确：“废除”后用“了”表示完成，应说“政府废除了这条法律。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfb926f5-1724-45b0-9e95-046b100ec553') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人道", "is_correct": true, "explanation": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质"}, {"text": "凶狠", "is_correct": false, "explanation": "凶狠指恶狠狠的样子，与「反人类」不构成反义"}, {"text": "残忍", "is_correct": false, "explanation": "近义：「残忍」与「反人类」意思相近，不是反义词"}, {"text": "冷漠", "is_correct": false, "explanation": "冷漠指对人缺乏热情，与「反人类」不构成词典列出的反义"}], "correct_answer": "人道", "explanations": {"人道": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质", "凶狠": "凶狠指恶狠狠的样子，与「反人类」不构成反义", "残忍": "近义：「残忍」与「反人类」意思相近，不是反义词", "冷漠": "冷漠指对人缺乏热情，与「反人类」不构成词典列出的反义"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人道", "is_correct": true, "explanation": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质"}, {"text": "粗鲁", "is_correct": false, "explanation": "粗鲁指言行不文雅，与「反人类」不构成反义"}, {"text": "随和", "is_correct": false, "explanation": "随和指性情温和、容易相处，与「反人类」不构成反义"}, {"text": "活泼", "is_correct": false, "explanation": "活泼指生动、爱动，与「反人类」不构成反义"}], "correct_answer": "人道", "explanations": {"人道": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质", "粗鲁": "粗鲁指言行不文雅，与「反人类」不构成反义", "随和": "随和指性情温和、容易相处，与「反人类」不构成反义", "活泼": "活泼指生动、爱动，与「反人类」不构成反义"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "反人类是对人们非常坏、非常残忍的。", "primary_collocate": null, "pronunciation": "fǎn rén lèi", "ipa": "fan˨˩˦ ɻən˧˥ lei˥˩", "syllable_count": 3, "sentences": [{"text": "他这样对待小狗，太反人类了。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老板让工人天天工作十八小时，真反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这种方法惩罚孩子，实在太反人类了。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把病人关在黑屋子里，这种做法很反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里的坏人做事非常反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得不给工人水喝，这样做太反人类了。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个故事里的国王又坏又残忍，他的法律很反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打骂老人，大家都说他的行为反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不让饿了的孩子吃饭，这个规定太反人类了。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到他那样折磨小动物，我觉得特别反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反人类罪", "label": "复合词"}], "register": "口语", "sense_fingerprint": "日常口语中形容做法对人非常坏、非常残忍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4c1239-4184-41d0-a500-af91482a0938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，不能用来评价对待小狗的方式"}, {"text": "反人类", "is_correct": true, "explanation": "正确：「反人类」在口语中形容对人非常坏、非常残忍，符合句意"}, {"text": "冷清", "is_correct": false, "explanation": "语义：「冷清」形容场所或氛围，与对待方式不相关"}, {"text": "高大", "is_correct": false, "explanation": "搭配：「高大」形容身材或物体的高度，不能修饰「对待」的方式"}], "explanations": {"甜": "语义：「甜」形容味道，不能用来评价对待小狗的方式", "反人类": "正确：「反人类」在口语中形容对人非常坏、非常残忍，符合句意", "冷清": "语义：「冷清」形容场所或氛围，与对待方式不相关", "高大": "搭配：「高大」形容身材或物体的高度，不能修饰「对待」的方式"}, "sentence_index": 0, "correct_answer": "反人类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天给孩子讲故事，这种做法很反人类。", "explanation": "这里应该用〈温馨〉。反人类指对人非常坏、非常残忍，给孩子讲故事是温暖的行为，要说温馨"}, {"text": "我们每次都帮老人过马路，真反人类。", "explanation": "这里应该用〈体贴〉。反人类指对人非常坏、非常残忍，帮老人过马路是体贴的行为，要说体贴"}, {"text": "他把自己的零花钱全部捐给了灾区，这种做法很反人类。", "explanation": "这里应该用〈慷慨〉。反人类指对人非常坏、非常残忍，捐钱救灾是善举，要说慷慨"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苦", "is_correct": false, "explanation": "语义：「苦」形容味道或处境，不能用来形容法律"}, {"text": "反人类", "is_correct": true, "explanation": "正确：「反人类」在口语中形容对人非常残忍，符合句意"}, {"text": "香", "is_correct": false, "explanation": "语义：「香」形容气味或味道，与「法律」不相容"}, {"text": "亮", "is_correct": false, "explanation": "搭配：「亮」多形容光线或颜色，不能修饰「法律」"}], "explanations": {"苦": "语义：「苦」形容味道或处境，不能用来形容法律", "反人类": "正确：「反人类」在口语中形容对人非常残忍，符合句意", "香": "语义：「香」形容气味或味道，与「法律」不相容", "亮": "搭配：「亮」多形容光线或颜色，不能修饰「法律」"}, "sentence_index": 6, "correct_answer": "反人类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把路边那棵老树砍得很反人类。", "explanation": "这里应该用〈粗暴〉。反人类描述的是对人非常残忍，砍树属于对树木的粗暴，不能说反人类"}, {"text": "志愿者每周去养老院陪伴老人，这种做法很反人类。", "explanation": "这里应该用〈关怀〉。反人类指对人非常坏、非常残忍，陪伴老人是关怀的行为，意思相反"}, {"text": "老师耐心地教我们做题，真是太反人类了。", "explanation": "这里应该用〈耐心〉。反人类指对人非常坏、非常残忍，耐心教学是对学生有益的行为，要说耐心"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的做法太反人类的了。", "corrected_sentence": "他的做法太反人类了。", "error_description": "错误：「反人类」作谓语后，「的」和「了」不能同时出现，「太反人类的了」不成立；正确：应说「太反人类了」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种惩罚太反人类的了。", "corrected_sentence": "这种惩罚太反人类了。", "error_description": "错误：「反人类」作谓语时，「太……了」中间不能加「的」，「太反人类的了」不成立；正确：应说「太反人类了」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人道", "is_correct": true, "explanation": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质"}, {"text": "残酷", "is_correct": false, "explanation": "近义：「残酷」与「反人类」意思相近，不是反义词"}, {"text": "勤奋", "is_correct": false, "explanation": "勤奋指努力用功，与「反人类」不构成反义"}, {"text": "平凡", "is_correct": false, "explanation": "平凡指普通、不突出，与「反人类」不构成反义"}], "correct_answer": "人道", "explanations": {"人道": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质", "残酷": "近义：「残酷」与「反人类」意思相近，不是反义词", "勤奋": "勤奋指努力用功，与「反人类」不构成反义", "平凡": "平凡指普通、不突出，与「反人类」不构成反义"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人道", "is_correct": true, "explanation": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质"}, {"text": "冷酷", "is_correct": false, "explanation": "近义：「冷酷」与「反人类」意思相近，不是反义词"}, {"text": "正直", "is_correct": false, "explanation": "正直指品行端正，与「反人类」不构成反义"}, {"text": "轻快", "is_correct": false, "explanation": "轻快指轻松活泼，与「反人类」不构成反义"}], "correct_answer": "人道", "explanations": {"人道": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质", "冷酷": "近义：「冷酷」与「反人类」意思相近，不是反义词", "正直": "正直指品行端正，与「反人类」不构成反义", "轻快": "轻快指轻松活泼，与「反人类」不构成反义"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "严重危害人类的；极端残暴的。", "primary_collocate": null, "pronunciation": "fǎn rén lèi", "ipa": "fan˨˩˦ ɻən˧˥ lei˥˩", "syllable_count": 3, "sentences": [{"text": "战争中的这些罪行是反人类的。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院认为他的行为是反人类的罪行。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都反对这种反人类的暴行。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在战争中犯下了反人类的罪行。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用毒气杀害平民是反人类的行为。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国谴责了这次反人类的屠杀。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的政府做了很多反人类的事。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上，老师讲了反人类的暴行。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说，这些人要为反人类的行为负责。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虐待俘虏是极其反人类的做法。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反人类罪", "label": "复合词"}], "register": "书面", "sense_fingerprint": "形容罪行、暴行严重危害人类、极其残暴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e4c1239-4184-41d0-a500-af91482a0938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好", "is_correct": false, "explanation": "语义：「好」是褒义，与「罪行」的恶性相矛盾，句子意思颠倒"}, {"text": "反人类", "is_correct": true, "explanation": "正确：「反人类」形容严重危害人类的罪行，符合句意"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：「漂亮」形容外表或事物的美好，不能用来修饰「罪行」"}, {"text": "轻松", "is_correct": false, "explanation": "语义：「轻松」指不费力或心情舒适，不能用于形容罪行"}], "explanations": {"好": "语义：「好」是褒义，与「罪行」的恶性相矛盾，句子意思颠倒", "反人类": "正确：「反人类」形容严重危害人类的罪行，符合句意", "漂亮": "搭配：「漂亮」形容外表或事物的美好，不能用来修饰「罪行」", "轻松": "语义：「轻松」指不费力或心情舒适，不能用于形容罪行"}, "sentence_index": 0, "correct_answer": "反人类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老奶奶把自己的午饭分给了流浪猫，这种行为很反人类。", "explanation": "这里应该用〈善良〉。反人类指严重危害人类、极端残暴，分食救助流浪猫是善良的行为，要说善良"}, {"text": "消防员冒着大火救出了三个孩子，这是极其反人类的行为。", "explanation": "这里应该用〈英勇〉。反人类指严重危害人类、极端残暴，冒险救人是英勇的行为，要说英勇"}, {"text": "志愿者在灾区连续工作了三天，他们的精神非常反人类。", "explanation": "这里应该用〈坚韧〉。反人类指严重危害人类、极端残暴，连续奋战的精神要说坚韧"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，不能用来形容政府做的事"}, {"text": "反人类", "is_correct": true, "explanation": "正确：「反人类」形容严重危害人类的行为，符合句意"}, {"text": "凉快", "is_correct": false, "explanation": "语义：「凉快」形容温度感受，与「做的事」不相容"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：「湿润」形容物体含水，不能修饰「事」"}], "explanations": {"甜": "语义：「甜」形容味道，不能用来形容政府做的事", "反人类": "正确：「反人类」形容严重危害人类的行为，符合句意", "凉快": "语义：「凉快」形容温度感受，与「做的事」不相容", "湿润": "搭配：「湿润」形容物体含水，不能修饰「事」"}, "sentence_index": 6, "correct_answer": "反人类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他帮邻居修好了屋顶，这是很反人类的事。", "explanation": "这里应该用〈友善〉。反人类指严重危害人类、极端残暴，帮邻居修屋顶是对人有益的善举，要说友善"}, {"text": "妈妈每天早起做饭，这种付出十分反人类。", "explanation": "这里应该用〈无私〉。反人类指严重危害人类、极端残暴，妈妈的付出是爱与奉献，要说无私"}, {"text": "大家都在努力保护环境，这种行为很反人类。", "explanation": "这里应该用〈有益〉。反人类指严重危害人类，保护环境对人类有益，要说有益"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们被控犯有反人类。", "corrected_sentence": "他们被控犯有反人类罪。", "error_description": "错误：「反人类」是形容词，不能作「犯有」的宾语，「犯有」需要名词，缺少「罪」；正确：应说「反人类罪」，这是名词复合词", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次屠杀是反人类。", "corrected_sentence": "这次屠杀是反人类的。", "error_description": "错误：「是」字判断句中形容词「反人类」后缺少「的」；正确：应说「这次屠杀是反人类的」，「的」要放在形容词之后", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e99db2b-f371-4bca-a83b-2a8b46ba82ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
