INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91903, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子顶上，撑着屋顶的长木头。", "primary_collocate": null, "pronunciation": "liáng", "ipa": "ljaŋ˧˥", "syllable_count": 1, "sentences": [{"text": "屋顶上有一根很粗的梁。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老房子的梁已经很旧了。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那根梁是木头做的，很长。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "梁断了，房子不安全了。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们把梁抬到了屋顶上。", "target_word": "梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梁坏了，要换一根新的。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一只小鸟站在梁上唱歌。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根梁撑着整个屋顶。", "target_word": "梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梁下面有两根大柱子。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷说，这根梁已经用了一百年。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "房梁", "label": "复合"}, {"form": "横梁", "label": "复合"}, {"form": "大梁", "label": "复合"}], "register": "中性", "sense_fingerprint": "梁：房子顶上撑着屋顶的长木头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91903, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梁", "is_correct": true, "explanation": "正确：梁（liáng），指房顶上撑着屋顶的长木头。"}, {"text": "两", "is_correct": false, "explanation": "liǎng（第三声）与 liáng（第二声）声调不同，意思是“两个”。"}, {"text": "亮", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是“明亮”。"}, {"text": "谅", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是“原谅”。"}, {"text": "连", "is_correct": false, "explanation": "lián 与 liáng 韵母不同（-ian 与 -iang），意思是“连接”。"}], "explanations": {"梁": "正确：梁（liáng），指房顶上撑着屋顶的长木头。", "两": "liǎng（第三声）与 liáng（第二声）声调不同，意思是“两个”。", "亮": "liàng（第四声）与 liáng（第二声）声调不同，意思是“明亮”。", "谅": "liàng（第四声）与 liáng（第二声）声调不同，意思是“原谅”。", "连": "lián 与 liáng 韵母不同（-ian 与 -iang），意思是“连接”。"}, "sentence_index": null, "correct_answer": "梁"}, "level_3": {"options": [{"text": "梁", "is_correct": true, "explanation": "正确：“梁”是房顶上撑着屋顶的长木头，与“一根很粗的”相符。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“根”和“粗”用于条状的实物，水是液体，不能说“一根很粗的水”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，不能是屋顶上的一根东西。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事是抽象的内容，不能是屋顶上的一根东西。"}], "explanations": {"梁": "正确：“梁”是房顶上撑着屋顶的长木头，与“一根很粗的”相符。", "水": "搭配：“根”和“粗”用于条状的实物，水是液体，不能说“一根很粗的水”。", "空气": "语义：空气看不见，不能是屋顶上的一根东西。", "故事": "语义：故事是抽象的内容，不能是屋顶上的一根东西。"}, "sentence_index": 0, "correct_answer": "梁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋顶上有一只梁。", "explanation": "这里应该用〈根〉。梁是长条形木料，量词用“根”，不用“只”。"}, {"text": "这根梁竖在地上，支撑着房子。", "explanation": "这里应该用〈柱子〉。梁是横放在墙或柱子上的木料，竖着立在地上、支撑房子的要说“柱子”。"}, {"text": "农民把梁装进粮仓里。", "explanation": "这里应该用〈粮食〉。梁是房屋的木构件，装进粮仓的要说“粮食”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91903, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "梁", "is_correct": true, "explanation": "正确：梁（liáng），指房顶上撑着屋顶的长木头。"}, {"text": "辆", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，是车的量词“一辆”。"}, {"text": "娘", "is_correct": false, "explanation": "niáng 与 liáng 声母不同（n 与 l），意思是“母亲”。"}, {"text": "莲", "is_correct": false, "explanation": "lián 与 liáng 韵母不同（-ian 与 -iang），意思是“莲花”。"}], "explanations": {"梁": "正确：梁（liáng），指房顶上撑着屋顶的长木头。", "辆": "liàng（第四声）与 liáng（第二声）声调不同，是车的量词“一辆”。", "娘": "niáng 与 liáng 声母不同（n 与 l），意思是“母亲”。", "莲": "lián 与 liáng 韵母不同（-ian 与 -iang），意思是“莲花”。"}, "sentence_index": null, "correct_answer": "梁"}, "level_3": {"options": [{"text": "梁", "is_correct": true, "explanation": "正确：“梁”是横木，小鸟可以站在上面。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是人或事物的称呼，不是可以站立的地方。"}, {"text": "歌", "is_correct": false, "explanation": "配价：“站在……上”要求处所名词，“歌”不能作处所。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想是抽象的，小鸟不能站在它上面。"}], "explanations": {"梁": "正确：“梁”是横木，小鸟可以站在上面。", "名字": "语义：名字是人或事物的称呼，不是可以站立的地方。", "歌": "配价：“站在……上”要求处所名词，“歌”不能作处所。", "思想": "语义：思想是抽象的，小鸟不能站在它上面。"}, "sentence_index": 6, "correct_answer": "梁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根梁很甜，可以直接吃。", "explanation": "这里应该用〈甘蔗〉。梁是木构件，不能吃，能直接吃的甜东西要说“甘蔗”。"}, {"text": "这根梁很细，可以用来穿针。", "explanation": "这里应该用〈线〉。梁是粗大的木构件，不能用来穿针，穿针要用“线”。"}, {"text": "屋顶上铺满了梁。", "explanation": "这里应该用〈瓦片〉。梁是横木，不能用来铺屋顶，屋顶要铺瓦片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91903, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只木梁撑着整个屋顶。", "corrected_sentence": "这根木梁撑着整个屋顶。", "error_description": "“梁”是长条形的木料，量词要用“根”，不能用“只”，应说“这根木梁”，不能说“这只木梁”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91903, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根木梁着撑整个房子。", "corrected_sentence": "这根木梁撑着整个房子。", "error_description": "“着”要紧跟动词，应说“撑着”，不能说“着撑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
