INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "架在墙或柱上支撑屋顶的横木。", "primary_collocate": null, "pronunciation": "liáng", "ipa": "ljaŋ˧˥", "syllable_count": 1, "sentences": [{"text": "木工把梁架在两面墙上。", "target_word": "梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梁的两头放在柱子上。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根梁横着架在墙上。", "target_word": "梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柱子上面架着一根梁。", "target_word": "梁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "梁放好以后，才能盖屋顶。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "师傅正在墙上装梁。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "梁要放平，屋顶才不会歪。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根梁不能放在湿的地方。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爬上梯子，检查墙上的梁。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两面墙中间要搭一根梁。", "target_word": "梁", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "房梁", "label": "复合"}, {"form": "横梁", "label": "复合"}, {"form": "大梁", "label": "复合"}], "register": "中性", "sense_fingerprint": "梁：架在墙或柱子上、用来支撑屋顶的横木", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a496a96-4d56-43eb-bcc0-f82a7320254a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91904, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梁", "is_correct": true, "explanation": "正确：梁（liáng），指架在墙或柱子上、支撑屋顶的横木。"}, {"text": "两", "is_correct": false, "explanation": "liǎng（第三声）与 liáng（第二声）声调不同，意思是“两个”。"}, {"text": "亮", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是“明亮”。"}, {"text": "谅", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，意思是“原谅”。"}, {"text": "连", "is_correct": false, "explanation": "lián 与 liáng 韵母不同（-ian 与 -iang），意思是“连接”。"}], "explanations": {"梁": "正确：梁（liáng），指架在墙或柱子上、支撑屋顶的横木。", "两": "liǎng（第三声）与 liáng（第二声）声调不同，意思是“两个”。", "亮": "liàng（第四声）与 liáng（第二声）声调不同，意思是“明亮”。", "谅": "liàng（第四声）与 liáng（第二声）声调不同，意思是“原谅”。", "连": "lián 与 liáng 韵母不同（-ian 与 -iang），意思是“连接”。"}, "sentence_index": null, "correct_answer": "梁"}, "level_3": {"options": [{"text": "梁", "is_correct": true, "explanation": "正确：“梁”是架在墙上的横木，与“架在两面墙上”相符。"}, {"text": "钉子", "is_correct": false, "explanation": "搭配：“架”要用于长条形的东西，钉子细小，不能说“架钉子”。"}, {"text": "水", "is_correct": false, "explanation": "语义：水是液体，不能被架在墙上。"}, {"text": "烟", "is_correct": false, "explanation": "语义：烟是气体，不能被架在墙上。"}], "explanations": {"梁": "正确：“梁”是架在墙上的横木，与“架在两面墙上”相符。", "钉子": "搭配：“架”要用于长条形的东西，钉子细小，不能说“架钉子”。", "水": "语义：水是液体，不能被架在墙上。", "烟": "语义：烟是气体，不能被架在墙上。"}, "sentence_index": 0, "correct_answer": "梁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "柱子上面架着一只梁。", "explanation": "这里应该用〈根〉。梁是长条形木料，量词用“根”，不用“只”。"}, {"text": "妈妈用梁缝了一件衣服。", "explanation": "这里应该用〈针线〉。梁是木构件，缝衣服要用针线。"}, {"text": "屋顶上铺着很多梁。", "explanation": "这里应该用〈瓦〉。梁是横木，屋顶上铺的是瓦，不是梁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91904, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "梁", "is_correct": true, "explanation": "正确：梁（liáng），指架在墙或柱子上、支撑屋顶的横木。"}, {"text": "辆", "is_correct": false, "explanation": "liàng（第四声）与 liáng（第二声）声调不同，是车的量词“一辆”。"}, {"text": "娘", "is_correct": false, "explanation": "niáng 与 liáng 声母不同（n 与 l），意思是“母亲”。"}, {"text": "莲", "is_correct": false, "explanation": "lián 与 liáng 韵母不同（-ian 与 -iang），意思是“莲花”。"}], "explanations": {"梁": "正确：梁（liáng），指架在墙或柱子上、支撑屋顶的横木。", "辆": "liàng（第四声）与 liáng（第二声）声调不同，是车的量词“一辆”。", "娘": "niáng 与 liáng 声母不同（n 与 l），意思是“母亲”。", "莲": "lián 与 liáng 韵母不同（-ian 与 -iang），意思是“莲花”。"}, "sentence_index": null, "correct_answer": "梁"}, "level_3": {"options": [{"text": "梁", "is_correct": true, "explanation": "正确：“梁”是横木，放平以后屋顶才不会歪，与句意相符。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗影，不能被放平来支撑屋顶。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见摸不着，与屋顶歪不歪没有关系。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，与屋顶歪不歪没有关系。"}], "explanations": {"梁": "正确：“梁”是横木，放平以后屋顶才不会歪，与句意相符。", "影子": "语义：影子是光线形成的暗影，不能被放平来支撑屋顶。", "声音": "语义：声音看不见摸不着，与屋顶歪不歪没有关系。", "名字": "语义：名字是称呼，与屋顶歪不歪没有关系。"}, "sentence_index": 6, "correct_answer": "梁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根梁竖在屋角，撑着屋顶。", "explanation": "这里应该用〈柱子〉。梁是横放的木料，竖着立在屋角撑屋顶的要说“柱子”。"}, {"text": "这根梁很平整，可以用来写字。", "explanation": "这里应该用〈纸〉。梁是承重的横木，写字要用纸。"}, {"text": "梁很硬，用来砌墙。", "explanation": "这里应该用〈砖〉。梁是木构件，砌墙要用砖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把梁架那面墙上。", "corrected_sentence": "工人把梁架在那面墙上。", "error_description": "“架”后面要用“在”引出处所，应说“架在那面墙上”，不能说“架那面墙上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋顶的一只梁装好以后，才能盖瓦。", "corrected_sentence": "屋顶的一根梁装好以后，才能盖瓦。", "error_description": "“梁”是长条形的木料，量词要用“根”，不能用“只”，应说“一根梁”，不能说“一只梁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca5d92bd-e7f1-4a40-8301-3aba10c0cb08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
