INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91905, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "戏是演员在台上演的故事。", "primary_collocate": null, "pronunciation": "xì", "ipa": "ɕi˥˩", "syllable_count": 1, "sentences": [{"text": "这出戏很好看。", "target_word": "戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喜欢看戏。", "target_word": "戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这出戏讲的是一家人的故事。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台上的演员正在演一出老戏。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这出戏有三个演员，故事很短。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天我和妈妈去看了一出新戏。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这出戏的故事很感人，我看哭了。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写了一出戏，讲的是小时候的朋友。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人最爱看这出戏，因为故事里的人都很好。", "target_word": "戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完这出戏，我才明白那个故事的意思。", "target_word": "戏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "戏迷", "label": "复合"}, {"form": "戏台", "label": "复合"}, {"form": "戲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "戏：演员在台上演出的一个故事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1766c185-9168-436d-834a-7e1714ef858c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "戏", "is_correct": true, "explanation": "戏（xì）指演员在台上演的故事，是正确答案。"}, {"text": "西", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是西方。"}, {"text": "吸", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是吸入。"}, {"text": "洗", "is_correct": false, "explanation": "xǐ（第三声）与 xì（第四声）声调不同，意思是清洗。"}, {"text": "喜", "is_correct": false, "explanation": "xǐ（第三声）与 xì（第四声）声调不同，意思是高兴。"}, {"text": "习", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是练习。"}], "explanations": {"戏": "戏（xì）指演员在台上演的故事，是正确答案。", "西": "xī（第一声）与 xì（第四声）声调不同，意思是西方。", "吸": "xī（第一声）与 xì（第四声）声调不同，意思是吸入。", "洗": "xǐ（第三声）与 xì（第四声）声调不同，意思是清洗。", "喜": "xǐ（第三声）与 xì（第四声）声调不同，意思是高兴。", "习": "xí（第二声）与 xì（第四声）声调不同，意思是练习。"}, "sentence_index": null, "correct_answer": "戏"}, "level_3": {"options": [{"text": "戏", "is_correct": true, "explanation": "戏：指舞台上演的戏剧，“这出戏”即一部剧目，是正确答案。"}, {"text": "惨剧", "is_correct": false, "explanation": "语义：“惨剧”指悲惨的事件，与“很好看”的评价相冲突。"}, {"text": "丑剧", "is_correct": false, "explanation": "语义：“丑剧”指丑陋或荒唐的表演，与“很好看”的评价相冲突。"}, {"text": "灾难", "is_correct": false, "explanation": "搭配：“灾难”不用量词“出”计量，且“很好看”不能用来形容灾难。"}], "explanations": {"戏": "戏：指舞台上演的戏剧，“这出戏”即一部剧目，是正确答案。", "惨剧": "语义：“惨剧”指悲惨的事件，与“很好看”的评价相冲突。", "丑剧": "语义：“丑剧”指丑陋或荒唐的表演，与“很好看”的评价相冲突。", "灾难": "搭配：“灾难”不用量词“出”计量，且“很好看”不能用来形容灾难。"}, "sentence_index": 0, "correct_answer": "戏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨晚看了一块戏，故事很感人。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“块”计量，“块”多用于石头、肥皂、土地等。"}, {"text": "这首戏的故事很感人，我看了很多遍。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“首”计量，“首”用于诗词和歌曲。"}, {"text": "他看了一幅戏，觉得很有意思。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“幅”计量，“幅”用于画作、照片等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91905, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "戏", "is_correct": true, "explanation": "戏（xì）指演员在台上演的故事，是正确答案。"}, {"text": "希", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是希望。"}, {"text": "息", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是呼吸或消息。"}, {"text": "溪", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是小河。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是座位。"}, {"text": "袭", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是袭击。"}], "explanations": {"戏": "戏（xì）指演员在台上演的故事，是正确答案。", "希": "xī（第一声）与 xì（第四声）声调不同，意思是希望。", "息": "xī（第一声）与 xì（第四声）声调不同，意思是呼吸或消息。", "溪": "xī（第一声）与 xì（第四声）声调不同，意思是小河。", "席": "xí（第二声）与 xì（第四声）声调不同，意思是座位。", "袭": "xí（第二声）与 xì（第四声）声调不同，意思是袭击。"}, "sentence_index": null, "correct_answer": "戏"}, "level_3": {"options": [{"text": "戏", "is_correct": true, "explanation": "戏：指舞台剧目，“这出戏”即一部剧，是正确答案。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“照片”不用量词“出”计量，也不是演出来的故事。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“饭菜”不用量词“出”计量，也没有“故事”。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：「笑话」指可笑的事，与「故事很感人，我看哭了」不符。"}], "explanations": {"戏": "戏：指舞台剧目，“这出戏”即一部剧，是正确答案。", "照片": "搭配：“照片”不用量词“出”计量，也不是演出来的故事。", "饭菜": "搭配：“饭菜”不用量词“出”计量，也没有“故事”。", "笑话": "语义：「笑话」指可笑的事，与「故事很感人，我看哭了」不符。"}, "sentence_index": 6, "correct_answer": "戏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看完一座戏，才明白那个故事的意思。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“座”计量，“座”用于山、桥、房屋等大型物体。"}, {"text": "妈妈今天带我去看一道戏，我很喜欢。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“道”计量，“道”用于菜、门、题、墙等。"}, {"text": "他做戏给别人看，才明白那个故事的意思。", "explanation": "这里的“做戏”指假装，表示“假装”的意思，与句中看完剧目的意思不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "剧团今晚演一张新戏。", "corrected_sentence": "剧团今晚演一出新戏。", "error_description": "量词错误：演出一部剧目，量词应用“出”（或“场”），不用“张”。“张”用于纸张、票、桌子等扁平物。应为“一出新戏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们昨晚演了一幅戏，观众都很感动。", "corrected_sentence": "他们昨晚演了一出戏，观众都很感动。", "error_description": "量词错误：「戏」的量词应为「出」，「幅」用于画作、照片等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
