INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "戏剧；演出。", "primary_collocate": null, "pronunciation": "xì", "ipa": "ɕi˥˩", "syllable_count": 1, "sentences": [{"text": "今晚有戏。", "target_word": "戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "戏几点开始？", "target_word": "戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "戏八点开始，我们早点去。", "target_word": "戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在戏里演一个老人。", "target_word": "戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "戏演完了，大家一起拍手。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上的戏很长，要演三个小时。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里每年过年都请人来唱戏。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，今天的戏不演了。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸带我去剧院看戏，那里的位子很舒服。", "target_word": "戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们每天晚上都要演戏，所以白天要好好休息。", "target_word": "戏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "戏迷", "label": "复合"}, {"form": "戏台", "label": "复合"}, {"form": "戲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "戏：戏剧演出这一活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1766c185-9168-436d-834a-7e1714ef858c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "戏", "is_correct": true, "explanation": "戏（xì）指戏剧、演出，是正确答案。"}, {"text": "西", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是西方。"}, {"text": "吸", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是吸入。"}, {"text": "洗", "is_correct": false, "explanation": "xǐ（第三声）与 xì（第四声）声调不同，意思是清洗。"}, {"text": "喜", "is_correct": false, "explanation": "xǐ（第三声）与 xì（第四声）声调不同，意思是高兴。"}, {"text": "习", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是练习。"}], "explanations": {"戏": "戏（xì）指戏剧、演出，是正确答案。", "西": "xī（第一声）与 xì（第四声）声调不同，意思是西方。", "吸": "xī（第一声）与 xì（第四声）声调不同，意思是吸入。", "洗": "xǐ（第三声）与 xì（第四声）声调不同，意思是清洗。", "喜": "xǐ（第三声）与 xì（第四声）声调不同，意思是高兴。", "习": "xí（第二声）与 xì（第四声）声调不同，意思是练习。"}, "sentence_index": null, "correct_answer": "戏"}, "level_3": {"options": [{"text": "戏", "is_correct": true, "explanation": "戏：指舞台上的演出，“今晚有戏”即今晚有演出，是正确答案。"}, {"text": "春天", "is_correct": false, "explanation": "语义：“春天”是季节，不能用来指今晚的演出。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指过去，与“今晚”相矛盾。"}, {"text": "星期天", "is_correct": false, "explanation": "搭配：“有”后接时间词不自然，应说“今晚是星期天”。"}], "explanations": {"戏": "戏：指舞台上的演出，“今晚有戏”即今晚有演出，是正确答案。", "春天": "语义：“春天”是季节，不能用来指今晚的演出。", "昨天": "语义：“昨天”指过去，与“今晚”相矛盾。", "星期天": "搭配：“有”后接时间词不自然，应说“今晚是星期天”。"}, "sentence_index": 0, "correct_answer": "戏"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天看了一道戏，很精彩。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“道”计量，“道”用于菜、门、题、墙等。"}, {"text": "我每天晚上都看一块戏。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“块”计量，“块”多用于石头、肥皂、土地等。"}, {"text": "这张戏很好看。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“张”计量，“张”多用于纸张、票、桌子等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91906, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "戏", "is_correct": true, "explanation": "戏（xì）指戏剧、演出，是正确答案。"}, {"text": "希", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是希望。"}, {"text": "息", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是呼吸或消息。"}, {"text": "溪", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是小河。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是座位。"}, {"text": "袭", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是袭击。"}], "explanations": {"戏": "戏（xì）指戏剧、演出，是正确答案。", "希": "xī（第一声）与 xì（第四声）声调不同，意思是希望。", "息": "xī（第一声）与 xì（第四声）声调不同，意思是呼吸或消息。", "溪": "xī（第一声）与 xì（第四声）声调不同，意思是小河。", "席": "xí（第二声）与 xì（第四声）声调不同，意思是座位。", "袭": "xí（第二声）与 xì（第四声）声调不同，意思是袭击。"}, "sentence_index": null, "correct_answer": "戏"}, "level_3": {"options": [{"text": "戏", "is_correct": true, "explanation": "戏：指舞台上演的戏剧，“唱戏”即演戏，是正确答案。"}, {"text": "名", "is_correct": false, "explanation": "语义：“唱名”指点名，与过年请人来表演无关。"}, {"text": "名", "is_correct": false, "explanation": "搭配：“唱名”是点名的说法，不能用来指节日里的表演。"}, {"text": "票", "is_correct": false, "explanation": "语义：“唱票”指选举时读出选票，与过年请人表演无关。"}], "explanations": {"戏": "戏：指舞台上演的戏剧，“唱戏”即演戏，是正确答案。", "名": "搭配：“唱名”是点名的说法，不能用来指节日里的表演。", "票": "语义：“唱票”指选举时读出选票，与过年请人表演无关。"}, "sentence_index": 6, "correct_answer": "戏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们每天晚上都要演一首戏，所以白天要好好休息。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“首”计量，“首”用于诗词和歌曲。"}, {"text": "他们每天晚上都要演一幅戏，所以白天要好好休息。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“幅”计量，“幅”用于画作、照片等。"}, {"text": "他们每天晚上都要演一座戏，所以白天要好好休息。", "explanation": "这里应该用〈出〉或〈场〉。戏不用「座」计量，「座」用于山、桥、房屋等大型物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今晚有一座戏，很多人都会去看。", "corrected_sentence": "今晚有一出戏，很多人都会去看。", "error_description": "量词错误：演出类的“戏”量词应用“出”。“座”用于山、桥、房屋等大型物体，不用于戏。应为“一出戏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7e8cafc-c99a-4cca-80c2-0155c3e6b1ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
