INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91908, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在政治上与当权者持不同意见的人或团体。", "primary_collocate": null, "pronunciation": "fǎn duì pài", "ipa": "fan˨˩˦ tweɪ˥˩ pʰaɪ˥˩", "syllable_count": 3, "sentences": [{"text": "在议会里，反对派有二十个座位。", "target_word": "反对派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反对派在选举中得到了很多支持。", "target_word": "反对派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政党成了新的反对派。", "target_word": "反对派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反对派提出了自己的计划。", "target_word": "反对派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统请反对派一起讨论预算。", "target_word": "反对派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反对派的报纸每天批评政府。", "target_word": "反对派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反对派在电视上说出了自己的看法。", "target_word": "反对派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他加入了反对派，想改变国家的政策。", "target_word": "反对派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反对派和政府在税收问题上意见不同。", "target_word": "反对派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举后，原来的执政党变成了反对派。", "target_word": "反对派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个反对派", "label": "量词"}, {"form": "反對派", "label": "繁体"}], "register": "中性", "sense_fingerprint": "政治上与当权者意见不同的人或团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5a5e0a7-1931-406f-8fa8-4b6b6a09a7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反对派", "is_correct": true, "explanation": "“反对派”是议会中的政治团体，可以占有议会的座位，句意通顺。"}, {"text": "地球", "is_correct": false, "explanation": "语义：地球是星球，不设座位，与议会无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“有二十个座位”只搭配会议室、车、剧场这类场所或交通工具，“冰箱”不能这样搭配。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，没有座位，不能出现在议会的语境里。"}], "explanations": {"反对派": "“反对派”是议会中的政治团体，可以占有议会的座位，句意通顺。", "地球": "语义：地球是星球，不设座位，与议会无关。", "冰箱": "搭配：“有二十个座位”只搭配会议室、车、剧场这类场所或交通工具，“冰箱”不能这样搭配。", "月亮": "语义：月亮是天体，没有座位，不能出现在议会的语境里。"}, "sentence_index": 0, "correct_answer": "反对派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场足球赛中，反对派领先了两分。", "explanation": "这里应该用〈对手〉。反对派专指政治上对立的一方，足球比赛中的竞争方要说对手。"}, {"text": "他们俩在厨房里是反对派，一起做饭。", "explanation": "这里应该用〈搭档〉。反对派指政治上持不同意见的一方，一起做饭的人要说搭档。"}, {"text": "他和我是反对派，都在做设计。", "explanation": "这里应该用〈同行〉。反对派指政治上的对立团体，做同一行业的人要说同行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反对派", "is_correct": true, "explanation": "“反对派”是有看法、能在电视上表态的团体，可以作主语。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果没有思想，不能在电视上发表看法。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“说出自己的看法”的主语应是有思想的人或团体，“花朵”不能这样搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是没有生命的东西，不能说出看法。"}], "explanations": {"反对派": "“反对派”是有看法、能在电视上表态的团体，可以作主语。", "水果": "语义：水果没有思想，不能在电视上发表看法。", "花朵": "搭配：“说出自己的看法”的主语应是有思想的人或团体，“花朵”不能这样搭配。", "石头": "语义：石头是没有生命的东西，不能说出看法。"}, "sentence_index": 6, "correct_answer": "反对派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的反对派每天一起打篮球。", "explanation": "这里应该用〈同学〉。反对派是政治上的团体，班里的同学不能叫反对派。"}, {"text": "他每天都和反对派去散步。", "explanation": "这里应该用〈朋友〉。反对派指政治上的对立团体，不能用来说一起散步的朋友。"}, {"text": "他的反对派今年考上了大学。", "explanation": "这里应该用〈孩子〉。反对派指政治上的对立团体，不能指考上大学的人，应说他的孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次选举后，两只反对派都提出了新方案。", "corrected_sentence": "这次选举后，两个反对派都提出了新方案。", "error_description": "量词错误：“反对派”是团体，应该用量词“个”，“只”用于动物或成对的东西。应把“两只反对派”改成“两个反对派”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "反对派对政府一起讨论了新预算。", "corrected_sentence": "反对派跟政府一起讨论了新预算。", "error_description": "介词错误：和“一起”搭配要用“跟”，说“反对派跟政府一起讨论”，不能用“对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
