INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91909, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91909, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "就是现在这一会儿。", "primary_collocate": null, "pronunciation": "cǐ kè", "ipa": "tsʰɹ̩˨˩ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "此刻他正坐在窗边看书。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻是晚上九点，街上人很少。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻屋子里非常安静。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻我只想好好睡一觉。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻的他，心情十分平静。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了此刻，我才明白她的话。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻你最需要的是休息。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她此刻正在厨房里做饭。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻城市里的灯都亮了。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻我们都在等他的电话。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "此刻：就是现在这一会儿，指眼下很短的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a326b33e-2943-4e82-b30a-8c790c137e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此刻", "is_correct": true, "explanation": "正确：“此刻”指现在这一会儿，与“正坐在窗边看书”的进行态吻合。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“正坐在窗边看书”的当下动作矛盾。"}, {"text": "此后", "is_correct": false, "explanation": "语义：“此后”指之后的时间，与句中正在进行的动作不符。"}, {"text": "从前", "is_correct": false, "explanation": "搭配：“从前”指过去，不能与“正坐在窗边看书”的现在进行态搭配。"}], "explanations": {"此刻": "正确：“此刻”指现在这一会儿，与“正坐在窗边看书”的进行态吻合。", "明天": "语义：“明天”指将来，与“正坐在窗边看书”的当下动作矛盾。", "此后": "语义：“此后”指之后的时间，与句中正在进行的动作不符。", "从前": "搭配：“从前”指过去，不能与“正坐在窗边看书”的现在进行态搭配。"}, "sentence_index": 0, "correct_answer": "此刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我此刻明天要出差。", "explanation": "此刻只指现在这一会儿，不能用于将来的时间。这里“此刻”与将来的安排冲突。"}, {"text": "那时我此刻只想好好睡一觉。", "explanation": "此刻只指现在，不能用于过去的时刻。这里“此刻”与过去的叙述矛盾。"}, {"text": "我此刻每天都只想好好睡一觉。", "explanation": "此刻只指一个时间点，不表示反复出现的习惯。这里“此刻”与经常性的状态冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此刻", "is_correct": true, "explanation": "正确：“此刻”指眼下这一会儿，与“最需要的是休息”的当下判断吻合。"}, {"text": "一刹那", "is_correct": false, "explanation": "语义：“一刹那”指瞬间，不能与“最需要的是休息”这种持续性需求搭配。"}, {"text": "片刻", "is_correct": false, "explanation": "语义：“片刻”指很短的时段，句中说的是持续的需要，句意不符。"}, {"text": "当场", "is_correct": false, "explanation": "搭配：“当场”强调场所和情境，不能引出“最需要的是休息”这类判断。"}], "explanations": {"此刻": "正确：“此刻”指眼下这一会儿，与“最需要的是休息”的当下判断吻合。", "一刹那": "语义：“一刹那”指瞬间，不能与“最需要的是休息”这种持续性需求搭配。", "片刻": "语义：“片刻”指很短的时段，句中说的是持续的需要，句意不符。", "当场": "搭配：“当场”强调场所和情境，不能引出“最需要的是休息”这类判断。"}, "sentence_index": 6, "correct_answer": "此刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那次以后，此刻他再也没来过。", "explanation": "这里应该用〈此后〉。此刻指说话的这一刻，不能表示之后的时段。"}, {"text": "那天早上，我此刻就出门了。", "explanation": "此刻只指说话的这一刻，不能用于过去的时间，这里应该用〈当时〉。"}, {"text": "他此刻很多次打电话来，我都没接。", "explanation": "此刻只指一个时间点，不能与表示反复次数的说法连用。这里应该用表示反复的〈每次〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "此刻此刻，他正在超市买东西。", "corrected_sentence": "此刻，他正在超市买东西。", "error_description": "错误：“此刻”重复出现，句中只需要一个时间词；正确：“此刻，他正在超市买东西。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她此刻的正在院子里浇花。", "corrected_sentence": "她此刻正在院子里浇花。", "error_description": "错误：“此刻”与“正在”之间多出“的”，句子不通；正确：“她此刻正在院子里浇花。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
