INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "这个时刻；现在。", "primary_collocate": null, "pronunciation": "cǐ kè", "ipa": "tsʰɹ̩˨˩ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "此刻，窗外正下着大雨。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻我心里非常紧张。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻教室里一点声音也没有。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他此刻就在回家的路上。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻，全场的观众都站了起来。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻的天空特别蓝。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她此刻最想见的人是妈妈。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻孩子们已经睡着了。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你此刻在想什么？", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此刻不是说这件事的时候。", "target_word": "此刻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "此刻：说话或叙述时的这个时刻，即现在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a326b33e-2943-4e82-b30a-8c790c137e9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此刻", "is_correct": true, "explanation": "正确：“此刻”指说话的这一刻，与“正下着大雨”的进行态吻合。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“正下着大雨”的当下描写矛盾。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”是泛指的未来，不能与“正下着”这样的当下景象搭配。"}, {"text": "从前", "is_correct": false, "explanation": "搭配：“从前”指过去，不能与“正下着”的现在进行态搭配。"}], "explanations": {"此刻": "正确：“此刻”指说话的这一刻，与“正下着大雨”的进行态吻合。", "明天": "语义：“明天”指将来，与“正下着大雨”的当下描写矛盾。", "将来": "语义：“将来”是泛指的未来，不能与“正下着”这样的当下景象搭配。", "从前": "搭配：“从前”指过去，不能与“正下着”的现在进行态搭配。"}, "sentence_index": 0, "correct_answer": "此刻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他此刻下个月要去北京。", "explanation": "此刻只指说话的当下这一刻，不能指将来的某个时间。这里“此刻”用于将来，表意矛盾。"}, {"text": "那天晚上，他此刻在回家的路上。", "explanation": "这里讲的是过去的事，应该用〈当时〉。此刻只指说话的当下。"}, {"text": "他此刻每天都回家吃饭。", "explanation": "此刻只指一个时间点，不表示反复出现的习惯，不能用于经常性的动作。这里“此刻”与经常性的动作冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此刻", "is_correct": true, "explanation": "正确：“此刻”指说话时的当下，与“最想见的人”这一当下心愿吻合。"}, {"text": "一会儿", "is_correct": false, "explanation": "搭配：“一会儿”指很短的时段，不能与“最想见的人是妈妈”这种稳定心愿搭配。"}, {"text": "刹那", "is_correct": false, "explanation": "语义：“刹那”指瞬间，句中所说的心愿并非一闪即逝。"}, {"text": "当场", "is_correct": false, "explanation": "搭配：“当场”强调地点与场合，不能引出“最想见的人是妈妈”这类心愿判断。"}], "explanations": {"此刻": "正确：“此刻”指说话时的当下，与“最想见的人”这一当下心愿吻合。", "一会儿": "搭配：“一会儿”指很短的时段，不能与“最想见的人是妈妈”这种稳定心愿搭配。", "刹那": "语义：“刹那”指瞬间，句中所说的心愿并非一闪即逝。", "当场": "搭配：“当场”强调地点与场合，不能引出“最想见的人是妈妈”这类心愿判断。"}, "sentence_index": 6, "correct_answer": "此刻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他离开以后，此刻再也没有回来。", "explanation": "这里应该用〈此后〉。此刻指说话的这一刻，不能表示离开之后的时段。"}, {"text": "那年夏天，她此刻正在上大学。", "explanation": "此刻只指说话的这一刻，不能用于过去的年份，这里应该用〈当时〉。"}, {"text": "他此刻很多次都没来。", "explanation": "此刻只指一个时间点，不能与表示反复次数的说法连用。这里应该用表示反复的〈每次〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "此刻的时候，楼下的邻居正在唱歌。", "corrected_sentence": "此刻，楼下的邻居正在唱歌。", "error_description": "错误：“此刻”后多出“的时候”，与“此刻”重复表示时间；正确：“此刻，楼下的邻居正在唱歌。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他此刻的正在操场上跑步。", "corrected_sentence": "他此刻正在操场上跑步。", "error_description": "错误：“此刻”与“正在”之间多出“的”，句子不通；正确：“他此刻正在操场上跑步。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0a5a3877-51e2-4fb0-8a4a-65f3cda5de34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
