INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91911, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反恐是不让坏人用暴力吓唬大家。", "primary_collocate": null, "pronunciation": "fǎn kǒng", "ipa": "fan˨˩ kʰʊŋ˨˩", "syllable_count": 2, "sentences": [{"text": "警察每天努力反恐，保护大家的安全。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "反恐是为了让人们安心生活。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家一直在反恐。", "target_word": "反恐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了让孩子们安全，各国一起反恐。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作是反恐，经常很晚才回家。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏人用暴力吓人，所以警察要反恐。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机场的警察正在认真反恐。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都希望反恐能成功。", "target_word": "反恐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "反恐的人保护着我们的生活。", "target_word": "反恐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里有很多反恐的警察。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "制止坏人用暴力吓唬、伤害普通人，保护大家安全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99fe3606-75b6-4d45-9eb3-6ab141772d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91911, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反恐", "is_correct": true, "explanation": "正确。「反恐」指制止恐怖活动，与「保护大家的安全」呼应。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：「逃避」表示躲开困难，与「努力」「保护大家的安全」的积极含义矛盾。"}, {"text": "反省", "is_correct": false, "explanation": "语义：「反省」指自我检讨，与「保护大家的安全」无关。"}, {"text": "反对", "is_correct": false, "explanation": "语义：「反对」表示不赞成，与「保护大家的安全」所描述的防护行动不符。"}], "explanations": {"反恐": "正确。「反恐」指制止恐怖活动，与「保护大家的安全」呼应。", "逃避": "语义：「逃避」表示躲开困难，与「努力」「保护大家的安全」的积极含义矛盾。", "反省": "语义：「反省」指自我检讨，与「保护大家的安全」无关。", "反对": "语义：「反对」表示不赞成，与「保护大家的安全」所描述的防护行动不符。"}, "sentence_index": 0, "correct_answer": "反恐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警方一直在反恐毒品犯罪。", "explanation": "这里应该用〈打击〉。「反恐」专指针对恐怖活动，毒品犯罪要用〈打击〉。"}, {"text": "我们一起反恐疾病，保护孩子。", "explanation": "这里应该用〈防治〉。「反恐」只用于恐怖活动，疾病要用〈防治〉。"}, {"text": "大家都反恐这种不良行为。", "explanation": "这里应该用〈反对〉。「反恐」专指针对恐怖活动，表示不赞成不良行为要用〈反对〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91911, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反恐", "is_correct": true, "explanation": "正确。「反恐」与「机场的警察」的工作相符，「认真」修饰的正是这项工作。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝」表示不接受，与警察在机场「认真」履行的职责相反。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：「逃跑」与警察的职责相反，「认真」也无法修饰「逃跑」。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：「发呆」与「认真」的意思相反，也与警察在机场工作的情境不符。"}], "explanations": {"反恐": "正确。「反恐」与「机场的警察」的工作相符，「认真」修饰的正是这项工作。", "拒绝": "语义：「拒绝」表示不接受，与警察在机场「认真」履行的职责相反。", "逃跑": "语义：「逃跑」与警察的职责相反，「认真」也无法修饰「逃跑」。", "发呆": "语义：「发呆」与「认真」的意思相反，也与警察在机场工作的情境不符。"}, "sentence_index": 6, "correct_answer": "反恐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海关一直在反恐走私。", "explanation": "这里应该用〈打击〉。「反恐」专指针对恐怖活动，对走私要用〈打击〉。"}, {"text": "士兵们在边境反恐敌人的进攻。", "explanation": "这里应该用〈抵御〉。「反恐」专指针对恐怖活动，抵挡敌人进攻要用〈抵御〉。"}, {"text": "大家都反恐假货。", "explanation": "这里应该用〈抵制〉。「反恐」专指针对恐怖活动，不买假货要用〈抵制〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91911, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "特种部队专门负责反恐了工作。", "corrected_sentence": "特种部队专门负责反恐工作。", "error_description": "错误在于「反恐」后面多加了「了」。「了」表示动作完成，这里是名词「工作」前的修饰语，不能加「了」。正确说法是「负责反恐工作」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91911, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察在城市里很反恐。", "corrected_sentence": "警察在城市里反恐。", "error_description": "错误在于「很」修饰了动词「反恐」。「很」一般不修饰这样的动词，应删去「很」。正确说法是「警察在城市里反恐」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
