INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91912, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反对和预防恐怖活动。", "primary_collocate": null, "pronunciation": "fǎn kǒng", "ipa": "fan˨˩ kʰʊŋ˨˩", "syllable_count": 2, "sentences": [{"text": "两国政府决定合作反恐。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "反恐需要各国一起努力。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警方加强了反恐工作。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在反恐部门工作了十年。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻里说，反恐行动已经开始了。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机场加强安全检查，也是为了反恐。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "联合国多次讨论反恐问题。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家认为反恐要从预防做起。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校给学生上了一节反恐安全课。", "target_word": "反恐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反恐不仅要抓坏人，也要预防危险。", "target_word": "反恐", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "反对并预防恐怖活动，多见于新闻和政务语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99fe3606-75b6-4d45-9eb3-6ab141772d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反恐", "is_correct": true, "explanation": "正确。「两国政府决定合作」后面接的是要共同完成的事务，「反恐」正是这样的事务。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：「逃避」表示躲开责任，与「决定合作」的积极含义矛盾。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：「合作」后面要接事务，不能接「游泳」。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：「合作」后面要接事务，「两国政府合作睡觉」不成立。"}], "explanations": {"反恐": "正确。「两国政府决定合作」后面接的是要共同完成的事务，「反恐」正是这样的事务。", "逃避": "语义：「逃避」表示躲开责任，与「决定合作」的积极含义矛盾。", "游泳": "搭配：「合作」后面要接事务，不能接「游泳」。", "睡觉": "搭配：「合作」后面要接事务，「两国政府合作睡觉」不成立。"}, "sentence_index": 0, "correct_answer": "反恐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "消防队每天都在反恐火灾。", "explanation": "这里应该用〈灭火〉。「反恐」只用于恐怖活动，扑灭火灾要用〈灭火〉。"}, {"text": "为了保护森林，我们一起反恐盗猎。", "explanation": "这里应该用〈打击〉。「反恐」专指针对恐怖活动，打击盗猎要用〈打击〉。"}, {"text": "大家都反恐这种浪费的做法。", "explanation": "这里应该用〈反对〉。「反恐」针对的是恐怖活动，表示不赞成浪费要用〈反对〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反恐", "is_correct": true, "explanation": "正确。「联合国讨论」的对象是国际安全问题，「反恐问题」符合新闻语境。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：「跳舞」是娱乐活动，不能作为联合国讨论的议题。"}, {"text": "散步", "is_correct": false, "explanation": "语义：「散步」是日常消遣，不能作为联合国讨论的议题。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：「点燃」指使物体燃烧，与「问题」无法搭配，也不符合讨论的语境。"}], "explanations": {"反恐": "正确。「联合国讨论」的对象是国际安全问题，「反恐问题」符合新闻语境。", "跳舞": "语义：「跳舞」是娱乐活动，不能作为联合国讨论的议题。", "散步": "语义：「散步」是日常消遣，不能作为联合国讨论的议题。", "点燃": "语义：「点燃」指使物体燃烧，与「问题」无法搭配，也不符合讨论的语境。"}, "sentence_index": 6, "correct_answer": "反恐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生每天都在反恐疾病。", "explanation": "这里应该用〈防治〉。「反恐」只用于恐怖活动，预防和治疗疾病要用〈防治〉。"}, {"text": "政府努力反恐通货膨胀。", "explanation": "这里应该用〈遏制〉。「反恐」针对的是恐怖活动，控制物价上涨要用〈遏制〉。"}, {"text": "农民用棍子反恐野猪。", "explanation": "这里应该用〈驱赶〉。「反恐」针对的是恐怖活动，赶走野猪要用〈驱赶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "专家们正在研究反恐了措施。", "corrected_sentence": "专家们正在研究反恐措施。", "error_description": "错误在于「反恐」后面多加了「了」。「了」表示动作完成，这里「反恐」是修饰名词「措施」的成分，不能加「了」。正确说法是「研究反恐措施」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
