INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91913, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在这件事以前。", "primary_collocate": null, "pronunciation": "cǐ qián", "ipa": "tsʰɨ˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "此前我从没听说过这件事。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试很难，此前我没有复习好。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此前，他没有做过这样的工作。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议很重要，此前我们做了很多准备。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此前的几次考试，她都得了第一。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他此前一直不同意这件事。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚了，此前谁也没想到。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此前发生的事，请你不要再提了。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行很开心，此前我从没坐过飞机。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事公开了，此前没有人知道。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指某件事发生以前的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '923791ca-0690-495c-bb48-7710886093fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91913, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此前", "is_correct": true, "explanation": "此前指某件事以前，与“从没听说过这件事”的经历相符。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指尚未发生的时间，与“从没听说过”表示的已有经历不合。"}, {"text": "未来", "is_correct": false, "explanation": "语义：“未来”指尚未到来的时间，不能表示已经发生过的经历。"}, {"text": "中午", "is_correct": false, "explanation": "搭配：“中午”是具体时刻，不能与“从没听说过这件事”搭配。"}], "explanations": {"此前": "此前指某件事以前，与“从没听说过这件事”的经历相符。", "明天": "语义：“明天”指尚未发生的时间，与“从没听说过”表示的已有经历不合。", "未来": "语义：“未来”指尚未到来的时间，不能表示已经发生过的经历。", "中午": "搭配：“中午”是具体时刻，不能与“从没听说过这件事”搭配。"}, "sentence_index": 0, "correct_answer": "此前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们吃完晚饭，此前一起去看了电影。", "explanation": "这里应该用〈之后〉。此前指某件事以前，看电影是在吃饭之后，不能用“此前”。"}, {"text": "他的此前很有名，你听说过吗？", "explanation": "这里应该用〈过去〉。此前只指某件事之前的时间，不能指一个人的过去。"}, {"text": "他没有来，此前你们可以走了。", "explanation": "这里应该用〈所以〉。此前只表示某件事以前，不表示因果关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此前", "is_correct": true, "explanation": "此前指某件事以前，与“他们结婚了”之后“谁也没想到”的语境相符。"}, {"text": "下周", "is_correct": false, "explanation": "语义：“下周”指未来，与已经发生的“结婚了”不合。"}, {"text": "凌晨", "is_correct": false, "explanation": "搭配：“凌晨”是具体时刻，不与“谁也没想到”搭配。"}, {"text": "黄昏", "is_correct": false, "explanation": "搭配：“黄昏”是具体时刻，不能用来限定“谁也没想到”的范围。"}], "explanations": {"此前": "此前指某件事以前，与“他们结婚了”之后“谁也没想到”的语境相符。", "下周": "语义：“下周”指未来，与已经发生的“结婚了”不合。", "凌晨": "搭配：“凌晨”是具体时刻，不与“谁也没想到”搭配。", "黄昏": "搭配：“黄昏”是具体时刻，不能用来限定“谁也没想到”的范围。"}, "sentence_index": 6, "correct_answer": "此前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事此前很重要，所以我们要认真做。", "explanation": "这里应该用〈非常〉。此前表示时间，不能修饰“重要”表示程度。"}, {"text": "他就站在我此前，我却没看见。", "explanation": "这里应该用〈面前〉。此前只用于时间，不能表示空间位置，站在人的前面要说〈面前〉。"}, {"text": "请把书放在电脑此前。", "explanation": "这里应该用〈前面〉。此前只表示时间，不能表示东西摆放的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "此前了，我们从没见过面。", "corrected_sentence": "此前，我们从没见过面。", "error_description": "错误：“此前”后面不能直接加“了”，应去掉“了”。正确说法是“此前，我们从没见过面。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "此前之前，我们很久没见了。", "corrected_sentence": "此前，我们很久没见了。", "error_description": "错误：“此前”和“之前”意思重复，只用其中一个即可，应说“此前，我们很久没见了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
