INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91914, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91914, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在这个时间以前。", "primary_collocate": null, "pronunciation": "cǐ qián", "ipa": "tsʰɨ˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这家店去年才开业，此前这里是银行。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他三点才到，此前我们一直在等。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上个月我搬了家，此前住在学校旁边。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十年前，他来到北京，此前一直住在上海。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年春天，她开始学中文，此前没学过。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周一开始上班，此前他一直在休息。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，此前外面一直在下雨。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十二月公司搬走了，此前这里很热闹。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年夏天我换了手机，此前用的是旧的。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天才回国，此前我们很久没见了。", "target_word": "此前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指某个时间点以前的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '923791ca-0690-495c-bb48-7710886093fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此前", "is_correct": true, "explanation": "此前表示某个时间点以前，与“去年才开业”的前后关系相符。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过较长时间后才出现，与“去年才开业”的时间关系不合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与这句话描述的时间先后不合。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”用于表示转折，这句话没有转折关系，不搭配。"}], "explanations": {"此前": "此前表示某个时间点以前，与“去年才开业”的前后关系相符。", "终于": "语义：“终于”表示经过较长时间后才出现，与“去年才开业”的时间关系不合。", "忽然": "语义：“忽然”表示突然发生，与这句话描述的时间先后不合。", "却": "搭配：“却”用于表示转折，这句话没有转折关系，不搭配。"}, "sentence_index": 0, "correct_answer": "此前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他先在上海工作，此前来到北京。", "explanation": "这里应该用〈之后〉。此前指在前面的时间，不能用来说明后来发生的事。"}, {"text": "我昨天才认识他，此前我们已经认识五年了。", "explanation": "时间矛盾：“昨天才认识他”与“此前我们已经认识五年了”前后不能并存。"}, {"text": "他站在门此前等我。", "explanation": "这里应该用〈前面〉。此前只表示时间，不能表示位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此前", "is_correct": true, "explanation": "此前表示某个时间以前，指天黑以前外面一直在下雨，与语境相符。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经完成，与“天黑了”引出的描述不搭配。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示即将发生，与“一直在下雨”的持续状态不合。"}, {"text": "很快", "is_correct": false, "explanation": "语义：“很快”表示不久之后，与“一直”表示的持续不合。"}], "explanations": {"此前": "此前表示某个时间以前，指天黑以前外面一直在下雨，与语境相符。", "已经": "搭配：“已经”表示已经完成，与“天黑了”引出的描述不搭配。", "马上": "语义：“马上”表示即将发生，与“一直在下雨”的持续状态不合。", "很快": "语义：“很快”表示不久之后，与“一直”表示的持续不合。"}, "sentence_index": 6, "correct_answer": "此前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电影八点开始，我们此前九点到吧。", "explanation": "时间矛盾：此前指八点以前，九点在八点以后，应该说“七点半到”。"}, {"text": "我们快迟到了，此前快走吧。", "explanation": "这里应该用〈赶快〉。此前只表示时间上的先后，不能用来催促别人，催促要说〈赶快〉。"}, {"text": "这个苹果此前好吃。", "explanation": "这里应该用〈很〉。此前表示时间，不能表示程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她五年前来到这里，此前了一直在广州工作。", "corrected_sentence": "她五年前来到这里，此前一直在广州工作。", "error_description": "错误：副词“此前”后面不能加“了”，应去掉“了”，说“此前一直在广州工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天才回国，此前了我们很久没有见面。", "corrected_sentence": "妈妈昨天才回国，此前我们很久没有见面。", "error_description": "错误：副词“此前”后面不能加“了”，应去掉“了”，说“此前我们很久没有见面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
