INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91915, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "召唤是大声叫人快来。", "primary_collocate": null, "pronunciation": "zhào huàn", "ipa": "ʈʂau̯˥˩ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "他站在河边大声召唤同伴快来。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失火了，他大声召唤邻居快出来。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在操场上大声召唤学生集合。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路上有人摔伤，他大声召唤路人快来帮忙。", "target_word": "召唤", "complexity_tier": "T3", "furigana": "shān lù shàng yǒu rén shuāi shāng ， tā dà shēng zhào huàn lù rén kuài lái bāng máng 。", "sentence_source": "generated"}, {"text": "他在山顶对着山下大声召唤队友。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救生员大声召唤游泳的人快上岸。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在楼下大声召唤我下去。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑远了，她大声召唤它回来。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人在田里大声召唤孙子快回家。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长一边跑一边召唤大家跟上。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "召唤了", "label": "体标"}, {"form": "召唤着", "label": "体标"}, {"form": "召唤过", "label": "体标"}, {"form": "召喚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大声喊人，催人快点过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91915, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隐藏", "is_correct": false, "explanation": "语义：隐藏是藏起来，与“大声叫同伴快来”的意思相反"}, {"text": "召唤", "is_correct": true, "explanation": "正确：召唤表示大声叫人快来，与此句语境相合"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是取笑别人，与叫同伴快来并不相关"}, {"text": "增加", "is_correct": false, "explanation": "搭配：增加说的是数量变多，不说“增加同伴快来”"}], "explanations": {"隐藏": "语义：隐藏是藏起来，与“大声叫同伴快来”的意思相反", "召唤": "正确：召唤表示大声叫人快来，与此句语境相合", "嘲笑": "语义：嘲笑是取笑别人，与叫同伴快来并不相关", "增加": "搭配：增加说的是数量变多，不说“增加同伴快来”"}, "sentence_index": 0, "correct_answer": "召唤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大声召唤大家明天放假。", "explanation": "这里应该用〈通知〉。召唤是叫人前来，告知消息要用通知"}, {"text": "他大声召唤了一杯咖啡。", "explanation": "这里应该用〈点〉。召唤的对象是人，咖啡是物，点咖啡要用点"}, {"text": "他大声召唤电梯下来。", "explanation": "这里应该用〈叫〉。召唤的对象是人、动物或神灵，电梯是物，叫电梯要说叫"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91915, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "躲避", "is_correct": false, "explanation": "语义：躲避是躲开，与爸爸叫我下楼的意思相反"}, {"text": "召唤", "is_correct": true, "explanation": "正确：召唤表示大声叫人过来，爸爸在楼下叫我下去，正合此处"}, {"text": "讥笑", "is_correct": false, "explanation": "语义：讥笑是嘲笑，与爸爸叫我下楼的语境不合"}, {"text": "驳斥", "is_correct": false, "explanation": "语义：驳斥是反驳别人的观点，对象是言论，不能说“驳斥我下去”"}], "explanations": {"躲避": "语义：躲避是躲开，与爸爸叫我下楼的意思相反", "召唤": "正确：召唤表示大声叫人过来，爸爸在楼下叫我下去，正合此处", "讥笑": "语义：讥笑是嘲笑，与爸爸叫我下楼的语境不合", "驳斥": "语义：驳斥是反驳别人的观点，对象是言论，不能说“驳斥我下去”"}, "sentence_index": 6, "correct_answer": "召唤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大声召唤了一场会议。", "explanation": "这里应该用〈召开〉。召唤的对象是人，会议要说召开，不能用召唤"}, {"text": "他大声召唤了一份外卖。", "explanation": "这里应该用〈订〉。召唤的对象是人，外卖是物，订外卖要用订"}, {"text": "他大声召唤了一份合同。", "explanation": "这里应该用〈签〉。召唤的对象是人，合同是文件，签合同要用签"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶在厨房大声被召唤孙子吃饭。", "corrected_sentence": "奶奶在厨房大声召唤孙子吃饭。", "error_description": "错误形式：“被”与后面的“召唤孙子吃饭”结构冲突，“孙子”的施受关系不清。正确形式：去掉“被”，“奶奶在厨房大声召唤孙子吃饭。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫跑远了，他大声把召唤它回来。", "corrected_sentence": "小猫跑远了，他大声召唤它回来。", "error_description": "错误形式：“把”后直接接动词“召唤”，缺少“把”字句要求的受事（如“把它……”）。正确形式：去掉“把”，“小猫跑远了，他大声召唤它回来。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
