INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91916, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "呼唤；叫人前来。", "primary_collocate": null, "pronunciation": "zhào huàn", "ipa": "ʈʂau̯˥˩ xwan˥˩", "syllable_count": 2, "sentences": [{"text": "远方的家人在召唤我回去。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的钟声召唤村民来开会。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故现场，他召唤同事前来支援。", "target_word": "召唤", "complexity_tier": "T3", "furigana": "shì gù xiàn chǎng ， tā zhào huàn tóng shì qián lái zhī yuán 。", "sentence_source": "generated"}, {"text": "国家召唤年轻人去西部工作。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板召唤大家到会议室开会。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铃声召唤学生回到教室。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大海在召唤着他。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长辈召唤他过去说几句话。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师召唤他，他马上跑了过去。", "target_word": "召唤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山谷里的号角召唤猎手们前来集合。", "target_word": "召唤", "complexity_tier": "T3", "furigana": "shān gǔ lǐ de háo jiǎo zhào huàn liè shǒu men qián lái jí hé 。", "sentence_source": "generated"}], "morphological_forms": [{"form": "召唤了", "label": "体标"}, {"form": "召唤着", "label": "体标"}, {"form": "召唤过", "label": "体标"}, {"form": "召喚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "呼唤、叫人前来，可指人、声音或抽象的感召", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6e59a67-b373-4e65-8aa0-e2aa10bbe482') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "驱赶", "is_correct": false, "explanation": "语义：驱赶是赶走，与远方家人盼我回去的语境相反"}, {"text": "召唤", "is_correct": true, "explanation": "正确：召唤指叫人前来，远方的家人盼我回去，正合此处"}, {"text": "召开", "is_correct": false, "explanation": "配价：召开的对象是会议，不能带“我”作宾语"}, {"text": "回避", "is_correct": false, "explanation": "语义：回避是躲开，与家人希望我回去的意思相反"}], "explanations": {"驱赶": "语义：驱赶是赶走，与远方家人盼我回去的语境相反", "召唤": "正确：召唤指叫人前来，远方的家人盼我回去，正合此处", "召开": "配价：召开的对象是会议，不能带“我”作宾语", "回避": "语义：回避是躲开，与家人希望我回去的意思相反"}, "sentence_index": 0, "correct_answer": "召唤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我召唤了一张火车票。", "explanation": "这里应该用〈买〉。召唤的对象是人、声音或抽象的感召，火车票是物，买票要说买"}, {"text": "周末我召唤了一桌好菜。", "explanation": "这里应该用〈点〉。召唤的对象是人、声音或抽象的感召，菜是物，点菜要说点"}, {"text": "我召唤了一辆出租车过来。", "explanation": "这里应该用〈叫〉。召唤的对象是人，出租车是物，叫车要说叫，不说召唤"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "辞退", "is_correct": false, "explanation": "语义：辞退需要雇主，大海不能辞退人，与此句语境不合"}, {"text": "招待", "is_correct": false, "explanation": "语义：招待是接待客人，大海并不在接待他，句意不通"}, {"text": "辱骂", "is_correct": false, "explanation": "语义：辱骂是用恶毒的话骂人，大海不会骂人，与此句语境不合"}, {"text": "召唤", "is_correct": true, "explanation": "正确：召唤表示以声音或力量把人唤来，大海对他的召唤正合此处"}], "explanations": {"辞退": "语义：辞退需要雇主，大海不能辞退人，与此句语境不合", "招待": "语义：招待是接待客人，大海并不在接待他，句意不通", "辱骂": "语义：辱骂是用恶毒的话骂人，大海不会骂人，与此句语境不合", "召唤": "正确：召唤表示以声音或力量把人唤来，大海对他的召唤正合此处"}, "sentence_index": 6, "correct_answer": "召唤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直召唤我快点交作业。", "explanation": "这里应该用〈催〉。召唤是叫人前来，催促别人快做事要用催"}, {"text": "我召唤了一杯热茶。", "explanation": "这里应该用〈倒〉。召唤的对象是人、声音或抽象的感召，茶是物，倒茶要说倒"}, {"text": "他召唤了一下自己的头发。", "explanation": "这里应该用〈梳〉。召唤的对象是人、声音或抽象的感召，头发是物，梳头要说梳"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上的老人把召唤孩子回家。", "corrected_sentence": "山上的老人召唤孩子回家。", "error_description": "错误形式：“把”后直接接动词“召唤”，“把”字句要求“把”紧跟受事（如“把孩子……”），这里结构不成立。正确形式：去掉“把”，“山上的老人召唤孩子回家。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师了召唤学生们到教室。", "corrected_sentence": "老师召唤学生们到教室。", "error_description": "错误形式：“了”直接放在动词“召唤”前。正确形式：去掉这里的“了”，写作“老师召唤学生们到教室”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98207fd9-112f-47d6-85e5-d2ee21191221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
