INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91917, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "过去发生的大事。", "primary_collocate": null, "pronunciation": "lì shǐ shì jiàn", "ipa": "li˥˩ ʂɨ˨˩˦ ʂɨ˥˩ tɕjɛn˥˩", "syllable_count": 4, "sentences": [{"text": "历史课上，老师讲了一个历史事件。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书写了很多历史事件。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这个历史事件是哪年发生的吗？", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对中国的历史事件很感兴趣。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试要记住每个历史事件的时间。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在博物馆看到了很多历史事件的照片。", "target_word": "历史事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常给我讲他经历过的历史事件。", "target_word": "历史事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲的是一个真实的历史事件。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们把这个历史事件写下来。", "target_word": "历史事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个历史事件发生在一百年前。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "重大历史事件", "label": "复合"}], "register": "中性", "sense_fingerprint": "过去发生的大事，课本、电影、博物馆里常讲到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史事件", "is_correct": true, "explanation": "正确。历史事件指过去发生的大事，可以在历史课上讲给学生听。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不是可以讲述的内容，与“老师讲了”不搭。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“讲”一般搭配故事、道理，不能说“讲了一个午饭”。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是可以讲述的事情，句中“讲了”没有合适的对象。"}], "explanations": {"历史事件": "正确。历史事件指过去发生的大事，可以在历史课上讲给学生听。", "书包": "语义：书包是物品，不是可以讲述的内容，与“老师讲了”不搭。", "午饭": "搭配：“讲”一般搭配故事、道理，不能说“讲了一个午饭”。", "汽车": "语义：汽车不是可以讲述的事情，句中“讲了”没有合适的对象。"}, "sentence_index": 0, "correct_answer": "历史事件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去参观了一个历史事件。", "explanation": "这里应该用〈历史遗址〉。“参观”的对象是可以去看的地方或建筑，历史事件是已经发生的事，不能被参观。"}, {"text": "他是一个很有名的历史事件。", "explanation": "这里把“历史事件”当成了指人的〈人物〉来用。历史事件指已经发生的大事，不能用来指人，应说“历史人物”。"}, {"text": "我昨天吃了一个历史事件。", "explanation": "搭配错误：历史事件是抽象的事情，不能被吃，“吃”的宾语应是食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史事件", "is_correct": true, "explanation": "正确。历史事件是经历过的大事，可以讲给晚辈听。"}, {"text": "菜谱", "is_correct": false, "explanation": "搭配：“经历”说的是事件、困难，不能说“经历过菜谱”。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物是生物，不是可以被经历过并讲述的事情。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具是物品，“经历过”与“讲”都没有合适的对象。"}], "explanations": {"历史事件": "正确。历史事件是经历过的大事，可以讲给晚辈听。", "菜谱": "搭配：“经历”说的是事件、困难，不能说“经历过菜谱”。", "宠物": "语义：宠物是生物，不是可以被经历过并讲述的事情。", "玩具": "语义：玩具是物品，“经历过”与“讲”都没有合适的对象。"}, "sentence_index": 6, "correct_answer": "历史事件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个历史事件已经长大了一百年。", "explanation": "搭配错误：“长大”只用于人或动物，历史事件不会生长。"}, {"text": "这个历史事件出生在一百年前。", "explanation": "这里应该用〈历史人物〉。“出生”只用于人，历史事件是已经发生的事，不能说“出生”。"}, {"text": "这个历史事件被我借给了朋友。", "explanation": "搭配错误：历史事件是已经发生的事，不是可以借出的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们这学期学习了几张历史事件。", "corrected_sentence": "我们这学期学习了几个历史事件。", "error_description": "量词错误：“历史事件”的量词应用“个”（或“件”），不能用“张”。错误形式是“几张历史事件”，正确形式是“几个历史事件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们曾经研究了过那个历史事件。", "corrected_sentence": "学生们曾经研究过那个历史事件。", "error_description": "助词叠用错误：“了”与经历体“过”不能同时用在同一动词上，应只保留“过”，说“曾经研究过那个历史事件”，不能说“研究了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
