INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在历史上发生的、有重大影响的事情。", "primary_collocate": null, "pronunciation": "lì shǐ shì jiàn", "ipa": "li˥˩ ʂɨ˨˩˦ ʂɨ˥˩ tɕjɛn˥˩", "syllable_count": 4, "sentences": [{"text": "这是一个改变世界的历史事件。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个历史事件影响了很多国家。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那场战争是一个重大的历史事件。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个历史事件对后来的人影响很大。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说，这个历史事件改变了中国的未来。", "target_word": "历史事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人都忘不了这个重要的历史事件。", "target_word": "历史事件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个历史事件让整个国家都变了。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一百年后，人们还会想起这个历史事件。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那次会议成了一个重要的历史事件。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个历史事件使两个国家变成了朋友。", "target_word": "历史事件", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "重大历史事件", "label": "复合"}], "register": "中性", "sense_fingerprint": "对国家和世界有重大影响、改变历史方向的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史事件", "is_correct": true, "explanation": "正确。历史事件指对国家和世界有重大影响的事，可以改变世界。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是日常食物，不能改变世界。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不是事件，不能改变世界。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“改变世界的”修饰的应是重大的事，“作业”不能与之组合。"}], "explanations": {"历史事件": "正确。历史事件指对国家和世界有重大影响的事，可以改变世界。", "午饭": "语义：午饭是日常食物，不能改变世界。", "小猫": "语义：小猫是动物，不是事件，不能改变世界。", "作业": "搭配：“改变世界的”修饰的应是重大的事，“作业”不能与之组合。"}, "sentence_index": 0, "correct_answer": "历史事件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个历史事件生了一个孩子。", "explanation": "这里把“历史事件”当成了能生育的人来用。历史事件不能生孩子，“生孩子”只用于人。"}, {"text": "他是一个重大的历史事件。", "explanation": "这里把“历史事件”当成了指人的〈人物〉来用。历史事件指发生的大事，不能用来指人，应说“历史人物”。"}, {"text": "这个历史事件昨晚在床上睡了一觉。", "explanation": "搭配错误：“睡觉”只用于人或动物，历史事件不会睡觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史事件", "is_correct": true, "explanation": "正确。历史事件是有重大影响的事，能让整个国家发生变化。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的数值，不能让整个国家发生变化。"}, {"text": "标点", "is_correct": false, "explanation": "语义：标点是符号，不能让整个国家发生变化。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是家具，不能让整个国家都变了。"}], "explanations": {"历史事件": "正确。历史事件是有重大影响的事，能让整个国家发生变化。", "体温": "语义：体温是身体的数值，不能让整个国家发生变化。", "标点": "语义：标点是符号，不能让整个国家发生变化。", "课桌": "语义：课桌是家具，不能让整个国家都变了。"}, "sentence_index": 6, "correct_answer": "历史事件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个历史事件在街上散步了一个小时。", "explanation": "搭配错误：“散步”只用于人或动物，历史事件不能散步。"}, {"text": "这个历史事件的价格是五块钱。", "explanation": "搭配错误：历史事件没有价格，“价格”只用于商品。"}, {"text": "这个历史事件被我借给了朋友。", "explanation": "搭配错误：历史事件是已经发生的事，不是可以借出的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张重大历史事件改变了很多国家的命运。", "corrected_sentence": "这个重大历史事件改变了很多国家的命运。", "error_description": "量词错误：“历史事件”前的量词应用“个”（或“件”），不能用“张”。错误形式是“这张重大历史事件”，正确形式是“这个重大历史事件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师曾经讨论了过那个重大历史事件。", "corrected_sentence": "老师曾经讨论过那个重大历史事件。", "error_description": "助词叠用错误：“了”与经历体“过”不能同时用在同一动词上，应只保留“过”，说“曾经讨论过那个重大历史事件”，不能说“讨论了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
