INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91919, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "右边是和左边相对的那一边，写字的手那一边。", "primary_collocate": null, "pronunciation": "yòu bian", "ipa": "joʊ˥˩ pjɛn", "syllable_count": 2, "sentences": [{"text": "我写字用右手，笔放在右边。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把书包放在桌子右边。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的右边坐着一位老人。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，银行就在超市右边。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸的右边写着我的名字。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的左边是小王，右边是小李。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片右边那个高个子是我哥哥。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我吃饭时，杯子在碗的右边。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑板右边贴着一张新地图。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图右边有一行小字。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "右边儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "与左边相对、写字的手所在的一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106b6cc5-ef4e-4494-9883-9314d895a3e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91919, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "右边", "is_correct": true, "explanation": "正确，“笔放在右边”说明笔的位置，与前文“用右手”呼应。"}, {"text": "右脚", "is_correct": false, "explanation": "语义：笔不会放在脚上，与写字的语境不合。"}, {"text": "今天", "is_correct": false, "explanation": "语义：“今天”是时间，不是放东西的地方，“笔放在今天”不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“放在”后面要加方位词，如“桌子上”，不能直接说“放在桌子”。"}], "explanations": {"右边": "正确，“笔放在右边”说明笔的位置，与前文“用右手”呼应。", "右脚": "语义：笔不会放在脚上，与写字的语境不合。", "今天": "语义：“今天”是时间，不是放东西的地方，“笔放在今天”不成立。", "桌子": "搭配：“放在”后面要加方位词，如“桌子上”，不能直接说“放在桌子”。"}, "sentence_index": 0, "correct_answer": "右边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这么做是右边的。", "explanation": "这里应该用〈对〉。右边只指方位，不能表示做法正确。"}, {"text": "他用右边写字，写得很漂亮。", "explanation": "这里应该用〈右手〉。“右边”指方位，不指手。"}, {"text": "他的想法很右边，总是反对改革。", "explanation": "这里应该用〈右倾〉。“右边”指方位，不指政治立场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91919, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "右边", "is_correct": true, "explanation": "正确，“右边”说明高个子所在的位置。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能表示人物所在的位置。"}, {"text": "大小", "is_correct": false, "explanation": "搭配：“大小”修饰“那个高个子”时需要加“的”，而且不能指位置。"}, {"text": "内容", "is_correct": false, "explanation": "语义：“内容”不指位置，与“那个高个子”的所在不合。"}], "explanations": {"右边": "正确，“右边”说明高个子所在的位置。", "颜色": "语义：“颜色”不能表示人物所在的位置。", "大小": "搭配：“大小”修饰“那个高个子”时需要加“的”，而且不能指位置。", "内容": "语义：“内容”不指位置，与“那个高个子”的所在不合。"}, "sentence_index": 6, "correct_answer": "右边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用右边在地图上写了一行小字。", "explanation": "这里应该用〈右手〉。“右边”指方位，不指手。"}, {"text": "你说得很右边，地图上确实有一行小字。", "explanation": "这里应该用〈对〉。“右边”只指方位，不能表示说得正确。"}, {"text": "地图上的字太小了，我的右边看不清。", "explanation": "这里应该用〈右眼〉。“右边”指方位，不指眼睛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91919, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门的一个右边有一把钥匙。", "corrected_sentence": "门的右边有一把钥匙。", "error_description": "量词错误：“右边”是方位词，不能用“一个”计数。应去掉“一个”，说“门的右边有一把钥匙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91919, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家在学校地右边。", "corrected_sentence": "我家在学校的右边。", "error_description": "助词错误：修饰方位词“右边”时要用“的”，应说“学校的右边”；“地”用于修饰动词，不能用在名词后面。应把“学校地右边”改为“学校的右边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
