INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91920, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面向前方时靠右手的一侧。", "primary_collocate": null, "pronunciation": "yòu bian", "ipa": "joʊ˥˩ pjɛn", "syllable_count": 2, "sentences": [{"text": "面向前面站好，右边是我的好朋友。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车时，右边有一辆白色的车。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向前走，右边有一家小书店。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请站在老师右边。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你往前看，右边那座山很高。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走到路口，右边就是医院。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车右边的门打不开。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在队伍右边，面向着前方。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐在前排的人，右边是窗户。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了桥，右边有一个公园。", "target_word": "右边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "右边儿", "label": "儿化"}], "register": "中性", "sense_fingerprint": "面向前方时靠右手的一侧", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106b6cc5-ef4e-4494-9883-9314d895a3e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "右边", "is_correct": true, "explanation": "正确，“右边”指面向前方时靠右手的一侧，人站在那里。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“好朋友”指人，“书包”不能与之搭配作主语。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不能是人，与“好朋友”不合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能是人，与“好朋友”的指称矛盾。"}], "explanations": {"右边": "正确，“右边”指面向前方时靠右手的一侧，人站在那里。", "书包": "搭配：“好朋友”指人，“书包”不能与之搭配作主语。", "窗户": "语义：窗户是建筑部件，不能是人，与“好朋友”不合。", "颜色": "语义：颜色不能是人，与“好朋友”的指称矛盾。"}, "sentence_index": 0, "correct_answer": "右边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把右边伸出来。", "explanation": "这里应该用〈右手〉。“右边”指方位，不指手。"}, {"text": "老师说我的答案是右边的。", "explanation": "这里应该用〈对〉。“右边”只指方位，不能表示答案正确。"}, {"text": "他踢球时总是用右边踢。", "explanation": "这里应该用〈右脚〉。“右边”指方位，不指脚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "右边", "is_correct": true, "explanation": "正确，“汽车右边的门”指汽车右侧的门，与“打不开”呼应。"}, {"text": "车牌", "is_correct": false, "explanation": "语义：车牌不是门所在的位置，“车牌的门”不合逻辑。"}, {"text": "发动机", "is_correct": false, "explanation": "语义：发动机不是门所在的位置，“发动机的门”不通。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“钥匙”不能修饰“门”表示位置，“钥匙的门”不成词组。"}], "explanations": {"右边": "正确，“汽车右边的门”指汽车右侧的门，与“打不开”呼应。", "车牌": "语义：车牌不是门所在的位置，“车牌的门”不合逻辑。", "发动机": "语义：发动机不是门所在的位置，“发动机的门”不通。", "钥匙": "搭配：“钥匙”不能修饰“门”表示位置，“钥匙的门”不成词组。"}, "sentence_index": 6, "correct_answer": "右边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个做法是右边的，大家都同意。", "explanation": "这里应该用〈对〉。右边只指方位，不能表示做法正确。"}, {"text": "他用右边打开门，很自然。", "explanation": "这里应该用〈右手〉。“右边”指方位，不指手。"}, {"text": "他的观点太右边，总是反对新措施。", "explanation": "这里应该用〈右倾〉。“右边”指方位，不指政治立场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的座位老师的右边。", "corrected_sentence": "我的座位在老师的右边。", "error_description": "缺少介词“在”：表示位置要说“座位在……的右边”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站在桥地右边。", "corrected_sentence": "车站在桥的右边。", "error_description": "助词错误：修饰方位词“右边”时要用“的”，应说“桥的右边”；“地”用于修饰动词，不能用在名词后面。应把“桥地右边”改为“桥的右边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
