INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91921, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一条河流过的那一大片地方。", "primary_collocate": null, "pronunciation": "liú yù", "ipa": "ljou˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "黄河流域的春天来得比较晚。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个流域的人们世世代代种水稻。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江流域夏天雨水很多。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住在珠江流域的一个小城。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片流域的土地很平，适合种田。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年夏天，这个流域下了很多雨。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个流域的冬天很冷，常常下雪。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了黄河流域的地图。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的流域不大，只有几个村子。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷一辈子都生活在淮河流域。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "黄河流域", "label": "复合"}], "register": "中性", "sense_fingerprint": "一条河流过的大片地方，如黄河流域、长江流域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87150d12-542a-4cd3-9d47-2268558069be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91921, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流域", "is_correct": true, "explanation": "正确答案。「流域」指一条河流过的大片地方。"}, {"text": "留意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同，「留意」意思是注意。"}, {"text": "流于", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，「流于」意思是停留在某种程度，如流于形式。"}, {"text": "留予", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，「留予」意思是留给。"}], "explanations": {"流域": "正确答案。「流域」指一条河流过的大片地方。", "留意": "yì（第四声）与 yù（第四声）韵母不同，「留意」意思是注意。", "流于": "yú（第二声）与 yù（第四声）声调不同，「流于」意思是停留在某种程度，如流于形式。", "留予": "yǔ（第三声）与 yù（第四声）声调不同，「留予」意思是留给。"}, "sentence_index": null, "correct_answer": "流域"}, "level_3": {"options": [{"text": "人口", "is_correct": false, "explanation": "语义：「人口」指人的总数，不是地方，「春天来得晚」说不通。"}, {"text": "流域", "is_correct": true, "explanation": "正确答案。「流域」指一大片地方，黄河流域的春天来得晚，说得通。"}, {"text": "作风", "is_correct": false, "explanation": "语义：「作风」指做事的态度和方式，不是地方，「作风的春天」说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体形，不能用来指一个地方的春天。"}], "explanations": {"人口": "语义：「人口」指人的总数，不是地方，「春天来得晚」说不通。", "流域": "正确答案。「流域」指一大片地方，黄河流域的春天来得晚，说得通。", "作风": "语义：「作风」指做事的态度和方式，不是地方，「作风的春天」说不通。", "身材": "体貌：「身材」指人的体形，不能用来指一个地方的春天。"}, "sentence_index": 0, "correct_answer": "流域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个流域很热情，见了谁都打招呼。", "explanation": "这里应该用〈人〉。流域是大片地区，不会打招呼；说人热情要用「人」。"}, {"text": "这个流域很深。", "explanation": "这里应该用〈湖泊〉。「深」说水的深浅，流域是陆地上的大片地区，不能说深。"}, {"text": "这片流域的海浪很大，渔船都不敢出海。", "explanation": "这里应该用〈海域〉。流域是陆地上河流所流经的大片地区，不会有海浪，渔船出海的只能是海域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91921, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不是地方，「那个颜色的冬天」说不通。"}, {"text": "流域", "is_correct": true, "explanation": "正确答案。「流域」指一大片地方，这个地区的冬天很冷、常常下雪，说得通。"}, {"text": "面孔", "is_correct": false, "explanation": "体貌：「面孔」指人的脸，不能用来指一个地区的冬天。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：「乐曲」是音乐作品，不是地方，不能修饰「冬天」来指地区。"}], "explanations": {"颜色": "语义：「颜色」不是地方，「那个颜色的冬天」说不通。", "流域": "正确答案。「流域」指一大片地方，这个地区的冬天很冷、常常下雪，说得通。", "面孔": "体貌：「面孔」指人的脸，不能用来指一个地区的冬天。", "乐曲": "语义：「乐曲」是音乐作品，不是地方，不能修饰「冬天」来指地区。"}, "sentence_index": 6, "correct_answer": "流域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "淮河流域每天都起得很早，吃过饭就去地里干活。", "explanation": "这里应该用〈农民〉。流域是地区，不会起床、干活；说人起早干活要用「农民」。"}, {"text": "淮河流域一生气就摔东西，谁也劝不住。", "explanation": "这里应该用〈他〉。流域是地区，不会生气；说人发脾气要用「他」。"}, {"text": "淮河流域又饿又累，走不动了。", "explanation": "这里应该用〈我〉。流域是地区，不会饿，也不会累；说人身体状态要用「我」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91921, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们一家人都住在一条珠江流域。", "corrected_sentence": "他们一家人都住在珠江流域。", "error_description": "量词错误：「珠江流域」是地区名，前面不用「条」（「条」用于河流、道路等细长的东西），应直接说「住在珠江流域」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91921, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条流域的河水很清。", "corrected_sentence": "这个流域的河水很清。", "error_description": "量词错误：「流域」是一大片地区，应说「这个流域」或「这片流域」，不能用「条」（「条」用于河流、道路等细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
