INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一条河流的干流和支流所流经的整个区域。", "primary_collocate": null, "pronunciation": "liú yù", "ipa": "ljou˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "长江流域包括干流和很多支流经过的地方。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄河流域一共有九个省区。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个流域里有大小河流上百条。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在调查整个流域的水质。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流域内的城市要一起保护河水。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "珠江流域的水系很复杂，支流很多。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府为这个流域制定了新的规划。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个流域面积很大，有十几万平方公里。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨后，整个流域都要注意洪水。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流域管理需要上游和下游的城市一起努力。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "长江流域", "label": "复合"}], "register": "中性", "sense_fingerprint": "干流和支流流经的整个区域，用于水系、水质、管理等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87150d12-542a-4cd3-9d47-2268558069be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91922, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流域", "is_correct": true, "explanation": "正确答案。「流域」指一条河的干流和支流流经的整个区域。"}, {"text": "留意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同，「留意」意思是注意。"}, {"text": "流于", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，「流于」意思是停留在某种程度，如流于形式。"}, {"text": "留予", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，「留予」意思是留给。"}], "explanations": {"流域": "正确答案。「流域」指一条河的干流和支流流经的整个区域。", "留意": "yì（第四声）与 yù（第四声）韵母不同，「留意」意思是注意。", "流于": "yú（第二声）与 yù（第四声）声调不同，「流于」意思是停留在某种程度，如流于形式。", "留予": "yǔ（第三声）与 yù（第四声）声调不同，「留予」意思是留给。"}, "sentence_index": null, "correct_answer": "流域"}, "level_3": {"options": [{"text": "河床", "is_correct": false, "explanation": "语义：「河床」是河底的地方，不能包括干流和支流，句子说不通。"}, {"text": "流域", "is_correct": true, "explanation": "正确答案。「流域」包括干流和支流流经的地方，长江流域正是如此。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体形，不能用来指一条江的地区。"}, {"text": "作风", "is_correct": false, "explanation": "搭配：「作风」指做事的态度和方式，不能作为「长江」的范围。"}], "explanations": {"河床": "语义：「河床」是河底的地方，不能包括干流和支流，句子说不通。", "流域": "正确答案。「流域」包括干流和支流流经的地方，长江流域正是如此。", "身材": "体貌：「身材」指人的体形，不能用来指一条江的地区。", "作风": "搭配：「作风」指做事的态度和方式，不能作为「长江」的范围。"}, "sentence_index": 0, "correct_answer": "流域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个流域很害羞，一见人就脸红。", "explanation": "这里应该用〈她〉。流域是地区，不会害羞、脸红；说人害羞要用「她」等指人的词。"}, {"text": "这个流域很深。", "explanation": "这里应该用〈水库〉。「深」说水的深浅，流域是陆地上的大片地区，不能说深。"}, {"text": "这片流域的海水很咸，鱼都是海鱼。", "explanation": "这里应该用〈海域〉。流域是河流所经过的陆地区域，海水很咸、有海鱼的只能是海域，不能说流域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不是可以被政府规划的对象，「为这个颜色制定规划」说不通。"}, {"text": "流域", "is_correct": true, "explanation": "正确答案。政府可以为一大片地区制定规划，「流域」正合适。"}, {"text": "面孔", "is_correct": false, "explanation": "体貌：「面孔」指人的脸，不能作为政府规划的对象。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：「乐曲」是音乐作品，不是地区，不能作为规划的范围。"}], "explanations": {"颜色": "语义：「颜色」不是可以被政府规划的对象，「为这个颜色制定规划」说不通。", "流域": "正确答案。政府可以为一大片地区制定规划，「流域」正合适。", "面孔": "体貌：「面孔」指人的脸，不能作为政府规划的对象。", "乐曲": "语义：「乐曲」是音乐作品，不是地区，不能作为规划的范围。"}, "sentence_index": 6, "correct_answer": "流域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个流域很会讲笑话，逗得大家直笑。", "explanation": "这里应该用〈他〉。流域是地区，不会讲笑话；说人幽默要用「他」。"}, {"text": "这个流域穿着一双很旧的鞋。", "explanation": "这里应该用〈他〉。流域是地区，不会穿鞋；说人穿鞋要用「他」。"}, {"text": "这个流域饿得走不动了，想找点吃的。", "explanation": "这里应该用〈我〉。流域是地区，不会饿；说人饿了要用「我」等指人的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条长江流域一带有很多支流。", "corrected_sentence": "长江流域一带有很多支流。", "error_description": "量词错误：「长江流域」是一大片地区，前面不能加「条」（「条」用于河流、道路等细长的东西），应直接说「长江流域一带」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府正在保护这条流域的水质。", "corrected_sentence": "政府正在保护这个流域的水质。", "error_description": "量词错误：「流域」是一大片地区，应说「这个流域」或「这片流域」，不能用「条」（「条」用于河流、道路等细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91923, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "异类", "is_correct": true, "explanation": "正确，“异类”与“同类”意思相反，指性质、种类不同的一类。"}, {"text": "河流", "is_correct": false, "explanation": "河流是地理事物，与“同类”的意思没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户指房屋的开口部分，与“同类”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头指一种天然的固体，与“同类”没有反义关系。"}], "correct_answer": "异类", "explanations": {"异类": "正确，“异类”与“同类”意思相反，指性质、种类不同的一类。", "河流": "河流是地理事物，与“同类”的意思没有反义关系。", "窗户": "窗户指房屋的开口部分，与“同类”没有反义关系。", "石头": "石头指一种天然的固体，与“同类”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91923, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "异类", "is_correct": true, "explanation": "正确，“异类”与“同类”意思相反，指性质、种类不同的一类。"}, {"text": "书包", "is_correct": false, "explanation": "书包是装东西的用具，与“同类”没有反义关系。"}, {"text": "树叶", "is_correct": false, "explanation": "树叶是植物的一部分，与“同类”没有反义关系。"}, {"text": "山峰", "is_correct": false, "explanation": "山峰指山的顶部，与“同类”没有反义关系。"}], "correct_answer": "异类", "explanations": {"异类": "正确，“异类”与“同类”意思相反，指性质、种类不同的一类。", "书包": "书包是装东西的用具，与“同类”没有反义关系。", "树叶": "树叶是植物的一部分，与“同类”没有反义关系。", "山峰": "山峰指山的顶部，与“同类”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91923, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "同类是样子和性质差不多的一类。", "primary_collocate": null, "pronunciation": "tóng lèi", "ipa": "tʰʊŋ˧˥ leɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "苹果和梨是同类，都是水果。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种鱼是同类，样子很像。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种鸟样子像，叫声也差不多，是同类。", "target_word": "同类", "complexity_tier": "T3", "furigana": "zhè liǎng zhǒng niǎo yàng zi xiàng, jiào shēng yě chà bu duō, shì tóng lèi.", "sentence_source": "generated"}, {"text": "鲸和鱼看起来像，其实不是同类。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你选的这些书都是同类，风格很统一。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三种虫子形状相似，习性也差不多，是同类。", "target_word": "同类", "complexity_tier": "T3", "furigana": "zhè sān zhǒng chóng zi xíng zhuàng xiāng sì, xí xìng yě chà bu duō, shì tóng lèi.", "sentence_source": "generated"}, {"text": "这几件衣服颜色不同，但都是同类。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狮子和老虎是同类吗？", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩爱好一样，算是同类。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把同类的东西放在一起。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同类项", "label": "复合"}], "register": "中性", "sense_fingerprint": "样子和性质差不多、属于同一类的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106b6cc5-ef4e-4494-9883-9314d895a3e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91923, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同类", "is_correct": true, "explanation": "正确答案，指样子和性质差不多的一类。"}, {"text": "同乐", "is_correct": false, "explanation": "lè 与 lèi 韵母不同（e 与 ei），意思是一起快乐。"}, {"text": "虫类", "is_correct": false, "explanation": "chóng 与 tóng 声母不同（ch 与 t），意思是昆虫这一类。"}, {"text": "同力", "is_correct": false, "explanation": "lì 与 lèi 韵母不同（i 与 ei），意思是共同的力量。"}], "explanations": {"同类": "正确答案，指样子和性质差不多的一类。", "同乐": "lè 与 lèi 韵母不同（e 与 ei），意思是一起快乐。", "虫类": "chóng 与 tóng 声母不同（ch 与 t），意思是昆虫这一类。", "同力": "lì 与 lèi 韵母不同（i 与 ei），意思是共同的力量。"}, "sentence_index": null, "correct_answer": "同类"}, "level_3": {"options": [{"text": "同类", "is_correct": true, "explanation": "正确，“同类”指同一类，与后半句“都是水果”呼应。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：苹果和梨不是人，不能说“是朋友”。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜与后半句“都是水果”矛盾。"}, {"text": "种类", "is_correct": false, "explanation": "搭配：“是种类”后面通常要带“同一”等限定，单独说“是种类”不自然。"}], "explanations": {"同类": "正确，“同类”指同一类，与后半句“都是水果”呼应。", "朋友": "语义：苹果和梨不是人，不能说“是朋友”。", "蔬菜": "语义：蔬菜与后半句“都是水果”矛盾。", "种类": "搭配：“是种类”后面通常要带“同一”等限定，单独说“是种类”不自然。"}, "sentence_index": 0, "correct_answer": "同类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两块地的同类是三百平米。", "explanation": "这里应该用〈面积〉。同类指性质或种类相近的一类，不表示面积大小。"}, {"text": "这两件衣服的同类是红色的。", "explanation": "这里应该用〈颜色〉。同类指性质或种类相近的一类，不表示颜色。"}, {"text": "这棵树的同类是五米。", "explanation": "这里应该用〈高度〉。同类指性质或种类相近的一类，不表示高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同类", "is_correct": true, "explanation": "正确，“同类”说明这几件衣服性质相近，与前半句“颜色不同”形成转折。"}, {"text": "同色", "is_correct": false, "explanation": "语义：“同色”与前半句“颜色不同”直接矛盾。"}, {"text": "同伴", "is_correct": false, "explanation": "语义：衣服不是人，不能说“但都是同伴”。"}, {"text": "款式", "is_correct": false, "explanation": "搭配：“但都是款式”语义不通，需要说“款式相同”之类。"}], "explanations": {"同类": "正确，“同类”说明这几件衣服性质相近，与前半句“颜色不同”形成转折。", "同色": "语义：“同色”与前半句“颜色不同”直接矛盾。", "同伴": "语义：衣服不是人，不能说“但都是同伴”。", "款式": "搭配：“但都是款式”语义不通，需要说“款式相同”之类。"}, "sentence_index": 6, "correct_answer": "同类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市里的商品同类很多，有上百种。", "explanation": "这里应该用〈种类〉。“种类”指事物的类别数量，“同类”只说明性质相近，不能用来说类别多。"}, {"text": "这袋米的同类是五公斤。", "explanation": "这里应该用〈重量〉。同类指性质或种类相近的一类，不表示重量。"}, {"text": "这件衣服的同类是两百块。", "explanation": "这里应该用〈价格〉。同类指性质或种类相近的一类，不表示价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两只狗样子很像，它们很同类。", "corrected_sentence": "这两只狗样子很像，它们是同类。", "error_description": "词性错误：“同类”是名词，不能受“很”修饰。应把“很”改为“是”，说“它们是同类”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把同类地书放在一起。", "corrected_sentence": "我们把同类的书放在一起。", "error_description": "助词错误：修饰名词“书”时要用“的”，应说“同类的书”；“地”用于修饰动词，不能放在名词前。应把“同类地书”改为“同类的书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91924, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "异类", "is_correct": true, "explanation": "正确，“异类”与“同类”意思相反，指性质、种类不同的人或事物。"}, {"text": "石板", "is_correct": false, "explanation": "石板是一种建筑材料，与“同类”没有反义关系。"}, {"text": "云朵", "is_correct": false, "explanation": "云朵是天空中的水汽凝结物，与“同类”没有反义关系。"}, {"text": "果汁", "is_correct": false, "explanation": "果汁是饮料，与“同类”没有反义关系。"}], "correct_answer": "异类", "explanations": {"异类": "正确，“异类”与“同类”意思相反，指性质、种类不同的人或事物。", "石板": "石板是一种建筑材料，与“同类”没有反义关系。", "云朵": "云朵是天空中的水汽凝结物，与“同类”没有反义关系。", "果汁": "果汁是饮料，与“同类”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
