INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "性质、种类相同的人或事物。", "primary_collocate": null, "pronunciation": "tóng lèi", "ipa": "tʰʊŋ˧˥ leɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他们俩脾气一样，真是同类。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店只卖同类的产品，选择不多。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把同类的问题放在一起回答。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝙蝠不是鸟，它和老鼠才是同类。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到同类受伤了，大象会过来帮忙。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把同类的垃圾放进同一个桶里。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个故事是同类，主人公都很勇敢。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是找同类交朋友。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫和老虎是同类，都是猫科动物。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里同类的书摆在一起，很好找。", "target_word": "同类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同类项", "label": "复合"}], "register": "中性", "sense_fingerprint": "性质、种类相同的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106b6cc5-ef4e-4494-9883-9314d895a3e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91924, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同类", "is_correct": true, "explanation": "正确答案，指性质、种类相同的人或事物。"}, {"text": "同乐", "is_correct": false, "explanation": "lè 与 lèi 韵母不同（e 与 ei），意思是一起快乐。"}, {"text": "虫类", "is_correct": false, "explanation": "chóng 与 tóng 声母不同（ch 与 t），意思是昆虫这一类。"}, {"text": "同力", "is_correct": false, "explanation": "lì 与 lèi 韵母不同（i 与 ei），意思是共同的力量。"}], "explanations": {"同类": "正确答案，指性质、种类相同的人或事物。", "同乐": "lè 与 lèi 韵母不同（e 与 ei），意思是一起快乐。", "虫类": "chóng 与 tóng 声母不同（ch 与 t），意思是昆虫这一类。", "同力": "lì 与 lèi 韵母不同（i 与 ei），意思是共同的力量。"}, "sentence_index": null, "correct_answer": "同类"}, "level_3": {"options": [{"text": "同类", "is_correct": true, "explanation": "正确，“真是同类”说明两人性质相同，与“脾气一样”呼应。"}, {"text": "上司", "is_correct": false, "explanation": "语义：“上司”表示上下级关系，与“脾气一样”的平等描述不合。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“脾气一样”说明彼此了解，与“陌生人”矛盾。"}, {"text": "书本", "is_correct": false, "explanation": "语义：“书本”不是人，与“他们俩”不合。"}], "explanations": {"同类": "正确，“真是同类”说明两人性质相同，与“脾气一样”呼应。", "上司": "语义：“上司”表示上下级关系，与“脾气一样”的平等描述不合。", "陌生人": "语义：“脾气一样”说明彼此了解，与“陌生人”矛盾。", "书本": "语义：“书本”不是人，与“他们俩”不合。"}, "sentence_index": 0, "correct_answer": "同类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子的同类是一百平米。", "explanation": "这里应该用〈面积〉。同类指性质或种类相近的一类，不表示面积大小。"}, {"text": "这盒笔的同类是红色的。", "explanation": "这里应该用〈颜色〉。同类指性质或种类相近的一类，不表示颜色。"}, {"text": "这件商品的同类是三百块。", "explanation": "这里应该用〈价格〉。同类指性质或种类相近的一类，不表示价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCL