INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同类", "is_correct": true, "explanation": "正确，“同类”说明两个故事性质相近，与后半句呼应。"}, {"text": "同伴", "is_correct": false, "explanation": "语义：故事不是人，不能说“是同伴”。"}, {"text": "同事", "is_correct": false, "explanation": "语义：“同事”指共事的人，不能用来指故事。"}, {"text": "样子", "is_correct": false, "explanation": "搭配：“是样子”不成句，“样子”需要带修饰语，如“是同一个样子”。"}], "explanations": {"同类": "正确，“同类”说明两个故事性质相近，与后半句呼应。", "同伴": "语义：故事不是人，不能说“是同伴”。", "同事": "语义：“同事”指共事的人，不能用来指故事。", "样子": "搭配：“是样子”不成句，“样子”需要带修饰语，如“是同一个样子”。"}, "sentence_index": 6, "correct_answer": "同类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书店里的书同类很多，选起来不容易。", "explanation": "这里应该用〈种类〉。“种类”指事物的类别数量，“同类”不能用来说类别多。"}, {"text": "这箱书的同类是二十公斤。", "explanation": "这里应该用〈重量〉。同类指性质或种类相近的一类，不表示重量。"}, {"text": "这场比赛的同类用了两个小时。", "explanation": "这里应该用〈时间〉。同类指性质或种类相近的一类，不表示时间长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个人的性格很像，很同类。", "corrected_sentence": "这两个人的性格很像，算是同类。", "error_description": "词性错误：“同类”是名词，不能受“很”修饰。应把“很”改为“算是”，说“算是同类”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把同类地玩具放进箱子里。", "corrected_sentence": "我们把同类的玩具放进箱子里。", "error_description": "助词错误：修饰名词“玩具”时要用“的”，应说“同类的玩具”；“地”用于修饰动词，不能放在名词前。应把“同类地玩具”改为“同类的玩具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
