INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91925, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名声是别人怎么说你，好或不好。", "primary_collocate": null, "pronunciation": "míng shēng", "ipa": "miŋ˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他的名声很好，大家都愿意帮他。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的名声不太好。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做了坏事，名声就会变差。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很爱惜自己的名声。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司的名声一直不错。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一句谎话会毁掉你的好名声。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了保住名声，什么都不敢说。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人名声不好，你要小心。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好名声需要很多年才能建立起来。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠诚实得到了好名声。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "别人对一个人好或不好的说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99fe3606-75b6-4d45-9eb3-6ab141772d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91925, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名声", "is_correct": true, "explanation": "正确。名声 míng shēng，指别人对某人好或不好的评价。"}, {"text": "名胜", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是名胜古迹，不是名声。"}, {"text": "民生", "is_correct": false, "explanation": "mín 与 míng 韵母不同（-in 与 -ing），意思是民众的生活，不是名声。"}, {"text": "名山", "is_correct": false, "explanation": "shān 与 shēng 韵母不同（-an 与 -eng），意思是有名的山，不是名声。"}], "explanations": {"名声": "正确。名声 míng shēng，指别人对某人好或不好的评价。", "名胜": "shèng（第四声）与 shēng（第一声）声调不同，意思是名胜古迹，不是名声。", "民生": "mín 与 míng 韵母不同（-in 与 -ing），意思是民众的生活，不是名声。", "名山": "shān 与 shēng 韵母不同（-an 与 -eng），意思是有名的山，不是名声。"}, "sentence_index": null, "correct_answer": "名声"}, "level_3": {"options": [{"text": "名声", "is_correct": true, "explanation": "正确。“名声很好”指别人对他的评价，与“大家都愿意帮他”相符。"}, {"text": "名单", "is_correct": false, "explanation": "语义：名单是人名的列表，不能用“很好”来形容，也与“大家都愿意帮他”不相干。"}, {"text": "名片", "is_correct": false, "explanation": "搭配：名片一般说“递名片”，不说“名片很好”。"}, {"text": "名牌", "is_correct": false, "explanation": "语义：名牌指商品的品牌，不能用来形容“他”。"}], "explanations": {"名声": "正确。“名声很好”指别人对他的评价，与“大家都愿意帮他”相符。", "名单": "语义：名单是人名的列表，不能用“很好”来形容，也与“大家都愿意帮他”不相干。", "名片": "搭配：名片一般说“递名片”，不说“名片很好”。", "名牌": "语义：名牌指商品的品牌，不能用来形容“他”。"}, "sentence_index": 0, "correct_answer": "名声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的名声权受到了侵犯。", "explanation": "这里应该用〈名誉〉。法律上的固定说法是“名誉权”，不说“名声权”。"}, {"text": "他的名声叫王明。", "explanation": "这里应该用〈名字〉。“叫”后面接的是人的称呼，名声不能这样用。"}, {"text": "这个包是一个好名声。", "explanation": "这里应该用〈名牌〉。“名声”指别人对人或事的评价，不能用来指商品的牌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91925, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "名声", "is_correct": true, "explanation": "正确。名声 míng shēng，指别人的评价。"}, {"text": "名称", "is_correct": false, "explanation": "ch 与 sh 声母不同（chēng 与 shēng），意思是事物的称呼，不是名声。"}, {"text": "民声", "is_correct": false, "explanation": "mín 与 míng 韵母不同（-in 与 -ing），意思是民众的呼声，不是名声。"}, {"text": "明星", "is_correct": false, "explanation": "xīng 与 shēng 声母、韵母都不同（x 与 sh，-ing 与 -eng），意思是有名的演员或运动员，不是名声。"}], "explanations": {"名声": "正确。名声 míng shēng，指别人的评价。", "名称": "ch 与 sh 声母不同（chēng 与 shēng），意思是事物的称呼，不是名声。", "民声": "mín 与 míng 韵母不同（-in 与 -ing），意思是民众的呼声，不是名声。", "明星": "xīng 与 shēng 声母、韵母都不同（x 与 sh，-ing 与 -eng），意思是有名的演员或运动员，不是名声。"}, "sentence_index": null, "correct_answer": "名声"}, "level_3": {"options": [{"text": "名声", "is_correct": true, "explanation": "正确。“保住名声”指维护别人对自己的评价。"}, {"text": "名句", "is_correct": false, "explanation": "语义：名句指著名的诗文语句，不能被“保住”，与“什么都不敢说”也不相干。"}, {"text": "名曲", "is_correct": false, "explanation": "语义：名曲指著名的乐曲，不能被“保住”。"}, {"text": "名册", "is_correct": false, "explanation": "搭配：“保住”一般说“保住位置、饭碗”，不说“保住名册”。"}], "explanations": {"名声": "正确。“保住名声”指维护别人对自己的评价。", "名句": "语义：名句指著名的诗文语句，不能被“保住”，与“什么都不敢说”也不相干。", "名曲": "语义：名曲指著名的乐曲，不能被“保住”。", "名册": "搭配：“保住”一般说“保住位置、饭碗”，不说“保住名册”。"}, "sentence_index": 6, "correct_answer": "名声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试的名声很靠前。", "explanation": "这里应该用〈名次〉。“靠前”说的是排名，名声不能“靠前”。"}, {"text": "他终于抢到了一个名声。", "explanation": "这里应该用〈名额〉。“抢到”的是机会或位置，名声不能被“抢到”。"}, {"text": "他的名声是一位老师。", "explanation": "这里把“名声”当成了人。“名声”是别人对一个人的评价，不是人，不能说“是一位……”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直有一只好名声。", "corrected_sentence": "他一直有一个好名声。", "error_description": "量词错误：“只”多用于动物或成对物品中的单个，名声要用“个”，应改为“一个好名声”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有很好名声，大家都信任他。", "corrected_sentence": "他有好名声，大家都信任他。", "error_description": "“很好”修饰名词时须加“的”：漏掉“的”是错因，应说“很好的名声”；删去“很”改为“好名声”也可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
