INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91926, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们对某人或某事的评价。", "primary_collocate": null, "pronunciation": "míng shēng", "ipa": "miŋ˧˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "这家医院的名声很好，病人很多。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校的名声传到了国外。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条坏评论让这家餐厅的名声变差了。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的名声一直不错，价格也合适。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了公司的名声，主动道歉了。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在行业里名声很大。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮过很多人，名声很快就传遍了全村。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的名声不太好，很多人不想合作。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老医生的好名声传遍了小镇。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店靠好吃的饭菜建立了名声。", "target_word": "名声", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "人们对某人或某事物的评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99fe3606-75b6-4d45-9eb3-6ab141772d2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91926, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "名声", "is_correct": true, "explanation": "正确。名声 míng shēng，指人们对某人或某事的评价。"}, {"text": "名胜", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，意思是名胜古迹，不是名声。"}, {"text": "民生", "is_correct": false, "explanation": "mín 与 míng 韵母不同（-in 与 -ing），意思是民众的生活，不是名声。"}, {"text": "名山", "is_correct": false, "explanation": "shān 与 shēng 韵母不同（-an 与 -eng），意思是有名的山，不是名声。"}], "explanations": {"名声": "正确。名声 míng shēng，指人们对某人或某事的评价。", "名胜": "shèng（第四声）与 shēng（第一声）声调不同，意思是名胜古迹，不是名声。", "民生": "mín 与 míng 韵母不同（-in 与 -ing），意思是民众的生活，不是名声。", "名山": "shān 与 shēng 韵母不同（-an 与 -eng），意思是有名的山，不是名声。"}, "sentence_index": null, "correct_answer": "名声"}, "level_3": {"options": [{"text": "名声", "is_correct": true, "explanation": "正确。“名声很好”说的是人们对医院的评价，与“病人很多”相符。"}, {"text": "名册", "is_correct": false, "explanation": "语义：名册是登记名字的册子，不能用“很好”来评价医院。"}, {"text": "名曲", "is_correct": false, "explanation": "语义：名曲指著名的乐曲，不能用来修饰医院。"}, {"text": "名句", "is_correct": false, "explanation": "搭配：名句一般说“引用名句”，不说“这家医院的名句很好”。"}], "explanations": {"名声": "正确。“名声很好”说的是人们对医院的评价，与“病人很多”相符。", "名册": "语义：名册是登记名字的册子，不能用“很好”来评价医院。", "名曲": "语义：名曲指著名的乐曲，不能用来修饰医院。", "名句": "搭配：名句一般说“引用名句”，不说“这家医院的名句很好”。"}, "sentence_index": 0, "correct_answer": "名声"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次比赛的名声很靠前。", "explanation": "这里应该用〈名次〉。“靠前”说的是排名，名声不能“靠前”。"}, {"text": "我的名声叫王丽。", "explanation": "这里应该用〈名字〉。“叫”后面接的是人的称呼，名声不能这样用。"}, {"text": "这本书的名声是《家》。", "explanation": "这里应该用〈名字〉。书叫什么是名字，名声是人们对它的评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91926, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "名声", "is_correct": true, "explanation": "正确。名声 míng shēng，指人们对某人或某事的评价。"}, {"text": "名称", "is_correct": false, "explanation": "ch 与 sh 声母不同（chēng 与 shēng），意思是事物的称呼，不是名声。"}, {"text": "民声", "is_correct": false, "explanation": "mín 与 míng 韵母不同（-in 与 -ing），意思是民众的呼声，不是名声。"}, {"text": "明星", "is_correct": false, "explanation": "xīng 与 shēng 声母、韵母都不同（x 与 sh，-ing 与 -eng），意思是有名的演员或运动员，不是名声。"}], "explanations": {"名声": "正确。名声 míng shēng，指人们对某人或某事的评价。", "名称": "ch 与 sh 声母不同（chēng 与 shēng），意思是事物的称呼，不是名声。", "民声": "mín 与 míng 韵母不同（-in 与 -ing），意思是民众的呼声，不是名声。", "明星": "xīng 与 shēng 声母、韵母都不同（x 与 sh，-ing 与 -eng），意思是有名的演员或运动员，不是名声。"}, "sentence_index": null, "correct_answer": "名声"}, "level_3": {"options": [{"text": "名声", "is_correct": true, "explanation": "正确。他帮过很多人，人们对他的好评价“名声”传遍了全村。"}, {"text": "名牌", "is_correct": false, "explanation": "语义：名牌指有名的商品品牌，与“他帮过很多人”无关，不能这样用。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片是一张印着姓名的卡片，帮助别人不会让名片“传遍全村”。"}, {"text": "名额", "is_correct": false, "explanation": "语义：名额指人数限额，一般说“分配、争取名额”，与帮助别人无关。"}], "explanations": {"名声": "正确。他帮过很多人，人们对他的好评价“名声”传遍了全村。", "名牌": "语义：名牌指有名的商品品牌，与“他帮过很多人”无关，不能这样用。", "名片": "语义：名片是一张印着姓名的卡片，帮助别人不会让名片“传遍全村”。", "名额": "语义：名额指人数限额，一般说“分配、争取名额”，与帮助别人无关。"}, "sentence_index": 6, "correct_answer": "名声"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个产品的名声很好记。", "explanation": "这里应该用〈名称〉。“好记”说的是名称，名声不能这样用。"}, {"text": "他抢到了一个名声。", "explanation": "这里应该用〈名额〉。“抢到”的是机会或位置，名声不能被“抢到”。"}, {"text": "请把你的名声写在这张纸上。", "explanation": "这里应该用〈名字〉。写在纸上的是名字，名声是别人的评价，不能写下来填表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院有一条好名声。", "corrected_sentence": "这家医院有一个好名声。", "error_description": "量词错误：名声用“个”，不用“条”；“条”多用于细长的东西，应改为“一个好名声”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家老店有很好名声。", "corrected_sentence": "这家老店有很好的名声。", "error_description": "的字缺失：“很好”修饰名词时要加“的”，应说“很好的名声”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b050b674-078c-4742-a41f-c6a1ccf76a12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
