INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91927, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种有刺的花，常常是红色，很香。", "primary_collocate": null, "pronunciation": "méi guī", "ipa": "mei̯˧˥ kwei̯˥", "syllable_count": 2, "sentences": [{"text": "她手里拿着一朵红玫瑰。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵玫瑰真香。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情人节那天，他送给她九朵玫瑰。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不敢摸玫瑰，因为它有刺。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的花瓶里有三朵玫瑰。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玫瑰的颜色又红又漂亮。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢玫瑰的香味。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把玫瑰放在窗边。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这束玫瑰多少钱？", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玫瑰的花瓣落了一地。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "朵", "label": "量词"}, {"form": "束", "label": "量词"}, {"form": "玫瑰花", "label": "复合词"}], "register": "中性", "sense_fingerprint": "有刺、常为红色、很香的一种花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a182e01-4fd0-41b9-afec-41667e58b233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91927, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玫瑰", "is_correct": true, "explanation": "正确：“玫瑰”是有刺、常为红色的花，能拿在手里，与句意相符。"}, {"text": "云", "is_correct": false, "explanation": "搭配：“拿着”的宾语要能用手握持，“云”不能拿在手里。"}, {"text": "火花", "is_correct": false, "explanation": "语义：“火花”是瞬间迸发的火星，不是花，也不能拿在手里。"}, {"text": "浪花", "is_correct": false, "explanation": "语义：“浪花”是水花，不是花卉，也不能拿在手里。"}], "explanations": {"玫瑰": "正确：“玫瑰”是有刺、常为红色的花，能拿在手里，与句意相符。", "云": "搭配：“拿着”的宾语要能用手握持，“云”不能拿在手里。", "火花": "语义：“火花”是瞬间迸发的火星，不是花，也不能拿在手里。", "浪花": "语义：“浪花”是水花，不是花卉，也不能拿在手里。"}, "sentence_index": 0, "correct_answer": "玫瑰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那朵玫瑰正在桌子上写作业，写得很认真。", "explanation": "这里应该用〈学生〉。“玫瑰”是花，不会写作业；写作业的是学生。"}, {"text": "他骑着那朵玫瑰去上学。", "explanation": "这里应该用〈自行车〉。“玫瑰”是花，不能骑；骑去上学的是自行车。"}, {"text": "我用那朵玫瑰修好了收音机。", "explanation": "这里应该用〈螺丝刀〉。“玫瑰”是花，不能用来修收音机；修理要用工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玫瑰", "is_correct": true, "explanation": "正确：“玫瑰”的香味人可以喜欢，与句意相符。"}, {"text": "石板", "is_correct": false, "explanation": "语义：“石板”没有香味，与“喜欢……的香味”说不通。"}, {"text": "砖头", "is_correct": false, "explanation": "语义：“砖头”没有香味，与“喜欢……的香味”说不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "搭配：“香味”多用于好闻的气味，不说“垃圾的香味”。"}], "explanations": {"玫瑰": "正确：“玫瑰”的香味人可以喜欢，与句意相符。", "石板": "语义：“石板”没有香味，与“喜欢……的香味”说不通。", "砖头": "语义：“砖头”没有香味，与“喜欢……的香味”说不通。", "垃圾": "搭配：“香味”多用于好闻的气味，不说“垃圾的香味”。"}, "sentence_index": 6, "correct_answer": "玫瑰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那朵玫瑰在考试中得了九十分。", "explanation": "这里应该用〈学生〉。“玫瑰”是花，不能参加考试；得分的是学生。"}, {"text": "这束玫瑰每天按时上下班。", "explanation": "这里应该用〈工人〉。“玫瑰”是花，不能上班；上下班的是工人。"}, {"text": "那朵玫瑰读完了三本书。", "explanation": "这里应该用〈读者〉。“玫瑰”是花，不会读书；读书的是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他送给我一块玫瑰。", "corrected_sentence": "他送给我一朵玫瑰。", "error_description": "错误：量词“块”用于块状物，花应用“朵”。正确形式是“送给我一朵玫瑰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的花园里开着一头红玫瑰。", "corrected_sentence": "她的花园里开着一朵红玫瑰。", "error_description": "错误：量词“头”用于牛、猪等动物，花应用“朵”。正确形式是“开着一朵红玫瑰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
