INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91928, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蔷薇科灌木，花多为红色，有香味，茎上有刺；也指这种花。", "primary_collocate": null, "pronunciation": "méi guī", "ipa": "mei̯˧˥ kwei̯˥", "syllable_count": 2, "sentences": [{"text": "花园里的玫瑰开花了。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玫瑰的茎上有刺。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种玫瑰是红色的，很香。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在院子里种了很多玫瑰。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一束红玫瑰送给妈妈。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玫瑰是一种灌木。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，玫瑰长出了新叶子。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，玫瑰的刺会扎手。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玫瑰的香味飘进了房间。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家花店的玫瑰很新鲜。", "target_word": "玫瑰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "朵", "label": "量词"}, {"form": "束", "label": "量词"}, {"form": "玫瑰花", "label": "复合词"}], "register": "中性", "sense_fingerprint": "蔷薇科有刺的灌木，也指它开的红色香花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a182e01-4fd0-41b9-afec-41667e58b233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玫瑰", "is_correct": true, "explanation": "正确：“玫瑰”是灌木，花园里能开花，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“开花”一般用于植物，“石头”不搭配。"}, {"text": "雕像", "is_correct": false, "explanation": "语义：“雕像”是无生命的人造物，与“开花”的生命特征矛盾。"}, {"text": "铁门", "is_correct": false, "explanation": "搭配：“铁门”是金属建筑构件，不能说“开花”。"}], "explanations": {"玫瑰": "正确：“玫瑰”是灌木，花园里能开花，与句意相符。", "石头": "搭配：“开花”一般用于植物，“石头”不搭配。", "雕像": "语义：“雕像”是无生命的人造物，与“开花”的生命特征矛盾。", "铁门": "搭配：“铁门”是金属建筑构件，不能说“开花”。"}, "sentence_index": 0, "correct_answer": "玫瑰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那朵玫瑰在花园里飞来飞去，很可爱。", "explanation": "这里应该用〈蝴蝶〉。“玫瑰”是植物，不会飞，飞来飞去的是蝴蝶。"}, {"text": "那棵玫瑰每天早上汪汪地叫。", "explanation": "这里应该用〈小狗〉。“玫瑰”是植物，不会叫；汪汪叫的是小狗。"}, {"text": "他用那朵玫瑰修好了自行车。", "explanation": "这里应该用〈螺丝刀〉。“玫瑰”是花，不能用来修车；修车要用螺丝刀这类工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玫瑰", "is_correct": true, "explanation": "正确：“玫瑰”是植物，春天会长出新叶子，与句意相符。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：“长出新叶子”说的是植物，小狗不长叶子，搭配不当。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不会长出叶子，与句意矛盾。"}, {"text": "石桌", "is_correct": false, "explanation": "语义：“石桌”是无生命的器物，不会长叶子，与“春天来了”的生长描述矛盾。"}], "explanations": {"玫瑰": "正确：“玫瑰”是植物，春天会长出新叶子，与句意相符。", "小狗": "搭配：“长出新叶子”说的是植物，小狗不长叶子，搭配不当。", "冰箱": "语义：“冰箱”是家用电器，不会长出叶子，与句意矛盾。", "石桌": "语义：“石桌”是无生命的器物，不会长叶子，与“春天来了”的生长描述矛盾。"}, "sentence_index": 6, "correct_answer": "玫瑰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他穿着那朵玫瑰去参加婚礼。", "explanation": "这里应该用〈裙子〉。“玫瑰”是花，不能穿在身上；穿着去参加婚礼的是衣服。"}, {"text": "那棵玫瑰每天晚上都要写作业。", "explanation": "这里应该用〈学生〉。“玫瑰”是植物，不会写作业；写作业的是学生。"}, {"text": "他骑着那朵玫瑰去上学。", "explanation": "这里应该用〈自行车〉。“玫瑰”是植物，不能骑；骑去上学的是自行车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在花园里摘了一头玫瑰。", "corrected_sentence": "妈妈在花园里摘了一朵玫瑰。", "error_description": "错误：量词“头”用于牛、猪等动物，花应用“朵”。正确形式是“摘了一朵玫瑰”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在花店买了一块玫瑰。", "corrected_sentence": "我在花店买了一束玫瑰。", "error_description": "错误：量词“块”用于块状物，花束要用“束”（或“朵”）。正确形式是“买了一束玫瑰”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
