INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91929, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "向来是从以前一直到现在都这样。", "primary_collocate": null, "pronunciation": "xiàng lái", "ipa": "ɕjɑŋ˥˩ laɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我向来不迟到。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸向来睡得很晚。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人向来重视家人。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向来对人很客气。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的夏天向来很热。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向来不说别人的坏话。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我向来喜欢听音乐。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张向来说到做到。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥向来不爱运动。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李向来很会照顾朋友。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从以前一直到现在都这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf3d60e-a1e3-44ad-8ec7-68f909d098f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "向来", "is_correct": true, "explanation": "正确：“向来”表示一直如此，与“不迟到”的习惯相符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”不能直接修饰“不迟到”这样的否定动作。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作正在进行，与长期的习惯说法不通。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”不能直接修饰否定的动作，不能说“非常不迟到”。"}], "explanations": {"向来": "正确：“向来”表示一直如此，与“不迟到”的习惯相符。", "很": "搭配：“很”不能直接修饰“不迟到”这样的否定动作。", "正在": "语义：“正在”表示动作正在进行，与长期的习惯说法不通。", "非常": "搭配：“非常”不能直接修饰否定的动作，不能说“非常不迟到”。"}, "sentence_index": 0, "correct_answer": "向来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作业向来写完了。", "explanation": "这里应该用〈已经〉。向来指长期如此，不能用于已完成的具体事件。"}, {"text": "经过三天的努力，他向来通过了考试。", "explanation": "这里应该用〈终于〉。向来指长期如此，不能用于经过努力后才出现的一次结果。"}, {"text": "火车向来要开了。", "explanation": "这里应该用〈马上〉。向来指长期的情况，不能用于即将发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向来", "is_correct": true, "explanation": "正确：“向来”表示长期的喜好，与“喜欢听音乐”相符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指立即发生，与长期的喜好不符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指不久前才开始，与“向来”表示的一贯喜好相反。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”要求共同行动，单人的喜好不能说“一起喜欢”。"}], "explanations": {"向来": "正确：“向来”表示长期的喜好，与“喜欢听音乐”相符。", "马上": "语义：“马上”指立即发生，与长期的喜好不符。", "刚刚": "语义：“刚刚”指不久前才开始，与“向来”表示的一贯喜好相反。", "一起": "搭配：“一起”要求共同行动，单人的喜好不能说“一起喜欢”。"}, "sentence_index": 6, "correct_answer": "向来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "最近一段时间，他向来很累。", "explanation": "这里应该用〈一直〉。向来指长期的情况，不能用于最近一段时间的状态。"}, {"text": "他向来搬去了上海。", "explanation": "这里应该用〈后来〉。向来指一直如此，搬家是一次性的变化，不能用“向来”来说。"}, {"text": "她向来哭了起来。", "explanation": "这里应该用〈突然〉。向来指长期的情况，不能用于一次突然发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
