INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91930, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从过去到现在一直如此。", "primary_collocate": null, "pronunciation": "xiàng lái", "ipa": "ɕjɑŋ˥˩ laɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "他向来不喝咖啡，只喝茶。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我向来起得很早。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师向来很严格。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西向来很便宜。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向来说话很小声。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家向来不吃辣的菜。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他向来喜欢一个人看书。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟向来怕黑，晚上不敢出门。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天向来很冷。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈向来不让我晚上玩手机。", "target_word": "向来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示从过去到现在一直是这样的副词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bf3d60e-a1e3-44ad-8ec7-68f909d098f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "向来", "is_correct": true, "explanation": "正确：“向来”表示一直如此，与“不喝咖啡”的习惯相符。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”不能直接修饰否定的动作，不能说“很不喝咖啡”。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”一般修饰形容词或心理动词，不能说“非常不喝咖啡”。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“不断”表示动作持续进行，与“不喝咖啡”的习惯说法不通。"}], "explanations": {"向来": "正确：“向来”表示一直如此，与“不喝咖啡”的习惯相符。", "很": "搭配：“很”不能直接修饰否定的动作，不能说“很不喝咖啡”。", "非常": "搭配：“非常”一般修饰形容词或心理动词，不能说“非常不喝咖啡”。", "不断": "语义：“不断”表示动作持续进行，与“不喝咖啡”的习惯说法不通。"}, "sentence_index": 0, "correct_answer": "向来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天他向来很忙。", "explanation": "这里应该用〈一直〉。向来指长期如此，多用于习惯或特点，不能用于最近几天的情况。"}, {"text": "他向来开始喝咖啡了。", "explanation": "这里应该用〈最近〉。向来指长期如此，不能与“开始”这种刚发生的变化搭配。"}, {"text": "作业向来写完了。", "explanation": "这里应该用〈已经〉。向来指长期的情况，不能用于已经完成的具体事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向来", "is_correct": true, "explanation": "正确：“向来”表示长期的习惯，与“喜欢一个人看书”相符。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指立即发生，与长期的喜好不符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上发生，与“向来”表示的一贯习惯相反。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”要求共同行动，与“一个人”的说法矛盾。"}], "explanations": {"向来": "正确：“向来”表示长期的习惯，与“喜欢一个人看书”相符。", "马上": "语义：“马上”指立即发生，与长期的喜好不符。", "立刻": "语义：“立刻”指马上发生，与“向来”表示的一贯习惯相反。", "一起": "搭配：“一起”要求共同行动，与“一个人”的说法矛盾。"}, "sentence_index": 6, "correct_answer": "向来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向来要去北京了。", "explanation": "这里应该用〈马上〉。向来指长期如此，不能用于即将发生的事。"}, {"text": "我向来在三年前见过他。", "explanation": "这里应该用〈曾经〉。向来指长期如此，不能用于三年前的一次经历。"}, {"text": "妈妈向来生气了。", "explanation": "这里应该用〈突然〉。向来指长期的情况，不能用来描述一次突发的事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad0badf5-6311-488a-aa29-6009ae476e02') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
