INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91931, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做东西的公司。", "primary_collocate": null, "pronunciation": "shēng chǎn qǐ yè", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩˦ tɕʰi˨˩˦ je˥˩", "syllable_count": 4, "sentences": [{"text": "他在一家生产企业做工程师。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家生产企业做的玩具很受欢迎。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们城里有很多生产企业。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家生产企业每天做一万双鞋。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐想去一家生产企业工作。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的杯子来自一家生产企业。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家生产企业为工人建了新宿舍。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家生产企业的工厂在城外。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的朋友开了一家生产企业，做家具。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产企业的工人早上七点就开始工作。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "生產企業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做东西、有工厂的公司，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87150d12-542a-4cd3-9d47-2268558069be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = 