INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诗歌", "is_correct": false, "explanation": "语义：「诗歌」是文学作品，不是公司，「在一家诗歌做工程师」说不通。"}, {"text": "生产企业", "is_correct": true, "explanation": "正确答案。「生产企业」指做东西的公司，工程师可以在这样的公司工作。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体形，不能用来指工作的地方。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不是公司，「在一家颜色做工程师」说不通。"}], "explanations": {"诗歌": "语义：「诗歌」是文学作品，不是公司，「在一家诗歌做工程师」说不通。", "生产企业": "正确答案。「生产企业」指做东西的公司，工程师可以在这样的公司工作。", "身材": "体貌：「身材」指人的体形，不能用来指工作的地方。", "颜色": "语义：「颜色」不是公司，「在一家颜色做工程师」说不通。"}, "sentence_index": 0, "correct_answer": "生产企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家生产企业每天帮客户存钱取钱。", "explanation": "这里应该用〈银行〉。生产企业是做东西的公司，办理存取款的是银行，不能说生产企业。"}, {"text": "这家生产企业每天看病的人很多。", "explanation": "这里应该用〈医院〉。生产企业是做东西的公司，不给人看病。"}, {"text": "这家生产企业有三百名学生。", "explanation": "这里应该用〈学校〉。生产企业是做东西的公司，不招收学生，「学生」说的是学校里的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fa3b21f-2fe6-4f02-ac3c-e780e3bc392d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
